export const KB = [{"d":"Устав ВС и ФСВНГ","t":"Статья 1.1. Соблюдение Устава","x":"Каждый военнослужащий обязан знать и соблюдать положения настоящего Устава. Незнание Устава не освобождает от ответственности.","r":"ВУ ст. 1.1","k":"обязан ли я знать устав ; не знал что так нельзя ; незнание устава не освобождает"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.2. Воинский долг","x":"Каждый военнослужащий обязан честно и качественно исполнять воинский долг, защищать национальные интересы, суверенитет и целостность территории Российской Федерации.","r":"ВУ ст. 1.2","k":"воинский долг что это ; обязанности военнослужащего в целом"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.3. Исполнение приказов","x":"Военнослужащий обязан исполнить законный приказ начальника. При получении заведомо незаконного приказа военнослужащий не исполняет его и незамедлительно докладывает непосредственному либо вышестоящему начальнику.","r":"ВУ ст. 1.3","k":"приказ незаконный что делать ; командир приказал сделать что-то против устава ; могу ли не выполнять приказ ; отказаться от приказа ; приказали нарушить закон ; старший приказал пропустить без документов ; заведомо незаконный приказ кому докладывать"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.4. Репутация Армии","x":"Запрещены действия, способные нанести ущерб репутации Армии или подорвать доверие к ней.","r":"ВУ ст. 1.4","k":"опозорил армию ; репутация армии ; выложил видео с базы в тикток ; дискредитация армии"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.5. Обращение по служебным вопросам","x":"При возникновении служебных вопросов военнослужащий обращается к командиру своего подразделения.","r":"ВУ ст. 1.5","k":"к кому обращаться с вопросом по службе ; куда обратиться если есть вопрос ; к кому идти с проблемой"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.6. Единоначалие","x":"Командир наделен распорядительной властью и несет персональную ответственность за подразделение.","r":"ВУ ст. 1.6","k":"кто главный в подразделении ; единоначалие ; командир отвечает за подразделение"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.7. Построения","x":"Во время объявленного построения военнослужащие обязаны явиться в назначенное место точно и в срок, кроме лиц, несущих службу на посту.","r":"ВУ ст. 1.7","k":"опоздал на построение ; объявили построение а я на посту ; надо ли идти на построение с поста ; не пришёл на построение ; построение когда ; сбор на плацу ; постовой на построение"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.8. Набор","x":"Набор в ряды Армии осуществляется посредством агитационных мероприятий и призывов по утвержденному графику.","r":"ВУ ст. 1.8","k":"как набирают в армию ; призыв агитация ; откуда берутся новобранцы"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.9. КМБ и Военная академия","x":"Курс молодого бойца проходит не более чем за 5 дней, Военная академия - не более чем за 10 дней. После провала Военной академии военнослужащий заносится в черный список на срок от 14 до 90 дней по решению командования.","r":"ВУ ст. 1.9","k":"сколько длится кмб ; провалил военную академию ; чёрный список после академии ; сколько дней на кмб ; не сдал академию что будет ; бан после провала вуза"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.10. Основания для увольнения","x":"Основаниями для увольнения являются: собственное желание; грубое нарушение Устава; нарушение законодательства; решение суда или предписание Прокуратуры; непрохождение КМБ или Военной академии; отсутствие в подразделении более 48 часов; нахождение в части без формы; самовольное оставление части; иные прямо предусмотренные настоящим Уставом основания. Наличие дисциплинарных взысканий влечет последствия в порядке, установленном Дисциплинарным уставом.","r":"ВУ ст. 1.10","k":"за что могут уволить ; основания увольнения ; уволят ли за отсутствие ; не был в части 48 часов ; пришёл без формы уволят ; самоволка увольнение ; хочу уволиться по собственному ; меня выгонят"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.11. Военная присяга","x":"Каждый военнослужащий, прибывший в часть и проходящий КМБ или Военную академию, обязан принять Военную присягу. Отказ от ее принятия или грубое нарушение присяги является основанием для увольнения.","r":"ВУ ст. 1.11","k":"обязательно ли принимать присягу ; отказался от присяги ; когда принимают присягу ; присяга обязательна ; не хочу присягу"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.12. Сбережение имущества","x":"Военнослужащий обязан бережно относиться к вооружению, технике, обмундированию и иному государственному имуществу. Запрещены умышленная порча, неаккуратное использование служебного транспорта, утрата или небрежное хранение оружия и спецсредств, использование казенного имущества в личных целях.","r":"ВУ ст. 1.12","k":"сломал служебную машину ; разбил военную технику ; потерял оружие что будет ; испортил форму ; разбил тачку части ; утеря оружия ; сломал технику части ; бережное отношение к имуществу"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.1. Служебный день","x":"Рабочий день для личного состава ВС и ФСВНГ устанавливается ежедневно с 11:00 до 21:30.","r":"ВУ ст. 2.1","k":"во сколько начинается служба ; рабочий день с какого часа ; график службы ; до скольки служба ; часы работы части ; во сколько заканчивается рабочий день ; служебный день"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.2. Перерыв","x":"Обеденное время устанавливается ежедневно с 18:00 до 19:00 и предоставляется без оформления увольнительной.","r":"ВУ ст. 2.2","k":"когда обед ; во сколько обед ; перерыв на еду ; нужна ли увольнительная на обед ; обеденное время ; перерыв"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.3. Вызов на службу","x":"Служебная деятельность не прекращается после завершения рабочего дня. Военнослужащий может быть вызван из отгула, кроме отпуска в мирное время.","r":"ВУ ст. 2.3","k":"могут ли вызвать в нерабочее время ; вызвали из отгула ; служба после рабочего дня ; выдернули на службу вечером"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.4. Вечерняя проверка","x":"Ежедневно в 21:00 проводится вечерняя проверка. Во время вечерней проверки постовые не покидают пост. Их присутствие подтверждается докладом по рации, через начальника караула либо после смены поста.","r":"ВУ ст. 2.4","k":"во сколько вечерняя проверка ; вечерняя проверка что это ; я на посту во время проверки ; надо ли идти с поста на вечернюю проверку ; поверка в 21"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.5. Изменение графика","x":"Командир части вправе временно корректировать график приказом.","r":"ВУ ст. 2.5","k":"изменили график ; командир поменял расписание"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.6. Увольнительное время и выход из части","x":"Рядовой и ефрейтор могут покидать часть только по увольнительной, при наличии необходимых и непереносимых для увольнительной причин. Начиная со звания младший сержант, военнослужащий вправе запросить и получить увольнительное время продолжительностью 60 минут в день (можно разбить на два промежутка длительностью 30 минут). Младший сержант и выше могут покидать часть после окончания службы при отсутствии ограничений, наряда, тревоги или дисциплинарного запрета.","r":"ВУ ст. 2.6","k":"могу ли выйти из части ; увольнительная как получить ; рядовой может выйти в город ; выход из части рядовому ; хочу отойти по делам ; увольнительное время 60 минут ; выйти за территорию ; можно ли покинуть часть ; младший сержант увольнительная ; уйти из части на час ; ефрейтор выход из части"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.7. Отпуск","x":"Младший сержант и выше имеют право на отпуск до 7 дней раз в месяц. По семейным обстоятельствам отпуск может быть предоставлен в ином объеме по решению вышестоящего командования.","r":"ВУ ст. 2.7","k":"отпуск сколько дней ; как взять отпуск ; положен ли отпуск рядовому ; отпуск по семейным ; отпуск раз в месяц"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.8. Отдых в части","x":"Для отдыха на территории части используются казарма, раздевалка и медицинский блок. Продолжительность отдыха не должна препятствовать службе.","r":"ВУ ст. 2.8","k":"где отдыхать в части ; можно ли поспать в казарме ; отдых на территории ; где можно посидеть отдохнуть"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.9. Повышенная готовность","x":"При переходе в режим повышенной боевой готовности (Код-4) часть переходит в круглосуточный режим, весь состав находится в расположении части.","r":"ВУ ст. 2.9","k":"код 4 что делать ; боевая тревога что делать ; объявили код 4 ; повышенная готовность ; круглосуточный режим ; все в часть по тревоге"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.10. Плановый медицинский осмотр","x":"Плановый медицинский осмотр проводится до вечерней проверки либо после замены военнослужащего на посту. Он проводится в независимое от вечерней проверки время и назначается сотрудниками медицинской роты.","r":"ВУ ст. 2.10","k":"медосмотр когда ; плановый медицинский осмотр ; надо ли на медосмотр с поста ; медрота осмотр"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.1. Военная форма","x":"В расположении части и на официальных мероприятиях обязательна военная форма. Форма должна соответствовать подразделению и воинскому званию.","r":"ВУ ст. 3.1","k":"можно ли ходить в гражданке по части ; форма обязательна ; в чём ходить в части ; без формы на территории ; гражданская одежда в части"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.2. Внешний вид и форма одежды","x":"Запрещаются спортивная и пляжная одежда, неопрятная одежда, яркие аксессуары, неустановленные знаки различия, криминальная или аморальная символика. Требования к прическе, бороде и усам устанавливаются настоящим Уставом и приказами командования.","r":"ВУ ст. 3.2","k":"можно ли в спортивках ; яркие аксессуары ; спортивная одежда в части ; неопрятный вид ; шорты в части ; пляжная одежда ; криминальная символика"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.3. Требования к внешнему виду военнослужащих","x":"Новобранцы до присвоения звания младшего сержанта обязаны иметь полностью выбритую голову и не допускаются к службе при наличии растительности на лице. Начиная со звания младшего сержанта, прическа военнослужащего должна быть аккуратной, соответствовать требованиям гигиены и не препятствовать ношению головных уборов, средств индивидуальной защиты, включая каску и противогаз.","r":"ВУ ст. 3.3","k":"надо ли бриться налысо ; борода можно ; лысая голова обязательна ; рядовой с бородой ; стрижка новобранца ; усы разрешены ; причёска какая должна быть ; растительность на лице ; щетина"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.4. Обращение с оружием","x":"Военнослужащий обязан относиться к оружию как к заряженному, не направлять его на людей без непосредственной необходимости, не держать палец на спусковом крючке до принятия решения о выстреле и быть уверенным в цели и обстановке за ней.","r":"ВУ ст. 3.4","k":"правила обращения с оружием ; куда направлять оружие ; палец на спусковом крючке ; техника безопасности с оружием ; оружие как заряженное ; направил оружие на человека"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.4.1. Право на ношение табельного оружия","x":"Постоянное ношение табельного оружия при исполнении служебных обязанностей допускается всеми военнослужащими, наличие такого обязательно на период фактического несения караульно-постовой службы, патрулирования, учений, тренировок, специальных операций либо иной служебной деятельности.","r":"ВУ ст. 3.4.1","k":"могу ли носить оружие постоянно ; обязательно ли оружие на посту ; табельное оружие когда носить ; право на ношение оружия ; нужен ли автомат на патруле"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.4.2. Сдача вооружения при выходе из части","x":"Военнослужащие в звании от рядового до подполковника включительно, покидающие территорию воинской части в гражданской форме, обязаны до выхода через контрольно-пропускной пункт сдать закрепленные за ними оружие, боеприпасы и специальные средства на склад вооружения. Запрещается оставлять табельное оружие, боеприпасы и специальные средства в личном транспортном средстве либо передавать их другому лицу без законных оснований. Исключение: ношение вооружения по гражданской форме допускается для военнослужащих ССО, ГРУ и Военной полиции при выполнении служебной или оперативной задачи, прямо предполагающей ношение оружия за пределами воинской части.","r":"ВУ ст. 3.4.2","k":"выхожу из части в гражданке с оружием ; куда сдать оружие перед выходом ; оставил оружие в машине ; передал оружие другу ; можно ли выехать с оружием ; сдача оружия на склад ; оружие за пределами части ; выезд в город с автоматом ; кому можно носить оружие в гражданке"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.5. Бодикамеры","x":"Бодикамера обязательна для сотрудников ВП, ОСБ, военнослужащих на КПП, патрулей и лиц, проводящих задержание. При неисправности камеры военнослужащий докладывает старшему и фиксирует обстоятельства в журнале.","r":"ВУ ст. 3.5","k":"нужна ли бодикамера ; бодикамера обязательна ; сломалась бодикамера ; камера не работает что делать ; без бодикамеры на кпп ; красный индикатор камеры"},{"d":"Устав ВС и ФСВНГ","t":"Статья 4.1. Иерархия","x":"Иерархическая структура Армии: Лидер Армии; Заместитель Лидера Армии; Начальник ВС и его заместители; Начальник ФСВНГ и его заместители; командиры подразделений.","r":"ВУ ст. 4.1","k":"кто главнее в армии ; иерархия армии ; структура командования ; кто выше начальник фсвнг или вс ; лидер армии кто"},{"d":"Устав ВС и ФСВНГ","t":"Статья 4.2. Должностные лица","x":"Лидер Армии осуществляет общее руководство. Заместитель Лидера действует в пределах порученных полномочий. Начальники ВС и ФСВНГ организуют работу подчиненных структур. Командиры подразделений обеспечивают службу и дисциплину личного состава.","r":"ВУ ст. 4.2","k":"кто чем руководит ; должностные лица ; чем занимается начальник фсвнг"},{"d":"Устав ВС и ФСВНГ","t":"Статья 4.3. Подразделения","x":"Военная полиция обеспечивает правопорядок и дисциплину. Медицинская рота оказывает медицинскую помощь. ГРУ, ССО, МСК, ОСБ, РВО, ОМОН, Военная академия и Военный комиссариат выполняют задачи в пределах своей компетенции и приказов командования.","r":"ВУ ст. 4.3","k":"какие есть подразделения ; чем занимается вп ; что такое осб ; рво омон гру ссо кто это ; медрота что делает ; список отделов ; куда пойти после 3 ранга ; какие отделы есть"},{"d":"Устав ВС и ФСВНГ","t":"Статья 4.4. Зоны ответственности","x":"Армия охраняет территорию воинской части, военный комиссариат, полигон “Алабино” и иные объекты, закрепленные приказами командования. Охрана не предоставляет военнослужащим право самостоятельно назначать гражданским лицам наказание. Приложение: полномочия по взысканиям: Командир подразделения вправе объявить устное предупреждение или выговор. Начальник ВС, Начальник ФСВНГ и их заместители вправе объявить строгий выговор и инициировать служебную проверку. Понижение в должности и увольнение рассматриваются Лидером Армии или уполномоченным им должностным лицом по результатам проверки. Полный перечень мер и порядок их применения определяются Дисциплинарным уставом.","r":"ВУ ст. 4.4","k":"что охраняет армия ; могу ли наказать гражданского ; сам назначить штраф гражданскому ; полигон алабино чей ; могу ли объявить выговор ; кто может дать выговор ; сержант может наказать рядового ; кто вправе выносить взыскания ; полномочия по взысканиям ; могу ли я выписать наказание гражданскому ; кто увольняет"},{"d":"Устав ВС и ФСВНГ","t":"Статья 4.4.1. Военный полигон “Алабино”","x":"Военный полигон “Алабино” является учебно-тренировочной и режимной территорией Армии, предназначенной для проведения тактических занятий, учений, тренировок подразделений, отработки действий личного состава, эксплуатации военной техники и иных мероприятий боевой подготовки. На территории полигона “Алабино” допускаются тренировки военнослужащих, передвижение и эксплуатация служебной военной техники, патрулирование и проведение учебных мероприятий при соблюдении требований безопасности, режима объекта и распоряжений командования. Самовольный выезд военной техники за пределы полигона “Алабино”, использование техники не по назначению, создание помех учебным мероприятиям, повреждение имущества или инфраструктуры полигона “Алабино” запрещаются. Порядок охраны полигона “Алабино”, перечень постов и правила патрулирования устанавливаются Уставом караульно-постовой службы.","r":"ВУ ст. 4.4.1","k":"что такое полигон алабино ; зачем полигон ; полигон режимная территория ; можно ли на полигон без брони"},{"d":"Устав ВС и ФСВНГ","t":"Статья 5.1. Субординация","x":"Субординация является системой иерархических отношений, уважения дисциплины и исполнения законных приказов.","r":"ВУ ст. 5.1","k":"что такое субординация ; субординация простыми словами"},{"d":"Устав ВС и ФСВНГ","t":"Статья 5.2. Воинское приветствие","x":"Военнослужащие обязаны соблюдать правила воинского приветствия, доклада и обращения к старшим по званию.","r":"ВУ ст. 5.2","k":"как обращаться к старшему ; воинское приветствие ; надо ли отдавать честь ; как докладывать старшему ; разрешите обратиться ; приветствие старшего по званию"},{"d":"Устав ВС и ФСВНГ","t":"Статья 5.3. Действия в отношении граждан","x":"Военнослужащие вправе пресекать незаконное проникновение на территорию режимного объекта, ограничивать доступ, задерживать лицо при законных основаниях и передавать его ВП, МВД либо иному компетентному органу. Самостоятельное назначение наказания гражданским лицам не допускается.","r":"ВУ ст. 5.3","k":"что я могу делать с гражданским ; могу ли задержать гражданского ; куда девать задержанного ; передать задержанного вп ; кому передать нарушителя ; могу ли сам наказать нарушителя ; гражданский лезет на территорию ; имею ли право задерживать ; могу ли доставить в полицию сам ; права в отношении граждан ; куда везти задержанного ; задержал человека что дальше"},{"d":"Устав ВС и ФСВНГ","t":"Статья 5.4. Применение силы","x":"Сила допускается только при нападении, непосредственной угрозе жизни, попытке незаконного проникновения или законном задержании. После применения силы обязательно: медицинская помощь при необходимости, доклад, фиксация на камеру и рапорт.","r":"ВУ ст. 5.4","k":"когда можно применять силу ; могу ли ударить нарушителя ; на меня напали ; применил силу что дальше ; после применения силы что делать ; можно ли бить задержанного ; нападение на посту ; он сопротивляется ; применение физической силы ; самооборона на посту ; рапорт после применения силы ; меня ударили ; меня душат ; меня бьют ; меня избивают ; меня топят ; на меня напал военнослужащий ; старший по званию применяет ко мне силу ; могу ли защищаться от офицера ; самооборона от сослуживца ; угроза моей жизни что делать ; меня пытаются убить"},{"d":"Устав ВС и ФСВНГ","t":"Статья 6.1. Теги подразделений","x":"В служебной связи используются утвержденные теги подразделений: ВП, МР, ГРУ, ССО, МСК, ВК, ОСБ, РВО, ОМОН и КС. Полковники и выше могут использовать связь без тэга в порядке, установленном командованием.","r":"ВУ ст. 6.1","k":"какие теги в рации ; тег подразделения ; как подписываться в рации ; теги вп мр гру"},{"d":"Устав ВС и ФСВНГ","t":"Статья 6.2. Коды обстановки","x":"Код-1 означает спокойную обстановку; Код-2 - скопление подозрительных лиц или нарушение порядка; Код-3 - проникновение, вооруженное нападение или массовое нарушение; Код-4 - боевую тревогу.","r":"ВУ ст. 6.2","k":"коды обстановки ; код 1 2 3 4 что значат ; какой код при нападении ; код при проникновении ; какой код стрельба ; код спокойная обстановка ; что значит код 2 ; коды по рации ; какой код тревоги"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.1.1. Специальные операции","x":"Основная задача при поставках и специальных операциях - загрузка и доставка груза без утрат и задержек. Запрещены действия, препятствующие безопасности операции.","r":"ВУ ст. 7.1.1","k":"спецоперация что делать ; поставка груза ; сопровождение груза"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.1.2. Реакция на стрельбу","x":"ССО, ГРУ и ОМОН являются основными подразделениями реагирования. При непосредственной угрозе жизни, нападении на пост или проникновении любой военнослужащий действует в пределах необходимой обороны, докладывает по рации и вызывает группу реагирования.","r":"ВУ ст. 7.1.2","k":"стреляют у части ; в меня стреляют ; нападение на пост что делать ; кто реагирует на стрельбу ; вызвать группу реагирования ; необходимая оборона на посту ; перестрелка на кпп ; могу ли стрелять в ответ"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.2. Военное положение","x":"При объявлении военного положения весь состав действует по распоряжениям Лидера Армии и командования, использует боевую форму и занимает назначенные позиции.","r":"ВУ ст. 7.2","k":"военное положение что делать ; объявили военное положение ; боевая форма когда"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.3. Код-3","x":"При объявлении Кода-3 военнослужащий получает обмундирование, докладывает местоположение, направление и приметы нарушителя, а при наличии транспорта - марку, модель, цвет и номер. Подразделения действуют в пределах компетенции и приказов старшего.","r":"ВУ ст. 7.3","k":"код 3 что делать ; объявили код 3 ; что докладывать при коде 3 ; приметы нарушителя доклад ; код 3 порядок действий"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.4. Обязанности постового","x":"Постовой обязан бдительно нести службу, требовать документы, не покидать пост до прибытия смены, немедленно докладывать о нештатной ситуации и применять оружие только в предусмотренных случаях.","r":"ВУ ст. 7.4","k":"обязанности постового ; что должен делать постовой ; могу ли уйти с поста ; смена не пришла ; сколько стоять на посту ; покинуть пост до смены ; что делать на посту ; нештатная ситуация на посту ; когда можно стрелять на посту ; стою уже несколько часов"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.5. Единый порядок инцидента","x":"При обнаружении нарушения военнослужащий докладывает по рации, фиксирует обстоятельства на бодикамеру, ограничивает доступ или пресекает угрозу в пределах полномочий, вызывает ВП или дежурного, передает лицо уполномоченному сотруднику и оформляет рапорт.","r":"ВУ ст. 7.5","k":"увидел нарушение что делать ; порядок действий при инциденте ; нашёл нарушителя ; что делать при происшествии ; вызвать вп или дежурного ; оформить рапорт ; алгоритм при нарушении ; как оформить задержание"},{"d":"Устав ВС и ФСВНГ","t":"Статья 8.1. Отчеты","x":"Отчеты подаются по утвержденной форме. При обнаружении ошибки создается новый отчет в порядке, установленном командованием.","r":"ВУ ст. 8.1","k":"как подать отчёт ; ошибся в отчёте ; форма отчёта ; отчёт не по форме ; переделать отчёт"},{"d":"Устав ВС и ФСВНГ","t":"Статья 8.2. Повышения","x":"Для повышения не должно быть активных дисциплинарных взысканий. Повышение проводится по системе подразделения и по представлению командира, согласованному с вышестоящим командованием.","r":"ВУ ст. 8.2","k":"как повыситься ; условия повышения ; с выговором повысят ; можно ли повыситься с активным выговором ; кто повышает ; представление на повышение"},{"d":"Устав ВС и ФСВНГ","t":"Статья 8.2.5. Повышение военнослужащего на посту","x":"Военнослужащий, несущий службу на посту, проходит процедуру повышения после сдачи поста либо через представителя подразделения.","r":"ВУ ст. 8.2.5","k":"я на посту как повыситься ; повышение во время поста ; сдать пост для повышения"},{"d":"Устав ВС и ФСВНГ","t":"Статья 8.3. Повторный инструктаж","x":"После нарушения правил оружия, КПП, связи или постовой службы военнослужащий до повторного допуска проходит инструктаж или проверку знаний. Инструктаж не заменяет дисциплинарное взыскание, если оно подлежит применению. Приложения:","r":"ВУ ст. 8.3","k":"повторный инструктаж ; после нарушения инструктаж ; проверка знаний после нарушения ; допуск после нарушения"},{"d":"Дисциплинарный устав","t":"Статья 1. Сфера действия и иерархия норм","x":"Настоящий Устав устанавливает основы воинской дисциплины, порядок применения дисциплинарных мер и меры поощрения военнослужащих Вооружённых Сил и сотрудников ФСВНГ.","r":"ДУ ст. 1","k":"что такое дисциплинарный устав ; на кого распространяется ду"},{"d":"Дисциплинарный устав","t":"Статья 2. Воинская дисциплина","x":"Воинская дисциплина основывается на сознательном исполнении обязанностей, соблюдении субординации, уважении к службе и достоинству других лиц, бережном отношении к имуществу и готовности действовать в интересах подразделения. Военнослужащий обязан соблюдать законодательство и уставы, исполнять законные приказы, поддерживать порядок, не допускать действий, подрывающих безопасность службы или авторитет ведомства.","r":"ДУ ст. 2","k":"что такое воинская дисциплина"},{"d":"Дисциплинарный устав","t":"Статья 3. Ответственность командования","x":"Командир организует службу, поддерживает дисциплину, рассматривает сведения о нарушениях в пределах компетенции и принимает меры, соразмерные тяжести проступка. Командиру запрещается унижать подчинённых, применять неуставное физическое или психологическое воздействие, скрывать сведения о серьёзном нарушении либо преследовать военнослужащего за добросовестное обращение.","r":"ДУ ст. 3","k":"командир унижает ; командир орёт и оскорбляет ; что обязан командир ; командир не реагирует на нарушение ; неуставное воздействие командира ; командир бьёт подчинённых ; начальник применяет физическую силу ; командир издевается над подчинёнными ; офицер применяет физическое воздействие ; генерал бьёт солдат ; командиру запрещено унижать"},{"d":"Дисциплинарный устав","t":"Статья 4. Полномочия Военной полиции и ОСБ","x":"Военная полиция выявляет нарушения, самостоятельно рассматривает \\ выносит \\ решает вопросы по привлечению к ответственности военнослужащих, в том числе по вопросам административной, дисциплинарной, уголовной в соответствие с процессуальным законодательством, обеспечивает порядок на военных объектах и передаёт информацию о нарушениях уполномоченным должностным лицам. Военная полиция действует в рамках законодательства и уставов. При выявлении нарушения сотрудником ФСВНГ, включая РВО, Кадровую службу и ОМОН, Военная полиция передаёт материалы и сведения в ОСБ. Самостоятельно дисциплинарные взыскания сотрудникам ФСВНГ Военная полиция не назначает. При выявлении нарушения сотрудником ВС, ОСБ передаёт материалы и сведения в военную полицию. Самостоятельно дисциплинарные взыскания сотрудникам ВС ОСБ не назначает. ОСБ рассматривает полученную информацию, самостоятельно рассматривает \\ выносит \\ решает вопросы по привлечению к ответственности ФСВНГ, в том числе по вопросам административной, дисциплинарной, уголовной в соответствие с процессуальным законодательством, и действует в пределах своей компетенции. Решение о дисциплинарной ответственности принимается уполномоченным должностным лицом после проверки обстоятельств. ОСБ работает по нарушениям только внутри подразделений ФСВНГ.","r":"ДУ ст. 4","k":"кто наказывает фсвнг ; военная полиция может наказать фсвнг ; что такое осб ; кто рассматривает нарушения ; куда жаловаться на нарушение ; вп или осб кто мне выговор даст ; кому сообщить о нарушении ; осб и вп полномочия ; куда обратиться если командир нарушает ; кто проверяет фсвнг ; куда жаловаться на генерала ; пожаловаться на офицера ; старший по званию нарушает кому доложить ; командир избил куда сообщить ; на кого жаловаться если бьёт командир"},{"d":"Дисциплинарный устав","t":"Статья 5. Принципы дисциплинарной ответственности","x":"Взыскание применяется за виновное нарушение и должно быть справедливым, соразмерным его характеру, последствиям, роли лица и обстоятельствам совершения. При назначении взыскания учитываются признание вины, содействие проверке, повторность, степень опасности нарушения и прежнее отношение военнослужащего к службе. За один проступок не может назначаться более одного дисциплинарного взыскания. Дисциплинарное взыскание не заменяет ответственность, установленную законодательством. При выборе меры учитываются тяжесть нарушения, последствия, степень вины, повторность и поведение военнослужащего. Взыскание должно быть адекватным и соразмерным проступку. Если статья предусматривает несколько возможных мер, уполномоченное лицо выбирает одну из них с учётом обстоятельств нарушения.","r":"ДУ ст. 5","k":"как назначают взыскание ; справедливость наказания ; признал вину смягчает ; повторное нарушение строже"},{"d":"Дисциплинарный устав","t":"Статья 6. Виды дисциплинарных взысканий","x":"К военнослужащему или сотруднику, признанному виновным в дисциплинарном проступке, в пределах компетенции могут применяться следующие меры: - беседа (устное предупреждение) - применяется за малозначительное нарушение и не вносится в планшет; - устный выговор - применяется за нарушение средней тяжести и учитывается в планшете как один активный выговор; - строгий выговор - применяется за грубое, повторное либо создавшее угрозу нарушение и учитывается в планшете как два активных выговора; - понижение в должности или звании - только уполномоченным руководителем в порядке, установленном внутренними актами; - увольнение со службы - применяется за наиболее тяжкие нарушения, грубую повторность либо накопление активных выговоров; оформляется уполномоченным руководителем после рассмотрения материалов проверки.","r":"ДУ ст. 6","k":"виды взысканий ; какие бывают выговоры ; беседа это наказание ; что такое строгий выговор ; за что устный выговор ; за что увольняют ; что мне будет за нарушение ; какое наказание за проступок ; понижение в звании за что ; список наказаний ; что грозит за проступок"},{"d":"Дисциплинарный устав","t":"Статья 6.1. Учёт и отработка активных выговоров","x":"Устный выговор учитывается в планшете как один активный выговор. Строгий выговор учитывается в планшете как два активных выговора. Беседа в планшет не вносится. Военнослужащий обязан отработать активный выговор в течение 48 часов с момента его выдачи в порядке, установленном командованием или руководителем подразделения. Если активный выговор не отработан в течение 48 часов, военнослужащему выдаётся дополнительный устный выговор. Если выговор не отработан в течение 96 часов с момента первоначальной выдачи, выдаётся ещё один устный выговор. Накопление трёх активных выговоров в планшете влечёт увольнение со службы. Решение об увольнении оформляется уполномоченным руководителем после проверки актуальности выговоров и обстоятельств их выдачи. Отработанный, снятый либо признанный необоснованным выговор не учитывается при подсчёте активных выговоров. Если медицинское освобождение объективно препятствует установленной форме отработки выговора, военнослужащему предоставляется возможность отработки способом, совместимым с медицинскими ограничениями. При отсутствии доступного совместимого способа течение сроков отработки, включая сроки 48 и 96 часов, приостанавливается на период подтверждённой невозможности отработки. После окончания указанного периода течение оставшегося срока возобновляется. Приостановление и возобновление срока фиксируются уполномоченным должностным лицом. За период приостановления дополнительные взыскания за просрочку не применяются.","r":"ДУ ст. 6.1","k":"сколько выговоров до увольнения ; как отработать выговор ; 48 часов отработка ; строгий выговор сколько активных ; три выговора увольнение ; не отработал выговор ; как снять выговор ; активный выговор что это ; планшет выговоры ; сколько времени на отработку"},{"d":"Дисциплинарный устав","t":"Статья 7. Порядок рассмотрения нарушения","x":"До применения взыскания уполномоченное лицо устанавливает обстоятельства нарушения, проверяет доступные доказательства и, когда это возможно, получает объяснение лица, в отношении которого ведётся проверка. Решение должно содержать существо нарушения, применённую норму и вид взыскания. Лицо вправе обжаловать решение командованию либо в иной предусмотренный проектом орган. Неустранимые сомнения в обстоятельствах проступка толкуются в пользу военнослужащего или сотрудника.","r":"ДУ ст. 7","k":"как рассматривают нарушение ; имею ли право на объяснение ; обжаловать взыскание ; решение по нарушению что должно содержать ; не согласен с выговором"},{"d":"Дисциплинарный устав","t":"Статья 8. Нарушение субординации","x":"Неисполнение законного приказа, неуважительное обращение к командиру или иному старшему по должности, а равно действия, препятствующие исполнению приказа, являются нарушением субординации. Оскорбление, угроза, насилие либо иное грубое воздействие в отношении командира или старшего по должности рассматриваются как грубое нарушение субординации. Возможные меры: устный выговор, строгий выговор или увольнение при угрозе, насилии либо грубой повторности.","r":"ДУ ст. 8","k":"нахамил командиру ; послал старшего ; не выполнил приказ ; нагрубил дежурному ; спор со старшим по званию ; оскорбил командира что будет ; неуважение к старшему ; препятствовал приказу ; конфликт с командиром ; что за неподчинение ; обозвал старшего ; огрызнулся на сержанта"},{"d":"Дисциплинарный устав","t":"Статья 9. Самовольное оставление места службы","x":"Самовольное оставление части, подразделения, места несения службы или самовольное прекращение исполнения служебной задачи без уважительной причины является дисциплинарным проступком. Тяжесть проступка определяется с учётом продолжительности отсутствия, последствий и статуса военнослужащего. Обстоятельства, объективно исключавшие возможность прибыть или продолжить службу, подлежат учёту. Подтверждённая невозможность продолжения службы по состоянию здоровья, экстренное обращение за медицинской помощью или эвакуация подлежат обязательному учёту при рассмотрении обстоятельств отсутствия. Невозможность своевременно доложить о состоянии здоровья сама по себе не образует нарушение, если она была объективно обусловлена состоянием военнослужащего. При первой возможности военнослужащий либо медицинский работник уведомляет командование. Возможные меры: устный выговор, строгий выговор или увольнение при оставлении поста, существенных последствиях либо повторном нарушении.","r":"ДУ ст. 9","k":"ушёл с поста ; самоволка ; бросил пост ; покинул часть без разрешения ; самовольное оставление ; ушёл с патруля ; прекратил задачу без разрешения ; сбежал со службы ; свалил с поста"},{"d":"Дисциплинарный устав","t":"Статья 10. Уклонение от службы и обязательных мероприятий","x":"Неявка без уважительной причины на обязательное построение, занятие, медицинский осмотр, инструктаж, служебное мероприятие или иной обязательный формат службы является дисциплинарным проступком. Уклонением от службы также является намеренное прекращение уже принятого военнослужащим наряда, патруля либо иной служебной задачи без передачи её в установленном порядке. Действующее медицинское освобождение является уважительной причиной неисполнения тех обязанностей и неявки на те мероприятия, на которые распространяются установленные ограничения. Ответственность за неявку на медицинский осмотр применяется при условии, что осмотр назначен уполномоченным лицом, требование доведено до военнослужащего и у него имелась возможность явиться. Несение постовой службы до прибытия смены, получение экстренной помощи и иные подтверждённые обстоятельства, объективно препятствующие явке, учитываются при установлении вины. Возможные меры: беседа, устный выговор, строгий выговор; при грубой повторности или срыве служебной задачи - увольнение.","r":"ДУ ст. 10","k":"опоздал на построение ; не пришёл на построение ; пропустил занятие ; не явился на медосмотр ; прогулял инструктаж ; не пришёл на мероприятие ; неявка на построение что грозит ; уклонение от службы ; бросил наряд ; проспал построение"},{"d":"Дисциплинарный устав","t":"Статья 11. Нарушение порядка несения службы","x":"Ненадлежащее несение караульной, патрульной, внутренней или иной служебной обязанности, если оно создало угрозу безопасности, порядку или имуществу, является дисциплинарным проступком. Самостоятельное заступление на пост или патруль допускается в рамках действующих уставов. Отсутствие индивидуального назначения либо журнала поста не освобождает лицо от ответственности за нарушение фактически принятой им службы. Возможные меры: беседа, устный выговор или строгий выговор; при создании угрозы безопасности, существенном вреде либо грубой повторности - увольнение.","r":"ДУ ст. 11","k":"плохо нёс службу ; халтурил на посту ; заступил на пост сам ; ненадлежащее несение службы ; самостоятельно вышел в патруль ; заснул в патруле"},{"d":"Дисциплинарный устав","t":"Статья 12. Нарушение порядка и общественной безопасности","x":"Действия или бездействие военнослужащего, нарушающие общественный порядок, безопасность военного объекта, установленный режим либо создающие угрозу гражданам, военнослужащим или имуществу, являются дисциплинарным проступком. Возможные меры: беседа, устный выговор или строгий выговор; при серьёзной угрозе безопасности, значимых последствиях либо грубой повторности - увольнение.","r":"ДУ ст. 12","k":"нарушил порядок ; создал угрозу ; хулиганил в части ; нарушение общественного порядка военнослужащим"},{"d":"Дисциплинарный устав","t":"Статья 12.1. Нарушение требований пожарной безопасности","x":"Нарушение требований пожарной безопасности, неосторожное обращение с огнём, создание пожароопасной ситуации, использование источников огня в запрещённой зоне либо игнорирование требований безопасности на складе, в казарме, гараже, технике или ином объекте Армии является дисциплинарным проступком. За нарушение может применяться беседа, устный выговор или строгий выговор. Если нарушение создало реальную угрозу жизни, повлекло ущерб имуществу либо совершено повторно, применяется строгий выговор или увольнение. Курение, использование электронных устройств для курения, кальянов и иных аналогичных средств в помещениях, на посту, на складе, вблизи техники, вооружения, горюче-смазочных материалов либо в иной запрещённой зоне является нарушением требований пожарной безопасности. Возможные меры: беседа, устный выговор или строгий выговор; при реальной угрозе жизни, ущербе имуществу либо повторном нарушении - строгий выговор или увольнение.","r":"ДУ ст. 12.1","k":"курил у склада ; развёл огонь ; пожарная безопасность ; курение в казарме ; огонь в гараже ; костёр на территории"},{"d":"Дисциплинарный устав","t":"Статья 13. Повреждение, утрата и незаконное использование имущества","x":"Умышленные либо небрежные действия, повлекшие утрату, порчу, повреждение или неправомерное использование государственного, ведомственного либо чужого имущества, являются дисциплинарным проступком. Нарушение, содержащее признаки преступления или административного правонарушения, передаётся для рассмотрения в порядке, установленном законодательством. Хищение, присвоение, незаконное удержание либо передача государственного, ведомственного или чужого имущества без законных оснований является грубым дисциплинарным проступком. За такое нарушение применяется строгий выговор или увольнение в зависимости от стоимости имущества, обстоятельств и последствий; при наличии признаков нарушения законодательства материалы передаются уполномоченному органу. Положения настоящей статьи распространяются на медицинские препараты, медицинское имущество и расходные материалы. Нарушение порядка учёта без установленных фактов утраты, присвоения, незаконной передачи или использования имущества не признаётся автоматически хищением либо утратой и оценивается по фактическим обстоятельствам. Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от характера вины, стоимости имущества и наступивших последствий.","r":"ДУ ст. 13","k":"сломал имущество ; украл имущество части ; потерял снаряжение ; взял чужое ; порча имущества наказание ; присвоил вещь ; хищение в части ; нашёл чужое и оставил себе ; утрата имущества ; испортил медикаменты ; нашёл чужой пистолет"},{"d":"Дисциплинарный устав","t":"Статья 14. Оружие, боеприпасы и специальные средства","x":"Нарушение правил хранения, учёта, переноски, передачи или применения оружия, боеприпасов и специальных средств является дисциплинарным проступком. Утеря, порча, оставление без присмотра либо небрежное хранение указанных предметов рассматриваются с учётом создаваемой опасности и наступивших последствий. Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от опасности нарушения, последствий и повторности.","r":"ДУ ст. 14","k":"потерял оружие ; оставил оружие без присмотра ; передал оружие другому ; нарушил правила с оружием ; патроны потерял ; стрелял без причины ; оружие без присмотра наказание ; небрежное хранение оружия"},{"d":"Дисциплинарный устав","t":"Статья 15. Состояние опьянения и запрещённые вещества","x":"Появление на службе в состоянии алкогольного, наркотического или иного опьянения, употребление запрещённых веществ во время службы, а равно необоснованный отказ от освидетельствования в случаях, предусмотренных законодательством, являются дисциплинарными проступками. Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.","r":"ДУ ст. 15","k":"пришёл пьяный на службу ; выпил на службе ; опьянение на посту ; наркотики в части ; отказался от освидетельствования ; пьяный военнослужащий что будет ; бухой на службе ; под кайфом на посту"},{"d":"Дисциплинарный устав","t":"Статья 16. Бездействие командира и незаконное привлечение к ответственности","x":"Умышленное бездействие командира при наличии сведений о существенном нарушении, сокрытие такого нарушения или воспрепятствование его проверке является дисциплинарным проступком. Привлечение военнослужащего к ответственности без оснований, вне компетенции либо с нарушением установленного порядка также является дисциплинарным проступком. Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.","r":"ДУ ст. 16","k":"командир скрыл нарушение ; командир бездействует ; незаконно наказали ; наказали без оснований ; командир покрывает"},{"d":"Дисциплинарный устав","t":"Статья 17. Военная форма и внешний вид","x":"Нарушение правил ношения военной формы, знаков различия, средств индивидуальной защиты и иных обязательных элементов внешнего вида является дисциплинарным проступком, если оно не обусловлено служебной необходимостью. Требования к причёске, растительности на лице и гигиене устанавливаются общим уставом и обязательны в пределах, прямо предусмотренных таким уставом. Возможные меры: беседа, устный выговор или строгий выговор при повторном либо демонстративном нарушении.","r":"ДУ ст. 17","k":"нарушение формы одежды ; без бронежилета ; не та форма что будет ; без знаков различия ; форма не по уставу наказание ; неправильная причёска взыскание ; борода наказание ; без броника"},{"d":"Дисциплинарный устав","t":"Статья 18. Честь ведомства и дискредитация","x":"Публичные действия, высказывания или материалы, содержащие оскорбление ведомства, его символики либо необоснованно подрывающие авторитет Вооружённых Сил или ФСВНГ, являются дисциплинарным проступком. Критика, обращение с жалобой или сообщение о нарушении не образуют проступка, если они сделаны добросовестно и в законной форме. Возможные меры: устный выговор, строгий выговор или увольнение при грубом, публичном либо повторном нарушении.","r":"ДУ ст. 18","k":"оскорбил фсвнг ; выложил видео позорящее армию ; подрыв авторитета ; публично обругал ведомство ; дискредитация ; можно ли жаловаться ; критика командования"},{"d":"Дисциплинарный устав","t":"Статья 19. Служебная информация и документы","x":"Разглашение охраняемой служебной информации, несанкционированный доступ к ней, подделка, уничтожение или неправомерное использование служебных документов являются дисциплинарными проступками. Предоставление заведомо ложных сведений в рапорте, объяснении, отчёте или ином служебном документе рассматривается как самостоятельный проступок. К служебным документам относятся приказы и приказания, директивы, рапорты и доклады, акты и протоколы, справки и удостоверения, медицинские карточки, заключения, направления и документы учёта медицинских препаратов и имущества. Подделка таких документов, оформление фиктивного осмотра или освобождения, внесение заведомо ложных сведений, несанкционированное изменение записей либо разглашение охраняемых медицинских сведений рассматриваются по настоящей статье. Добросовестная техническая ошибка, исправленная в установленном порядке, сама по себе не признаётся подделкой или предоставлением заведомо ложных сведений. Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от характера информации, последствий и повторности.","r":"ДУ ст. 19","k":"слил служебную информацию ; подделал документ ; соврал в рапорте ; ложные сведения в отчёте ; разгласил информацию ; подделка отчёта ; скриншот чужой в отчёте ; фейковый отчёт"},{"d":"Дисциплинарный устав","t":"Статья 20. Злоупотребление полномочиями и конфликт интересов","x":"Использование служебных полномочий, имущества, доступа, транспорта либо специального статуса в личных интересах, а также принятие решения при неурегулированном конфликте интересов являются дисциплинарными проступками. Служебные полномочия не могут использоваться для личной выгоды, давления на граждан или военнослужащих либо обхода установленной процедуры. Использование медицинского осмотра, заключения, освобождения или направления на обследование для личной выгоды, давления, мести либо вмешательства в кадровые решения вне предоставленных полномочий является злоупотреблением. Медицинское освобождение не допускается использовать в качестве дисциплинарного наказания. Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.","r":"ДУ ст. 20","k":"использовал служебную машину для себя ; конфликт интересов ; злоупотребление полномочиями ; взял служебный транспорт по личным делам ; использовал статус в личных целях"},{"d":"Дисциплинарный устав","t":"Статья 21. Поведение в строю и на территории части","x":"Военнослужащий обязан соблюдать порядок на построениях, плацу, в казармах и на территории части, не мешать проведению служебных мероприятий и не создавать опасность другим лицам. Самовольное передвижение бегом по плацу во время проведения построения при наличии сформированного строя запрещается. Исключение составляют случаи исполнения команды или распоряжения командования. Возможные меры: беседа, устный выговор или строгий выговор при повторном нарушении, срыве мероприятия либо создании опасности.","r":"ДУ ст. 21","k":"бегал по плацу ; мешал построению ; порядок на плацу ; поведение в строю ; шумел в казарме ; нарушил порядок на построении ; баловался в строю"},{"d":"Дисциплинарный устав","t":"Статья 22. Символика, ритуалы и азартные игры","x":"Надругательство над государственными или ведомственными символами, срыв установленного воинского ритуала, а также организация или участие в азартных играх в служебное время либо на служебной территории являются дисциплинарными проступками. Возможные меры: устный выговор, строгий выговор или увольнение при грубом, публичном либо повторном нарушении.","r":"ДУ ст. 22","k":"азартные игры в части ; играл в карты на службе ; сорвал ритуал ; надругался над флагом ; казино в части"},{"d":"Дисциплинарный устав","t":"Статья 23. Самоуправство и неуставные взаимоотношения","x":"Принуждение военнослужащего к действиям, не предусмотренным законодательством, уставом или законным приказом, самовольное применение взысканий, а равно унижение, травля или неуставное воздействие на подчинённого являются дисциплинарными проступками. Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.","r":"ДУ ст. 23","k":"сержант заставляет ; неуставные отношения ; дедовщина ; травля ; меня унижает старший ; принуждают к чему-то не по уставу ; самовольно наказал подчинённого ; командир требует деньги ; заставляют делать не по уставу ; издевательства старших ; вымогают деньги за повышение ; командир бьёт ; офицер избивает подчинённого ; старший по званию душит ; генерал издевается ; начальник применяет силу без причины ; дедовщина от офицера ; меня топят старшие ; неуставное физическое воздействие ; старший заставляет унизительное ; офицер применяет насилие ко мне ; что будет командиру за избиение подчинённого"},{"d":"Дисциплинарный устав","t":"Статья 24. Оказание помощи","x":"Неоказание посильной помощи раненому, пострадавшему, военнослужащему, гражданину либо сотруднику, находящемуся в опасном состоянии, когда помощь могла быть оказана без неоправданного риска, является дисциплинарным проступком. Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от опасности ситуации и последствий неоказания помощи.","r":"ДУ ст. 24","k":"не помог раненому ; прошёл мимо пострадавшего ; неоказание помощи ; не помог гражданскому ; обязан ли помогать"},{"d":"Дисциплинарный устав","t":"Статья 25. Заведомо ложное сообщение и клевета","x":"Заведомо ложное сообщение о нарушении, преступлении или происшествии, а равно распространение заведомо недостоверных сведений, порочащих честь и достоинство другого лица, является дисциплинарным проступком. Возможные меры: устный выговор, строгий выговор или увольнение при тяжких последствиях, грубой клевете либо повторном нарушении.","r":"ДУ ст. 25","k":"ложный донос ; наврал про нарушение ; клевета ; оговорил сослуживца ; ложное сообщение о нарушении"},{"d":"Дисциплинарный устав","t":"Статья 26. Воспрепятствование законной деятельности","x":"Неповиновение законным требованиям уполномоченного сотрудника, создание препятствий проверке, служебному мероприятию либо законной деятельности государственного органа является дисциплинарным проступком. Возможные меры: устный выговор, строгий выговор или увольнение при умышленном срыве законной деятельности, угрозе либо грубой повторности.","r":"ДУ ст. 26","k":"не подчинился вп ; мешал проверке ; препятствовал осб ; не выполнил требование проверяющего ; воспрепятствование"},{"d":"Дисциплинарный устав","t":"Статья 27. Халатность","x":"Неисполнение либо ненадлежащее исполнение обязанностей вследствие недобросовестного отношения к службе, если это повлекло или могло повлечь вред безопасности, порядку, имуществу или интересам службы, является дисциплинарным проступком. При оценке исполнения медицинских обязанностей учитываются подготовка работника, предоставленные полномочия, доступность необходимых средств и фактическая возможность оказать помощь. Неблагоприятный результат оказания помощи сам по себе не доказывает халатность. Необходимо установить конкретное нарушение обязанности, вину и предусмотренные настоящей статьёй обстоятельства. Неисполнение командиром доведённых до него действующих медицинских ограничений при наличии возможности обеспечить их соблюдение оценивается по настоящей статье либо иной применимой специальной норме с учётом характера вины и последствий. Возможные меры: беседа, устный выговор, строгий выговор или увольнение в зависимости от возможного либо наступившего вреда.","r":"ДУ ст. 27","k":"халатность ; забыл проверить ; не сделал по недосмотру ; плохо выполнил обязанности ; по невнимательности"},{"d":"Дисциплинарный устав","t":"Статья 28. Связи с преступной деятельностью","x":"Сокрытие достоверно известных сведений о подготовке либо совершении преступления, а также использование служебного положения в интересах преступной деятельности является дисциплинарным проступком и подлежит передаче для рассмотрения по законодательству. Возможные меры: строгий выговор или увольнение. Материалы подлежат передаче для рассмотрения по законодательству.","r":"ДУ ст. 28","k":"знал о преступлении и молчал ; скрыл преступление ; связь с преступниками ; помогал преступникам по службе"},{"d":"Дисциплинарный устав","t":"Статья 29. Режим объекта, связь и транспорт","x":"Нарушение пропускного и внутриобъектового режима, правил служебной связи или использования служебного транспорта является дисциплинарным проступком. Ведение отдельного журнала поста или назначение военнослужащего на пост не являются обязательными условиями для признания нарушения. Значимые инциденты фиксируются служебным сообщением, рапортом либо иным установленным способом. Использование личного транспорта на территории воинской части допускается только по маршрутам и через пункты пропуска, прямо определённые действующим караульным уставом или распоряжением командования. Возможные меры: беседа, устный выговор или строгий выговор; при создании угрозы безопасности, существенных последствиях либо грубой повторности - увольнение.","r":"ДУ ст. 29","k":"нарушил пропускной режим ; пропустил без документов ; нарушил правила рации ; служебный транспорт нарушение ; пустил чужого на территорию ; нарушение режима объекта ; мат в рации ; неправильно использовал рацию ; что будет если пропущу без проверки"},{"d":"Дисциплинарный устав","t":"Статья 30. Иные нарушения","x":"Нарушение обязанностей, прямо установленных законодательством, настоящим Уставом, иными уставами или законным приказом, может являться дисциплинарным проступком при наличии вины и доказанных обстоятельств. Общая формулировка настоящей статьи не применяется для обхода специальных норм Устава или назначения взыскания за поведение, которое не было заранее запрещено либо не нарушило законную обязанность. Возможные меры: беседа, устный выговор или строгий выговор в пределах нарушенной конкретной нормы. Увольнение не может назначаться только на основании настоящей статьи.","r":"ДУ ст. 30","k":"иные нарушения ; нарушение приказа наказание"},{"d":"Дисциплинарный устав","t":"Статья 31. Основания для поощрения","x":"Поощрение применяется за добросовестную службу, инициативу, образцовое исполнение обязанностей, успешное выполнение сложной задачи, помощь подразделению, дисциплинированность и иные заслуги перед ведомством.","r":"ДУ ст. 31","k":"за что поощряют ; как получить благодарность ; поощрение за что"},{"d":"Дисциплинарный устав","t":"Статья 32. Виды поощрений","x":"В пределах компетенции могут применяться следующие меры поощрения: - снятие ранее наложенного дисциплинарного взыскания; - объявление благодарности; - награждение ценным подарком либо денежной премией в порядке, установленном проектом; - досрочное присвоение очередного звания или представление к повышению; - занесение в книгу почёта либо иную форму публичного признания заслуг.","r":"ДУ ст. 32","k":"виды поощрений ; как снять выговор поощрением ; премия за службу ; досрочное звание ; благодарность что даёт ; какие бывают награды"},{"d":"Дисциплинарный устав","t":"Статья 33. Порядок применения поощрений","x":"Поощрение объявляется уполномоченным должностным лицом и должно быть обосновано конкретными заслугами военнослужащего или сотрудника. Поощрение не освобождает от ответственности за совершённые нарушения.","r":"ДУ ст. 33","k":"кто объявляет поощрение ; поощрение освобождает от наказания"},{"d":"Дисциплинарный устав","t":"Статья 34. Применение Устава","x":"Настоящий Устав применяется совместно с общим уставом Вооружённых Сил, уставом караульно-постовой службы и действующим законодательством проекта. Положения Устава подлежат периодическому пересмотру командованием при изменении законодательства, структуры ведомств или игровых механик. Изменения не могут ухудшать положение лица задним числом.","r":"ДУ ст. 34","k":"как применяется ду ; ду и укпс вместе"},{"d":"Дисциплинарный устав","t":"Статья 35. Толкование","x":"Официальное толкование положений настоящего Устава осуществляется уполномоченным руководством проекта в соответствии с законодательством. При наличии пробела применяется наиболее близкая по смыслу норма с соблюдением принципов справедливости, соразмерности и презумпции добросовестности.","r":"ДУ ст. 35","k":"кто толкует устав ; пробел в уставе"},{"d":"Устав караульно-постовой службы","t":"Статья 1","x":"Настоящий Устав определяет предназначение, порядок организации и несения караульной службы, права и обязанности военнослужащих, несущих караульную службу, а также для регламентирует порядок несения постовой службы военнослужащих ВС РФ, а так же ФСВНГ.","r":"УКПС ст. 1","k":"что такое укпс ; устав караульно-постовой службы о чём ; укпс расшифровка"},{"d":"Устав караульно-постовой службы","t":"Статья 2","x":"Настоящим Уставом руководствуются все военнослужащие органов военного управления, воинских частей, органов военной полиции,федеральной службы войск национальной гвардии и лица гражданского персонала Вооруженных Сил Российской Федерации, замещающие воинские должности.","r":"УКПС ст. 2","k":"на кого распространяется укпс ; укпс для фсвнг"},{"d":"Устав караульно-постовой службы","t":"Статья 3","x":"Караульная служба предназначена для надежной охраны и обороны боевых знамен, хранилищ (складов) с вооружением, военной техникой, другим военным имуществом, объектов Вооруженных Сил Российской Федерации и иных военных и государственных объектов, а также для охраны военнослужащих, содержащихся на гауптвахте и в дисциплинарной части.","r":"УКПС ст. 3","k":"зачем караульная служба ; что охраняет караул ; назначение караула"},{"d":"Устав караульно-постовой службы","t":"Статья 4","x":"Руководство караульной службой внутренних караулов воинский частей осуществляют командиры этих частей и их прямые начальники.","r":"УКПС ст. 4","k":"кто руководит караулом"},{"d":"Устав караульно-постовой службы","t":"Статья 5","x":"Приказы и распоряжения Министра обороны командующих территориальными воинскими формированиями по организации и несению караульной службы обязательным для выполнения подведомственными воинскими формированиями, их военнослужащими и иными должностными лицами, входящими в состав конкретного субъекта.","r":"УКПС ст. 5","k":"приказы по караулу обязательны"},{"d":"Устав караульно-постовой службы","t":"Статья 6","x":"Командующие воинскими формированиями обязаны периодически проверять качество несения караульной службы на подведомственных субъектах.","r":"УКПС ст. 6","k":"проверка караула командующим"},{"d":"Устав караульно-постовой службы","t":"Статья 7","x":"При расположении войск в полевых условиях мероприятия по поддержанию воинской дисциплины, охране субъектов воинских частей и военных объектов проводятся в соответствии с Уставами воинских формирований Вооруженных Сил Российской Федерации и настоящим Уставом.","r":"УКПС ст. 7","k":"полевые условия караул"},{"d":"Устав караульно-постовой службы","t":"Статья 8","x":"Непосредственное выполнение задач караульной службы осуществляется подразделениями воинских частей, отделом собственной безопасности а также военной комендатурой в пределах компетенции, определенной настоящим Уставом и Уставами конкретных воинских формирований.","r":"УКПС ст. 8","k":"кто несёт караульную службу ; осб и комендатура в карауле"},{"d":"Устав караульно-постовой службы","t":"Статья 9","x":"Каждый военнослужащий обязан оказывать требуемую помощь лицам, несущим караульную службу.","r":"УКПС ст. 9","k":"обязан помогать караулу ; помощь караулу"},{"d":"Устав караульно-постовой службы","t":"Статья 10","x":"Каждый военнослужащий обязан знать в лицо своего командира или зам командира","r":"УКПС ст. 10","k":"знать командира в лицо ; должен ли знать командира"},{"d":"Устав караульно-постовой службы","t":"Статья 11","x":"Военнослужащий, заметив нарушение правил несения службы кем-либо из состава наряда, караула, обязан немедленно сообщить об этом дежурному по части, в орган военной полиции или отдел собственной безопасности и доложить непосредственному командиру (начальнику).","r":"УКПС ст. 11","k":"увидел что постовой нарушает ; сослуживец спит на посту куда сообщить ; нарушение в карауле кому доложить ; заметил нарушение наряда ; напарник нарушает на посту"},{"d":"Устав караульно-постовой службы","t":"Статья 12","x":"Начальником караульной службы является командир части либо назначенное приказом должностное лицо.","r":"УКПС ст. 12","k":"кто начальник караула"},{"d":"Устав караульно-постовой службы","t":"Статья 13","x":"К постоянным караулам относятся караулы, перечень которых определяется настоящим Уставом и караульная служба на которых осуществляется непрерывно без необходимости оформления сопроводительных документов или письменных и(или) устных распоряжений на организацию и осуществление караулов.","r":"УКПС ст. 13","k":"постоянные караулы ; что такое постоянный караул"},{"d":"Устав караульно-постовой службы","t":"Статья 14","x":"Временные караулы создаются приказами командиров воинских частей (формирований) либо приказом (указом) Министра обороны Российской Федерации, Премьер-министра и иными должностными лицами, которым предоставлено такое право в соответствии с действующим законодательством Российской Федерации.","r":"УКПС ст. 14","k":"временный караул ; кто создаёт временные караулы"},{"d":"Устав караульно-постовой службы","t":"Статья 15","x":"Перечень постоянных караулов на территории Московской области: воинская часть ; территориальные военные объекты материального снабжения, склады с вооружением, стоянки военной техники, объекты стратегического (военного) значения; военный комиссариат Московской области, пункты отборы; государственные объекты материального снабжения.","r":"УКПС ст. 15","k":"список постоянных караулов ; какие объекты охраняются ; перечень караулов московской области"},{"d":"Устав караульно-постовой службы","t":"Статья 16","x":"Порядок несения караульной службы, перечень постов в караулах и порядок посещения указанных в статье 13 территорий, определяется настоящим Уставом.","r":"УКПС ст. 16","k":"порядок караульной службы где определён"},{"d":"Устав караульно-постовой службы","t":"Статья 17","x":"Порядок несения караульной службы и перечень постов в караулах на объектах материального снабжения и объекта стратегического значения защищен Федеральным законом \"О государственной тайне\" и устанавливается исключительно приказами командиров (начальников) воинских формирований в соответствии с подведомственностью.","r":"УКПС ст. 17","k":"гостайна караул ; посты на секретных объектах"},{"d":"Устав караульно-постовой службы","t":"Статья 18","x":"Каждый из перечисленных в статье 13 настоящего Устава объект охраняется Вооруженными Силами Российской Федерации. 18.1 Военные склады материального снабжения, склады с вооружением, стоянки военной техники, объекты стратегического (военного) значения, территории воинских частей являются закрытыми для свободного посещения и нахождения. Порядок прохода и пребывания на указанных территориях определяется Федеральным законом \"О государственной собственности, закрытых и охраняемых территориях\" и Федеральным законом \"О Вооруженных Силах Российской Федерации\" . 18.2 Нахождение на иных территориях, не перечисленных в части 1 статьи 16 настоящего Устава, не ограничивается при соблюдении установленных правил поведения, за исключением обстоятельств, определяемых действующим законодательством. Раздел 3. Постовая служба в караулах","r":"УКПС ст. 18","k":"кто охраняет объекты ; охрана складов"},{"d":"Устав караульно-постовой службы","t":"Статья 19","x":"Заступить на постовую службу в караулах может любой военнослужащих со звания Рядовой","r":"УКПС ст. 19","k":"с какого звания можно на пост ; рядовой может заступить на пост ; кто может стоять на посту ; могу ли я стоять на кпп рядовым ; кадет на пост"},{"d":"Устав караульно-постовой службы","t":"Статья 20","x":"Перечень постов в каждом из постоянных караулов определяется настоящим Уставом, может дополняться и корректироваться в связи с определенными обстоятельствами приказами командиров воинских частей (формирований), Министра обороны Российской Федерации.","r":"УКПС ст. 20","k":"перечень постов кто определяет"},{"d":"Устав караульно-постовой службы","t":"Статья 21","x":"Перечень постов во временно организуемых караулах определяется соответствующим приказом (указом) командиров (начальников), Министра обороны Российской Федерации, Премьер-министра, иных должностных лиц в пределах компетенции.","r":"УКПС ст. 21","k":"посты во временных караулах"},{"d":"Устав караульно-постовой службы","t":"Статья 22","x":"Перечень постов в карауле на территории воинской части: контрольно-пропускной пункт №1 (главный КПП); контрольно-пропускной пункт №2 (запасной КПП); вышки №1 - №8 по периметру воинской части; главный склад; военный полигон.","r":"УКПС ст. 22","k":"какие посты в части ; список постов вч ; вышки по периметру ; где стоять посты ; главный склад пост ; кпп 1 и кпп 2 какие ; сколько постов в части"},{"d":"Устав караульно-постовой службы","t":"Статья 22.1","x":"На территории военного полигона “Алабино” устанавливаются три постоянных поста: - контрольно-пропускной пункт №1; - контрольно-пропускной пункт №2; - наблюдательная вышка. Оба КПП являются основными пунктами прохода, въезда и выезда на и с территории полигона. Наблюдательная вышка предназначена для визуального контроля территории, выявления нарушений режима, незаконного проникновения, происшествий и своевременного доклада по средствам связи. Дежурство на постах несут военнослужащие мотострелкового корпуса и роты вневедомственной охраны","r":"УКПС ст. 22.1","k":"посты на алабино ; какие посты на полигоне ; кпп полигона ; вышка на полигоне ; куда заступить на алабино"},{"d":"Устав караульно-постовой службы","t":"Статья 22.2","x":"На территории военного полигона “Алабино” допускается пешее и автомобильное патрулирование. Патрулирование может осуществляться военнослужащими, самостоятельно заступившими на патрульную службу, либо военнослужащими, действующими по распоряжению командования. Отдельное назначение на патруль не является обязательным условием его несения. Патруль обязан контролировать режим территории, выявлять незаконное проникновение, обеспечивать безопасность вблизи зон проведения учений и тренировок, не препятствовать учебным мероприятиям и докладывать о выявленных нарушениях по рации.","r":"УКПС ст. 22.2","k":"патруль на полигоне ; можно ли патрулировать алабино ; патрулирование пешком или на машине ; самостоятельно в патруль на полигоне"},{"d":"Устав караульно-постовой службы","t":"Статья 23","x":"Перечень постов в карауле на территории военного комиссариата, пунктов отбора: главный вход; призывной кабинет; дежурный пост.","r":"УКПС ст. 23","k":"посты в военкомате ; военный комиссариат посты ; призывной кабинет пост"},{"d":"Устав караульно-постовой службы","t":"Статья 24","x":"Численность военнослужащих одновременно несущих караульно-постовую службу на территории воинской части устанавливается внутренними актами и должностными регламентами","r":"УКПС ст. 24","k":"сколько человек на посту ; численность караула"},{"d":"Устав караульно-постовой службы","t":"Статья 25","x":"Старший наряда назначается приказом. Старшинство по званию применяется только при отсутствии назначенного старшего наряда.","r":"УКПС ст. 25","k":"кто старший в наряде ; старший наряда как назначается ; кто главный на посту если нет старшего ; старшинство по званию на посту ; напарник старше по званию командует"},{"d":"Устав караульно-постовой службы","t":"Статья 26","x":"При приеме и сдаче поста проверяются оружие, средства связи, состояние охраняемого объекта, наличие происшествий и замечаний. Смена фиксируется докладом в рацию.","r":"УКПС ст. 26","k":"как принять пост ; как сдать пост ; что проверять при приёме поста ; смена поста доклад ; сдача поста порядок ; заступил на пост что докладывать ; пересменка на посту"},{"d":"Устав караульно-постовой службы","t":"Статья 26.1. Ухудшение состояния здоровья постового","x":"При ухудшении состояния здоровья постовой незамедлительно докладывает дежурному либо старшему наряда и запрашивает медицинскую помощь. Для прохождения планового медицинского осмотра постовой сдаёт пост сменяющему военнослужащему в порядке статьи 26 настоящего Устава. Самостоятельный уход с поста для планового осмотра до сдачи поста не допускается. Если состояние здоровья исключает безопасное продолжение службы либо требуется экстренная помощь, медицинская помощь оказывается безотлагательно. Дежурный либо старший наряда организует замену и обеспечивает непрерывность охраны объекта. При невозможности постового самостоятельно доложить о своём состоянии доклад осуществляет обнаруживший его военнослужащий либо медицинский работник. Военнослужащий с действующими медицинскими ограничениями не допускается к постовой службе, если её условия несовместимы с указанными ограничениями. Доклад и передача поста осуществляются по служебной связи. Ведение отдельного журнала поста для этого не требуется.","r":"УКПС ст. 26.1","k":"плохо себя чувствую на посту ; заболел на посту ; нужно к медику с поста ; ухудшилось здоровье на посту ; могу ли уйти с поста к врачу ; медосмотр во время поста ; сдать пост по болезни ; ранен на посту ; стало плохо на кпп ; медицинские ограничения пост ; отойти с поста"},{"d":"Устав караульно-постовой службы","t":"Статья 27","x":"Бодикамера обязательна для сотрудников ВП, ОСБ, военнослужащих на КПП, патрулей и лиц, проводящих задержание. При неисправности камеры военнослужащий докладывает старшему.","r":"УКПС ст. 27","k":"нужна ли бодикамера на кпп ; бодикамера на посту ; камера сломалась на посту ; обязательна ли камера в патруле ; бодикамера при задержании"},{"d":"Устав караульно-постовой службы","t":"Статья 28","x":"При заступлении на пост, каждый военнослужащий обязан предварительно провести проверку табельного оружия и средств радиосвязи на предмет их исправности. При обнаружении неисправности в работе, принять меры по устранению поломки либо заменить на исправные. Постовой или патрульный не вправе использовать полученное для службы оружие в личных целях, передавать его другим лицам либо покидать с ним территорию части без служебной необходимости.","r":"УКПС ст. 28","k":"что проверить перед постом ; проверка оружия перед заступлением ; рация не работает на посту ; неисправное оружие на посту ; могу ли взять оружие с поста домой ; оружие в личных целях ; унёс оружие с поста"},{"d":"Устав караульно-постовой службы","t":"Статья 29","x":"При несении постовой службы запрещается: терять концентрацию, отвлекаться на телефон и иные электронные средства, на разговоры; оставлять вооружение без контроля, снимать его с плеча без необходимости привести его в боевую готовность; нарушать действующее законодательство, особенно в области этики; игнорировать запросы о состоянии поста в рацию; своевременно не докладывать о состоянии поста; нарушать требования настоящего Устава в области организации пропуска на территорию и с территории объекта; бездействовать при совершении преступлений и(или) правонарушений на подведомственных территориях; бездействовать при просьбе оказания помощи гражданам и сотрудникам в пределах компетенции. Военнослужащим во время несения постовой службы на любом посту запрещается танцевать и совершать иные действия, не связанные с исполнением служебных обязанностей. Разрешено совершать действия, непосредственно необходимые для выполнения уставных предписаний, применения разрешённого снаряжения или оказания медицинской помощи.","r":"УКПС ст. 29","k":"что запрещено на посту ; телефон на посту ; можно ли разговаривать на посту ; снимать оружие с плеча ; оружие в руках на посту ; держать автомат наизготовку ; игнорировать рацию ; не доложил о состоянии поста ; танцевать на посту ; бездействие при нарушении ; отвлекаться на посту ; залипать в телефон на посту ; сидеть в дискорде на посту ; можно ли на посту помочь гражданскому ; болтать с напарником на посту"},{"d":"Устав караульно-постовой службы","t":"Статья 30","x":"Обязанности военнослужащих, несущих постовую службу на КПП №1: постовой проверяет документы водителя, номер автомобиля, цель въезда и наличие записи в журнале транспортных средств. При отказе от предусмотренной проверки въезд не допускается. Постовой также проверяет документы прибывающих лиц, докладывает о нарушениях, пресекает незаконное проникновение в пределах полномочий и своевременно докладывает о состоянии поста. Полковники и выше проходят без оформления увольнительной, но предъявляют служебное удостоверение. При покидании воинской части на личном транспорте или без установленной формы одежды, независимо от занимаемой должности, военнослужащий обязан предъявить удостоверение постовому и не препятствовать осмотру багажника транспортного средства (( постовой вправе через отыгровку типа “/do Есть ли в машине @dynamicID запрещенные или нелегальные средства?”, игнорирование вопроса или заведомо ложный ответ наказывается по 5.9 ОПП )). Постовой вправе проводить досмотр военнослужащих, гражданских лиц, ручной клади и транспортных средств при въезде или выезде с территории воинской части в целях соблюдения пропускного режима, выявления запрещенных предметов и проверки законности ношения оружия, боеприпасов и специальных средств. Военнослужащий, покидающий часть в гражданской форме, обязан по требованию постового подтвердить сдачу оружия, боеприпасов и специальных средств в порядке, установленном внутренним уставом (статья 3.4.2 ВУ). При выявлении оружия, боеприпасов или специальных средств у лица, которое обязано было их сдать, постовой не допускает дальнейший выход с…","r":"УКПС ст. 30","k":"обязанности на кпп 1 ; что делать на кпп ; водитель не показывает документы ; машина без пропуска ; проверка документов на кпп ; журнал транспортных средств ; полковник без удостоверения ; могу ли досматривать машину ; досмотр багажника ; отказался от проверки на кпп ; гражданский рвётся на территорию ; как проверять въезжающих ; осмотр машины отыгровка ; человек без документов на кпп ; не пускать без документов ; порядок на главном кпп ; выезд в гражданке подтвердить сдачу оружия ; водитель не выходит из машины ; чел быкует на кпп ; досмотр без задержания ; могу ли обыскать на кпп ; досмотр на кпп когда ; обыскать гражданского при въезде ; проверить сумку на кпп ; досмотреть ручную кладь"},{"d":"Устав караульно-постовой службы","t":"Статья 31","x":"Военнослужащие со звания генерал-лейтенант включительно освобождаются от проверок при пересечении любого из КПП, постовые обязаны знать их в лицо.","r":"УКПС ст. 31","k":"генерал на кпп ; кого не проверять на кпп ; генерал-лейтенант без проверки ; кто проходит без проверки ; знать в лицо генералов"},{"d":"Устав караульно-постовой службы","t":"Статья 32","x":"КПП №2 является резервно-служебным. Он используется для колонн снабжения, призывных колонн, служебного транспорта, патрулей и правительственных кортежей только при закрытии КПП №1 либо по отдельному приказу командования.","r":"УКПС ст. 32","k":"кпп 2 когда используется ; запасной кпп зачем ; колонна через кпп 2 ; кортеж через какой кпп ; закрыт кпп 1"},{"d":"Устав караульно-постовой службы","t":"Статья 33","x":"Обязанности военнослужащих на КПП №2 аналогичны обязанностям на КПП №1 и выполняются только в период законного использования КПП №2.","r":"УКПС ст. 33","k":"обязанности на кпп 2 ; что делать на втором кпп ; стою на кпп 2"},{"d":"Устав караульно-постовой службы","t":"Статья 34","x":"На территорию воинской части запрещается въезд на личных транспортных средствах, не зарегистрированных в установленном порядке в журнале транспортных средств. Регистрацию автомобиля санкционируют командиры ВП и ОСБ в пределах полномочий.","r":"УКПС ст. 34","k":"можно ли заехать на личной машине ; личный транспорт в части ; регистрация машины в журнале ; кто регистрирует автомобиль ; заехать на своей тачке ; личное авто на территории ; незарегистрированная машина въезд"},{"d":"Устав караульно-постовой службы","t":"Статья 34.2","x":"Въезд личного транспорта военнослужащих и гражданских лиц допускается исключительно через КПП №1. КПП №2 не используется для въезда личного транспорта.","r":"УКПС ст. 34.2","k":"через какой кпп заезжать на личной ; личная машина через кпп 2 ; въезд личного транспорта"},{"d":"Устав караульно-постовой службы","t":"Статья 34.3","x":"Личный транспорт допускается при наличии записи в журнале транспортных средств и подтвержденной цели въезда.","r":"УКПС ст. 34.3","k":"условия въезда личной машины ; запись в журнале и цель въезда"},{"d":"Устав караульно-постовой службы","t":"Статья 34.4","x":"После въезда личный транспорт следует по утвержденному маршруту на выделенную парковочную зону. Сквозной проезд по территории части, остановка у штаба, складов, казарм, автопарка, постов и иных режимных объектов запрещены.","r":"УКПС ст. 34.4","k":"где парковаться в части ; можно ли проехать через часть ; сквозной проезд ; остановился у штаба на машине ; парковка в части ; маршрут для личного транспорта ; куда ставить машину"},{"d":"Устав караульно-постовой службы","t":"Статья 34.5","x":"Выезд личного транспорта производится через КПП №1. Допуск автомобиля может быть приостановлен или отменен при отсутствии транспортного средства в журнале.","r":"УКПС ст. 34.5","k":"выезд на личной машине ; через какой кпп выезжать ; машины нет в журнале выезд ; отменили допуск машины"},{"d":"Устав караульно-постовой службы","t":"Статья 35","x":"Разовые пропуска на территорию части уполномочены оформлять командиры военной полиции и руководство вооруженных сил.","r":"УКПС ст. 35","k":"кто выдаёт разовый пропуск ; разовый пропуск как оформить ; пропуск на территорию гражданскому ; кто может оформить пропуск ; временный пропуск"},{"d":"Устав караульно-постовой службы","t":"Статья 36","x":"Военнослужащим несущим постовую службу на контрольно-пропускном пункте №1 и контрольно-пропускном пункте № 2 запрещается : 1. Спать, сидеть и прислоняться к чему-либо. 2. Читать, писать, петь. 3. Есть, пить и курить. 4. Принимать от кого-либо или передавать кому-либо предметы, не связанные с исполнением служебных обязанностей. Запрет не распространяется на установленную передачу служебного имущества, получение разрешённых средств первой помощи и действия, необходимые для оказания медицинской помощи. 5. Справлять естественные надобности на посту. 6. Досылать патрон в патронник без необходимости, как и доставать оружие без необходимости. 7. Использовать средства личной связи. 8. Танцевать или совершать иные действия, не связанные с несением постовой службы.","r":"УКПС ст. 36","k":"что запрещено на кпп ; можно ли сидеть на посту ; можно ли курить на кпп ; спать на посту ; прислоняться к стене на кпп ; есть на посту ; пить воду на кпп ; читать на посту ; петь на посту ; передать предмет через кпп ; взять что-то у гражданского на кпп ; справить нужду на посту ; туалет на посту ; досылать патрон ; доставать оружие без нужды ; телефон на кпп ; личная связь на кпп ; танцевать на кпп ; сесть на стул на кпп ; залипать в телефон на кпп ; принять посылку на кпп ; перекусить на посту ; сон на посту"},{"d":"Устав караульно-постовой службы","t":"Статья 37","x":"Режимным объектом является территория внутри периметра части, доступ к которой осуществляется через КПП №1 и КПП №2. Территория с внешней стороны КПП режимным объектом не является. За пределами режимного объекта военнослужащие действуют в пределах закона и при необходимости вызывают компетентные органы.","r":"УКПС ст. 37","k":"что такое режимный объект ; где заканчивается территория части ; за кпп это территория части ; могу ли задерживать за территорией ; за пределами кпп что могу ; снаружи кпп режимный объект ; полномочия за территорией части ; арест за пределами части ; территория снаружи кпп"},{"d":"Уголовный кодекс РО","t":"Статья 1. Уголовное законодательство РО","x":"1. Уголовное законодательство РО состоит из настоящего Кодекса. Новые законы, предусматривающие уголовную ответственность, подлежат включению в настоящий Кодекс. 2. Настоящий кодекс основывается на Конституции РО и общепризнанных принципах и нормах международного права.","r":"УК ст. 1"},{"d":"Уголовный кодекс РО","t":"Статья 2. Задачи Уголовного кодекса РО","x":"1. Задачами настоящего Кодекса являются: охрана прав и свобод человека и гражданина, собственности, общественного порядка и общественной безопасности, окружающей среды, конституционного строя РО от преступных посягательств, обеспечение мира и безопасности человечества, а также предупреждение преступлений. 2. Для осуществления этих задач настоящий Кодекс устанавливает основание и принципы уголовной ответственности, определяет, какие опасные для личности, общества или государства деяния признаются преступлениями, и устанавливает виды наказаний и иные меры уголовно-правового характера за совершение преступлений.","r":"УК ст. 2"},{"d":"Уголовный кодекс РО","t":"Статья 3. Принцип законности","x":"1. Преступность деяния, а также его наказуемость и иные уголовно-правовые последствия определяются только настоящим Кодексом. 2. Применение уголовного закона по аналогии не допускается.","r":"УК ст. 3"},{"d":"Уголовный кодекс РО","t":"Статья 4. Принцип равенства граждан перед законом","x":"Лица, совершившие преступления, равны перед законом и подлежат уголовной ответственности независимо от пола, расы, национальности, языка, происхождения, имущественного и должностного положения, места жительства, отношения к религии, убеждений, принадлежности к общественным объединениям, а также других обстоятельств.","r":"УК ст. 4"},{"d":"Уголовный кодекс РО","t":"Статья 5. Принцип вины","x":"1. Лицо подлежит уголовной ответственности только за те общественно опасные действия (бездействие) и наступившие общественно опасные последствия, в отношении которых установлена его вина. 2. Объективное вменение, то есть уголовная ответственность за невиновное причинение вреда, не допускается.","r":"УК ст. 5"},{"d":"Уголовный кодекс РО","t":"Статья 6. Принцип справедливости","x":"1. Наказание и иные меры уголовно-правового характера, применяемые к лицу, совершившему преступление, должны быть справедливыми, то есть соответствовать характеру и степени общественной опасности преступления, обстоятельствам его совершения и личности виновного. 2. Никто не может нести уголовную ответственность дважды за одно и то же преступление.","r":"УК ст. 6"},{"d":"Уголовный кодекс РО","t":"Статья 7. Принцип гуманизма","x":"1. Уголовное законодательство РО обеспечивает безопасность человека. 2. Наказание и иные меры уголовно-правового характера, применяемые к лицу, совершившему преступление, не могут иметь своей целью причинение физических страданий или унижение человеческого достоинства.","r":"УК ст. 7"},{"d":"Уголовный кодекс РО","t":"Статья 8. Основание уголовной ответственности","x":"Основанием уголовной ответственности является совершение деяния, содержащего все признаки состава преступления, предусмотренного настоящим Кодексом.","r":"УК ст. 8"},{"d":"Уголовный кодекс РО","t":"Статья 9. Действие уголовного закона во времени","x":"1. Преступность и наказуемость деяния определяются уголовным законом, действовавшим во время совершения этого деяния. 2. Временем совершения преступления признается время совершения общественно опасного действия (бездействия) независимо от времени наступления последствий. 3. Уголовный закон, устраняющий преступность деяния, смягчающий наказание или иным образом улучшающий положение лица, совершившего преступление, имеет обратную силу, то есть распространяется на лиц, совершивших соответствующие деяния до вступления такого закона в силу, в том числе на лиц, отбывающих наказание или отбывших наказание, но имеющих судимость. Уголовный закон, устанавливающий преступность деяния, усиливающий наказание или иным образом ухудшающий положение лица, обратной силы не имеет.","r":"УК ст. 9"},{"d":"Уголовный кодекс РО","t":"Статья 10. Понятие преступления","x":"1. Преступлением признается виновно совершенное общественно опасное деяние, запрещенное настоящим Кодексом под угрозой наказания. 2. Не является преступлением деяние, хотя формально и содержащее признаки какого-либо деяния, предусмотренного настоящим Кодексом, но в силу малозначительности не представляющее общественной опасности.","r":"УК ст. 10"},{"d":"Уголовный кодекс РО","t":"Статья 11. Категории преступлений","x":"1. В зависимости от характера и степени общественной опасности деяния, предусмотренные настоящим Кодексом, подразделяются на преступления небольшой тяжести, преступления средней тяжести, тяжкие преступления и особо тяжкие преступления. 2. Преступлениями небольшой тяжести признаются умышленные и неосторожные деяния, за совершение которых максимальное наказание, предусмотренное настоящим Кодексом, не превышает 20 месяцев лишения свободы. 3. Преступлениями средней тяжести признаются умышленные деяния, за совершение которых максимальное наказание, предусмотренное настоящим Кодексом, не превышает 30 месяцев лишения свободы, и неосторожные деяния, за совершение которых максимальное наказание, предусмотренное настоящим Кодексом, не превышает 35 месяцев лишения свободы. 4. Тяжкими преступлениями признаются умышленные деяния, за совершение которых максимальное наказание, предусмотренное настоящим Кодексом, не превышает 40 месяцев лишения свободы, и неосторожные деяния, за совершение которых максимальное наказание, предусмотренное настоящим Кодексом, не превышает 45 месяцев лишения свободы. 5. Особо тяжкими преступлениями признаются умышленные деяния, за совершение которых настоящим Кодексом предусмотрено наказание в виде лишения свободы на срок свыше 40 месяцев или более строгое наказание.","r":"УК ст. 11"},{"d":"Уголовный кодекс РО","t":"Статья 12. Совокупность преступлений","x":"1. Совокупностью преступлений признается совершение двух или более преступлений, ни за одно из которых лицо не было осуждено, за исключением случаев, когда совершение двух или более преступлений предусмотрено статьями Особенной части настоящего Кодекса в качестве обстоятельства, влекущего более строгое наказание. При совокупности преступлений лицо несет уголовную ответственность за каждое совершенное преступление по соответствующей статье или части статьи настоящего Кодекса. 2. Совокупностью преступлений признается и одно действие (бездействие), содержащее признаки преступлений, предусмотренных двумя или более статьями настоящего Кодекса. 3. Если преступление предусмотрено общей и специальной нормами, совокупность преступлений отсутствует и уголовная ответственность наступает по специальной норме.","r":"УК ст. 12"},{"d":"Уголовный кодекс РО","t":"Статья 13. Рецидив преступлений","x":"Рецидивом преступлений признается совершение умышленного преступления лицом, имеющим судимость за ранее совершенное умышленное преступление.","r":"УК ст. 13"},{"d":"Уголовный кодекс РО","t":"Статья 14. Формы вины","x":"1. Виновным в преступлении признается лицо, совершившее деяние умышленно или по неосторожности. 2. Деяние, совершенное только по неосторожности, признается преступлением лишь в случае, когда это специально предусмотрено соответствующей статьей Особенной части настоящего Кодекса.","r":"УК ст. 14"},{"d":"Уголовный кодекс РО","t":"Статья 15. Преступление, совершенное умышленно","x":"1. Преступлением, совершенным умышленно, признается деяние, совершенное с прямым или косвенным умыслом. 2. Преступление признается совершенным с прямым умыслом, если лицо осознавало общественную опасность своих действий (бездействия), предвидело возможность или неизбежность наступления общественно опасных последствий и желало их наступления. 3. Преступление признается совершенным с косвенным умыслом, если лицо осознавало общественную опасность своих действий (бездействия), предвидело возможность наступления общественно опасных последствий, не желало, но сознательно допускало эти последствия либо относилось к ним безразлично.","r":"УК ст. 15"},{"d":"Уголовный кодекс РО","t":"Статья 16. Преступление, совершенное по неосторожности","x":"1. Преступлением, совершенным по неосторожности, признается деяние, совершенное по легкомыслию или небрежности. 2. Преступление признается совершенным по легкомыслию, если лицо предвидело возможность наступления общественно опасных последствий своих действий (бездействия), но без достаточных к тому оснований самонадеянно рассчитывало на предотвращение этих последствий. 3. Преступление признается совершенным по небрежности, если лицо не предвидело возможности наступления общественно опасных последствий своих действий (бездействия), хотя при необходимой внимательности и предусмотрительности должно было и могло предвидеть эти последствия.","r":"УК ст. 16"},{"d":"Уголовный кодекс РО","t":"Статья 17. Ответственность за преступление, совершенное с двумя формами вины","x":"Если в результате совершения умышленного преступления причиняются тяжкие последствия, которые по закону влекут более строгое наказание и которые не охватывались умыслом лица, уголовная ответственность за такие последствия наступает только в случае, если лицо предвидело возможность их наступления, но без достаточных к тому оснований самонадеянно рассчитывало на их предотвращение, или в случае, если лицо не предвидело, но должно было и могло предвидеть возможность наступления этих последствий. В целом такое преступление признается совершенным умышленно.","r":"УК ст. 17"},{"d":"Уголовный кодекс РО","t":"Статья 18. Невиновное причинение вреда","x":"1. Деяние признается совершенным невиновно, если лицо, его совершившее, не осознавало и по обстоятельствам дела не могло осознавать общественной опасности своих действий (бездействия) либо не предвидело возможности наступления общественно опасных последствий и по обстоятельствам дела не должно было или не могло их предвидеть. 2. Деяние признается также совершенным невиновно, если лицо, его совершившее, хотя и предвидело возможность наступления общественно опасных последствий своих действий (бездействия), но не могло предотвратить эти последствия в силу несоответствия своих психофизиологических качеств требованиям экстремальных условий или нервно-психическим перегрузкам.","r":"УК ст. 18"},{"d":"Уголовный кодекс РО","t":"Статья 19. Оконченное и неоконченное преступления","x":"1. Преступление признается оконченным, если в совершенном лицом деянии содержатся все признаки состава преступления, предусмотренного настоящим Кодексом. 2. Неоконченным преступлением признаются приготовление к преступлению и покушение на преступление. 3. Уголовная ответственность за неоконченное преступление наступает по статье настоящего Кодекса, предусматривающей ответственность за оконченное преступление, со ссылкой на статью 20 настоящего Кодекса.","r":"УК ст. 19"},{"d":"Уголовный кодекс РО","t":"Статья 20. Приготовление к преступлению и покушение на преступление","x":"1. Приготовлением к преступлению признаются приискание, изготовление или приспособление лицом средств или орудий совершения преступления, приискание соучастников преступления, сговор на совершение преступления либо иное умышленное создание условий для совершения преступления, если при этом преступление не было доведено до конца по независящим от этого лица обстоятельствам. 2. Покушением на преступление признаются умышленные действия (бездействие) лица, непосредственно направленные на совершение преступления, если при этом преступление не было доведено до конца по независящим от этого лица обстоятельствам.","r":"УК ст. 20","k":"покушение на преступление это ; не довёл преступление до конца ; пытался но не смог статья ; приготовление к преступлению"},{"d":"Уголовный кодекс РО","t":"Статья 21. Добровольный отказ от преступления","x":"1. Добровольным отказом от преступления признается прекращение лицом приготовления к преступлению либо прекращение действий (бездействия), непосредственно направленных на совершение преступления, если лицо осознавало возможность доведения преступления до конца. 2. Лицо не подлежит уголовной ответственности за преступление, если оно добровольно и окончательно отказалось от доведения этого преступления до конца. 3. Лицо, добровольно отказавшееся от доведения преступления до конца, подлежит уголовной ответственности в том случае, если фактически совершенное им деяние содержит иной состав преступления. 4. Организатор преступления и подстрекатель к преступлению не подлежат уголовной ответственности, если эти лица своевременным сообщением органам власти или иными предпринятыми мерами предотвратили доведение преступления исполнителем до конца. Пособник преступления не подлежит уголовной ответственности, если он предпринял все зависящие от него меры, чтобы предотвратить совершение преступления. 5. Если действия организатора или подстрекателя, предусмотренные частью четвертой настоящей статьи, не привели к предотвращению совершения преступления исполнителем, то предпринятые ими меры могут быть признаны смягчающими обстоятельствами при назначении наказания.","r":"УК ст. 21"},{"d":"Уголовный кодекс РО","t":"Статья 22. Понятие соучастия в преступлении","x":"Соучастием в преступлении признается умышленное совместное участие двух или более лиц в совершении умышленного преступления.","r":"УК ст. 22"},{"d":"Уголовный кодекс РО","t":"Статья 23. Виды соучастников преступления","x":"1. Соучастниками преступления наряду с исполнителем признаются организатор, подстрекатель и пособник. 2. Исполнителем признается лицо, непосредственно совершившее преступление либо непосредственно участвовавшее в его совершении совместно с другими лицами (соисполнителями), а также лицо, совершившее преступление посредством использования других лиц, не подлежащих уголовной ответственности в силу возраста, невменяемости или других обстоятельств, предусмотренных настоящим Кодексом. 3. Организатором признается лицо, организовавшее совершение преступления или руководившее его исполнением, а равно лицо, создавшее организованную группу или преступное сообщество (преступную организацию) либо руководившее ими. 4. Подстрекателем признается лицо, склонившее другое лицо к совершению преступления путем уговора, подкупа, угрозы или другим способом. 5. Пособником признается лицо, содействовавшее совершению преступления советами, указаниями, предоставлением информации, средств или орудий совершения преступления либо устранением препятствий, а также лицо, заранее обещавшее скрыть преступника, средства или орудия совершения преступления, следы преступления либо предметы, добытые преступным путем, а равно лицо, заранее обещавшее приобрести или сбыть такие предметы.","r":"УК ст. 23"},{"d":"Уголовный кодекс РО","t":"Статья 24. Совершение преступления группой лиц, группой лиц по предварительному сговору, организованной группой или преступным сообществом (преступной организацией)","x":"1. Преступление признается совершенным группой лиц, если в его совершении совместно участвовали два или более исполнителя без предварительного сговора. 2. Преступление признается совершенным группой лиц по предварительному сговору, если в нем участвовали лица, заранее договорившиеся о совместном совершении преступления. 3. Преступление признается совершенным организованной группой, если оно совершено устойчивой группой лиц, заранее объединившихся для совершения одного или нескольких преступлений. 4. Преступление признается совершенным преступным сообществом (преступной организацией), если оно совершено структурированной организованной группой или объединением организованных групп, действующих под единым руководством, члены которых объединены в целях совместного совершения одного или нескольких тяжких либо особо тяжких преступлений для получения прямо или косвенно финансовой или иной материальной выгоды. 5. Создание организованной группы в случаях, не предусмотренных статьями Особенной части настоящего Кодекса, влечет уголовную ответственность за приготовление к тем преступлениям, для совершения которых она создана. 6. Совершение преступления группой лиц, группой лиц по предварительному сговору, организованной группой или преступным сообществом (преступной организацией) влечет более строгое наказание на основании и в пределах, предусмотренных настоящим Кодексом.","r":"УК ст. 24"},{"d":"Уголовный кодекс РО","t":"Статья 25. Эксцесс исполнителя преступления","x":"Эксцессом исполнителя признается совершение исполнителем преступления, не охватывающегося умыслом других соучастников. За эксцесс исполнителя другие соучастники преступления уголовной ответственности не подлежат.","r":"УК ст. 25"},{"d":"Уголовный кодекс РО","t":"Статья 26. Необходимая оборона","x":"1. Не является преступлением причинение вреда посягающему лицу в состоянии необходимой обороны, то есть при защите личности и прав обороняющегося или других лиц, охраняемых законом интересов общества или государства от общественно опасного посягательства, если это посягательство было сопряжено с насилием, опасным для жизни обороняющегося или другого лица, либо с непосредственной угрозой применения такого насилия. 2. Защита от посягательства, не сопряженного с насилием, опасным для жизни обороняющегося или другого лица, либо с непосредственной угрозой применения такого насилия, является правомерной, если при этом не было допущено превышения пределов необходимой обороны, то есть умышленных действий, явно не соответствующих характеру и опасности посягательства. 3. Не являются превышением пределов необходимой обороны действия обороняющегося лица, если это лицо вследствие неожиданности посягательства не могло объективно оценить степень и характер опасности нападения. 4. Не являются превышением пределов необходимой обороны действия лица, направленные на защиту себя и своей семьи от насилия или угрозы применения насилия либо на защиту своего имущества против лица, незаконно проникшего в его жилище. 5. Положения настоящей статьи в равной мере распространяются на всех лиц независимо от их профессиональной или иной специальной подготовки и служебного положения, а также независимо от возможности избежать общественно опасного посягательства или обратиться за помощью к другим лицам или органам власти.","r":"УК ст. 26","k":"необходимая оборона по закону ; самооборона закон ; причинил вред нападавшему ответственность ; не преступление при обороне ; оборона от насилия опасного для жизни"},{"d":"Уголовный кодекс РО","t":"Статья 27. Причинение вреда при задержании лица, совершившего преступление","x":"1. Не является преступлением причинение вреда лицу, совершившему преступление, при его задержании для доставления органам власти и пресечения возможности совершения им новых преступлений, если иными средствами задержать такое лицо не представлялось возможным и при этом не было допущено превышения необходимых для этого мер. 2. Превышением мер, необходимых для задержания лица, совершившего преступление, признается их явное несоответствие характеру и степени общественной опасности совершенного задерживаемым лицом преступления и обстоятельствам задержания, когда лицу без необходимости причиняется явно чрезмерный, не вызываемый обстановкой вред. Такое превышение влечет за собой уголовную ответственность только в случаях умышленного причинения вреда.","r":"УК ст. 27"},{"d":"Уголовный кодекс РО","t":"Статья 28. Крайняя необходимость","x":"1. Не является преступлением причинение вреда охраняемым уголовным законом интересам в состоянии крайней необходимости, то есть для устранения опасности, непосредственно угрожающей личности и правам данного лица или иных лиц, охраняемым законом интересам общества или государства, если эта опасность не могла быть устранена иными средствами и при этом не было допущено превышения пределов крайней необходимости. 2. Превышением пределов крайней необходимости признается причинение вреда, явно не соответствующего характеру и степени угрожавшей опасности и обстоятельствам, при которых опасность устранялась, когда указанным интересам был причинен вред равный или более значительный, чем предотвращенный. Такое превышение влечет за собой уголовную ответственность только в случаях умышленного причинения вреда.","r":"УК ст. 28"},{"d":"Уголовный кодекс РО","t":"Статья 29. Обоснованный риск","x":"1. Не является преступлением причинение вреда охраняемым уголовным законом интересам при обоснованном риске для достижения общественно полезной цели. 2. Риск признается обоснованным, если указанная цель не могла быть достигнута не связанными с риском действиями (бездействием) и лицо, допустившее риск, предприняло достаточные меры для предотвращения вреда охраняемым уголовным законом интересам. 3. Риск не признается обоснованным, если он заведомо был сопряжен с угрозой для жизни многих людей, с угрозой экологической катастрофы или общественного бедствия.","r":"УК ст. 29"},{"d":"Уголовный кодекс РО","t":"Статья 30. Исполнение приказа или распоряжения","x":"1. Не является преступлением причинение вреда охраняемым уголовным законом интересам лицом, действующим во исполнение обязательных для него приказа или распоряжения. Уголовную ответственность за причинение такого вреда несет лицо, отдавшее незаконные приказ или распоряжение. 2. Лицо, совершившее умышленное преступление во исполнение заведомо незаконных приказа или распоряжения, несет уголовную ответственность на общих основаниях. Неисполнение заведомо незаконных приказа или распоряжения исключает уголовную ответственность.","r":"УК ст. 30"},{"d":"Уголовный кодекс РО","t":"Статья 31. Физическое или психическое принуждение","x":"1. Не является преступлением причинение вреда охраняемым уголовным законом интересам в результате физического принуждения, если вследствие такого принуждения лицо не могло руководить своими действиями (бездействием). 2. Вопрос об уголовной ответственности за причинение вреда охраняемым уголовным законом интересам в результате психического принуждения, а также в результате физического принуждения, вследствие которого лицо сохранило возможность руководить своими действиями, решается с учетом положений настоящего Кодекса.","r":"УК ст. 31"},{"d":"Уголовный кодекс РО","t":"Статья 32. Понятие и цели наказания","x":"1. Наказание есть мера государственного принуждения, назначаемая по решению уполномоченного лица. Наказание применяется к лицу, признанному виновным в совершении преступления, и заключается в предусмотренных настоящим Кодексом лишении или ограничении прав и свобод этого лица. 2. Наказание применяется в целях восстановления социальной справедливости, а также в целях исправления осужденного и предупреждения совершения новых преступлений.","r":"УК ст. 32"},{"d":"Уголовный кодекс РО","t":"Статья 33. Виды наказаний","x":"1. Видами наказаний являются: а) штраф; б) лишение права занимать определенные должности или заниматься определенной деятельностью; в) увольнение с государственной или военной службы, в том числе с лишением всех званий (военного билета), наград и привилегий; г) исправительные работы; д) принудительные работы; е) лишение свободы на определенный срок. 2. Исправительные работы, принудительные работы, лишение свободы на определенный срок могут определяться только в качестве основного вида наказания. 3. Уголовный штраф, лишение права занимать определенные должности или заниматься определенной деятельностью могут определяться как в качестве дополнительного, так и в качестве основного вида наказания. 4. Увольнение с государственной или военной службы, в том числе с лишением всех званий, наград и привилегий может определяться только в качестве дополнительного вида наказания. 5. Суд при назначении наказания за преступление может назначить в качестве дополнительного вида наказания увольнение с государственной или военной службы, в том числе с лишением всех званий, наград и привилегий и лишение права занимать определенные должности или заниматься определенной деятельностью даже если такое наказание не предусмотрено санкцией соответствующей статьи.","r":"УК ст. 33"},{"d":"Уголовный кодекс РО","t":"Статья 34. Лица, уполномоченные на привлечение лица к уголовной ответственности и назначение наказания за совершение преступления","x":"1. Органы внутренних дел (полиция), Федеральной Службы Безопасности РО, военной полиции Вооруженных Сил РО, органы прокуратуры и Следственного комитета РО правомочны признавать лицо виновным в совершении преступления и назначить ему за совершенное преступление наказание в виде штрафа или лишения свободы на определенный срок. 2. Суд правомочен признать лицо виновным в совершении преступления и назначить ему за совершенное преступление любого наказания, предусмотренного ч. 1 ст. 33 настоящего Кодекса, с учетом правил назначения наказания, предусмотренных законом. 3. Дополнительные виды наказания могут быть назначены только судом.","r":"УК ст. 34"},{"d":"Уголовный кодекс РО","t":"Статья 35. Штраф","x":"1. Штраф есть денежное взыскание, назначаемое в пределах, предусмотренных настоящим Кодексом. 2. Штраф устанавливается в размере санкции соответствующей статьи. Суд при назначении штрафа в качестве основного вида наказания может выходить за рамки санкции соответствующей статьи и назначить штраф в размере не более 300.000 рублей.","r":"УК ст. 35"},{"d":"Уголовный кодекс РО","t":"Статья 36. Лишение права занимать определенные должности или заниматься определенной деятельностью","x":"1. Лишение права занимать определенные должности или заниматься определенной деятельностью состоит в запрещении занимать должности на государственной службе, в органах местного самоуправления либо заниматься определенной профессиональной или иной деятельностью. 2. В случае если санкцией соответствующей статьи не предусмотрено иное, лишение права занимать определенные должности или заниматься определенной деятельностью устанавливается на срок от 1 до 7 лет.","r":"УК ст. 36"},{"d":"Уголовный кодекс РО","t":"Статья 37. Исправительные работы","x":"1. Исправительные работы назначаются осужденному, имеющему основное место работы, а равно не имеющему его. Осужденный, имеющий основное место работы, отбывает исправительные работы по основному месту работы. Осужденный, не имеющий основного места работы, отбывает исправительные работы в местах, определяемых судом. 2. Из заработной платы осужденного к исправительным работам производятся удержания в доход государства в размере, установленном приговором суда, в пределах от пяти до двадцати процентов. 3. Если суд придет к выводу о том, что исправление подсудимого возможно без назначения наказания в виде реального лишения свободы за совершение преступления небольшой или средней тяжести, если такое наказание предусмотрено санкцией соответствующей статьи, суд может назначить вместо реального лишения свободы в качестве основного вида наказания назначить подсудимому наказание в виде исправительных работ на срок до 20 месяцев. 4. В случае злостного уклонения осужденного от отбывания исправительных работ суд может заменить неотбытое наказание принудительными работами или лишением свободы.","r":"УК ст. 37"},{"d":"Уголовный кодекс РО","t":"Статья 38. Принудительные работы","x":"1. Принудительные работы заключаются в привлечении осужденного к труду в местах, определяемых судом. 2. Места, порядок и иные условия отбывания принудительных работ определяется судом. 3. Если суд придет к выводу о том, что исправление подсудимого возможно без назначения наказания в виде реального лишения свободы за совершение преступления небольшой или средней тяжести или тяжкого преступления, если такое наказание предусмотрено санкцией соответствующей статьи, суд может назначить вместо реального лишения свободы в качестве основного вида наказания назначить подсудимому наказание в виде принудительных работ на срок до 30 месяцев.","r":"УК ст. 38"},{"d":"Уголовный кодекс РО","t":"Статья 39. Лишение свободы на определенный срок","x":"1. Лишение свободы заключается в изоляции признанного в совершении преступления лица от общества путем направления его в исправительное учреждение. Лишение свободы на определенный срок устанавливается на срок от 5 до 50 месяцев. 2. При частичном или полном сложении сроков лишения свободы при назначении наказаний по совокупности преступлений максимальный срок лишения свободы не может быть более 100 месяцев.","r":"УК ст. 39"},{"d":"Уголовный кодекс РО","t":"Статья 40. Общие начала назначения наказания","x":"1. Лицу, признанному виновным в совершении преступления, назначается справедливое наказание в пределах, предусмотренных соответствующей статьей Особенной части настоящего Кодекса, и с учетом положений Общей части настоящего Кодекса. 2. При назначении наказания учитываются характер и степень общественной опасности преступления и личность виновного, в том числе обстоятельства, смягчающие и отягчающие наказание.","r":"УК ст. 40"},{"d":"Уголовный кодекс РО","t":"Статья 41. Правила назначения наказания по совокупности преступлений","x":"1. При совокупности преступлений наказание назначается отдельно за каждое совершенное преступление. 2. В случае назначения наказания за совершение преступлений по совокупности, окончательное наказание назначается путем поглощения менее строгого наказания более строгим. 3. В случае назначения наказания за совершение преступлений по совокупности судом, окончательное наказание может назначаться как по правилу поглощения менее строгого наказания более строгим, так и путем полного или частичного сложения назначенных наказаний. 4. В случае назначения по совокупности преступлений наказания за совершение преступления, предусмотренного ст. 104 настоящего Кодекса, окончательное наказание может назначаться как по правилу, предусмотренному ч. 2 настоящей статьи, так и путем однократного полного или частичного сложения самого строгого назначенного наказания с наказанием за совершение преступления, предусмотренного ст. 104 настоящего Кодекса.","r":"УК ст. 41"},{"d":"Уголовный кодекс РО","t":"Статья 42. Обстоятельства, смягчающие наказание","x":"Смягчающими обстоятельствами признаются: а) совершение преступления в результате физического или психического принуждения либо в силу материальной, служебной или иной зависимости; б) совершение преступления при нарушении условий правомерности необходимой обороны, задержания лица, совершившего преступление, крайней необходимости, обоснованного риска, исполнения приказа или распоряжения; в) противоправность или аморальность поведения потерпевшего, явившегося поводом для преступления; г) явка с повинной, активное способствование раскрытию и расследованию преступления, изобличению и уголовному преследованию других соучастников преступления; д) оказание медицинской и иной помощи потерпевшему после совершения преступления, добровольное возмещение имущественного ущерба и морального вреда, причиненных в результате преступления, иные действия, направленные на заглаживание вреда, причиненного потерпевшему; е) иные обстоятельства.","r":"УК ст. 42"},{"d":"Уголовный кодекс РО","t":"Статья 43. Обстоятельства, отягчающие наказание","x":"1. Отягчающими обстоятельствами признаются: а) совершение преступления в составе группы лиц, группы лиц по предварительному сговору, организованной группы или преступного сообщества (преступной организации); б) совершение преступления по мотивам политической, идеологической, расовой, национальной или религиозной ненависти, или вражды либо по мотивам ненависти или вражды в отношении какой-либо социальной группы; в) совершение преступления из мести за правомерные действия других лиц, а также с целью скрыть другое преступление или облегчить его совершение; г) совершение преступления в отношении лица или его близких в связи с осуществлением данным лицом служебной деятельности или выполнением общественного долга; д) совершение преступления с особой жестокостью, садизмом, издевательством, а также мучениями для потерпевшего; е) совершение преступления с использованием доверия, оказанного виновному в силу его служебного положения или договора; ё) совершение преступления с использованием форменной одежды или документов представителя власти; ж) совершение преступления в состоянии алкогольного или наркотического опьянения; з) совершение преступления с использованием психического давления на потерпевшего; и) рецидив преступлений; й) совершение преступления в отношении потерпевшего, находящегося в отношении виновного в заведомо беспомощном положении; к) наступление тяжких последствий в результате совершения преступления. 2. Не может признаваться отягчающим наказание такое обстоятельство, которое хотя и предусмотрено частью 1 настоящей статьи, однако является одним из квалифицирующих…","r":"УК ст. 43"},{"d":"Уголовный кодекс РО","t":"Статья 44. Назначение более мягкого наказания, чем предусмотрено за данное преступление","x":"При наличии исключительных обстоятельств, связанных с целями и мотивами преступления, ролью виновного, его поведением во время или после совершения преступления, и других обстоятельств, существенно уменьшающих степень общественной опасности преступления, а равно при активном содействии участника группового преступления раскрытию этого преступления, в том числе в случае заключения подозреваемым или обвиняемым досудебного соглашения о сотрудничестве, наказание может быть назначено ниже низшего предела, предусмотренного статьей Особенной части настоящего Кодекса, суд может назначить более мягкий вид наказания, чем предусмотрен санкцией соответствующей статьи.","r":"УК ст. 44"},{"d":"Уголовный кодекс РО","t":"Статья 45. Назначение наказания за неоконченное преступление","x":"1. При назначении наказания за неоконченное преступление учитываются обстоятельства, в силу которых преступление не было доведено до конца. 2. Срок или размер наказания за приготовление к преступлению не может превышать половины максимального срока или размера наиболее строгого вида наказания, предусмотренного соответствующей статьей Особенной части настоящего Кодекса за оконченное преступление. 3. Срок или размер наказания за покушение на преступление не может превышать трех четвертей максимального срока или размера наиболее строгого вида наказания, предусмотренного соответствующей статьей Особенной части настоящего Кодекса за оконченное преступление.","r":"УК ст. 45"},{"d":"Уголовный кодекс РО","t":"Статья 46. Освобождение от уголовной ответственности в связи с назначением судебного штрафа или исправительных работ","x":"1. Лицо, впервые совершившее преступление небольшой или средней тяжести, может быть освобождено судом от уголовной ответственности, с назначением судебного штрафа. 2. Судебный штраф есть денежное взыскание, назначаемое судом при освобождении лица от уголовной ответственности в случаях, предусмотренных настоящей статьей. 3. В случае неуплаты судебного штрафа в установленный судом срок, судебный штраф отменяется и лицо привлекается к уголовной ответственности по соответствующей статье Особенной части настоящего Кодекса.","r":"УК ст. 46"},{"d":"Уголовный кодекс РО","t":"Статья 47. Освобождение от уголовной ответственности в связи с истечением сроков давности уголовного преследования","x":"1. Лицо освобождается от уголовной ответственности, если со дня совершения преступления истекли следующие сроки: а) пятнадцать лет после совершения преступления небольшой тяжести; б) двадцать лет после совершения преступления средней тяжести; в) двадцать пять лет после совершения тяжкого преступления; г) тридцать пять лет после совершения особо тяжкого преступления.","r":"УК ст. 47"},{"d":"Уголовный кодекс РО","t":"Статья 48. Амнистия","x":"1. Амнистия объявляется Федеральным Собранием РО в отношении индивидуально не определенного круга лиц. 2. Актом об амнистии лица, совершившие преступления, могут быть освобождены от уголовной ответственности. Лица, осужденные за совершение преступлений, могут быть освобождены от наказания, либо назначенное им наказание может быть сокращено или заменено более мягким видом наказания, либо такие лица могут быть освобождены от дополнительного вида наказания. С лиц, отбывших наказание, актом об амнистии может быть снята судимость.","r":"УК ст. 48"},{"d":"Уголовный кодекс РО","t":"Статья 49. Помилование","x":"1. Помилование осуществляется Премьер Министром РО в отношении индивидуально определенного лица. 2. Актом помилования лицо, осужденное за преступление, может быть освобождено от дальнейшего отбывания наказания либо назначенное ему наказание может быть сокращено или заменено более мягким видом наказания. С лица, отбывшего наказание, актом помилования может быть снята судимость.","r":"УК ст. 49"},{"d":"Уголовный кодекс РО","t":"Статья 50. Судимость","x":"1. Лицо, привлеченное к уголовной ответственности за совершение преступления, считается судимым со дня вступления в законную силу соответствующего решения должностного лица до момента погашения или снятия судимости. Судимость в соответствии с настоящим Кодексом учитывается при рецидиве преступлений, назначении наказания и влечет за собой иные правовые последствия в случаях и в порядке, которые установлены законом. 2. Погашение или снятие судимости аннулирует все правовые последствия, предусмотренные настоящим Кодексом, связанные с судимостью. 3. Судимость возникает лишь при назначении за совершение тяжкого или особо-тяжкого преступления наказания в виде лишения свободы на срок 40 месяцев и более. 4. Процедура погашения судимости устанавливается законом и актами Председателя Верховного суда РО. 5. Судимость может быть погашена досрочно путем внесения компенсационного платежа в казну правительства в размере 130.000 рублей через сотрудников Министерства Юстиции, Прокуратуры, Судей всех инстанций, иных лиц установленных законодательством.","r":"УК ст. 50"},{"d":"Уголовный кодекс РО","t":"Статья 50.1. Залог","x":"1. Лицо, которому за совершение небольшого или средней тяжести преступления назначено наказание в виде лишения свободы на определенный срок может быть освобождено от отбывания наказания в связи с внесением залога. 2. Залог вносится либо лицом, привлеченным к уголовной ответственности лично, либо его представителем или законным представителем в учреждение органа государственной власти, где осужденный отбывает наказание. 3. Залог за освобождение от наказания за совершение преступления небольшой тяжести составляет 50.000 рублей, а за совершение преступления средней тяжести - 75.000 рублей. 4. В случае назначения наказания в виде лишения свободы лицу по совокупности преступлений, сумма залога рассчитывается из самого тяжкого совершенного преступления. 5. Лицо не может быть освобождено от наказания в связи с внесением залога за совершение тяжких и особо-тяжких преступлений.","r":"УК ст. 50.1"},{"d":"Уголовный кодекс РО","t":"Статья 51. Убийство","x":"[Р/Ф] [★★★★★] Убийство, то есть умышленное причинение смерти другому человеку, — наказывается лишением свободы на срок 50 месяцев. [★★★★★] Убийство: а) двух или более лиц; б) лица или его близких в связи с осуществлением данным лицом служебной деятельности или выполнением общественного долга; в) лица, заведомо для виновного находящегося в беспомощном состоянии, а равно сопряженное с похищением человека; г) совершенное с особой жестокостью; д) совершенное общественно опасным способом; е) по мотиву кровной мести; ж) совершенное группой лиц, группой лиц по предварительному сговору или организованной группой; з) из хулиганских побуждений, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 51","k":"убийство статья ; убил человека какая статья ; убийство военнослужащего статья ; умышленное причинение смерти"},{"d":"Уголовный кодекс РО","t":"Статья 52. Убийство, совершенное при превышении пределов необходимой обороны либо при превышении мер, необходимых для задержания лица, совершившего преступление","x":"[Р/Ф] [★★★] Убийство, совершенное при превышении пределов необходимой обороны либо при превышении мер, необходимых для задержания лица, совершившего преступление, — наказывается лишением свободы на срок 30 месяцев.","r":"УК ст. 52","k":"превысил самооборону ; убил при задержании статья ; превышение необходимой обороны ; убил нападавшего что мне будет"},{"d":"Уголовный кодекс РО","t":"Статья 53. Причинение смерти по неосторожности","x":"[Р/Ф] [★★★] Причинение смерти по неосторожности, — наказывается лишением свободы на срок 30 месяцев.","r":"УК ст. 53"},{"d":"Уголовный кодекс РО","t":"Статья 54. Умышленное причинение тяжкого вреда здоровью","x":"[Р/Ф] [★★★★★] Умышленное причинение тяжкого вреда здоровью, опасного для жизни человека, или повлекшего за собой потерю зрения, речи, слуха либо какого-либо органа или утрату органом его функций, прерывание беременности, психическое расстройство, заболевание наркоманией либо токсикоманией, или выразившегося в неизгладимом обезображивании лица, или вызвавшего значительную стойкую утрату общей трудоспособности не менее чем на одну треть или заведомо для виновного полную утрату профессиональной трудоспособности, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 54"},{"d":"Уголовный кодекс РО","t":"Статья 55. Причинение тяжкого или средней тяжести вреда здоровью при превышении пределов необходимой обороны либо при превышении мер, необходимых для задержания лица, совершившего преступление","x":"[Р/Ф] [★★★] Умышленное причинение тяжкого вреда здоровью, совершенное при превышении пределов необходимой обороны, — наказывается штрафом в размере от 35.000 до 60.000 рублей либо лишением свободы на срок 30 месяцев. [Р/Ф] [★★★] Умышленное причинение тяжкого или средней тяжести вреда здоровью, совершенное при превышении мер, необходимых для задержания лица, совершившего преступление, — наказывается штрафом в размере 50.000 рублей либо лишением свободы на срок 30 месяцев.","r":"УК ст. 55"},{"d":"Уголовный кодекс РО","t":"Статья 56. Истязание","x":"[Р/Ф] [★★] Причинение физических или психических страданий путем систематического нанесения побоев либо иными насильственными действиями, если это не повлекло последствий, указанных в статьях 53 и 54 настоящего Кодекса, — наказывается лишением свободы на срок 20 месяцев. [Р/Ф] [★★★] То же деяние, совершенное с особой жестокостью, издевательством или мучениями для потерпевшего, а равно совершенное группой лиц, группой лиц по предварительному сговору или организованной группой, — наказывается лишением свободы на срок 30 месяцев.","r":"УК ст. 56"},{"d":"Уголовный кодекс РО","t":"Статья 57. Угроза убийством или причинением тяжкого вреда здоровью","x":"[Р] [★★★] Угроза убийством или причинением тяжкого вреда здоровью, если имелись основания опасаться осуществления этой угрозы, — наказывается штрафом в размере от 25.000 до 100.000 рублей либо лишением свободы на срок 30 месяцев.","r":"УК ст. 57","k":"угрожал убить статья ; угроза убийством ; сказал что убьёт меня ; грозился зарезать ; угроза тяжким вредом"},{"d":"Уголовный кодекс РО","t":"Статья 58. Похищение человека","x":"[Ф] [★★★★★] Похищение человека, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 58"},{"d":"Уголовный кодекс РО","t":"Статья 59. Незаконное лишение свободы","x":"[Р/Ф] [★★★★] Незаконное лишение человека свободы, не связанное с его похищением, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 59"},{"d":"Уголовный кодекс РО","t":"Статья 60. Клевета","x":"[Р] Клевета, то есть распространение заведомо ложных сведений, порочащих честь и достоинство другого лица или подрывающих его репутацию, — наказывается штрафом в размере от 5.000 до 30.000 рублей. [Р] [★★] Клевета, совершенная с использованием своего служебного положения, а равно соединенная с обвинением лица в совершении преступления против половой неприкосновенности и половой свободы личности либо в совершении тяжкого или особо-тяжкого преступления, — наказывается штрафом в размере от 20.000 до 100.000 рублей либо лишением свободы на срок 20 месяцев.","r":"УК ст. 60"},{"d":"Уголовный кодекс РО","t":"Статья 61. Изнасилование","x":"[Р/Ф] [★★★★] Изнасилование, то есть половое сношение с применением насилия или с угрозой его применения к потерпевшей или к другим лицам либо с использованием беспомощного состояния потерпевшей, — наказывается лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] Изнасилование: а) совершенное группой лиц, группой лиц по предварительному сговору или организованной группой; б) соединенное с угрозой убийством или причинением тяжкого вреда здоровью, а также совершенное с особой жестокостью по отношению к потерпевшей или к другим лицам; в) повлекшее по неосторожности смерть потерпевшего, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 61"},{"d":"Уголовный кодекс РО","t":"Статья 62. Понуждение к действиям сексуального характера","x":"[Р] [★★★] Понуждение лица к половому сношению, мужеложству, лесбиянству или совершению иных действий сексуального характера путем шантажа, угрозы уничтожением, повреждением или изъятием имущества либо с использованием материальной или иной зависимости потерпевшего (потерпевшей), — наказывается лишением свободы на срок 30 месяцев.","r":"УК ст. 62"},{"d":"Уголовный кодекс РО","t":"Статья 63. Нарушение равенства прав и свобод человека и гражданина","x":"[Р] [★★] Дискриминация, то есть нарушение прав, свобод и законных интересов человека и гражданина в зависимости от его пола, расы, национальности, языка, происхождения, имущественного и должностного положения, места жительства, отношения к религии, убеждений, принадлежности к общественным объединениям или каким-либо социальным группам, совершенное лицом с использованием своего служебного положения, — наказывается штрафом в размере от 30.000 до 90.000 рублей, либо лишением свободы на срок 20 месяцев.","r":"УК ст. 63"},{"d":"Уголовный кодекс РО","t":"Статья 64. Нарушение неприкосновенности жилища","x":"[Р/Ф] [★★★] Незаконное проникновение в жилище, совершенное против воли проживающего в нем лица, — наказывается штрафом в размере до 50.000 рублей, либо лишением свободы на срок 30 месяцев. [Р/Ф] [★★★★] То же деяние, совершенное с применением насилия или с угрозой его применения, а равно совершенные лицом с использованием своего служебного положения, — наказывается штрафом в размере до 75.000 рублей, либо лишением свободы на срок 40 месяцев.","r":"УК ст. 64"},{"d":"Уголовный кодекс РО","t":"Статья 65. Кража","x":"[Р/Ф] [★★★] Кража, то есть тайное хищение чужого имущества, — наказывается штрафом в размере до 50.000 рублей, либо лишением свободы на срок 30 месяцев. [Р/Ф] [★★★★] Кража, совершенная: а) группой лиц по предварительному сговору или организованной группой; б) с незаконным проникновением в жилище, помещение либо иное хранилище, — наказывается штрафом в размере до 90.000 рублей, либо лишением свободы на срок 40 месяцев. Примечания. Под хищением в статьях настоящего Кодекса понимаются совершенные с корыстной целью противоправные безвозмездное изъятие и (или) обращение чужого имущества в пользу виновного или других лиц, причинившие ущерб собственнику или иному владельцу этого имущества. Под помещением в статьях настоящей главы понимаются строения и сооружения независимо от форм собственности, предназначенные для временного нахождения людей или размещения материальных ценностей в производственных или иных служебных целях.","r":"УК ст. 65"},{"d":"Уголовный кодекс РО","t":"Статья 66. Грабеж и разбой","x":"[Р/Ф] [★★★] Грабеж, то есть открытое хищение чужого имущества, — наказывается лишением свободы на срок 30 месяцев. [Р/Ф] [★★★★] Грабеж, совершенный: а) группой лиц по предварительному сговору; б) с незаконным проникновением в жилище, помещение либо иное хранилище; в) с применением насилия, не опасного для жизни или здоровья, либо с угрозой применения такого насилия, — наказывается лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★] Разбой, то есть нападение в целях хищения чужого имущества, совершенное с применением насилия, опасного для жизни или здоровья, либо с угрозой применения такого насилия, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 66"},{"d":"Уголовный кодекс РО","t":"Статья 67. Неправомерное завладение транспортным средством, угон","x":"[Р/Ф] [★★★] Неправомерное завладение автомобилем или иным транспортным средством вне зависимости от цели такого завладения, — наказывается лишением свободы на срок 30 месяцев. Пояснение: «Неправомерное завладение» означает, что виновный не только получил контроль над транспортом, но и сдвинул его — например, угнал машину с парковки или увел лодку от причала. Цель завладения (кража, временное использование или иная) не влияет на квалификацию. Если человек занял транспортное средство — например, проник в чужую машину, завёл её или использовал как укрытие, но не сдвинул с места, — не считается «завладением». Такие действия квалифицируются как мелкое хулиганство, поскольку не приводят к утрате владельцем фактического доступа к транспорту в полном объёме. Исключение для транспорта государственных служащих. Если транспортное средство принадлежит государственному служащему и используется в служебных целях, то занятие его без перемещения имеет особый статус. В этом случае гражданин обязан покинуть такое транспортное средство по первому требованию госслужащего. Невыполнение требования пресекается в соответствии с законодательством, но само занятие без перемещения остается вне рамок статьи 67. Транспортировка транспортного средства, числящегося в угоне, на ином воздушном/водном/железнодорожным и др. видах транспорта также является неправомерным завладением, в том числе если ТС было сдвинуто посредством косвенного вмешательства обвиняемого лица, либо нахождения в нём без сообщения в компетентные органы.","r":"УК ст. 67"},{"d":"Уголовный кодекс РО","t":"Статья 68. Умышленное уничтожение или повреждение имущества","x":"[Р] [★★★] Умышленные уничтожение или повреждение чужого имущества, если эти деяния повлекли причинение значительного ущерба, — наказывается штрафом в размере до 50.000 рублей либо лишением свободы на срок 30 месяцев.","r":"УК ст. 68"},{"d":"Уголовный кодекс РО","t":"Статья 69. Незаконное предпринимательство","x":"[Ф] [★★★★] Осуществление предпринимательской деятельности без регистрации или без лицензии, если это деяние причинило крупный ущерб гражданам, организациям или государству, — наказывается штрафом в размере до 100.000 рублей либо лишением свободы на срок 40 месяцев.","r":"УК ст. 69"},{"d":"Уголовный кодекс РО","t":"Статья 70. Террористический акт","x":"[Ф] [★★★★★] Совершение взрыва, поджога или иных действий, устрашающих население и создающих опасность гибели человека, причинения значительного имущественного ущерба либо наступления иных тяжких последствий, в целях дестабилизации деятельности органов власти или международных организаций либо воздействия на принятие ими решений, а также угроза совершения указанных действий в целях воздействия на принятие решений органами власти или международными организациями, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 70"},{"d":"Уголовный кодекс РО","t":"Статья 71. Публичные призывы к осуществлению террористической деятельности, публичное оправдание терроризма или пропаганда терроризма","x":"[Р/Ф] [★★★] Публичные призывы к осуществлению террористической деятельности, публичное оправдание терроризма или пропаганда терроризма, — наказывается штрафом в размере до 70.000 рублей, либо лишением свободы на срок 30 месяцев.","r":"УК ст. 71"},{"d":"Уголовный кодекс РО","t":"Статья 72. Бандитизм","x":"[Ф] [★★★★★] Создание устойчивой вооруженной группы (банды) в целях нападения на граждан или организации, а равно руководство такой группой (бандой), — наказываются лишением свободы на срок 50 месяцев. [Ф] [★★★★] Участие в устойчивой вооруженной группе (банде) или в совершаемых ею нападениях, — наказываются лишением свободы на срок 40 месяцев.","r":"УК ст. 72"},{"d":"Уголовный кодекс РО","t":"Статья 73. Хулиганство","x":"[Р/Ф] [★★★★] Хулиганство, то есть грубое нарушение общественного порядка, выражающее явное неуважение к обществу, совершенное: а) с применением насилия к гражданам либо угрозой его применения; б) по мотивам политической, идеологической, расовой, национальной или религиозной ненависти или вражды либо по мотивам ненависти или вражды в отношении какой-либо социальной группы; в) на железнодорожном, морском, внутреннем водном или воздушном транспорте, а также на любом ином транспорте общего пользования; г) с применением оружия или предметов, используемых в качестве оружия; д) группой лиц, группой лиц по предварительному сговору или организованной группой; е) связанное с сопротивлением представителю власти либо иному лицу, исполняющему обязанности по охране общественного порядка или пресекающему нарушение общественного порядка; ё) с применением взрывчатых веществ или взрывных устройств, — наказывается штрафом в размере до 50.000 рублей либо лишением свободы на срок 40 месяцев.","r":"УК ст. 73","k":"хулиганство статья ; дебоширит с насилием ; хулиган на территории ; грубое нарушение порядка с насилием"},{"d":"Уголовный кодекс РО","t":"Статья 73.1. Незаконное проникновение на режимный объект","x":"[Р/Ф] [★★★★] Незаконное проникновение на режимный объект равно как и нахождение на таковом объекте, — наказывается штрафом в размере от 80.000 до 150.000 рублей, либо лишением свободы на срок 40 месяцев.","r":"УК ст. 73.1"},{"d":"Уголовный кодекс РО","t":"Статья 74. Незаконные приобретение, передача, хранение, перевозка, пересылка, ношение, сбыт или изготовление огнестрельного оружия, его основных частей и боеприпасов к нему, а также специальных средств","x":"[Р/Ф] [★★★★] Незаконные приобретение, передача, хранение, сбыт, перевозка, пересылка, ношение огнестрельного оружия, его основных частей и боеприпасов к нему, а также специальных средств, — наказывается штрафом в размере 50.000 рублей, либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] Незаконные изготовление, переделка или ремонт огнестрельного оружия, его основных частей, а равно незаконное изготовление боеприпасов к огнестрельному оружию — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 74","k":"незаконное оружие статья ; у гражданского автомат без лицензии ; хранение оружия без разрешения статья ; нашёл незаконный ствол какая статья ; незаконное ношение оружия ; сбыт оружия статья ; самодельное оружие"},{"d":"Уголовный кодекс РО","t":"Статья 75. Незаконные приобретение, хранение, перевозка, изготовление, переработка наркотических средств, психотропных веществ или их аналогов, а также незаконные приобретение, хранение, перевозка растений, содержащих наркотические средства или психотропные вещества, либо их частей, содержащих наркотические средства или психотропные вещества","x":"[Р/Ф] [★★★] Незаконные приобретение, хранение, перевозка, изготовление, переработка без цели сбыта наркотических средств, психотропных веществ или их аналогов в значительном размере, а также незаконные приобретение, хранение, перевозка без цели сбыта растений, содержащих наркотические средства или психотропные вещества, либо их частей, содержащих наркотические средства или психотропные вещества, в незначительном размере (до 5 грамм) — наказывается штрафом в размере до 50.000 рублей, либо лишением свободы на срок 30 месяцев. [Р/Ф] [★★★★] Те же деяния, совершенные в крупном размере (до 20 грамм), — наказываются лишением свободы на срок 40 месяцев. [Ф] [★★★★★] Те же деяния, совершенные в особо крупном размере (свыше 20 грамм), — наказываются лишением свободы на срок 50 месяцев.","r":"УК ст. 75"},{"d":"Уголовный кодекс РО","t":"Статья 76. Незаконные производство, сбыт или пересылка наркотических средств, психотропных веществ или их аналогов, а также незаконные сбыт или пересылка растений, содержащих наркотические средства или психотропные вещества, либо их частей, содержащих наркотические средства или психотропные вещества","x":"[Ф] [★★★★★] Незаконные производство, сбыт или пересылка наркотических средств, психотропных веществ или их аналогов, а также незаконные сбыт или пересылка растений, содержащих наркотические средства или психотропные вещества, либо их частей, содержащих наркотические средства или психотропные вещества, — наказываются лишением свободы на срок 50 месяцев.","r":"УК ст. 76"},{"d":"Уголовный кодекс РО","t":"Статья 77. Жестокое обращение с животными","x":"[Р] [★★★] Жестокое обращение с животным в целях причинения ему боли и (или) страданий, а равно из хулиганских побуждений или из корыстных побуждений, повлекшее его гибель или увечье, — наказывается штрафом в размере от 50.000 до 75.000 рублей либо лишением свободы на срок 30 месяцев.","r":"УК ст. 77"},{"d":"Уголовный кодекс РО","t":"Статья 78. Нарушение правил дорожного движения и эксплуатации транспортных средств","x":"[Р] [★★★] Нарушение лицом, управляющим автомобилем, либо другим механическим транспортным средством, правил дорожного движения или эксплуатации транспортных средств, повлекшее по неосторожности причинение тяжкого вреда здоровью человека, — наказывается штрафом в размере до 60.000 рублей либо лишением свободы на срок 30 месяцев. [Р/Ф] [★★★★] То же деяние, повлекшее по неосторожности смерть человека, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 78"},{"d":"Уголовный кодекс РО","t":"Статья 79. Государственная измена","x":"[Ф] [★★★★★] Государственная измена, то есть совершенные гражданином РО шпионаж, выдача иностранному государству, международной либо иностранной организации или их представителям сведений, составляющих государственную тайну, доверенную лицу или ставшую известной ему по службе, работе, учебе или в иных случаях, предусмотренных законодательством РО, переход на сторону противника либо оказание финансовой, материально-технической, консультационной или иной помощи иностранному государству, международной либо иностранной организации или их представителям в деятельности, направленной против безопасности РО, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 79"},{"d":"Уголовный кодекс РО","t":"Статья 80. Разглашение государственной тайны","x":"[Ф] [★★★★] Разглашение сведений, составляющих государственную тайну, лицом, которому она была доверена или стала известна по службе, работе, учебе или в иных случаях, предусмотренных законодательством РО, если эти сведения стали достоянием других лиц, при отсутствии признаков преступления, предусмотренного статьей 79 настоящего Кодекса, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 80"},{"d":"Уголовный кодекс РО","t":"Статья 81. Утрата документов, содержащих государственную тайну","x":"[Ф] [★★★] Нарушение лицом, имеющим допуск к государственной тайне, установленных правил обращения с содержащими государственную тайну документами, а равно с предметами, сведения о которых составляют государственную тайну, если это повлекло по неосторожности их утрату или наступление тяжких последствий, — наказывается штрафом в размере от 30.000 до 70.000 рублей либо лишением свободы на срок 30 месяцев.","r":"УК ст. 81"},{"d":"Уголовный кодекс РО","t":"Статья 82. Злоупотребление должностными полномочиями","x":"[Р/Ф] [★★★★] Использование должностным лицом своих служебных полномочий вопреки интересам службы, если это деяние совершено из корыстной или иной личной заинтересованности и повлекло существенное нарушение прав и законных интересов граждан или организаций либо охраняемых законом интересов общества или государства, — наказывается штрафом в размере от 50.000 до 100.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★] То же деяние, совершенное лицом, занимающим государственную должность РО или главой Федерального органа исполнительной власти или его заместителем, — наказывается штрафом в размере от 70.000 до 150.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] Деяния, предусмотренные частями первой или второй настоящей статьи, повлекшие тяжкие последствия, — наказываются лишением свободы на срок 50 месяцев.","r":"УК ст. 82"},{"d":"Уголовный кодекс РО","t":"Статья 83. Нецелевое расходование бюджетных средств","x":"[Ф] [★★★] Расходование бюджетных средств должностным лицом получателя бюджетных средств на цели, не соответствующие условиям их получения, определенным утвержденными бюджетом, бюджетной росписью, уведомлением о бюджетных ассигнованиях, сметой доходов и расходов либо иным документом, являющимся основанием для получения бюджетных средств, совершенное в крупном размере — наказывается штрафом в размере от 40.000 до 70.000 рублей, либо лишением свободы на срок 30 месяцев. [Ф] [★★★★] То же деяние, совершенное: а) группой лиц по предварительному сговору; б) в особо крупном размере, — наказывается лишением свободы на срок 40 месяцев. Примечание. Крупным размером в настоящей статье признается сумма бюджетных средств, превышающая пятьдесят тысяч рублей, а особо крупным размером — сто пятьдесят тысяч рублей.","r":"УК ст. 83"},{"d":"Уголовный кодекс РО","t":"Статья 84. Превышение должностных полномочий","x":"[Р/Ф] [★★★★] Совершение должностным лицом действий, явно выходящих за пределы его полномочий и повлекших существенное нарушение прав и законных интересов граждан или организаций либо охраняемых законом интересов общества или государства, — наказывается штрафом в размере от 65.000 до 100.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★] То же деяние, совершенное лицом, занимающим государственную должность РО или главой Федерального органа исполнительной власти или его заместителем, — наказывается штрафом в размере от 40.000 до 80.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] Деяния, предусмотренные частями первой или второй настоящей статьи, если они совершены: а) с применением насилия или с угрозой его применения; б) с применением оружия или специальных средств; в) с причинением тяжких последствий; г) группой лиц, группой лиц по предварительному сговору или организованной группой; д) из корыстной или иной личной заинтересованности, — наказываются лишением свободы на срок 50 месяцев.","r":"УК ст. 84"},{"d":"Уголовный кодекс РО","t":"Статья 85. Неисполнение сотрудником органа внутренних дел приказа","x":"[Р/Ф] [★★] Умышленное неисполнение сотрудником органа внутренних дел приказа начальника, отданного в установленном порядке и не противоречащего закону, причинившее существенный вред правам и законным интересам граждан или организаций либо охраняемым законом интересам общества или государства, — наказывается штрафом в размере от 20.000 до 40.000 рублей, либо лишением свободы на срок 20 месяцев. [Р/Ф] [★★★] То же деяние, совершенное группой лиц, группой лиц по предварительному сговору или организованной группой, а равно повлекшее тяжкие последствия, — наказывается лишением свободы на срок 30 месяцев.","r":"УК ст. 85"},{"d":"Уголовный кодекс РО","t":"Статья 86. Получение взятки","x":"[Р/Ф] [★★★★] Получение должностным лицом, иностранным должностным лицом либо должностным лицом публичной международной организации лично или через посредника взятки в виде денег, ценных бумаг, иного имущества либо в виде незаконных оказания ему услуг имущественного характера, предоставления иных имущественных прав за совершение действий (бездействие) в пользу взяткодателя или представляемых им лиц, — наказывается штрафом в размере от 50.000 до 100.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] То же деяние, совершенное в значительном размере, — наказывается лишением свободы на срок 50 месяцев. Примечание. Значительным размером взятки в настоящей статье и статье 86 и 87 настоящего Кодекса признаются сумма денег, стоимость ценных бумаг, иного имущества, услуг имущественного характера, иных имущественных прав, превышающие пятьдесят тысяч рублей.","r":"УК ст. 86"},{"d":"Уголовный кодекс РО","t":"Статья 87. Дача взятки","x":"[Р/Ф] [★★★★] Дача взятки должностному лицу, иностранному должностному лицу либо должностным лицом публичной международной организации лично или через посредника, — наказывается штрафом в размере до 70.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] То же деяние, совершенное в значительном размере, — наказывается штрафом в размере до 80.000 рублей либо лишением свободы на срок 50 месяцев. Примечание. Лицо, давшее взятку, освобождается от уголовной ответственности, если оно активно способствовало раскрытию и (или) расследованию преступления и либо в отношении его имело место вымогательство взятки со стороны должностного лица, либо лицо после совершения преступления добровольно сообщило в орган, имеющий право возбудить уголовное дело, о даче взятки.","r":"УК ст. 87"},{"d":"Уголовный кодекс РО","t":"Статья 88. Халатность","x":"[Ф] [★★★★] Халатность, то есть неисполнение или ненадлежащее исполнение должностным лицом своих обязанностей вследствие недобросовестного или небрежного отношения к службе либо обязанностей по должности, если это повлекло причинение крупного ущерба или существенное нарушение прав и законных интересов граждан или организаций либо охраняемых законом интересов общества или государства, — наказывается штрафом в размере от 60.000 до 80.000 рублей либо лишением свободы на срок 40 месяцев. [Ф] [★★★★★] То же деяние, повлекшее по неосторожности причинение тяжкого вреда здоровью или смерти человеку, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 88"},{"d":"Уголовный кодекс РО","t":"Статья 89. Воспрепятствование осуществлению правосудия и производству предварительного расследования","x":"[Р/Ф] [★★★★] Вмешательство в какой бы то ни было форме в деятельность суда в целях воспрепятствования осуществлению правосудия, — наказывается штрафом в размере до 100.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★] Вмешательство в какой бы то ни было форме в деятельность прокурора, следователя или лица, производящего дознание, в целях воспрепятствования всестороннему, полному и объективному расследованию дела, — наказывается штрафом в размере до 80.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] Деяния, предусмотренные частями первой или второй настоящей статьи, совершенные лицом с использованием своего служебного положения, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 89"},{"d":"Уголовный кодекс РО","t":"Статья 90. Посягательство на жизнь лица, осуществляющего правосудие или предварительное расследование","x":"[Р/Ф] [★★★★★] Посягательство на жизнь судьи, присяжного заседателя или иного лица, участвующего в отправлении правосудия, прокурора, следователя, лица, производящего дознание, защитника, эксперта, специалиста, сотрудника органов принудительного исполнения РО, а равно их близких в связи с рассмотрением дел или материалов в суде, производством предварительного расследования либо исполнением приговора, решения суда или иного судебного акта, совершенное в целях воспрепятствования законной деятельности указанных лиц либо из мести за такую деятельность, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 90"},{"d":"Уголовный кодекс РО","t":"Статья 91. Неуважение к суду","x":"[Р/Ф] [★★★★] Неуважение к суду, то есть совершение действий (бездействия), свидетельствующих о явном пренебрежении к установленным правилам или порядку проведения судебного заседания, либо неявка участника судебного заседания, вызванного на него надлежащим образом, без уважительной причины или разрешения суда, — наказывается штрафом в размере до 100.000 рублей, либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] То же деяние, выразившееся в оскорблении судьи, присяжного заседателя или иного лица, участвующего в отправлении правосудия, — наказывается штрафом в размере до 80.000 рублей, либо лишением свободы на срок 50 месяцев.","r":"УК ст. 91"},{"d":"Уголовный кодекс РО","t":"Статья 92. Привлечение заведомо невиновного к уголовной ответственности или незаконное возбуждение уголовного дела","x":"[Ф] [★★★★] Привлечение заведомо невиновного к уголовной ответственности — наказывается лишением свободы на срок 40 месяцев. [Ф] [★★★★★] То же деяние, соединенное с обвинением лица в совершении тяжкого или особо тяжкого преступления либо повлекшее причинение крупного ущерба или иные тяжкие последствия, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 92"},{"d":"Уголовный кодекс РО","t":"Статья 93. Незаконное освобождение от уголовной ответственности","x":"[Ф] [★★★★] Незаконное освобождение от уголовной ответственности лица, подозреваемого или обвиняемого в совершении преступления, прокурором, следователем или лицом, производящим дознание, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 93"},{"d":"Уголовный кодекс РО","t":"Статья 94. Незаконные задержание, заключение под стражу или содержание под стражей","x":"[Р/Ф] [★★★★] Заведомо незаконное задержание — наказывается лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] Заведомо незаконные заключение под стражу или содержание под стражей — наказываются лишением свободы на срок 50 месяцев.","r":"УК ст. 94"},{"d":"Уголовный кодекс РО","t":"Статья 95. Принуждение к даче показаний","x":"[Ф] [★★★★] Принуждение подозреваемого, обвиняемого, осужденного, оправданного, потерпевшего или свидетеля к даче показаний либо эксперта или специалиста к даче заключения или показаний путем применения угроз, шантажа или иных незаконных действий со стороны следователя, лица, производящего дознание, или иного сотрудника правоохранительного органа, а равно другого лица с ведома или молчаливого согласия следователя, лица, производящего дознание, или иного сотрудника правоохранительного органа, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 95"},{"d":"Уголовный кодекс РО","t":"Статья 95.1. Разглашение данных предварительного расследования","x":"[Ф] [★★★★] Разглашение данных предварительного расследования лицом, предупрежденным в установленном законом порядке о недопустимости их разглашения, если оно совершено без согласия следователя или лица, производящего дознание, — наказывается штрафом в размере до 50.000 рублей либо лишением свободы на срок 40 месяцев.","r":"УК ст. 95.1"},{"d":"Уголовный кодекс РО","t":"Статья 96. Вынесение заведомо неправосудных приговора, решения или иного судебного акта","x":"[Ф] [★★★★] Вынесение судьей (судьями) заведомо неправосудных приговора, решения или иного судебного акта — наказывается штрафом в размере до 100.000 рублей либо лишением свободы на срок 40 месяцев. [Ф] [★★★★★] То же деяние, связанное с вынесением незаконного приговора суда к лишению свободы или повлекшее иные тяжкие последствия, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 96"},{"d":"Уголовный кодекс РО","t":"Статья 97. Заведомо ложный донос","x":"[Р/Ф] [★★★★] Заведомо ложный донос о совершении преступления — наказывается штрафом в размере до 50.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] То же деяние, соединенное с обвинением лица в совершении тяжкого или особо тяжкого преступления, — наказывается штрафом в размере до 100.000 рублей либо лишением свободы на срок 50 месяцев.","r":"УК ст. 97"},{"d":"Уголовный кодекс РО","t":"Статья 98. Заведомо ложные показание, заключение эксперта, специалиста","x":"[Ф] [★★★★] Заведомо ложные показание свидетеля, потерпевшего либо заключение или показание эксперта, показание специалиста, в суде либо в ходе досудебного производства, — наказывается штрафом в размере до 45.000 рублей либо лишением свободы на срок 40 месяцев. Примечание. Свидетель, потерпевший, эксперт, специалист или переводчик освобождаются от уголовной ответственности, если они добровольно в ходе досудебного производства или судебного разбирательства до вынесения приговора суда или решения суда заявили о ложности данных ими показаний, заключения или заведомо неправильном переводе.","r":"УК ст. 98"},{"d":"Уголовный кодекс РО","t":"Статья 99. Отказ свидетеля или потерпевшего от дачи показаний","x":"[Р/Ф] [★★★★] Отказ свидетеля или потерпевшего от дачи показаний либо уклонение потерпевшего от прохождения освидетельствования, от производства в отношении его судебной экспертизы в случаях, когда не требуется его согласие, или от предоставления образцов почерка и иных образцов для сравнительного исследования, — наказывается штрафом в размере от 15.000 до 40.000 рублей либо лишением свободы на срок 40 месяцев.","r":"УК ст. 99"},{"d":"Уголовный кодекс РО","t":"Статья 100. Побег из места лишения свободы, из-под ареста или из-под стражи","x":"[Р/Ф] [★★★★] Побег из места лишения свободы, из-под ареста или из-под стражи, совершенный лицом, отбывающим наказание или находящимся в предварительном заключении, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 100"},{"d":"Уголовный кодекс РО","t":"Статья 100.1. Уклонение от отбывания наказания","x":"[Р/Ф] [от ★ до ★★★★★] Уклонение от отбывания наказания в местах лишения свободы, проявляющееся в неявке лица, объявленного в розыск, в органы правопорядка, — наказывается лишением свободы на срок, предусмотренный приоритетом действующего розыска, где 1 приоритет равняется 10 месяцам лишения свободы. Примечание. Относится к лицам, объявленным в розыск автоматической диспетчерской системой. В данном случае приоритет розыска статичен и не обновляется, наказание следует исходя из фактического приоритета.","r":"УК ст. 100.1"},{"d":"Уголовный кодекс РО","t":"Статья 101. Неисполнение приговора суда, решения суда или иного судебного акта, постановления следователя или прокурора","x":"[Р/Ф] [★★★★] Неисполнение или ненадлежащее исполнение приговора суда, решения суда или иного судебного акта, акта следователя или прокурора, в том числе акта реагирования, запроса или поручения таких лиц, а равно воспрепятствование их исполнению — наказывается лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] То же деяние, совершенное представителем власти, государственным служащим или служащим государственного учреждения, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 101"},{"d":"Уголовный кодекс РО","t":"Статья 102. Посягательство на жизнь сотрудника правоохранительного органа","x":"[Р/Ф] [★★★★★] Посягательство на жизнь сотрудника правоохранительного органа, военнослужащего, а равно их близких в целях воспрепятствования законной деятельности указанных лиц по охране общественного порядка и обеспечению общественной безопасности либо из мести за такую деятельность, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 102","k":"стрелял в меня какая статья ; открыл огонь по постовому ; покушение на военнослужащего ; пытался убить сотрудника ; напал на военного с оружием статья ; хотел убить меня на посту ; выстрелил в военнослужащего ; посягательство на жизнь военного ; стрелял по кпп статья ; стрелял в патруль"},{"d":"Уголовный кодекс РО","t":"Статья 103. Применение насилия в отношении представителя власти","x":"[Р/Ф] [★★★★] Применение насилия, не опасного для жизни или здоровья, либо угроза применения насилия в отношении представителя власти или его близких в связи с исполнением им своих должностных обязанностей, — наказывается штрафом в размере до 60.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] Применение насилия, опасного для жизни или здоровья, в отношении лиц, указанных в части первой настоящей статьи, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 103","k":"ударил военнослужащего статья ; напал на постового статья ; применил насилие к сотруднику ; толкнул представителя власти ; угрожал насилием военнослужащему ; избил военного какая статья ; насилие в отношении представителя власти ; ударил меня на посту статья ему ; напал на меня без оружия статья"},{"d":"Уголовный кодекс РО","t":"Статья 104. Оскорбление представителя власти","x":"[Р/Ф] [★★★] Публичное оскорбление представителя власти при исполнении им своих должностных обязанностей или в связи с их исполнением — наказывается штрафом в размере до 40.000 рублей либо лишением свободы на срок 30 месяцев. Примечание: Публичным признается оскорбление представителя власти, совершенное в СМИ, либо в группе трех и более человек, которые могли стать свидетелями данного нарушения.","r":"УК ст. 104","k":"оскорбил представителя власти статья ; обозвал военного публично ; оскорбление представителя власти ; оскорбил постового при свидетелях"},{"d":"Уголовный кодекс РО","t":"Статья 105. Неповиновение законному требованию должностного лица правоохранительного органа","x":"[Р/Ф] [★★★] Неповиновение законному распоряжению или требованию сотрудника полиции, военнослужащего, иного правоохранительного служащего по охране общественного порядка и обеспечению общественной безопасности, а равно воспрепятствование исполнению ими служебных обязанностей, — наказывается штрафом в размере до 40.000 рублей либо лишением свободы на срок 30 месяцев. [Р/Ф] [★★★★] Неповиновение законному распоряжению или требованию прокурора, следователя, — наказывается штрафом в размере до 60.000 рублей либо лишением свободы на срок 40 месяцев.","r":"УК ст. 105","k":"не подчинился требованию военнослужащего статья ; отказался выполнять требование постового статья ; неповиновение военнослужащему ; не выполнил законное требование"},{"d":"Уголовный кодекс РО","t":"Статья 106. Самоуправство","x":"[Р/Ф] [★★★] Самоуправство, то есть самовольное, вопреки установленному законом или иным нормативным правовым актом порядку совершение каких-либо действий, правомерность которых оспаривается организацией или гражданином, если такими действиями причинен существенный вред, — наказывается штрафом в размере до 35.000 рублей либо лишением свободы на срок 30 месяцев. [Р/Ф] [★★★★] То же деяние, совершенное с применением насилия или с угрозой его применения, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 106"},{"d":"Уголовный кодекс РО","t":"Статья 107. Незаконная помеха при задержании, аресте нарушителя, равно как содействие помехе задержанию, аресту нарушителя","x":"[Р/Ф] [★★★] Любые умышленные действия лица, направленные на физическое или иное воспрепятствование законным действиям представителя власти по ограничению свободы подозреваемого или обвиняемого в совершении правонарушения (преступления), — наказываются лишением свободы на срок 30 месяцев. Понятие преступлений против военной службы Преступлениями против военной службы признаются предусмотренные настоящей главой преступления против установленного порядка прохождения военной службы, совершенные военнослужащими, проходящими военную службу по призыву либо по контракту, а также гражданами, пребывающими в запасе, во время прохождения ими военных сборов.","r":"УК ст. 107","k":"мешал задержанию статья ; помеха задержанию ; сопротивлялся при задержании статья ; друг мешал задержать ; отбивал задержанного ; препятствовал задержанию"},{"d":"Уголовный кодекс РО","t":"Статья 108. Неисполнение приказа","x":"[В] [★★] Неисполнение подчиненным приказа начальника, отданного в установленном порядке, причинившее существенный вред интересам службы, — наказывается штрафом в размере до 40.000 рублей либо лишением свободы на срок 20 месяцев с обязательным лишением воинского звания (военного билета).","r":"УК ст. 108"},{"d":"Уголовный кодекс РО","t":"Статья 109. Самовольное оставление части или места службы","x":"[Р/Ф/В] [★★★] Самовольное оставление части или места службы, а равно неявка в срок без уважительных причин на службу при увольнении из части, — наказывается лишением свободы на срок 30 месяцев с обязательным лишением воинского звания (военного билета).","r":"УК ст. 109"},{"d":"Уголовный кодекс РО","t":"Статья 110. Дезертирство","x":"[Р/Ф/В] [★★★★] Дезертирство, то есть самовольное оставление части или места службы в целях уклонения от прохождения военной службы, а равно неявка в тех же целях на службу, — наказывается лишением свободы на срок 40 месяцев с обязательным лишением воинского звания (военного билета).","r":"УК ст. 110"},{"d":"Уголовный кодекс РО","t":"Статья 111. Умышленные уничтожение или повреждение военного имущества","x":"[В] [★★★★] Умышленные уничтожение или повреждение оружия, боеприпасов или предметов военной техники, — наказывается штрафом в размере до 60.000 рублей либо лишением свободы на срок 40 месяцев с обязательным лишением воинского звания (военного билета).","r":"УК ст. 111"},{"d":"Уголовный кодекс РО","t":"Статья 112. Насильственные действия в отношении начальника","x":"[В] [★★★★] Нанесение побоев или применение иного насилия в отношении начальника, совершенные во время исполнения им обязанностей военной службы или в связи с исполнением этих обязанностей, — лишением свободы на срок 40 месяцев с обязательным лишением воинского звания (военного билета).","r":"УК ст. 112"},{"d":"Уголовный кодекс РО","t":"Статья 113. Оскорбление военнослужащего","x":"[В] 1. [★★] Оскорбление одним военнослужащим другого во время исполнения или в связи с исполнением обязанностей военной службы, — наказывается штрафом в размере до 30.000 рублей либо лишением свободы на срок 20 месяцев. [В] 2. [★★★] Умышленные уничтожение или повреждение оружия, боеприпасов или предметов военной техники, — наказывается штрафом в размере до 40.000 рублей либо лишением свободы на срок 30 месяцев. Одобрен Государственной Думой 21 августа 2026 года Подписан Премьер Министром РО 21 августа 2026 года [https://docs.google.com/document/d/1bHKw9AgS-x1sD3UFkYfdKtQboHIi7IYxK49aFS8CkXY/edit?tab=t.0](https://docs.google.com/document/d/1bHKw9AgS-x1sD3UFkYfdKtQboHIi7IYxK49aFS8CkXY/edit?tab=t.0) [https://docs.google.com/document/d/187Vzf0Nnv4JthV_EMvDvur8yoguU2UU1zLWyLP0vzJ8/edit?tab=t.0](https://docs.google.com/document/d/187Vzf0Nnv4JthV_EMvDvur8yoguU2UU1zLWyLP0vzJ8/edit?tab=t.0)","r":"УК ст. 113","k":"оскорбил сослуживца статья ; военный оскорбил военного ; оскорбление военнослужащего военнослужащим"},{"d":"КоАП РО","t":"Статья 1.1. Законодательство об административных правонарушениях","x":"1. Законодательство об административных правонарушениях состоит из настоящего Кодекса. Законодательство об административных правонарушениях может также дополняться иными законами, устанавливающими перечень административных правонарушений и(или) порядок производства по ним. 2. Основным источником законодательства об административных правонарушениях признается настоящий Кодекс. В случае установления противоречия между законом, дополняющим законодательство об административных правонарушениях, и настоящим Кодексом, суд, прокурор, иное должностное лицо применяет положения настоящего Кодекса.","r":"КоАП ст. 1.1"},{"d":"КоАП РО","t":"Статья 1.2. Задачи законодательства об административных правонарушениях","x":"Задачами законодательства об административных правонарушениях являются защита личности, охрана прав и свобод человека и гражданина, охрана здоровья граждан, санитарно-эпидемиологического благополучия населения, защита общественной нравственности, охрана окружающей среды, установленного порядка осуществления государственной власти, общественного порядка и общественной безопасности, собственности, защита законных экономических интересов физических и юридических лиц, общества и государства от административных правонарушений, а также предупреждение административных правонарушений.","r":"КоАП ст. 1.2"},{"d":"КоАП РО","t":"Статья 1.3. Принцип равенства перед законом","x":"1. Лица, совершившие административные правонарушения, равны перед законом. Физические лица подлежат административной ответственности независимо от пола, расы, национальности, языка, происхождения, имущественного и должностного положения, места жительства, отношения к религии, убеждений, принадлежности к общественным объединениям, а также других обстоятельств. Юридические лица подлежат административной ответственности независимо от места нахождения, организационно-правовых форм, подчиненности, а также других обстоятельств. 2. Особые условия применения мер обеспечения производства по делу об административном правонарушении и привлечения к административной ответственности должностных лиц, выполняющих определенные государственные функции (депутатов, судей, прокуроров, сотрудников Следственного комитета РО и иных лиц), устанавливаются Конституцией РО и федеральными законами.","r":"КоАП ст. 1.3"},{"d":"КоАП РО","t":"Статья 1.4. Презумпция невиновности","x":"1. Лицо подлежит административной ответственности только за те административные правонарушения, в отношении которых установлена его вина. 2. Лицо, в отношении которого ведется производство по делу об административном правонарушении, считается невиновным, пока его вина не будет доказана в порядке, предусмотренном настоящим Кодексом, и установлена вступившим в законную силу постановлением (решением) судьи, органа, должностного лица, рассмотревших дело. 3. Лицо, привлекаемое к административной ответственности, не обязано доказывать свою невиновность, за исключением случаев, предусмотренных примечанием к настоящей статье. 4. Неустранимые сомнения в виновности лица, привлекаемого к административной ответственности, толкуются в пользу этого лица. Примечание. Положения части 3 настоящей статьи не распространяются на должностное лицо, совершившее административное правонарушение.","r":"КоАП ст. 1.4"},{"d":"КоАП РО","t":"Статья 1.5. Обеспечение законности при применении мер административного принуждения в связи с административным правонарушением","x":"1. Лицо, привлекаемое к административной ответственности, не может быть подвергнуто административному наказанию и мерам обеспечения производства по делу об административном правонарушении иначе как на основаниях и в порядке, установленных законом. 2. Применение уполномоченными на то органом или должностным лицом административного наказания и мер обеспечения производства по делу об административном правонарушении в связи с административным правонарушением осуществляется в пределах компетенции указанных органа или должностного лица в соответствии с законом. 3. При применении мер административного принуждения не допускаются решения и действия (бездействие), унижающие человеческое достоинство.","r":"КоАП ст. 1.5"},{"d":"КоАП РО","t":"Статья 1.6. Действие законодательства об административных правонарушениях во времени","x":"1. Лицо, совершившее административное правонарушение, подлежит ответственности на основании закона, действовавшего во время совершения административного правонарушения. 2. Закон, смягчающий или отменяющий административную ответственность за административное правонарушение либо иным образом улучшающий положение лица, совершившего административное правонарушение, имеет обратную силу, то есть распространяется и на лицо, которое совершило административное правонарушение до вступления такого закона в силу и в отношении которого постановление о назначении административного наказания не исполнено. Закон, устанавливающий или отягчающий административную ответственность за административное правонарушение либо иным образом ухудшающий положение лица, обратной силы не имеет. 3. В случае одновременного вступления в силу положений закона, отменяющих административную ответственность за содеянное и устанавливающих за то же деяние уголовную ответственность, лицо подлежит административной ответственности на основании закона, действовавшего во время совершения административного правонарушения. 4. Производство по делу об административном правонарушении осуществляется на основании закона, действующего во время производства по указанному делу.","r":"КоАП ст. 1.6"},{"d":"КоАП РО","t":"Статья 2.1. Административное правонарушение","x":"1. Административным правонарушением признается противоправное, виновное действие (бездействие) физического или юридического лица, за которое настоящим Кодексом или иными Федеральными законами об административных правонарушениях установлена административная ответственность. 2. Юридическое лицо признается виновным в совершении административного правонарушения, если будет установлено, что у него имелась возможность для соблюдения правил и норм, за нарушение которых настоящим Кодексом или Федеральным законом предусмотрена административная ответственность, но данным лицом не были приняты все зависящие от него меры по их соблюдению. 3. Назначение административного наказания юридическому лицу не освобождает от административной ответственности за данное правонарушение виновное физическое лицо, равно как и привлечение к административной или уголовной ответственности физического лица не освобождает от административной ответственности за данное правонарушение юридическое лицо.","r":"КоАП ст. 2.1"},{"d":"КоАП РО","t":"Статья 2.2. Формы вины","x":"1. Административное правонарушение признается совершенным умышленно, если лицо, его совершившее, осознавало противоправный характер своего действия (бездействия), предвидело его вредные последствия и желало наступления таких последствий или сознательно их допускало либо относилось к ним безразлично. 2. Административное правонарушение признается совершенным по неосторожности, если лицо, его совершившее, предвидело возможность наступления вредных последствий своего действия (бездействия), но без достаточных к тому оснований самонадеянно рассчитывало на предотвращение таких последствий либо не предвидело возможности наступления таких последствий, хотя должно было и могло их предвидеть.","r":"КоАП ст. 2.2"},{"d":"КоАП РО","t":"Статья 2.3. Административная ответственность должностных лиц","x":"Административной ответственности подлежит должностное лицо в случае совершения им административного правонарушения в связи с неисполнением либо ненадлежащим исполнением своих служебных обязанностей.","r":"КоАП ст. 2.3"},{"d":"КоАП РО","t":"Статья 2.4. Крайняя необходимость","x":"Не является административным правонарушением причинение лицом вреда охраняемым законом интересам в состоянии крайней необходимости, то есть для устранения опасности, непосредственно угрожающей личности и правам данного лица или других лиц, а также охраняемым законом интересам общества или государства, если эта опасность не могла быть устранена иными средствами и если причиненный вред является менее значительным, чем предотвращенный вред.","r":"КоАП ст. 2.4"},{"d":"КоАП РО","t":"Статья 2.5. Возможность освобождения от административной ответственности при малозначительности административного правонарушения","x":"При малозначительности совершенного административного правонарушения судья, орган, должностное лицо, уполномоченные решить дело об административном правонарушении, могут освободить лицо, совершившее административное правонарушение, от административной ответственности и ограничиться устным замечанием.","r":"КоАП ст. 2.5"},{"d":"КоАП РО","t":"Статья 2.6. Административная ответственность юридических лиц","x":"1. Юридические лица подлежат административной ответственности за совершение административных правонарушений в случаях, предусмотренных статьями раздела II настоящего Кодекса или иными Федеральными законами. 2. В случае, если в статьях разделов настоящего Кодекса не указано, что установленные статьями нормы применяются только к физическому лицу или только к юридическому лицу, данные нормы в равной мере действуют в отношении и физического, и юридического лица, за исключением случаев, если по смыслу данные нормы относятся и могут быть применены только к физическому лицу.","r":"КоАП ст. 2.6"},{"d":"КоАП РО","t":"Статья 3.1. Цели административного наказания","x":"1. Административное наказание является установленной государством мерой ответственности за совершение административного правонарушения и применяется в целях предупреждения совершения новых правонарушений как самим правонарушителем, так и другими лицами. 2. Административное наказание не может иметь своей целью унижение человеческого достоинства физического лица, совершившего административное правонарушение, или причинение ему физических страданий, а также нанесение вреда деловой репутации юридического лица.","r":"КоАП ст. 3.1"},{"d":"КоАП РО","t":"Статья 3.2. Виды административных наказаний","x":"1. За совершение административных правонарушений могут устанавливаться и применяться следующие административные наказания: а) предупреждение; б) административный штраф; в) конфискация орудия совершения или предмета административного правонарушения; г) лишение специального права, предоставленного физическому лицу; д) административный арест; е) административное приостановление деятельности. 2. В отношении юридического лица могут применяться административные наказания, перечисленные в пунктах 1 - 3, 6 части 1 настоящей статьи.","r":"КоАП ст. 3.2"},{"d":"КоАП РО","t":"Статья 3.3. Основные и дополнительные административные наказания","x":"1. Предупреждение, административный штраф, административный арест, административное приостановление деятельности могут устанавливаться и применяться только в качестве основных административных наказаний. 2. Конфискация орудия совершения или предмета административного правонарушения, лишение специального права могут устанавливаться и применяться в качестве как основного, так и дополнительного административного наказания. 3. За одно административное правонарушение может быть назначено основное либо основное и дополнительное административное наказание из наказаний, указанных в санкции применяемой статьи Особенной части настоящего Кодекса. Если санкция применяемой статьи предусматривает обязательное назначение основного и дополнительного административных наказаний, но при этом одно из них не может быть назначено лицу, в отношении которого ведется производство по делу об административном правонарушении, назначается только то из административных наказаний, которое может быть назначено указанному лицу.","r":"КоАП ст. 3.3"},{"d":"КоАП РО","t":"Статья 3.4. Предупреждение","x":"1. Предупреждение - мера административного наказания, выраженная в официальном порицании физического или юридического лица. Предупреждение выносится в письменной форме. 2. Предупреждение устанавливается за впервые совершенные административные правонарушения при отсутствии причинения вреда или возникновения угрозы причинения вреда жизни и здоровью людей, объектам животного и растительного мира, окружающей среде, безопасности государства, угрозы чрезвычайных ситуаций природного и техногенного характера, а также при отсутствии имущественного ущерба.","r":"КоАП ст. 3.4"},{"d":"КоАП РО","t":"Статья 3.5. Административный штраф","x":"1. Административный штраф является денежным взысканием, выражается в твердой денежной сумме и устанавливается для граждан в размере, не превышающем 100.000 рублей, для должностных лиц в размере, не превышающем 150.000 рублей, для юридических лиц не превышающем 1.000.000 рублей. 2. Размер административного штрафа не может быть менее пятисот рублей.","r":"КоАП ст. 3.5"},{"d":"КоАП РО","t":"Статья 3.6. Административный арест","x":"Административный арест заключается в содержании нарушителя в условиях изоляции от общества и устанавливается на срок до 24 суток. Административный арест назначается судьей, должностным лицом.","r":"КоАП ст. 3.6"},{"d":"КоАП РО","t":"Статья 4.1. Общие правила назначения административного наказания","x":"1. Административное наказание за совершение административного правонарушения назначается в пределах, установленных законом, предусматривающим ответственность за данное административное правонарушение, в соответствии с настоящим Кодексом. 2. При назначении административного наказания физическому лицу учитываются характер совершенного им административного правонарушения, личность виновного, его имущественное положение, обстоятельства, смягчающие административную ответственность, и обстоятельства, отягчающие административную ответственность. 3. Назначение административного наказания не освобождает лицо от исполнения обязанности, за неисполнение которой административное наказание было назначено. 4. Никто не может нести административную ответственность дважды за одно и то же административное правонарушение.","r":"КоАП ст. 4.1"},{"d":"КоАП РО","t":"Статья 4.2. Замена административного наказания устным предупреждением","x":"1. За впервые совершенное административное правонарушение, выявленное должностным лицом (органом), административное наказание, подлежащее применению, по решению указанных лиц может быть заменено на предупреждение, при отсутствии причинения вреда или возникновения угрозы причинения вреда жизни и здоровью людей, объектам животного и растительного мира, окружающей среде, объектам безопасности государства, угрозы чрезвычайных ситуаций природного и техногенного характера, а также при отсутствии имущественного ущерба. 2. В случае замены административного наказания на предупреждение дополнительное административное наказание, предусмотренное соответствующей статьей Особенной части настоящего Кодекса, не применяется.","r":"КоАП ст. 4.2"},{"d":"КоАП РО","t":"Статья 4.2.1. Освобождение от наказания в виде административного ареста в связи с внесением залога","x":"1. Лицо, которому за совершение административного правонарушения назначено наказание в виде административного ареста, может быть освобождено от отбывания наказания в связи с внесением залога. 2. Залог вносится либо лицом, привлеченным к административной ответственности лично, либо его представителем или законным представителем в учреждение органа государственной власти, где привлеченный отбывает наказание. 3. Залог за освобождение от наказания рассчитывается по следующему правилу: за каждые сутки административного ареста, неотбытые лицом, привлеченным к административной ответственности, залог составляет 4.000 рублей.","r":"КоАП ст. 4.2.1"},{"d":"КоАП РО","t":"Статья 4.3. Обстоятельства, смягчающие административную ответственность","x":"1. Обстоятельствами, смягчающими административную ответственность, признаются: а) раскаяние лица, совершившего административное правонарушение; б) добровольное прекращение противоправного поведения лицом, совершившим административное правонарушение; в) добровольное сообщение лицом, совершившим административное правонарушение, в орган, уполномоченный осуществлять производство по делу об административном правонарушении, о совершенном административном правонарушении; г) оказание лицом, совершившим административное правонарушение, содействия органу, уполномоченному осуществлять производство по делу об административном правонарушении; д) предотвращение лицом, совершившим административное правонарушение, вредных последствий административного правонарушения; е) добровольное возмещение лицом, совершившим административное правонарушение, причиненного ущерба или добровольное устранение причиненного вреда потерпевшему. 2. Суд, орган, должностное лицо, рассматривающие дело об административном правонарушении, могут признать смягчающими обстоятельства, не указанные в настоящем Кодексе об административных правонарушениях.","r":"КоАП ст. 4.3"},{"d":"КоАП РО","t":"Статья 4.4. Обстоятельства, отягчающие административную ответственность","x":"1. Обстоятельствами, отягчающими административную ответственность, признаются: а) продолжение противоправного поведения, несмотря на требование уполномоченных на то лиц прекратить его; б) повторное совершение однородного административного правонарушения, то есть совершение административного правонарушения в период, когда лицо считается подвергнутым административному наказанию; в) совершение административного правонарушения в составе группы лиц; г) совершение административного правонарушения в условиях чрезвычайного или военного положений, а также контр-террористической операции. 2. Обстоятельства, предусмотренные частью 1 настоящей статьи, не могут учитываться как отягчающие в случае, если указанные обстоятельства предусмотрены в качестве квалифицирующего признака административного правонарушения соответствующими нормами об административной ответственности за совершение административного правонарушения.","r":"КоАП ст. 4.4"},{"d":"КоАП РО","t":"Статья 4.5. Назначение административных наказаний за совершение нескольких административных правонарушений","x":"При совершении лицом двух и более административных правонарушений административное наказание назначается за каждое совершенное административное правонарушение.","r":"КоАП ст. 4.5"},{"d":"КоАП РО","t":"Статья 4.6. Давность привлечения к административной ответственности","x":"1. Срок давности привлечения к административной ответственности устанавливается в 15 месяцев и исчисляется со дня совершения административного правонарушения. 2. При ведущемся производстве по административному правонарушению срок давности привлечения к административной ответственности за совершенное административное правонарушение может быть продлен на основании постановления должностного лица, прокурора или суда.","r":"КоАП ст. 4.6"},{"d":"КоАП РО","t":"Статья 4.7. Возмещение имущественного ущерба и морального вреда, причиненных административным правонарушением","x":"1. Судья, рассматривая дело об административном правонарушении, вправе при отсутствии спора о возмещении имущественного ущерба одновременно с назначением административного наказания решить вопрос о возмещении имущественного ущерба. Споры о возмещении имущественного ущерба разрешаются судом в порядке гражданского судопроизводства. 2. По делу об административном правонарушении, рассматриваемому иными уполномоченными органом или должностным лицом, спор о возмещении имущественного ущерба разрешается судом в порядке гражданского судопроизводства. 3. Споры о возмещении морального вреда, причиненного административным правонарушением, рассматриваются судом в порядке гражданского судопроизводства.","r":"КоАП ст. 4.7"},{"d":"КоАП РО","t":"Статья 5.1. Нарушение трудового законодательства и иных нормативных правовых актов, содержащих нормы трудового права","x":"1. Нарушение трудового законодательства и иных нормативных правовых актов, содержащих нормы трудового права, - влечет предупреждение или наложение административного штрафа на должностных лиц в размере от 25.000 до 75.000 рублей; на юридических лиц - от 50.000 до 200.000 рублей. 2. Совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, лицом, ранее подвергнутым административному наказанию за аналогичное административное правонарушение, - влечет наложение административного штрафа на должностных лиц в размере от 50.000 до 120.000 рублей; на юридических лиц - от 100.000 до 250.000 рублей.","r":"КоАП ст. 5.1"},{"d":"КоАП РО","t":"Статья 5.2. Нарушение законодательства о собраниях, митингах, демонстрациях, шествиях и пикетировании","x":"Воспрепятствование организации или проведению собрания, митинга, демонстрации, шествия или пикетирования, проводимых в соответствии с законодательством РО, либо участию в них, а равно принуждение к участию в них - влечет наложение административного штрафа на граждан в размере от 30.000 до 50.000 рублей; на должностных лиц - от 50.000 до 150.000 рублей.","r":"КоАП ст. 5.2"},{"d":"КоАП РО","t":"Статья 5.3. Нарушение порядка рассмотрения обращений граждан","x":"Нарушение установленного законодательством РО порядка рассмотрения обращений граждан, объединений граждан, в том числе юридических лиц, должностными лицами государственных органов, государственных учреждений и иных организаций, на которые возложено осуществление публично значимых функций, - влечет наложение административного штрафа в размере от 10.000 до 50.000 рублей.","r":"КоАП ст. 5.3"},{"d":"КоАП РО","t":"Статья 5.4. Оскорбление","x":"1. [★★] Оскорбление, то есть унижение чести и достоинства другого лица, выраженное в неприличной или иной противоречащей общепринятым нормам морали и нравственности форме, - влечет наложение административного штрафа на граждан в размере от 10.000 до 25.000 рублей или административный арест на срок до 20 суток; на должностных лиц - от 30.000 до 50.000 рублей или административный арест на срок до 20 суток; на юридических лиц - от 25.000 до 100.000 рублей. 2. [★★] Оскорбление, содержащееся в публичном выступлении, публично демонстрирующемся произведении или средствах массовой информации либо совершенное публично с использованием информационно-телекоммуникационных сетей, включая сеть \"Интернет\", или в отношении нескольких лиц, в том числе индивидуально не определенных, - влечет наложение административного штрафа на граждан в размере от 12.000 до 28.000 рублей или административный арест на срок до 20 суток; на должностных лиц - от 50.000 до 100.000 рублей или административный арест на срок до 20 суток; на юридических лиц - от 85.000 до 130.000 рублей. 3. [★★] Оскорбление, совершенное лицом, замещающим государственную должность в связи с осуществлением своих полномочий (должностных обязанностей), - влечет наложение административного штрафа в размере от 90.000 до 130.000 рублей или административный арест на срок до 20 суток.","r":"КоАП ст. 5.4"},{"d":"КоАП РО","t":"Статья 5.5. Клевета","x":"Клевета, то есть распространение заведомо ложных сведений, порочащих честь и достоинство другого лица или подрывающих его репутацию, - влечет наложение административного штрафа на юридических лиц в размере от 100.000 до 200.000 рублей.","r":"КоАП ст. 5.5"},{"d":"КоАП РО","t":"Статья 6.1. Побои","x":"[★★] Нанесение побоев или совершение иных насильственных действий, причинивших физическую боль, если эти действия не содержат уголовно наказуемого деяния, - влечет наложение административного штрафа в размере от 20.000 до 50.000 рублей, либо административный арест на срок до 20 суток.","r":"КоАП ст. 6.1"},{"d":"КоАП РО","t":"Статья 6.2. Занятие проституцией","x":"[★★] Занятие проституцией - влечет наложение административного штрафа в размере от 1.000 до 10.000 рублей или административный арест на срок до 15 суток.","r":"КоАП ст. 6.2"},{"d":"КоАП РО","t":"Статья 6.3. Пропаганда нетрадиционных сексуальных отношений и (или) предпочтений, смены пола, отказа от деторождения","x":"[★★] Пропаганда нетрадиционных сексуальных отношений и (или) предпочтений, смены пола либо отказа от деторождения, выразившаяся в распространении информации и (или) совершении публичных действий, направленных на формирование нетрадиционных сексуальных установок, привлекательности нетрадиционных сексуальных отношений и (или) предпочтений, смены пола либо отказа от деторождения или искаженного представления о социальной равноценности традиционных и нетрадиционных сексуальных отношений и (или) предпочтений либо социальной равноценности рождения детей и отказа от деторождения, либо навязывание информации о нетрадиционных сексуальных отношениях и (или) предпочтениях, смене пола либо об отказе от деторождения, вызывающей интерес к таким отношениям и (или) предпочтениям, смене пола либо отказу от деторождения - влечет наложение административного штрафа на граждан в размере от 25.000 до 100.000 рублей или административный арест на срок до 20 суток; на должностных лиц - от 50.000 до 150.000 рублей.","r":"КоАП ст. 6.3"},{"d":"КоАП РО","t":"Статья 6.4. Курение в общественных местах","x":"Курение, то есть использование специальных устройств или предметов (сигарет, кальянов, вейпов и пр.) в общественных местах - влечет наложение административного штрафа в размере от 5.000 до 15.000 рублей.","r":"КоАП ст. 6.4"},{"d":"КоАП РО","t":"Статья 6.7. Воспрепятствование оказанию медицинской помощи","x":"Воспрепятствование в какой бы то ни было форме законной деятельности медицинского работника по оказанию медицинской помощи, если это действие не содержит признаков уголовно наказуемого деяния, - влечет наложение административного штрафа в размере от 10.000 до 30.000 рублей.","r":"КоАП ст. 6.7"},{"d":"КоАП РО","t":"Статья 7.1. Уничтожение или повреждение чужого имущества","x":"[★] Умышленное уничтожение или повреждение чужого имущества, если эти действия не повлекли причинение значительного ущерба, - влечет наложение административного штрафа в размере от 3.000 до 15.000 рублей или административный арест на срок до 10 суток.","r":"КоАП ст. 7.1"},{"d":"КоАП РО","t":"Статья 8.1. Управление транспортным средством, не зарегистрированным в установленном порядке","x":"Управление транспортным средством, не зарегистрированным в установленном порядке, - влечет наложение административного штрафа в размере от 3.000 до 7.000 рублей.","r":"КоАП ст. 8.1"},{"d":"КоАП РО","t":"Статья 8.2. Управление транспортным средством с нарушением правил установки на нем государственных регистрационных знаков","x":"1. Управление транспортным средством с нечитаемыми, нестандартными или установленными с нарушением требований государственного стандарта государственными регистрационными знаками, за исключением случаев, предусмотренных частью 2 настоящей статьи, - влечет предупреждение или наложение административного штрафа в размере до 5.000 рублей. 2. Управление транспортным средством без государственных регистрационных знаков, а равно управление транспортным средством без установленных на предусмотренных для этого местах государственных регистрационных знаков либо управление транспортным средством с государственными регистрационными знаками, видоизмененными или оборудованными с применением материалов, препятствующих идентификации государственных регистрационных знаков либо позволяющих их видоизменить или скрыть, - влечет наложение административного штрафа в размере от 5.000 до 18.000 рублей или лишение права управления транспортными средствами. 3. Управление транспортным средством с государственными регистрационными знаками, оборудованными с применением устройств, препятствующих идентификации государственных регистрационных знаков либо позволяющих их видоизменить или скрыть, - влечет лишение права управления транспортными средствами.","r":"КоАП ст. 8.2"},{"d":"КоАП РО","t":"Статья 8.3. Управление транспортным средством водителем, не имеющим при себе документов","x":"1. Управление транспортным средством водителем, не имеющим при себе регистрационных документов на транспортное средство - влечет предупреждение или наложение административного штрафа в размере до 3.000 рублей. 2. Управление транспортным средством водителем, не имеющим при себе документов на право управления им - влечет предупреждение или наложение административного штрафа в размере до 7.000 рублей. 3. Передача управления транспортным средством лицу, не имеющему при себе документов на право управления им, - влечет наложение административного штрафа в размере до 25.000 рублей.","r":"КоАП ст. 8.3"},{"d":"КоАП РО","t":"Статья 8.4. Нарушение правил применения ремней безопасности или мотошлемов","x":"Управление транспортным средством водителем, не пристегнутым ремнем безопасности, перевозка пассажиров, не пристегнутых ремнями безопасности, если конструкцией транспортного средства предусмотрены ремни безопасности, а равно управление мотоциклом или мопедом либо перевозка на мотоцикле пассажиров без мотошлемов или в незастегнутых мотошлемах - влечет предупреждение либо наложение административного штрафа в размере до 5.000 рублей.","r":"КоАП ст. 8.4"},{"d":"КоАП РО","t":"Статья 8.5. Управление транспортным средством водителем, не имеющим права управления транспортным средством","x":"1. Управление транспортным средством водителем, не имеющим права управления транспортным средством (за исключением учебной езды), - влечет наложение административного штрафа в размере от 15.000 до 25.000 рублей. [★★] 2. Управление транспортным средством водителем, лишенным права управления транспортными средствами, - влечет наложение административного штрафа в размере от 30.000 до 50.000 рублей, либо административный арест на срок до пятнадцати суток. 3. Передача управления транспортным средством лицу, заведомо не имеющему права управления транспортным средством (за исключением учебной езды) или лишенному такого права, - влечет наложение административного штрафа в размере 50.000 рублей.","r":"КоАП ст. 8.5"},{"d":"КоАП РО","t":"Статья 8.6. Превышение установленной скорости движения","x":"1. Превышение установленной скорости движения транспортного средства на величину более 15 км/ч - влечет наложение административного штрафа в размере до 10.000 рублей. 2. Превышение установленной скорости движения транспортного средства на величину более 40 км/ч - влечет наложение административного штрафа в размере до 25.000 рублей. 3. Превышение установленной скорости движения транспортного средства на величину более 60 км/ч - влечет наложение административного штрафа в размере до 35.000 рублей или лишение права управления транспортными средствами.","r":"КоАП ст. 8.6"},{"d":"КоАП РО","t":"Статья 8.7. Нарушение правил движения через железнодорожные пути","x":"Пересечение железнодорожного пути вне железнодорожного переезда, выезд на железнодорожный переезд при закрытом или закрывающемся шлагбауме либо остановка или стоянка на железнодорожном переезде либо проезд через нерегулируемый железнодорожный переезд, если к переезду в пределах видимости приближается поезд, - влечет наложение административного штрафа в размере 15.000 рублей.","r":"КоАП ст. 8.7"},{"d":"КоАП РО","t":"Статья 8.8. Проезд на запрещающий жест регулировщика","x":"Проезд на запрещающий жест регулировщика, - влечет наложение административного штрафа в размере 2.000 рублей.","r":"КоАП ст. 8.8"},{"d":"КоАП РО","t":"Статья 8.9. Нарушение правил проезда перекрестков","x":"Выезд на перекресток или пересечение проезжей части дороги в случае образовавшегося затора, который вынудил водителя остановиться, создав препятствие для движения транспортных средств в поперечном направлении, - влечет наложение административного штрафа в размере до 2.500 рублей.","r":"КоАП ст. 8.9"},{"d":"КоАП РО","t":"Статья 8.10. Нарушение правил расположения транспортного средства на проезжей части дороги, встречного разъезда или обгона","x":"1. Нарушение правил расположения транспортного средства на проезжей части дороги, встречного разъезда, а равно движение по обочинам или пересечение организованной транспортной или пешей колонны либо занятие места в ней - влечет наложение административного штрафа в размере до 3.500 рублей. 2. Движение по велосипедным или пешеходным дорожкам либо тротуарам - влечет наложение административного штрафа в размере до 4.750 рублей.","r":"КоАП ст. 8.10"},{"d":"КоАП РО","t":"Статья 8.11. Несоблюдение требований, предписанных дорожными знаками или разметкой проезжей части дороги","x":"1. Несоблюдение требований, предписанных дорожными знаками или разметкой проезжей части дороги - влечет предупреждение или наложение административного штрафа в размере до 2.500 рублей. 2. Движение во встречном направлении по дороге с односторонним движением - влечет наложение административного штрафа в размере до 3.000 рублей.","r":"КоАП ст. 8.11"},{"d":"КоАП РО","t":"Статья 8.12. Нарушение правил остановки или стоянки транспортных средств","x":"1. Нарушение правил остановки или стоянки транспортных средств - влечет предупреждение или наложение административного штрафа в размере до 5.000 рублей. 2. Нарушение правил остановки или стоянки транспортных средств в местах, отведенных для остановки, - влечет наложение административного штрафа в размере до 7.000 рублей.","r":"КоАП ст. 8.12"},{"d":"КоАП РО","t":"Статья 8.13. Нарушение правил пользования внешними световыми приборами, звуковыми сигналами, аварийной сигнализацией или знаком аварийной остановки","x":"Нарушение правил пользования внешними световыми приборами, звуковыми сигналами, аварийной сигнализацией или знаком аварийной остановки - влечет предупреждение или наложение административного штрафа в размере до 2.500 рублей.","r":"КоАП ст. 8.13"},{"d":"КоАП РО","t":"Статья 8.14. Нарушение Правил дорожного движения или правил эксплуатации транспортного средства, повлекшее причинение легкого или средней тяжести вреда здоровью потерпевшего","x":"1. Нарушение Правил дорожного движения или правил эксплуатации транспортного средства, повлекшее причинение легкого вреда здоровью потерпевшего, - влечет наложение административного штрафа в размере от 15.000 до 25.000 рублей или лишение права управления транспортными средствами. 2. Нарушение Правил дорожного движения или правил эксплуатации транспортного средства, повлекшее причинение средней тяжести вреда здоровью потерпевшего, - влечет наложение административного штрафа в размере от 20.000 до 37.000 рублей или лишение права управления транспортными средствами.","r":"КоАП ст. 8.14"},{"d":"КоАП РО","t":"Статья 8.15. Невыполнение требования об остановке транспортного средства","x":"[★★] Невыполнение законного требования сотрудника полиции или должностного лица федерального органа исполнительной власти, осуществляющего функции по контролю и надзору в сфере транспорта, об остановке транспортного средства, - влечет наложение административного штрафа в размере от 10.000 до 30.000 рублей или административный арест на срок до 20 суток.","r":"КоАП ст. 8.15"},{"d":"КоАП РО","t":"Статья 8.16. Нарушение Правил дорожного движения пешеходом или иным лицом, участвующим в процессе дорожного движения","x":"Нарушение пешеходом или пассажиром транспортного средства Правил дорожного движения - влечет предупреждение или наложение административного штрафа в размере до 3.000 рублей.","r":"КоАП ст. 8.16"},{"d":"КоАП РО","t":"Статья 8.17. Неуплата штрафов, выданных на автотранспортное средство.","x":"Запрещается передвижение, использование, стоянка транспортного средства, имеющего 10 и более активных (неоплаченных) штрафов - влечет эвакуацию транспортного средства на спецстоянку (штрафстоянку) и оплату повышенного административного штрафа по тарифам спецстоянки","r":"КоАП ст. 8.17"},{"d":"КоАП РО","t":"Статья 8.19. Нарушение установленных правил дорожного движения в области обязанностей пассажиров и водителей, если данное правонарушение не регулируется настоящим кодексом.","x":"Запрещается нарушение правил дорожного движения в области обязанностей водителей и пассажиров, если данное правонарушение отдельно не регулируется настоящим кодексом, - влечет наложение административного штрафа в размере от 1.500 до 20.000 рублей.","r":"КоАП ст. 8.19"},{"d":"КоАП РО","t":"Статья 8.20. Нарушение установленных правил дорожного движения в области обязанностей пешеходов и велосипедистов, если данное правонарушение не регулируется настоящим кодексом.","x":"Запрещается нарушение правил дорожного движения в области обязанностей пешеходов и велосипедистов, если данное правонарушение отдельно не регулируется настоящим кодексом, - влечет наложение административного штрафа в размере от 1.500 до 8.000 рублей.","r":"КоАП ст. 8.20"},{"d":"КоАП РО","t":"Статья 8.21. Нарушение установленных правил дорожного движения в области расположения ТС на проезжей части, если данное правонарушение не регулируется настоящим кодексом.","x":"Запрещается нарушение правил дорожного движения в области расположения ТС на проезжей части, если данное правонарушение отдельно не регулируется настоящим кодексом, - влечет наложение административного штрафа в размере от 1.500 до 10.000 рублей, и/или эвакуацию транспортного средства.","r":"КоАП ст. 8.21"},{"d":"КоАП РО","t":"Статья 8.22. Нарушение установленных правил дорожного движения в области обгона и иных схожих маневров, если данное правонарушение не регулируется настоящим кодексом.","x":"Запрещается нарушение правил дорожного движения в области обгона и иных схожих маневров, если данное правонарушение отдельно не регулируется настоящим кодексом, - влечет наложение административного штрафа в размере от 1.500 до 15.000 рублей, и/или лишение права на управление ТС.","r":"КоАП ст. 8.22"},{"d":"КоАП РО","t":"Статья 8.23. Нарушение установленных правил дорожного движения в области остановки и стоянки, если данное правонарушение не регулируется настоящим кодексом.","x":"Запрещается нарушение правил дорожного движения в области остановки и стоянки, если данное правонарушение отдельно не регулируется настоящим кодексом, - влечет наложение административного штрафа в размере от 1.500 до 10.000 рублей, и/или эвакуацию транспортного средства.","r":"КоАП ст. 8.23"},{"d":"КоАП РО","t":"Статья 8.24. Нарушение установленных правил дорожного движения в области проезда перекрестков, если данное правонарушение не регулируется настоящим кодексом.","x":"Запрещается нарушение правил дорожного движения в области проезда перекрестков, если данное правонарушение отдельно не регулируется настоящим кодексом, - влечет наложение административного штрафа в размере от 1.500 до 25.000 рублей.","r":"КоАП ст. 8.24"},{"d":"КоАП РО","t":"Статья 8.25. Иные нарушения правил дорожного движения, не установленные настоящим кодексом.","x":"Запрещается нарушение правил дорожного движения, отдельно не указанных в настоящем кодексе, - влечет наложение административного штрафа в размере от 1.500 до 20.000 рублей.","r":"КоАП ст. 8.25"},{"d":"КоАП РО","t":"Статья 9.1. Невыполнение законных требований депутата Федерального Собрания РО","x":"1. [★★] Невыполнение должностным лицом государственного органа, организации или общественного объединения законных требований депутата Федерального Собрания РО либо создание препятствий в осуществлении их деятельности - влечет наложение административного штрафа в размере от 35.000 до 55.000 рублей либо административный арест на срок до 15 суток. 2. Несоблюдение должностным лицом установленных сроков предоставления информации (документов, материалов, ответов на обращения) депутату Федерального Собрания РО - влечет наложение административного штрафа в размере от 30.000 до 70.000 рублей.","r":"КоАП ст. 9.1"},{"d":"КоАП РО","t":"Статья 9.2. Неисполнение распоряжения судьи","x":"1. [★★] Неисполнение законного распоряжения судьи о прекращении действий, нарушающих установленные в суде правила, - влечет наложение административного штрафа в размере от 10.000 до 25.000 рублей или административный арест на срок до пятнадцати суток. 2. Неисполнение законного распоряжения судебного пристава по обеспечению установленного порядка деятельности судов о прекращении действий, нарушающих установленные в суде правила, - влечет наложение административного штрафа в размере от 10.000 до 25.000 рублей.","r":"КоАП ст. 9.2"},{"d":"КоАП РО","t":"Статья 9.3. Непринятие мер по частному определению или постановлению суда, представлению судьи","x":"1. Оставление должностным лицом без рассмотрения частного определения или постановления суда, представления судьи либо непринятие мер по устранению указанных в определении, постановлении или представлении нарушений закона - влечет наложение административного штрафа в размере от 30.000 до 50.000 рублей. 2. Неисполнение или ненадлежащее рассмотрение должностным лицом частного определения или постановления суда, представления судьи - влечет наложение административного штрафа в размере от 35.000 до 55.000 рублей.","r":"КоАП ст. 9.3"},{"d":"КоАП РО","t":"Статья 9.4. Неуважение к Федеральному Собранию","x":"[★★] Неуважение к Федеральному Собранию РО, то есть нарушение установленного порядка проведения заседаний Федерального Собрания или оскорбление депутата Федерального Собрания или неисполнение законного распоряжения Председателя Федерального Собрания или иных должностных лиц, обеспечивающих безопасность заседания, если эти деяния не содержат признаков уголовно-наказуемого деяния, - влечет наложение административного штрафа в размере от 25.000 до 50.000 рублей или административный арест на срок до 20 суток.","r":"КоАП ст. 9.4"},{"d":"КоАП РО","t":"Статья 9.5. Неявка депутата на заседания Федерального Собрания","x":"1. Неявка депутата Федерального Собрания на пленарное или экстренное заседание Федерального Собрания, надлежащим образом уведомленного о таковом заседании, - влечет наложение административного штрафа в размере от 35.000 до 50.000 рублей. 2. Неявка всех заявленных депутатов от органа государственной власти или политической партии РО на экстренное или пленарное заседание Федерального Собрания РО, уведомленных надлежащим образом о таковом заседании - влечет наложение административного штрафа для юридических лиц в размере от 80.000 до 150.000 рублей.","r":"КоАП ст. 9.5"},{"d":"КоАП РО","t":"Статья 9.6. Умышленное совершение государственным служащим деяния, запрещенного нормами служебного поведения","x":"1. Оскорбительное, пренебрежительное или унижающее честь и достоинство гражданина обращение со стороны государственного служащего при исполнении им должностных обязанностей, а равно использование нецензурных слов, кличек, прозвищ или фамильярного обращения - влечет наложение административного штрафа в размере от 20.000 до 200.000 рублей. 2. Несоблюдение государственным служащим требований к внешнему виду, установленных нормативными правовыми актами РО - влечет наложение административного штрафа в размере от 10.000 до 100.000 рублей.","r":"КоАП ст. 9.6"},{"d":"КоАП РО","t":"Статья 10.1. Оскорбление представителя государственной власти","x":"[★★] Оскорбление лица, состоящего на государственной службе, в связи с исполнением им должностных обязанностей, - влечет наложение административного штрафа в размере от 10.000 до 25.000 рублей или административный арест на срок 15 суток.","r":"КоАП ст. 10.1"},{"d":"КоАП РО","t":"Статья 10.2. Отказ от уплаты административного штрафа","x":"[★★] Отказ от уплаты административного штрафа, то есть передача штрафного тикета обратно без уплаты штрафа или устный или письменный отказ лица от уплаты штрафа или игнорирование штрафного тикета, - влечет наложение административного штрафа в двукратном размере суммы неуплаченного административного штрафа, но не менее 3.000 рублей, либо административный арест на срок до 20 суток.","r":"КоАП ст. 10.2"},{"d":"КоАП РО","t":"Статья 10.3. Не рассмотрение или ненадлежащее рассмотрение акта прокурорского реагирования","x":"Не рассмотрение, а равно рассмотрение протеста прокурора, представления прокурора в нарушение установленного законом срока - влечет наложение административного штрафа в размере от 20.000 до 40.000 рублей.","r":"КоАП ст. 10.3"},{"d":"КоАП РО","t":"Статья 10.4. Заведомо ложный вызов специализированных служб","x":"Заведомо ложный вызов пожарной охраны, полиции, скорой медицинской помощи или иных специализированных служб - влечет наложение административного штрафа в размере от 3.000 до 8.000 рублей.","r":"КоАП ст. 10.4"},{"d":"КоАП РО","t":"Статья 10.5. Нарушение порядка деятельности иностранного агента","x":"1. Несообщение лицом, не включенным в реестр иностранных агентов, об осуществлении им деятельности в качестве иностранного агента - влечет наложение административного штрафа на граждан в размере от 30.000 до 50.000 рублей; на должностных лиц - в размере от 60.000 до 120.000 рублей. 2. То же деяние, совершенное юридическим лицом, - влечет наложение административного штрафа в размере от 40.000 до 110.000 рублей с административным приостановлением деятельности данного юридического лица на срок до трех месяцев. 3. Неисполнение иностранным агентом обязанности или ограничения, предусмотренного законодательством РО об иностранных агентах, если эти действия (бездействие) не содержат признаков уголовно-наказуемого деяния - влечет наложение административного штрафа на граждан в размере от 35.000 до 55.000 рублей; на должностных лиц - в размере от 60.000 до 120.000 рублей; на юридических лиц - от 100.000 до 200.000 рублей.","r":"КоАП ст. 10.5"},{"d":"КоАП РО","t":"Статья 10.6. Отказ от прохождения либо неудовлетворительное прохождение государственной проверки","x":"1. Отказ организации либо ее должностных лиц от прохождения предусмотренной законом государственной проверки, выражающийся в непредставлении необходимых документов, сведений и материалов, иные действия (бездействия), повлекшие нарушение установленной процедуры государственной проверки, - влечет наложение административного штрафа от 20.000 до 40.000 рублей; на юридических лиц - от 50.000 до 500.000 рублей. 2. Неудовлетворительное прохождение государственной проверки вследствие допущенных нарушений, препятствующих признанию ее результатов соответствующими установленным требованиям, - влечет наложение административного штрафа до 500.000 рублей юридическим лицам.","r":"КоАП ст. 10.6"},{"d":"КоАП РО","t":"Статья 10.7. Незаконный отказ в доступе должностному лицу органа исполнительной власти, осуществляющего федеральный государственный контроль (надзор) в сфере здравоохранения, к осмотру территорий, помещений организации, в отношении которой проводится государственная проверка","x":"Незаконный отказ в доступе, а равно незаконное воспрепятствование доступу должностного лица Федерального органа исполнительной власти, осуществляющего федеральный государственный контроль (надзор) в сфере здравоохранения, проводящего государственную проверку в соответствии с законодательством РО, к осмотру производственных, складских, служебных и иных помещений и территорий, находящихся в пользовании проверяемой организации - влечет наложение административного штрафа на должностных лиц в размере 25.000 рублей; на юридических лиц - от 50.000 до 100.000 рублей.","r":"КоАП ст. 10.7"},{"d":"КоАП РО","t":"Статья 11.1. Мелкое хулиганство","x":"[★★] Мелкое хулиганство, то есть нарушение общественного порядка, выражающее явное неуважение к обществу, сопровождающееся нецензурной бранью в общественных местах, оскорбительным приставанием к гражданам, а равно уничтожением или повреждением чужого имущества, - влечет наложение административного штрафа в размере от 5.000 до 20.000 рублей или административный арест на срок до пятнадцати суток.","r":"КоАП ст. 11.1"},{"d":"КоАП РО","t":"Статья 11.2. Нарушение установленного порядка организации либо проведения собрания, митинга, демонстрации, шествия или пикетирования","x":"1. Нарушение организатором публичного мероприятия установленного порядка организации либо проведения собрания, митинга, демонстрации, шествия или пикетирования, за исключением случаев, предусмотренных настоящей статьей, - влечет наложение административного штрафа в размере от 25.000 до 50.000 рублей. 2. Организация либо проведение публичного мероприятия без подачи в установленном порядке уведомления о проведении публичного мероприятия, - влечет наложение административного штрафа в размере от 30.000 до 70.000 рублей. 3. [★★] Нарушение участником публичного мероприятия установленного порядка проведения собрания, митинга, демонстрации, шествия или пикетирования - влечет наложение административного штрафа в размере от 20.000 до 35.000 рублей или административный арест на срок до 20 суток.","r":"КоАП ст. 11.2"},{"d":"КоАП РО","t":"Статья 11.3. Публичные действия, направленные на дискредитацию использования Вооруженных Сил РО","x":"1. Публичные действия, направленные на дискредитацию использования Вооруженных Сил РО в целях защиты интересов РО и ее граждан, поддержания международного мира и безопасности, в том числе публичные призывы к воспрепятствованию использования Вооруженных Сил РО в указанных целях, либо на дискредитацию исполнения государственными органами РО своих полномочий за пределами территории РО в указанных целях, а равно на дискредитацию оказания добровольческими формированиями, организациями или лицами содействия в выполнении задач, возложенных на Вооруженные Силы РО или войска национальной гвардии РО, если эти действия не содержат признаков уголовно наказуемого деяния, - влекут наложение административного штрафа в размере от 40.000 до 55.000 рублей; на юридических лиц - от 100.000 до 250.000 рублей. 2. Те же действия, сопровождающиеся призывами к проведению несанкционированных публичных мероприятий, а равно создающие угрозу причинения вреда жизни и (или) здоровью граждан, имуществу, угрозу массового нарушения общественного порядка и (или) общественной безопасности либо угрозу создания помех функционированию или прекращения функционирования объектов жизнеобеспечения, транспортной или социальной инфраструктуры, кредитных организаций, объектов энергетики, промышленности или связи, если эти действия не содержат признаков уголовно наказуемого деяния, - влекут наложение административного штрафа в размере от 50.000 до 70.000 рублей; на юридических лиц - от 200.000 до 300.000 рублей.","r":"КоАП ст. 11.3"},{"d":"КоАП РО","t":"Статья 11.4. Нарушение порядка, установленного в период действия чрезвычайного или военного положения","x":"1. [★★] Нарушение установленного режима комендантского часа, действующего в период чрезвычайного или военного положения, - влечет административный арест на срок до 20 суток или наложение административного штрафа в размере до 20.000 рублей. 2. [★★] Организация, проведение либо активное участие в публичном мероприятии (включая собрание, митинг, демонстрацию, шествие или пикетирование) в период действия чрезвычайного или военного положения - влечет административный арест на срок до 20 суток или наложение административного штрафа в размере до 35.000 рублей. 3. [★★] Отказ гражданина предъявить по требованию уполномоченного лица удостоверение личности в зоне действия чрезвычайного или военного положения - влечет административный арест на срок до 15 суток или наложение административного штрафа в размере до 15.000 рублей.","r":"КоАП ст. 11.4"},{"d":"КоАП РО","t":"Статья 11.5. Распитие в общественных местах алкогольных напитков","x":"[★] Распитие в общественных местах алкогольной продукции, а равно нахождение в общественном месте в состоянии алкогольного опьянения - влечет наложение административного штрафа в размере от 4.000 до 12.000 рублей или административный арест на срок до 10 суток. Примечание 1. Для целей настоящего Кодекса под общественным местом понимается любая территория или объект, предназначенные (используемые) для свободного доступа неопределенного круга лиц, включая (но не ограничиваясь): улицы, парки, скверы, пляжи, транспорт общего пользования, а также здания, строения, сооружения (в том числе административные, торговые, культурно-развлекательные, спортивные, медицинские и иные учреждения) и непосредственно прилегающие к ним территории.","r":"КоАП ст. 11.5"},{"d":"КоАП РО","t":"Статья 11.6. Нахождение в общественном месте в неприемлемом виде","x":"[★] Нахождение в общественном месте без любого из элементов верхней одежды, то есть с оголенным торсом и(или) низом, - влечет предупреждение или наложение административного штрафа в размере от 5.000 до 15.000 рублей или административный арест на срок 10 суток.","r":"КоАП ст. 11.6"},{"d":"КоАП РО","t":"Статья 11.7. Обнажение оружия в общественных местах","x":"[★★] Обнажение огнестрельного и (или) холодного вида оружия, специальных средств или спортивного инвентаря в общественном месте, лицом не состоящим на государственной службе в правоохранительных органах РО или не исполняющим на тот момент должностные обязанности, без обоснованной необходимости, - влечет предупреждение или наложение административного штрафа в размере от 10.000 до 20.000 рублей или административный арест на срок до 15 суток.","r":"КоАП ст. 11.7"},{"d":"КоАП РО","t":"Статья 11.8. Нарушение режима посещения закрытых территорий","x":"[★★★] Незаконное проникновение на закрытую, в соответствии с законодательством РО, территорию, равно как и нахождение на такой территории - влечет наложение административного штрафа на граждан в размере от 50.000 до 80.000 рублей либо административный арест на срок до 24 суток.","r":"КоАП ст. 11.8"},{"d":"КоАП РО","t":"Статья 12.1. Судьи и органы, уполномоченные рассматривать дела об административных правонарушениях","x":"Дела об административных правонарушениях, предусмотренных настоящим Кодексом, рассматриваются в пределах компетенции, установленной настоящим Кодексом: 1) судьями; 2) федеральными органами исполнительной власти, их структурными подразделениями, территориальными органами и структурными подразделениями территориальных органов, а также иными государственными органами в соответствии с задачами и функциями, возложенными на них федеральными законами либо нормативными правовыми актами Премьер Министра РО или Правительства РО; 3) органами прокуратуры РО, прокурорами; 4) председателем Федерального Собрания РО.","r":"КоАП ст. 12.1"},{"d":"КоАП РО","t":"Статья 12.2. Судьи","x":"Судьи уполномочены рассматривать дело о любом административном правонарушении, предусмотренном настоящим Кодексом.","r":"КоАП ст. 12.2"},{"d":"КоАП РО","t":"Статья 12.3. Органы внутренних дел (полиция)","x":"Органы внутренних дел (полиция) рассматривают дела об административных правонарушениях при непосредственном обнаружении должностными лицами органов внутренних дел (полиции) признаков административных правонарушений, за исключением правонарушений предусмотренных ст. 5.1, 5.3, 5.5, 9.1 - 9.6, 10.3, 10.5, 10.6, 10.7, 11.3 настоящего Кодекса.","r":"КоАП ст. 12.3"},{"d":"КоАП РО","t":"Статья 12.4. Органы прокуратуры (прокуроры)","x":"Органы прокуратуры РО (прокуроры) уполномочены рассматривать дело о любом административном правонарушении, предусмотренном настоящим Кодексом.","r":"КоАП ст. 12.4"},{"d":"КоАП РО","t":"Статья 12.5. Председатель Федерального Собрания РО","x":"Председатель Федерального Собрания (Государственной Думы) РО рассматривает дела об административных правонарушениях при непосредственном обнаружении им признаков административных правонарушений, предусмотренных ст. 9.1, 9.4, 9.5 настоящего Кодекса.","r":"КоАП ст. 12.5"},{"d":"КоАП РО","t":"Статья 12.6. Органы военной полиции Вооруженных Сил РО","x":"Органы военной полиции Вооруженных Сил РО рассматривают дела об административных правонарушениях при непосредственном обнаружении ими признаков административных правонарушений в отношении военнослужащих Вооруженных Сил РО.","r":"КоАП ст. 12.6"},{"d":"КоАП РО","t":"Статья 13.1. Задачи производства по делам об административных правонарушениях","x":"Задачами производства по делам об административных правонарушениях являются всестороннее, полное, объективное и своевременное выяснение обстоятельств каждого дела, разрешение его в соответствии с законом, обеспечение исполнения вынесенного постановления, а также выявление причин и условий, способствовавших совершению административных правонарушений.","r":"КоАП ст. 13.1"},{"d":"КоАП РО","t":"Статья 13.2. Доведение до сведения участников производства по делу об административном правонарушении информации о поступивших судье внепроцессуальных обращениях","x":"1. Не допускается внепроцессуальное обращение к судье, в производстве которого находится дело об административном правонарушении, либо к председателю суда, его заместителю, председателю судебного состава или председателю судебной коллегии по делам об административных правонарушениях, находящимся в производстве суда. 2. Информация о внепроцессуальных обращениях государственных органов, иных органов, организаций, должностных лиц или граждан, поступивших судье, в производстве которого находится дело об административном правонарушении, либо председателю суда, его заместителю, председателю судебного состава или председателю судебной коллегии по делам об административных правонарушениях, находящимся в производстве суда, подлежит преданию гласности и доведению до сведения участников производства по делу и не является основанием для проведения процессуальных действий или принятия процессуальных решений по делам об административных правонарушениях.","r":"КоАП ст. 13.2"},{"d":"КоАП РО","t":"Статья 13.3. Ходатайства","x":"1. Лица, участвующие в производстве по делу об административном правонарушении, имеют право заявлять ходатайства, подлежащие обязательному рассмотрению судьей, органом, должностным лицом, в производстве которых находится данное дело. 2. Ходатайство заявляется в письменной форме и подлежит немедленному рассмотрению. Решение об отказе в удовлетворении ходатайства выносится судьей, органом, должностным лицом, в производстве которых находится дело об административном правонарушении, в виде определения или решения на месте.","r":"КоАП ст. 13.3"},{"d":"КоАП РО","t":"Статья 13.4. Обстоятельства, исключающие производство по делу об административном правонарушении","x":"1. Производство по делу об административном правонарушении не может быть начато, а начатое производство подлежит прекращению при наличии хотя бы одного из следующих обстоятельств: 1) отсутствие события административного правонарушения; 2) отсутствие состава административного правонарушения; 3) действия лица в состоянии крайней необходимости; 4) издание акта амнистии, если такой акт устраняет применение административного наказания; 5) признание утратившими силу закона или его положения, устанавливающих административную ответственность за содеянное, за исключением случая одновременного вступления в силу положений закона, отменяющих административную ответственность за содеянное и устанавливающих за то же деяние уголовную ответственность; 6) истечение сроков давности привлечения к административной ответственности; 7) смерть физического лица, в отношении которого ведется производство по делу об административном правонарушении; 8) иные предусмотренные настоящим Кодексом обстоятельства, при наличии которых лицо, совершившее действия (бездействие), содержащие признаки состава административного правонарушения, освобождается от административной ответственности.","r":"КоАП ст. 13.4"},{"d":"КоАП РО","t":"Статья 13.5. Прокурорский надзор","x":"Генеральный прокурор РО и назначаемые им прокуроры осуществляют в пределах своей компетенции надзор за соблюдением Конституции РО и исполнением действующих на территории РО законов при производстве по делам об административных правонарушениях, за исключением дел, находящихся в производстве суда.","r":"КоАП ст. 13.5"},{"d":"КоАП РО","t":"Статья 13.6. Подача процессуальных документов участниками производства по делу об административном правонарушении","x":"Заявление, ходатайство, жалоба, протест и иные документы подаются участниками производства по делу об административном правонарушении в электронном виде, в том числе в форме электронного документа. Ходатайства могут быть заявлены в простой устной форме при рассмотрении дела об административном правонарушении на месте. В случае подачи заявления, ходатайства, жалобы, протеста и иных документов в электронном виде, в том числе в форме электронного документа, прилагаемые к ним документы должны быть представлены также в электронном виде, в том числе в форме электронного документа.","r":"КоАП ст. 13.6"},{"d":"КоАП РО","t":"Статья 13.7. Истребование материалов дела об административном правонарушении","x":"1. При подготовке к рассмотрению жалобы на постановление (решение) по делу об административном правонарушении судья выносит определение об истребовании материалов дела об административном правонарушении, если для рассмотрения жалобы необходимо получение указанных материалов. 2. В определении об истребовании материалов дела указываются наименование суда, сведения о деле, постановление (решение) по которому обжалуется, сведения о лице, в отношении которого вынесено постановление, статья настоящего Кодекса, предусматривающая административную ответственность за совершенное административное правонарушение, а также орган, должностное лицо или судья, в распоряжении которых находятся материалы дела. 3. Материалы дела об административном правонарушении направляются в суд, вынесший определение об их истребовании, не позднее суток со дня получения определения, если иной срок не установлен в самом определении. 4. Орган, должностное лицо или судья, в распоряжении которых находятся материалы дела об административном правонарушении, обязаны направить в суд материалы дела в полном объеме.","r":"КоАП ст. 13.7"},{"d":"КоАП РО","t":"Статья 14.1. Лицо, в отношении которого ведется производство по делу об административном правонарушении","x":"1. Лицо, в отношении которого ведется производство по делу об административном правонарушении, вправе знакомиться со всеми материалами дела, с аудио- и видеозаписями, делать выписки из материалов дела об административном правонарушении, давать объяснения, представлять доказательства, заявлять ходатайства и отводы, пользоваться юридической помощью защитника, а также иными процессуальными правами в соответствии с настоящим Кодексом. 2. Дело об административном правонарушении рассматривается с участием лица, в отношении которого ведется производство по делу об административном правонарушении. В отсутствие указанного лица дело может быть рассмотрено, если имеются данные о надлежащем извещении лица о месте и времени рассмотрения дела и если от лица не поступило ходатайство об отложении рассмотрения дела либо если такое ходатайство оставлено без удовлетворения. 3. Судья, орган, должностное лицо, рассматривающие дело об административном правонарушении, вправе признать обязательным присутствие при рассмотрении дела лица, в отношении которого ведется производство по делу об административном правонарушении. 4. Сотрудник, ведущий дело об административном правонарушении, обязан хранить доказательства оснований для возбуждения дела об административном правонарушении в течение 48 часов, запись должна быть цельная, со звуком, без элементов монтажа.","r":"КоАП ст. 14.1"},{"d":"КоАП РО","t":"Статья 14.2. Потерпевший","x":"1. Потерпевшим является физическое лицо или юридическое лицо, которым административным правонарушением причинен физический, имущественный или моральный вред. 2. Потерпевший вправе знакомиться со всеми материалами дела об административном правонарушении, с аудио- и видеозаписями, делать выписки из материалов дела об административном правонарушении, давать объяснения, представлять доказательства, заявлять ходатайства и отводы, пользоваться юридической помощью представителя, обжаловать постановление (решение) по данному делу, пользоваться иными процессуальными правами в соответствии с настоящим Кодексом. 3. Потерпевший может быть опрошен.","r":"КоАП ст. 14.2"},{"d":"КоАП РО","t":"Статья 14.3. Законные представители юридического лица","x":"1. Защиту прав и законных интересов юридического лица, в отношении которого ведется производство по делу об административном правонарушении, или юридического лица, являющегося потерпевшим, осуществляют его законные представители. 2. Законными представителями юридического лица в соответствии с настоящим Кодексом являются его руководитель, а также иное лицо, признанное в соответствии с законом или учредительными документами органом юридического лица. Полномочия законного представителя юридического лица подтверждаются документами, удостоверяющими его служебное положение. 3. Дело об административном правонарушении, совершенном юридическим лицом, рассматривается судьей с участием его законного представителя или защитника. В отсутствие указанных лиц дело может быть рассмотрено лишь в случаях, если имеются данные о надлежащем извещении лиц о месте и времени рассмотрения дела и если от них не поступило ходатайство об отложении рассмотрения дела либо если такое ходатайство оставлено без удовлетворения. 4. При рассмотрении дела об административном правонарушении, совершенном юридическим лицом, судья, орган, должностное лицо, в производстве которых находится дело об административном правонарушении, вправе признать обязательным присутствие законного представителя юридического лица.","r":"КоАП ст. 14.3"},{"d":"КоАП РО","t":"Статья 14.4. Защитник и представитель","x":"1. Для оказания юридической помощи лицу, в отношении которого ведется производство по делу об административном правонарушении, в производстве по делу об административном правонарушении может участвовать защитник, а для оказания юридической помощи потерпевшему - представитель. 2. В качестве защитника или представителя к участию в производстве по делу об административном правонарушении допускается адвокат или иное лицо. 3. Полномочия адвоката удостоверяются ордером. Полномочия иного лица, оказывающего юридическую помощь, удостоверяются доверенностью, оформленной в соответствии с законом. 4. Защитник и представитель, допущенные к участию в производстве по делу об административном правонарушении, вправе знакомиться со всеми материалами дела, с аудио- и видеозаписями, делать выписки из материалов дела об административном правонарушении, представлять доказательства, заявлять ходатайства и отводы, участвовать в рассмотрении дела, обжаловать применение мер обеспечения производства по делу, постановление (решение) по делу, пользоваться иными процессуальными правами в соответствии с настоящим Кодексом.","r":"КоАП ст. 14.4"},{"d":"КоАП РО","t":"Статья 14.5. Свидетель","x":"1. В качестве свидетеля по делу об административном правонарушении может быть вызвано лицо, которому могут быть известны обстоятельства дела, подлежащие установлению. 2. Свидетель обязан явиться по вызову судьи, органа, должностного лица, в производстве которых находится дело об административном правонарушении, и дать правдивые показания: сообщить все известное ему по делу, ответить на поставленные вопросы. 3. Свидетель вправе не свидетельствовать против себя самого, своего супруга. 4. Свидетель предупреждается об ответственности за дачу заведомо ложных показаний. 5. За отказ или за уклонение от исполнения обязанностей, предусмотренных частью 2 настоящей статьи, свидетель несет ответственность, предусмотренную законом.","r":"КоАП ст. 14.5"},{"d":"КоАП РО","t":"Статья 14.6. Прокурор","x":"1. Прокурор в пределах своих полномочий вправе: 1) возбуждать производство по делу об административном правонарушении; 2) участвовать в рассмотрении дела об административном правонарушении, представлять доказательства, заявлять ходатайства, давать заключения по вопросам, возникающим во время рассмотрения дела; 3) приносить протест на постановление (решение) по делу об административном правонарушении независимо от участия в деле, а также совершать иные предусмотренные федеральным законом действия. 2. Прокурор извещается о месте и времени рассмотрения дела об административном правонарушении, возбужденного по инициативе прокурора.","r":"КоАП ст. 14.6"},{"d":"КоАП РО","t":"Статья 15.1. Обстоятельства, подлежащие выяснению по делу об административном правонарушении","x":"По делу об административном правонарушении выяснению подлежат: 1) наличие события административного правонарушения; 2) лицо, совершившее противоправные действия (бездействие), за которые настоящим Кодексом или федеральным законом предусмотрена административная ответственность; 3) виновность лица в совершении административного правонарушения; 4) обстоятельства, смягчающие административную ответственность, и обстоятельства, отягчающие административную ответственность; 5) характер и размер ущерба, причиненного административным правонарушением; 6) обстоятельства, исключающие производство по делу об административном правонарушении; 7) иные обстоятельства, имеющие значение для правильного разрешения дела, а также причины и условия совершения административного правонарушения.","r":"КоАП ст. 15.1"},{"d":"КоАП РО","t":"Статья 15.2. Доказательства","x":"1. Доказательствами по делу об административном правонарушении являются любые фактические данные, на основании которых судья, орган, должностное лицо, в производстве которых находится дело, устанавливают наличие или отсутствие события административного правонарушения, виновность лица, привлекаемого к административной ответственности, а также иные обстоятельства, имеющие значение для правильного разрешения дела. 2. Эти данные устанавливаются объяснениями лица, в отношении которого ведется производство по делу об административном правонарушении, показаниями потерпевшего, свидетелей, иными документами, а также показаниями специальных технических средств, вещественными доказательствами. 3. Не допускается использование доказательств по делу об административном правонарушении, если указанные доказательства получены с нарушением закона.","r":"КоАП ст. 15.2"},{"d":"КоАП РО","t":"Статья 15.3. Объяснения лица, в отношении которого ведется производство по делу об административном правонарушении, показания потерпевшего и свидетелей","x":"1. Объяснения лица, в отношении которого ведется производство по делу об административном правонарушении, показания потерпевшего и свидетелей представляют собой сведения, имеющие отношение к делу и сообщенные указанными лицами в устной или письменной форме. 2. Объяснения лица, в отношении которого ведется производство по делу об административном правонарушении, показания потерпевшего и свидетелей отражаются в аудио (видео) протоколе, постановлении по делу об административном правонарушении.","r":"КоАП ст. 15.3"},{"d":"КоАП РО","t":"Статья 15.4. Вещественные доказательства","x":"1. Под вещественными доказательствами по делу об административном правонарушении понимаются орудия совершения или предметы административного правонарушения, в том числе орудия совершения или предметы административного правонарушения, сохранившие на себе его следы. 2. Вещественные доказательства в случае необходимости фотографируются или фиксируются иным установленным способом и приобщаются к делу об административном правонарушении. О наличии вещественных доказательств делается запись в протоколе об административном правонарушении или в ином протоколе, предусмотренном настоящим Кодексом.","r":"КоАП ст. 15.4"},{"d":"КоАП РО","t":"Статья 15.5. Документы","x":"1. Документы признаются доказательствами, если сведения, изложенные или удостоверенные в них организациями, их объединениями, должностными лицами и гражданами, имеют значение для производства по делу об административном правонарушении. 2. Документы могут содержать сведения, зафиксированные как в письменной, так и в иной форме. К документам относятся материалы фото- и киносъемки, звуко- и видеозаписи, информационных баз и банков данных и иные носители информации. 3. Судья, орган, должностное лицо, в производстве которых находится дело об административном правонарушении, обязаны принять необходимые меры по обеспечению сохранности документов до разрешения дела по существу, а также принять решение о них по окончании рассмотрения дела.","r":"КоАП ст. 15.5"},{"d":"КоАП РО","t":"Статья 15.6. Поручения и запросы по делу об административном правонарушении","x":"1. Для получения доказательств по делу об административном правонарушении должностное лицо, осуществляющее производство по делу об административном правонарушении, вправе направлять запросы в органы исполнительной власти и подведомственные ему учреждения, иные органы исполнительной власти либо поручения о совершении отдельных действий, предусмотренных настоящим Кодексом, должностному лицу указанного органа или учреждения. 2. Поручение либо запрос по делу об административном правонарушении подлежит исполнению не позднее чем в двухдневный срок со дня получения указанного поручения либо запроса.","r":"КоАП ст. 15.6"},{"d":"КоАП РО","t":"Статья 15.7. Истребование сведений","x":"Судья, орган, должностное лицо, в производстве которых находится дело об административном правонарушении, вправе вынести определение об истребовании сведений, необходимых для разрешения дела, в том числе сведений (информации), необходимых для расчета размера административного штрафа. Истребуемые сведения должны быть направлены в двухдневный срок со дня получения определения. При невозможности представления указанных сведений организация обязана в однодневный срок уведомить об этом в письменной форме судью, орган, должностное лицо, вынесших определение.","r":"КоАП ст. 15.7"},{"d":"КоАП РО","t":"Статья 15.8. Оценка доказательств","x":"Судья, члены коллегиального органа, должностное лицо, осуществляющие производство по делу об административном правонарушении, оценивают доказательства по своему внутреннему убеждению, основанному на всестороннем, полном и объективном исследовании всех обстоятельств дела в их совокупности. Никакие доказательства не могут иметь заранее установленную силу.","r":"КоАП ст. 15.8"},{"d":"КоАП РО","t":"Статья 16.1. Меры обеспечения производства по делу об административном правонарушении","x":"1. В целях пресечения административного правонарушения, установления личности нарушителя, составления протокола об административном правонарушении при невозможности его составления на месте выявления административного правонарушения, обеспечения своевременного и правильного рассмотрения дела об административном правонарушении и исполнения принятого по делу постановления уполномоченное лицо вправе в пределах своих полномочий применять следующие меры обеспечения производства по делу об административном правонарушении: 1) административное задержание; 2) личный досмотр, досмотр вещей, досмотр транспортного средства, находящихся при физическом лице; осмотр принадлежащих юридическому лицу помещений, территорий, находящихся там вещей и документов; 3) освидетельствование на состояние алкогольного опьянения; 4) медицинское освидетельствование на состояние алкогольного опьянения; 5) задержание транспортного средства; 6) привод; 7) отстранение от управления транспортным средством. 2. При применении мер обеспечения производства по делу об административном правонарушении, рассмотрении дела об административном правонарушении, производстве предусмотренных настоящим Кодексом процессуальных действий, а равно судья, или по его поручению секретарь судебного заседания, должностное лицо, представитель коллегиального органа, рассматривающие дело, обязаны вести полную непрерывную видеозапись фактических обстоятельств происходящего и иных сведений, имеющих значение для производства по делу и любых других процессуальных действий. Видеозапись осуществляется техническими средствами, обеспечивающими…","r":"КоАП ст. 16.1"},{"d":"КоАП РО","t":"Статья 16.2. Административное задержание","x":"1. Административное задержание - кратковременное ограничение свободы физического лица, применяемое в целях пресечения административного правонарушения, установления личности правонарушителя, составления протокола об административном правонарушении, назначения административного наказания либо обеспечения исполнения постановления по делу об административном правонарушении, если иное не установлено настоящим Кодексом. 2. Применением административного задержания признается также кратковременное ограничение свободы физического лица, выраженное в обязательном требовании следовать за должностным лицом, оставаться в определенном месте либо не покидать место совершения административного правонарушения на время производства необходимых процессуальных действий, предусмотренных настоящим Кодексом. 3. Административное задержание вправе осуществлять должностные лица органов внутренних дел (полиции), органов Федеральной Службы Безопасности РО, органов военной полиции Вооруженных Сил РО.","r":"КоАП ст. 16.2"},{"d":"КоАП РО","t":"Статья 16.2.1. Порядок административного задержания подозреваемого","x":"1. Задержание лица производится в следующей последовательности: а) применить специальные средства с целью ограничить свободу лица; б) предъявить свое служебное удостоверение или иной идентификационный знак, подтверждающий принадлежность к органам государственной власти; в) на усмотрение сотрудника, проводящего задержание, провести обыск; г) разъяснить основания задержания и права, установленные частью 2 статьи 16.2.1 настоящего Кодекса; д) доставить подозреваемого в территориальный орган власти, отдел внутренних дел или иное место для дознания или следствия; е) провести идентификацию личности задержанного и проверку на принадлежность задержанного к государственным органам; ж) реализовать права задержанного (на ожидание ответа адвоката отводится 3 минуты, на его приезд - 7. Задержанный вправе выбрать между государственным и частным защитником. На звонок и разговор по телефону отводится 2 минуты); з) в случае, если задержанный является государственным служащим, уведомить уполномоченные органы о задержании согласно ст. 16.2.2 настоящего Кодекса; з) произвести следственные действия, если в этом есть необходимость. 2. В рамках административного задержания лицо имеет право хранить молчание и не свидетельствовать против себя и своего супруга, знакомиться с материалами дела, пользоваться юридической помощью защитника (адвоката), право запросить бесплатного защитника, осуществлять телефонный звонок и разговор длительностью до 2 минут, заявлять ходатайства и отводы.","r":"КоАП ст. 16.2.1","k":"порядок административного задержания ; права при административном задержании ; что зачитать при административном задержании ; хранить молчание защитник звонок 2 минуты ; административное задержание последовательность"},{"d":"КоАП РО","t":"Статья 16.2.2. Особый порядок административного задержания","x":"1. В случае, если задержанное лицо состоит на государственной службе РО и (или) является должностным лицом органа государственной власти, государственного органа, после доставления задержанного лица в место рассмотрения дела незамедлительно вызывается прокурор и вышестоящее должностное лицо (руководитель) задержанного лица. 2. На время ожидания ответа указанных лиц процессуальный срок, установленный ч. 1 ст. 16.2.2 настоящего Кодекса, приостанавливается, но не более чем на 10 минут. 3. При прибытии прокурора должностное лицо, осуществляющее административное задержание, передает прокурору все материалы дела об административном правонарушении. Прокурор заслушивает объяснения сторон по делу, знакомится с материалами дела, после чего дает оценку правомерности задержания, устанавливает наличие или отсутствие состава административного правонарушения в действиях (бездействии) задержанного лица и выносит одно из следующих решений: 1) о назначении административного наказания, определяя вид и размер наказания; 2) об освобождении лица, подвергнутого административному задержанию. 4. В случае невозможности прибытия прокурора в 10-минутный срок с момента его вызова задержанное лицо подлежит освобождению, а все имеющиеся материалы дела об административном правонарушении - передаче в прокуратуру РО.","r":"КоАП ст. 16.2.2"},{"d":"КоАП РО","t":"Статья 16.3. Личный досмотр, досмотр вещей, досмотр транспортного средства, находящихся при физическом лице, осмотр принадлежащих юридическому лицу помещений, территорий, находящихся там вещей и документов","x":"Личный досмотр, досмотр вещей, находящихся при физическом лице, то есть обследование вещей, проводимое без нарушения их конструктивной целостности, осмотр принадлежащих юридическому лицу или индивидуальному предпринимателю используемых для осуществления предпринимательской деятельности помещений, территорий и находящихся там вещей и документов производится должностными лицами, производящими производство по делу об административном правонарушении, за совершение которого предусмотрено наказание в виде административного ареста.","r":"КоАП ст. 16.3","k":"что такое личный досмотр ; досмотр вещей без нарушения целостности ; чем досмотр отличается от обыска ; досмотр транспортного средства понятие"},{"d":"КоАП РО","t":"Статья 16.4. Отстранение от управления транспортным средством, освидетельствование на состояние алкогольного опьянения и медицинское освидетельствование на состояние опьянения","x":"1. Лицо, которое управляет транспортным средством соответствующего вида и в отношении которого имеются достаточные основания полагать, что это лицо находится в состоянии опьянения, подлежит отстранению от управления транспортным средством до устранения причины отстранения. 2. Отстранение от управления транспортным средством соответствующего вида, освидетельствование на состояние алкогольного опьянения, направление на медицинское освидетельствование на состояние опьянения осуществляются должностными лицами, которым предоставлено право государственного надзора и контроля за безопасностью движения и эксплуатации транспортного средства соответствующего вида, с применением видеозаписи. 3. Критерии, при наличии которых имеются достаточные основания полагать, что лицо находится в состоянии опьянения и подлежит направлению на медицинское освидетельствование, и порядок проведения медицинского освидетельствования на состояние опьянения устанавливаются федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере здравоохранения.","r":"КоАП ст. 16.4"},{"d":"КоАП РО","t":"Статья 16.5. Задержание транспортного средства","x":"1. В целях пресечения нарушений правил дорожного движения, в том числе нарушений, предусмотренных в части несоблюдения требований, предписанных дорожными знаками или разметкой, запрещающими остановку или стоянку транспортных средств, правил эксплуатации, использования транспортного средства и управления транспортным средством соответствующего вида, применяется задержание (эвакуация) транспортного средства, то есть исключение транспортного средства из процесса перевозки людей и грузов путем перемещения его при помощи другого транспортного средства и помещения на свободную парковку общего пользования. 2. Задержание транспортного средства прекращается непосредственно на месте задержания транспортного средства в присутствии лица, которое может управлять данным транспортным средством, если причина задержания транспортного средства устранена до начала движения транспортного средства и (или) уплачен административный штраф.","r":"КоАП ст. 16.5"},{"d":"КоАП РО","t":"Статья 16.6. Привод","x":"1. В случаях неявки лица на рассмотрение дела об административном правонарушении, при условии что его явка признана судьей, органом, должностным лицом обязательной, применяется привод физического лица либо законного представителя юридического лица, в отношении которых ведется производство по делу об административном правонарушении, привлекаемого к административной ответственности, а также свидетеля. 2. Привод осуществляется органом внутренних дел (полицией), органом федеральной службы безопасности на основании определения указанного органа, иного органа, должностного лица, рассматривающих дело об административном правонарушении, в порядке, установленном федеральным органом исполнительной власти в области внутренних дел.","r":"КоАП ст. 16.6"},{"d":"КоАП РО","t":"Статья 17.1. Возбуждение дела об административном правонарушении","x":"1. Поводами к возбуждению дела об административном правонарушении являются: 1) непосредственное обнаружение должностными лицами, уполномоченными составлять протоколы об административных правонарушениях, достаточных данных, указывающих на наличие события административного правонарушения; 2) поступившие из правоохранительных органов, а также из других государственных органов, от общественных объединений материалы, содержащие данные, указывающие на наличие события административного правонарушения; 3) сообщения и заявления физических и юридических лиц, а также сообщения в средствах массовой информации, содержащие данные, указывающие на наличие события административного правонарушения; 4) фиксация административного правонарушения в области дорожного движения работающими в автоматическом режиме специальными техническими средствами, имеющими функции фото- и киносъемки, видеозаписи, или средствами фото- и киносъемки, видеозаписи. 2. Указанные в части 1 настоящей статьи материалы, сообщения, заявления подлежат рассмотрению должностными лицами, уполномоченными составлять протоколы об административных правонарушениях. 3. Дело об административном правонарушении может быть возбуждено должностным лицом, уполномоченным составлять протоколы об административных правонарушениях, только при наличии хотя бы одного из поводов, предусмотренных частью 1 настоящей статьи, и достаточных данных, указывающих на наличие события административного правонарушения. 4. Дело об административном правонарушении считается возбужденным с момента: 1) применения мер обеспечения производства по делу об…","r":"КоАП ст. 17.1"},{"d":"КоАП РО","t":"Статья 17.2. Протокол об административном правонарушении","x":"1. О совершении административного правонарушения составляется протокол, за исключением случаев, предусмотренных статьями 17.6, 18.6 настоящего Кодекса. 2. В протоколе об административном правонарушении указываются дата и место его составления, должность, имя и фамилия лица, составившего протокол, сведения о лице, в отношении которого возбуждено дело об административном правонарушении, фамилии, имена, адреса места жительства свидетелей и потерпевших, если имеются свидетели и потерпевшие, место, время совершения и событие административного правонарушения, статья настоящего Кодекса или Федерального закона, предусматривающая административную ответственность за данное административное правонарушение, объяснение физического лица или законного представителя юридического лица (при наличии), в отношении которых возбуждено дело, иные сведения, необходимые для разрешения дела. 3. При составлении протокола об административном правонарушении физическому лицу или законному представителю юридического лица, в отношении которых возбуждено дело об административном правонарушении, а также иным участникам производства по делу разъясняются их права и обязанности, предусмотренные настоящим Кодексом. 4. Физическому лицу или законному представителю юридического лица, в отношении которых возбуждено дело об административном правонарушении, по их ходатайству должна быть предоставлена возможность ознакомления с протоколом об административном правонарушении.","r":"КоАП ст. 17.2"},{"d":"КоАП РО","t":"Статья 17.3. Должностные лица, уполномоченные составлять протоколы об административных правонарушениях","x":"1. Протоколы об административных правонарушениях, предусмотренных настоящим Кодексом, составляются должностными лицами органов, уполномоченных рассматривать дела об административных правонарушениях в соответствии с главой 12 настоящего Кодекса, в пределах компетенции соответствующего органа. 2. Помимо случаев, предусмотренных частью 1 настоящей статьи, протоколы об административных правонарушениях вправе составлять должностные лица федеральных органов исполнительной власти, их структурных подразделений и территориальных органов, должностные лица иных государственных органов в соответствии с задачами и функциями, возложенными на них федеральными законами либо нормативными правовыми актами Премьер Министра РО или Правительства РО: 1) Федеральный орган исполнительной власти, осуществляющий федеральный государственный контроль (надзор) в сфере юстиции, об административных правонарушениях, предусмотренных ст. 5.1, 5.3, 6.4, 9.1, 9.2, 9.3, 9.4, 9.5, 10.1, 10.2, 10.4, 10.7, 10.8, 11.2, 11.3, 11.9 настоящего Кодекса; 2) Федеральный орган исполнительной власти, осуществляющий федеральный государственный контроль (надзор) в сфере здравоохранения, об административных правонарушениях, предусмотренных ст. ст. 6.2, 6.5, 6.7, 10.9 настоящего Кодекса.","r":"КоАП ст. 17.3"},{"d":"КоАП РО","t":"Статья 17.4. Возбуждение дел об административных правонарушениях прокурором","x":"1. При осуществлении надзора за соблюдением Конституции РО и исполнением законов, действующих на территории РО, прокурор вправе возбудить дело о любом административном правонарушении, ответственность за которое предусмотрена настоящим Кодексом или Федеральным законом. 2. О возбуждении дела об административном правонарушении прокурором выносится постановление, которое должно содержать сведения, предусмотренные статьей 17.2 настоящего Кодекса. Указанное постановление выносится в сроки, установленные статьей 17.5 настоящего Кодекса.","r":"КоАП ст. 17.4"},{"d":"КоАП РО","t":"Статья 17.5. Сроки составления протокола об административном правонарушении","x":"1. Протокол об административном правонарушении составляется немедленно после выявления совершения административного правонарушения, за исключением случаев, предусмотренных частями 2 и 3 настоящей статьи, ст. 17.6 настоящего Кодекса. 2. В случае, если требуется дополнительное выяснение обстоятельств дела либо данных о физическом лице или сведений о юридическом лице, в отношении которых возбуждается дело об административном правонарушении, протокол об административном правонарушении составляется в течение суток с момента выявления административного правонарушения. 3. В случае проведения административного расследования протокол об административном правонарушении составляется по окончании расследования в сроки, предусмотренные законодательством.","r":"КоАП ст. 17.5"},{"d":"КоАП РО","t":"Статья 17.6. Назначение административного наказания без составления протокола","x":"В случае, если непосредственно после совершения физическим лицом административного правонарушения уполномоченным на то должностным лицом назначается административное наказание в виде предупреждения, административного штрафа или административного ареста, протокол об административном правонарушении не составляется, а выносится решение по делу об административном правонарушении в порядке ст. 18.6 настоящего Кодекса.","r":"КоАП ст. 17.6"},{"d":"КоАП РО","t":"Статья 17.7. Административное расследование","x":"1. При необходимости проведения административного расследования осуществляются экспертиза и иные процессуальные действия, требующие значительных временных затрат. Под административным расследованием понимается комплекс требующих значительных временных затрат процессуальных действий, направленных на выяснение всех обстоятельств административного правонарушения, их фиксирование, юридическую квалификацию и процессуальное оформление. Проведение административного расследования должно состоять из реальных действий, направленных на получение необходимых сведений, в том числе путем проведения экспертизы, установления потерпевших, свидетелей, допроса лиц, проживающих в другой местности. 2. Решение о возбуждении дела об административном правонарушении и проведении административного расследования принимается должностным лицом, уполномоченным в соответствии со статьей 17.3 настоящего Кодекса составлять протокол об административном правонарушении, в виде определения, а прокурором - в виде постановления немедленно после выявления факта совершения административного правонарушения. 3. В определении о возбуждении дела об административном правонарушении и проведении административного расследования указываются дата и место составления определения, должность, фамилия и инициалы лица, составившего определение, повод для возбуждения дела об административном правонарушении, данные, указывающие на наличие события административного правонарушения, статья настоящего Кодекса либо Федерального закона, предусматривающая административную ответственность за данное административное правонарушение. При…","r":"КоАП ст. 17.7"},{"d":"КоАП РО","t":"Статья 17.8. Направление протокола (постановления прокурора) об административном правонарушении для рассмотрения дела об административном правонарушении","x":"1. Протокол (постановление прокурора) об административном правонарушении и другие материалы дела об административном правонарушении направляются судье, в орган, должностному лицу, уполномоченным рассматривать дело об административном правонарушении, незамедлительно с момента составления протокола (вынесения постановления) об административном правонарушении. 2. В случае, если протокол об административном правонарушении составлен неправомочным лицом, а также в иных случаях, предусмотренных настоящим Кодексом, недостатки протокола и других материалов дела об административном правонарушении устраняются в срок не более суток со дня их поступления (получения) от судьи, органа, должностного лица, рассматривающих дело об административном правонарушении. Материалы дела об административном правонарушении с внесенными в них изменениями и дополнениями возвращаются указанным судье, органу, должностному лицу в течение суток со дня устранения соответствующих недостатков.","r":"КоАП ст. 17.8"},{"d":"КоАП РО","t":"Статья 18.1. Подготовка к рассмотрению дела об административном правонарушении","x":"Судья, орган, должностное лицо при подготовке к рассмотрению дела об административном правонарушении выясняют следующие вопросы: 1) относится ли к их компетенции рассмотрение данного дела; 2) имеются ли обстоятельства, исключающие возможность рассмотрения данного дела судьей, членом коллегиального органа, должностным лицом; 3) правильно ли составлены протокол об административном правонарушении и другие протоколы, предусмотренные настоящим Кодексом, а также правильно ли оформлены иные материалы дела; 4) имеются ли обстоятельства, исключающие производство по делу; 5) достаточно ли имеющихся по делу материалов для его рассмотрения по существу; 6) имеются ли ходатайства и отводы.","r":"КоАП ст. 18.1"},{"d":"КоАП РО","t":"Статья 18.2. Отвод судьи, члена коллегиального органа, должностного лица","x":"1. Судья, член коллегиального органа, должностное лицо, на рассмотрение которых передано дело об административном правонарушении, не могут рассматривать данное дело в случае, если это лицо: 1) является родственником лица, в отношении которого ведется производство по делу об административном правонарушении, потерпевшего, законного представителя физического или юридического лица, защитника или представителя; 2) лично, прямо или косвенно заинтересовано в разрешении дела. 2. При наличии обстоятельств, предусмотренных частью 1 настоящей статьи, судья, член коллегиального органа, должностное лицо обязаны заявить самоотвод. Заявление о самоотводе подается председателю соответствующего суда, руководителю коллегиального органа, вышестоящему должностному лицу. 3. При наличии обстоятельств, предусмотренных частью 1 настоящей статьи, лицо, в отношении которого ведется производство по делу об административном правонарушении, потерпевший, законный представитель физического или юридического лица, защитник, представитель, прокурор вправе заявить отвод судье, члену коллегиального органа, должностному лицу, который разрешается этим же лицом.","r":"КоАП ст. 18.2"},{"d":"КоАП РО","t":"Статья 18.3. Назначение дела об административном правонарушении к рассмотрению","x":"1. Судья, орган, должностное лицо, производящее производство по делу об административном правонарушении, установив в порядке письменного производства, что дело достаточно подготовлено для его рассмотрения по существу, выносит определение о назначении дела к рассмотрению, в котором указывает: дату и место вынесения определения; должностное лицо, вынесшее определение; место рассмотрения дела об административном правонарушении; дату и время рассмотрения дела об административном правонарушении; лица, вызванные на рассмотрение дела об административном правонарушении. 2. Определение о назначении дела об административном правонарушении к рассмотрению выносится не позднее чем за 20 часов до времени рассмотрения дела, о чем лица, вызванные на рассмотрение дела, уведомляются не позднее чем за 12 часов до времени рассмотрения дела.","r":"КоАП ст. 18.3"},{"d":"КоАП РО","t":"Статья 18.4. Рассмотрение дела об административном правонарушении","x":"1. Дело об административном правонарушении рассматривается в следующем порядке: 1) объявляется, кто рассматривает дело, какое дело подлежит рассмотрению, кто и на основании какого закона привлекается к административной ответственности; 2) устанавливается факт явки лиц, вызванных на рассмотрение дела; 3) проверяются полномочия законных представителей физического или юридического лица, защитника и представителя; 4) выясняется, извещены ли участники производства по делу в установленном порядке, выясняются причины неявки участников производства по делу и принимается решение о рассмотрении дела в отсутствие указанных лиц либо об отложении рассмотрения дела; 5) разъясняются лицам, участвующим в рассмотрении дела, их права и обязанности; 6) рассматриваются заявленные отводы и ходатайства; 7) стороны по делу озвучивают вступительное слово; 8) опрашиваются свидетели, потерпевшие по делу, лицо, в отношении которого ведется производство по делу; 9) стороны по делу выступают в прениях.","r":"КоАП ст. 18.4"},{"d":"КоАП РО","t":"Статья 18.5. Решение по делу об административном правонарушении","x":"1. По результатам рассмотрения дела об административном правонарушении судья, орган, должностное лицо выносит одно из следующих решений: постановление по делу об административном правонарушении, которое должно содержать: а) должность, фамилию, имя судьи, должностного лица, наименование и состав коллегиального органа, вынесших постановление, их адрес; б) дату и место рассмотрения дела; в) сведения о лице, в отношении которого рассмотрено дело; г) обстоятельства, установленные при рассмотрении дела; д) статью настоящего Кодекса или Федерального закона, предусматривающую административную ответственность за совершение административного правонарушения, либо основания прекращения производства по делу; е) мотивированное решение по делу; ё) срок и порядок обжалования постановления; постановление о прекращении производства по делу об административном правонарушении в случае: а) наличия хотя бы одного из основаций, предусмотренных ч. 1 ст. 13.4 настоящего Кодекса; б) объявления устного замечания в соответствии со статьей 2.5 настоящего Кодекса. 2. Если при решении вопроса о назначении судьей административного наказания за административное правонарушение одновременно решается вопрос о возмещении имущественного ущерба, то в постановлении по делу об административном правонарушении указываются размер ущерба, подлежащего возмещению, сроки и порядок его возмещения. 3. Постановление по делу об административном правонарушении, вынесенное коллегиальным органом, принимается простым большинством голосов членов коллегиального органа, присутствующих на заседании. 4. Постановление по делу об…","r":"КоАП ст. 18.5"},{"d":"КоАП РО","t":"Статья 18.6. Особый порядок рассмотрения дела об административном правонарушении","x":"1. В случае, предусмотренном статьей 17.6 настоящего Кодекса, должностное лицо на месте либо в помещении органа государственной власти, если лицо, в отношении которого ведется производство по делу об административном правонарушении, задержано в порядке ст. ст. 16.2, 16.2.1 настоящего Кодекса, заслушивает объяснения сторон, после чего в устной форме выносит одно из следующих решений: 1) о признании лица, в отношении которого ведется производство по делу об административном правонарушении, виновным в совершении административного правонарушения и назначении ему наказания; 2) о прекращении дела об административном правонарушении и объявлении устного замечания на основании ст. 2.5 настоящего Кодекса; 3) о прекращении дела об административном правонарушении по одному или нескольким основаниям, предусмотренным ч. 1 ст. 13.4 настоящего Кодекса. 2. В случае, предусмотренном статьей 17.6 настоящего Кодекса, если лицо, в отношении которого ведется производство по делу об административном правонарушении, задержано и состоит на государственной службе РО и (или) является должностным лицом органа государственной власти, государственного органа, то дело об административном правонарушении рассматривается в порядке ст. 16.2.2 настоящего Кодекса.","r":"КоАП ст. 18.6"},{"d":"КоАП РО","t":"Статья 19.1. Право на обжалование постановления или решения по делу об административном правонарушении","x":"1. Постановление или решение по делу об административном правонарушении может быть обжаловано лицами, указанными в статьях 14.1 - 14.6 настоящего Кодекса: 1) вынесенное судьей - в вышестоящий суд; 2) вынесенное коллегиальным органом - в городской (окружной) суд по месту нахождения коллегиального органа; 3) вынесенное должностным лицом - в вышестоящий орган, вышестоящему должностному лицу, в прокуратуру либо в суд по месту рассмотрения дела. 2. Постановление или решение по делу об административном правонарушении, вынесенное судьей, может быть также обжаловано в вышестоящий суд органом, должностным лицом, которое составило протокол об административном правонарушении настоящего Кодекса. 3. В случае, если жалоба на постановление или решение по делу об административном правонарушении поступила в суд и в вышестоящий орган, вышестоящему должностному лицу, жалобу рассматривает суд. По результатам рассмотрения жалобы выносится решение. 4. Определение об отказе в возбуждении дела об административном правонарушении обжалуется в соответствии с правилами, установленными настоящей главой.","r":"КоАП ст. 19.1"},{"d":"КоАП РО","t":"Статья 19.2. Порядок подачи жалобы на постановление по делу об административном правонарушении","x":"1. Жалоба на решение по делу об административном правонарушении подается непосредственно в соответствующий суд, вышестоящий орган, вышестоящему должностному лицу в течение 48 часов с момента вынесения решения. 2. В случае, если рассмотрение жалобы не относится к компетенции судьи, должностного лица, которым обжаловано постановление по делу об административном правонарушении, жалоба направляется на рассмотрение по подведомственности в течение суток. 3. Жалоба на постановление по делу об административном правонарушении государственной пошлиной не облагается.","r":"КоАП ст. 19.2"},{"d":"КоАП РО","t":"Статья 19.3. Решение по жалобе на постановление по делу об административном правонарушении","x":"По результатам рассмотрения жалобы на постановление по делу об административном правонарушении выносится одно из следующих решений: 1) об оставлении постановления без изменения, а жалобы без удовлетворения; 2) об изменении постановления, если при этом не усиливается административное наказание или иным образом не ухудшается положение лица, в отношении которого вынесено постановление; 3) об отмене постановления и о прекращении производства по делу при наличии оснований, предусмотренных п. 2 ч. 1 ст. 18.5 настоящего Кодекса, а также при недоказанности обстоятельств, на основании которых было вынесено постановление; 4) об отмене постановления и о возвращении дела на новое рассмотрение судье, в орган, должностному лицу, правомочным рассмотреть дело, в случаях существенного нарушения процессуальных требований, предусмотренных настоящим Кодексом, если это не позволило всесторонне, полно и объективно рассмотреть дело, а также в связи с необходимостью применения закона об административном правонарушении, влекущем назначение более строгого административного наказания, если потерпевшим по делу подана жалоба на мягкость примененного административного наказания; 5) об отмене постановления и о направлении дела на рассмотрение по подведомственности, если при рассмотрении жалобы установлено, что постановление было вынесено неправомочными судьей, органом, должностным лицом.","r":"КоАП ст. 19.3"},{"d":"КоАП РО","t":"Статья 19.4. Пересмотр решения, вынесенного по жалобе на постановление по делу об административном правонарушении","x":"1. Постановление по делу об административном правонарушении, вынесенное должностным лицом, и (или) решение вышестоящего должностного лица по жалобе на это постановление могут быть обжалованы в суд по месту рассмотрения жалобы, а затем в вышестоящий суд. 2. Постановление по делу об административном правонарушении, вынесенное коллегиальным органом, и (или) решение судьи по жалобе на это постановление могут быть обжалованы в вышестоящий суд. 3. Подача последующих жалоб на постановление по делу об административном правонарушении и (или) решения по жалобе на это постановление, их рассмотрение и разрешение осуществляются в порядке и в сроки, установленные статьями 19.2 - 19.3 настоящего Кодекса. 4. Решение суда по жалобе на вынесенное должностным лицом постановление по делу об административном правонарушении может быть обжаловано помимо участника производства органом, должностным лицом, которое вынесло такое постановление.","r":"КоАП ст. 19.4"},{"d":"КоАП РО","t":"Статья 19.5. Решение по жалобе на решение по жалобе на постановление по делу об административном правонарушении","x":"По результатам рассмотрения жалобы на решение по жалобе на постановление по делу об административном правонарушении выносится одно из следующих решений: 1) об оставлении постановления и решения без изменения, а жалобы без удовлетворения; 2) об изменении постановления или решения, если при этом не усиливается административное наказание или иным образом не ухудшается положение лица, в отношении которого вынесено постановление; 3) об отмене решения и направлении жалобы на постановление по делу на новое рассмотрение уполномоченному на это лицу; 4) об отмене решения и постановления и направлении дела об административном правонарушении на рассмотрение уполномоченному на это лицу. Одобрен Государственной Думой 21 августа 2026 года Подписан Премьер-Министром РО 21 августа 2026 года","r":"КоАП ст. 19.5"},{"d":"УПК РО","t":"Статья 1. Законы, определяющие порядок уголовного судопроизводства","x":"ч. 1. Порядок уголовного процесса на территории РО устанавливается настоящим Кодексом, основанным на Конституции РО. ч. 2. Порядок уголовного процесса, установленный настоящим Кодексом, является обязательным для судов, органов прокуратуры, органов предварительного следствия и органов дознания, а также иных участников уголовного судопроизводства.","r":"УПК ст. 1"},{"d":"УПК РО","t":"Статья 2. Действие процессуального закона во времени","x":"При производстве по уголовному делу применяется процессуальный закон, действующий во время производства соответствующего процессуального действия или принятия процессуального решения, если иное не установлено настоящим Кодексом.","r":"УПК ст. 2"},{"d":"УПК РО","t":"Статья 3. Назначение уголовного процесса","x":"ч. 1. Уголовный процесс имеет своим назначением: 1) защиту прав и законных интересов лиц и организаций, потерпевших от преступлений; 2) защиту личности от незаконного и необоснованного обвинения, осуждения, ограничения ее прав и свобод. ч. 2. Уголовное преследование и назначение виновным справедливого наказания в той же мере отвечают назначению уголовного судопроизводства, что и отказ от уголовного преследования невиновных, освобождение их от наказания, реабилитация каждого, кто необоснованно подвергся уголовному преследованию.","r":"УПК ст. 3"},{"d":"УПК РО","t":"Статья 4. Разумный срок уголовного процесса","x":"ч. 1. Уголовный процесс осуществляется в разумный срок. ч. 2. Уголовный процесс осуществляется в сроки, установленные настоящим Кодексом. Продление этих сроков допустимо в случаях и в порядке, которые предусмотрены настоящим Кодексом, но уголовное преследование, назначение наказания и прекращение уголовного преследования должны осуществляться в разумный срок. ч. 3. Обстоятельства, связанные с организацией работы органов следствия, прокуратуры и суда, а также рассмотрение уголовного дела различными инстанциями не может приниматься во внимание в качестве оснований для превышения разумных сроков осуществления уголовного процесса.","r":"УПК ст. 4"},{"d":"УПК РО","t":"Статья 5. Законность при производстве по уголовному делу","x":"ч. 1. Суд, прокурор, следователь, дознаватель не вправе применять закон, противоречащий настоящему Кодексу. ч. 2. Суд, прокурор, следователь, дознаватель, установив в ходе производства по уголовному делу несоответствие закона или иного нормативного правового акта настоящему Кодексу, принимает решение в соответствии с настоящим Кодексом. ч. 3. Нарушение норм настоящего Кодекса судом, прокурором, следователем, дознавателем в ходе уголовного процесса влечет за собой признание недопустимыми полученных таким путем доказательств. ч. 4. Определения суда, постановления судьи, прокурора, следователя, дознавателя должны быть законными, обоснованными и мотивированными.","r":"УПК ст. 5"},{"d":"УПК РО","t":"Статья 6. Уважение чести и достоинства личности","x":"ч. 1. В ходе уголовного процесса запрещаются осуществление действий и принятие решений, унижающих честь участника уголовного процесса, а также обращение, унижающее его человеческое достоинство либо создающее опасность для его жизни и здоровья. ч. 2. Никто из участников уголовного процесса не может подвергаться насилию, пыткам, другому жестокому или унижающему человеческое достоинство обращению.","r":"УПК ст. 6"},{"d":"УПК РО","t":"Статья 7. Неприкосновенность личности","x":"ч. 1. Никто не может быть задержан по подозрению в совершении преступления или заключен под стражу при отсутствии на то законных оснований, предусмотренных настоящим Кодексом. ч. 2. Суд, прокурор, следователь, дознаватель обязаны немедленно освободить всякого незаконно задержанного, или лишенного свободы, или содержащегося под стражей свыше срока, предусмотренного настоящим Кодексом. ч. 3. Лицо, которое задержано по подозрению в совершении преступления, должно содержаться в условиях, исключающих угрозу его жизни и здоровью.","r":"УПК ст. 7"},{"d":"УПК РО","t":"Статья 8. Охрана прав и свобод человека и гражданина в уголовном судопроизводстве","x":"ч. 1. Суд, прокурор, следователь, дознаватель обязаны разъяснять подозреваемому, обвиняемому, потерпевшему, гражданскому истцу, гражданскому ответчику, а также другим участникам уголовного судопроизводства их права, обязанности и ответственность и обеспечивать возможность осуществления этих прав. ч. 2. В случае согласия лиц, обладающих свидетельским иммунитетом, дать показания дознаватель, следователь, прокурор и суд обязаны предупредить указанных лиц о том, что их показания могут использоваться в качестве доказательств в ходе дальнейшего производства по уголовному делу. ч. 3. При наличии достаточных данных о том, что потерпевшему, свидетелю или иным участникам уголовного судопроизводства, а также их близким родственникам, родственникам или близким лицам угрожают убийством, применением насилия, уничтожением или повреждением их имущества либо иными опасными противоправными деяниями, суд, прокурор, руководитель следственного органа, следователь, орган дознания, начальник органа дознания, начальник подразделения дознания и дознаватель принимают в пределах своей компетенции в отношении указанных лиц меры безопасности, предусмотренные законодательством РО. ч. 4. Вред, причиненный лицу в результате нарушения его прав и свобод судом, а также должностными лицами, осуществляющими уголовное преследование, подлежит возмещению по основаниям и в порядке, которые установлены настоящим Кодексом.","r":"УПК ст. 8"},{"d":"УПК РО","t":"Статья 9. Неприкосновенность жилища","x":"Обыск, выемка в жилище, осмотр жилища производится только с согласия проживающих в нем лиц или на основании судебного решения, за исключением случаев, предусмотренных законом.","r":"УПК ст. 9"},{"d":"УПК РО","t":"Статья 10. Тайна переписки, телефонных и иных переговоров, почтовых, телеграфных и иных сообщений","x":"ч. 1. Ограничение права гражданина на тайну переписки, телефонных и иных переговоров, почтовых, телеграфных и иных сообщений допускается только на основании судебного решения. ч. 2. Наложение ареста на почтовые и телеграфные отправления и их выемка в учреждениях связи, контроль и запись телефонных и иных переговоров, получение информации о соединениях между абонентами и (или) абонентскими устройствами могут производиться только на основании судебного решения.","r":"УПК ст. 10"},{"d":"УПК РО","t":"Статья 11. Презумпция невиновности","x":"ч. 1. Обвиняемый считается невиновным, пока его виновность в совершении преступления не будет доказана в предусмотренном настоящим Кодексом порядке и установлена вступившим в законную силу решением должностного лица или органа государственной власти. ч. 2. Подозреваемый или обвиняемый не обязан доказывать свою невиновность. Бремя доказывания обвинения и опровержения доводов, приводимых в защиту подозреваемого или обвиняемого, лежит на стороне обвинения. ч. 3. Все сомнения в виновности обвиняемого, которые не могут быть устранены в порядке, установленном настоящим Кодексом, толкуются в пользу обвиняемого. ч. 4. Решение о признании лица виновным в совершении преступления не может быть основано на предположениях.","r":"УПК ст. 11"},{"d":"УПК РО","t":"Статья 12. Состязательность сторон","x":"ч. 1. Уголовный процесс осуществляется на основе состязательности сторон. ч. 2. Функции обвинения, защиты и разрешения уголовного дела отделены друг от друга и не могут быть возложены на один и тот же орган или одно и то же должностное лицо. ч. 3. Суд не является органом уголовного преследования, не выступает на стороне обвинения или стороне защиты, за исключением случаев, предусмотренных законом. Суд создает необходимые условия для исполнения сторонами их процессуальных обязанностей и осуществления предоставленных им прав. ч. 4. Стороны обвинения и защиты равноправны перед судом.","r":"УПК ст. 12"},{"d":"УПК РО","t":"Статья 13. Обеспечение подозреваемому и обвиняемому права на защиту","x":"ч. 1. Подозреваемому и обвиняемому обеспечивается право на защиту, которое они могут осуществлять лично либо с помощью защитника и (или) законного представителя. ч. 2. Суд, прокурор, следователь и дознаватель разъясняют подозреваемому и обвиняемому их права и обеспечивают им возможность защищаться всеми не запрещенными настоящим Кодексом способами и средствами. ч. 3. В случаях, предусмотренных настоящим Кодексом, обязательное участие защитника и (или) законного представителя подозреваемого или обвиняемого обеспечивается должностными лицами, осуществляющими производство по уголовному делу. ч. 4. В случаях, предусмотренных настоящим Кодексом и иными федеральными законами, подозреваемый и обвиняемый могут пользоваться помощью защитника бесплатно.","r":"УПК ст. 13"},{"d":"УПК РО","t":"Статья 14. Право на обжалование процессуальных действий и решений","x":"Действия (бездействие) и решения суда, прокурора, руководителя следственного органа, следователя, органа дознания, начальника органа дознания, начальника подразделения дознания и дознавателя могут быть обжалованы в порядке, установленном настоящим Кодексом.","r":"УПК ст. 14"},{"d":"УПК РО","t":"Статья 15. Виды уголовного преследования","x":"ч. 1. В зависимости от характера и тяжести совершенного преступления уголовное преследование, включая обвинение в суде, осуществляется в публичном, частно-публичном и частном порядке. ч. 2. Уголовные дела о преступлениях, предусмотренных статьей 63 Уголовного кодекса РО, считаются уголовными делами частного обвинения, возбуждаются не иначе как по заявлению потерпевшего, его законного представителя, за исключением случаев, предусмотренных частью четвертой настоящей статьи, и подлежат прекращению в связи с примирением потерпевшего с обвиняемым. Примирение допускается до вынесения решения по делу. ч. 3. Уголовные дела частно-публичного обвинения возбуждаются не иначе как по заявлению потерпевшего или его законного представителя, но прекращению в связи с примирением потерпевшего с обвиняемым не подлежат. К уголовным делам частно-публичного обвинения относятся уголовные дела о преступлениях, предусмотренных статьями 64, 65, ч. 1 ст. 68, 69, ч. 1 ст. 70, 72 Уголовного кодекса РО. К уголовным делам частно-публичного обвинения не могут быть отнесены уголовные дела о преступлениях, предусмотренных статьями ч. 1 ст. 68, 69, ч. 1 ст. 70, 72 Уголовного кодекса РО, в случаях, если преступлением причинен вред интересам государственного унитарного предприятия, государственной корпорации, государственной компании либо если предметом преступления явилось государственное имущество. ч. 4. Следователь, дознаватель возбуждает уголовное дело о любом преступлении, указанном в частях второй и третьей настоящей статьи, и при отсутствии заявления потерпевшего или его законного представителя, если…","r":"УПК ст. 15"},{"d":"УПК РО","t":"Статья 16. Обязанность осуществления уголовного преследования","x":"ч. 1. Уголовное преследование от имени государства по уголовным делам публичного и частно-публичного обвинения осуществляют прокурор, а также следователь и дознаватель. ч. 2. В каждом случае обнаружения признаков преступления прокурор, следователь, орган дознания и дознаватель принимают предусмотренные настоящим Кодексом меры по установлению события преступления, изобличению лица или лиц, виновных в совершении преступления. ч. 3. Требования, поручения и запросы прокурора, следователя, органа дознания и дознавателя, предъявленные в пределах их полномочий, установленных настоящим Кодексом, обязательны для исполнения всеми учреждениями, предприятиями, организациями, должностными лицами и гражданами. ч. 4. Прокурор вправе после возбуждения уголовного дела заключить с подозреваемым или обвиняемым досудебное соглашение о сотрудничестве. ч. 5. Прокурор, дознаватель, следователь обязаны хранить доказательства повода для возбуждения уголовного дела в течении 48 часов.","r":"УПК ст. 16"},{"d":"УПК РО","t":"Статья 17. Основания отказа в возбуждении уголовного дела или прекращения уголовного дела","x":"ч. 1. Уголовное дело не может быть возбуждено, а возбужденное уголовное дело подлежит прекращению по следующим основаниям: 1) отсутствие события преступления; 2) отсутствие в деянии состава преступления; 3) истечение сроков давности уголовного преследования; 4) отсутствие заявления потерпевшего, если уголовное дело может быть возбуждено не иначе как по его заявлению, за исключением случаев, предусмотренных частью четвертой статьи 15 настоящего Кодекса, либо неявка частного обвинителя в судебное заседание без уважительных причин; 5) отсутствие заключения суда о наличии признаков преступления в действиях одного из лиц, указанных в части первой статьи 102 настоящего Кодекса. ч. 2. Уголовное дело подлежит прекращению по основанию, предусмотренному пунктом 2 части первой настоящей статьи, в случае, когда до вступления приговора в законную силу преступность и наказуемость этого деяния были устранены новым уголовным законом. ч. 3. Прекращение уголовного дела влечет за собой одновременно прекращение уголовного преследования. ч. 4. Уголовное дело подлежит прекращению в случае прекращения уголовного преследования в отношении всех подозреваемых или обвиняемых.","r":"УПК ст. 17"},{"d":"УПК РО","t":"Статья 18. Основания прекращения уголовного преследования","x":"Уголовное преследование в отношении подозреваемого или обвиняемого прекращается по следующим основаниям: 1) непричастность подозреваемого или обвиняемого к совершению преступления; 2) прекращение уголовного дела по основаниям, предусмотренным пунктами части первой статьи 17 настоящего Кодекса; 3) вследствие акта об амнистии; 4) наличие в отношении подозреваемого или обвиняемого вступившего в законную силу решения по уголовному делу по тому же обвинению либо определения суда или постановления судьи о прекращении уголовного дела по тому же обвинению; 5) наличие в отношении подозреваемого или обвиняемого неотмененного постановления дознавателя, следователя или прокурора о прекращении уголовного дела по тому же обвинению либо об отказе в возбуждении уголовного дела.","r":"УПК ст. 18"},{"d":"УПК РО","t":"Статья 19. Полномочия суда","x":"ч. 1. Только суд, в том числе в ходе досудебного производства, правомочен принимать решения: 1) об избрании меры пресечения в виде запрета определенных действий; 2) о возмещении имущественного вреда; 3) о производстве осмотра жилища при отсутствии согласия проживающих в нем лиц; 4) о производстве обыска и (или) выемки в жилище; 5) о производстве выемки заложенной или сданной на хранение в ломбард вещи; 6) о производстве личного обыска, за исключением случаев, предусмотренных настоящим Кодексом; 7) о производстве выемки предметов и документов, содержащих государственную или иную охраняемую федеральным законом тайну, а также предметов и документов, содержащих информацию о вкладах и счетах граждан в банках и иных кредитных организациях; 8) о контроле и записи телефонных и иных переговоров; 9) о получении информации о соединениях между абонентами и (или) абонентскими устройствами. ч. 2. Суд правомочен в ходе досудебного производства рассматривать жалобы на действия (бездействие) и решения прокурора, следователя и дознавателя в случаях и порядке, которые предусмотрены настоящим Кодексом. ч. 3. Если при судебном рассмотрении уголовного дела будут выявлены обстоятельства, способствовавшие совершению преступления, нарушения прав и свобод граждан, а также другие нарушения закона, допущенные при производстве дознания, предварительного расследования или при рассмотрении уголовного дела нижестоящим судом, то суд вправе вынести частное определение или постановление, в котором обращается внимание соответствующих организаций и должностных лиц на данные обстоятельства и факты нарушений…","r":"УПК ст. 19"},{"d":"УПК РО","t":"Статья 20. Подсудность уголовных дел","x":"ч. 1. Районному или городскому суду (окружному) по месту совершения преступления подсудны уголовные дела о любых преступлениях, предусмотренных Уголовным кодексом РО, за исключением случаев, предусмотренных частью второй настоящей статьи. ч. 2. Верховному Суду РО подсудны уголовные дела о любых преступлениях, предусмотренных Уголовным кодексом РО, в отношении любого лица, указанного в статье части первой статьи 102 настоящего Кодекса. ч. 3. Апелляционные жалобы (представления) на решения районных или городских судов рассматриваются апелляционным судом общей юрисдикции, а на решения Верховного Суда РО - Федеральным Судом РО. ч. 4. Кассационные жалобы (представления) на решения районных или городских судов, апелляционных судов общей юрисдикции рассматриваются Верховным судом РО, а на решения Верховного Суда РО - Федеральным Судом РО.","r":"УПК ст. 20"},{"d":"УПК РО","t":"Статья 21. Прокурор","x":"ч. 1. Прокурор является должностным лицом, уполномоченным в пределах компетенции, предусмотренной настоящим Кодексом, осуществлять от имени государства уголовное преследование в ходе уголовного процесса, а также надзор за процессуальной деятельностью органов предварительного расследования. ч. 2. В ходе досудебного производства по уголовному делу прокурор уполномочен: 1) проверять исполнение требований закона при приеме, регистрации и разрешении сообщений, заявлений о преступлениях; 2) выносить мотивированное постановление о направлении соответствующих материалов в следственный орган для решения вопроса об уголовном преследовании по фактам выявленных прокурором нарушений уголовного законодательства; 3) требовать от следственных органов устранения нарушений законодательства, допущенных при приеме, регистрации и разрешении сообщений, заявлений о преступлениях, производстве предварительного расследования; 4) давать письменные указания о направлении расследования, производстве процессуальных действий; 5) давать согласие на возбуждение перед судом ходатайства о производстве процессуального действия, которое допускается на основании судебного решения; 6) истребовать и проверять законность и обоснованность решений следователя, дознавателя об отказе в возбуждении, приостановлении или прекращении уголовного дела и принимать по ним решение в соответствии с настоящим Кодексом; 7) отменять незаконные или необоснованные постановления нижестоящего прокурора, а также незаконные или необоснованные постановления следователя, дознавателя в порядке, установленном настоящим Кодексом; 8)…","r":"УПК ст. 21"},{"d":"УПК РО","t":"Статья 22. Следователь","x":"ч. 1. Следователь является должностным лицом, уполномоченным в пределах компетенции, предусмотренной настоящим Кодексом, осуществлять предварительное следствие по уголовному делу. ч. 2. Следователь уполномочен: 1) возбуждать уголовное дело в порядке, установленном настоящим Кодексом; 2) принимать уголовное дело к своему производству или передавать его по подследственности; 3) самостоятельно направлять ход расследования, принимать решение о производстве следственных и иных процессуальных действий, за исключением случаев, когда в соответствии с настоящим Кодексом требуется получение судебного решения; 4) самостоятельно производить оперативно-розыскные и неотложные процессуальные действия; 4.1) давать обязательное для исполнения письменное поручение об организации участия в следственном действии лица, участие которого в данном следственном действии признано необходимым; 5) обжаловать решение прокурора об отмене постановления о возбуждении уголовного дела, о возвращении уголовного дела следователю для производства дополнительного следствия, изменения объема обвинения либо квалификации действий обвиняемых или пересоставления обвинительного заключения и устранения выявленных недостатков; 6) осуществлять иные полномочия, предусмотренные настоящим Кодексом. ч. 3. В случае несогласия с требованиями прокурора об устранении нарушений законодательства, допущенных в ходе предварительного следствия, следователь обязан представить свои письменные возражения прокурору.","r":"УПК ст. 22"},{"d":"УПК РО","t":"Статья 22.1. Дознаватель","x":"ч. 1. Дознавателем является должностное лицо органов внутренних дел, ФСБ РО, федеральной службы охраны, военной полиции Вооруженных Сил РО. ч. 2. Дознаватель уполномочен: 1) возбуждать уголовное дело в порядке, установленном настоящим Кодексом; 2) самостоятельно производить следственные и иные процессуальные действия и принимать процессуальные решения, за исключением случаев, когда в соответствии с настоящим Кодексом на это требуются согласие прокурора и (или) судебное решение; 3) давать органу дознания в случаях и порядке, установленных настоящим Кодексом, обязательные для исполнения письменные поручения о проведении оперативно-розыскных мероприятий, о производстве отдельных следственных действий, об исполнении постановлений о задержании, приводе, заключении под стражу и о производстве иных процессуальных действий, а также получать содействие при их осуществлении; 4) обжаловать в порядке, установленном настоящим Кодексом, решения прокурора о возвращении уголовного дела дознавателю для производства дополнительного дознания либо пересоставления обвинительного заключения; 5) давать дознавателю или органу дознания обязательное для исполнения письменное поручение об организации участия в следственном действии лица, участие которого в данном следственном действии признано необходимым; 6) осуществлять иные полномочия, предусмотренные настоящим Кодексом. ч. 3. Указания прокурора, данные в соответствии с настоящим Кодексом, обязательны для дознавателя. При этом дознаватель вправе обжаловать указания прокурора вышестоящему прокурору. Обжалование данных указаний не приостанавливает…","r":"УПК ст. 22.1"},{"d":"УПК РО","t":"Статья 23. Потерпевший","x":"ч. 1. Потерпевшим является физическое лицо, которому преступлением причинен физический, имущественный, моральный вред, а также юридическое лицо в случае причинения преступлением вреда его имуществу и деловой репутации. Решение о признании потерпевшим принимается незамедлительно с момента возбуждения уголовного дела и оформляется постановлением следователя, дознавателя, судьи или определением суда. Если на момент возбуждения уголовного дела отсутствуют сведения о лице, которому преступлением причинен вред, решение о признании потерпевшим принимается незамедлительно после получения данных об этом лице. ч. 2. Потерпевший вправе: 1) знать о предъявленном обвиняемому обвинении; 2) давать показания; 3) отказаться свидетельствовать против самого себя, своего супруга (своей супруги) и других близких родственников. При согласии потерпевшего дать показания он должен быть предупрежден о том, что его показания могут быть использованы в качестве доказательств по уголовному делу, в том числе и в случае его последующего отказа от этих показаний; 4) представлять доказательства; 5) заявлять ходатайства и отводы; 6) давать показания на русском языке; 7) иметь представителя; 8) участвовать с разрешения следователя в следственных действиях, производимых по его ходатайству либо ходатайству его представителя; 9) знакомиться с протоколами следственных действий, произведенных с его участием, и подавать на них замечания; 10) знакомиться с постановлением о назначении судебной экспертизы и заключением эксперта; 11) знакомиться по окончании предварительного расследования, в том числе в случае…","r":"УПК ст. 23"},{"d":"УПК РО","t":"Статья 24. Гражданский истец","x":"ч. 1. Гражданским истцом является физическое или юридическое лицо, предъявившее требование о возмещении имущественного вреда, при наличии оснований полагать, что данный вред причинен ему непосредственно преступлением. Решение о признании гражданским истцом оформляется определением суда или постановлением судьи, следователя, дознавателя. Гражданский истец может предъявить гражданский иск и для имущественной компенсации морального вреда. ч. 2. Гражданский иск может быть предъявлен после возбуждения уголовного дела и до окончания судебного следствия при разбирательстве данного дела в суде первой инстанции. При предъявлении гражданского иска гражданский истец освобождается от уплаты государственной пошлины. ч. 3. Гражданский истец вправе: 1) поддерживать гражданский иск; 2) представлять доказательства; 3) давать объяснения по предъявленному иску; 4) заявлять ходатайства и отводы; 5) давать показания и объяснения на русском языке; 6) отказаться свидетельствовать против самого себя, своего супруга (своей супруги) и других близких родственников. При согласии гражданского истца дать показания он должен быть предупрежден о том, что его показания могут быть использованы в качестве доказательств по уголовному делу, в том числе и в случае его последующего отказа от этих показаний; 7) иметь представителя; 8) знакомиться с протоколами следственных действий, произведенных с его участием; 9) участвовать с разрешения следователя в следственных действиях, производимых по его ходатайству либо ходатайству его представителя; 10) отказаться от предъявленного им гражданского иска. До принятия…","r":"УПК ст. 24"},{"d":"УПК РО","t":"Статья 25. Представители потерпевшего, гражданского истца","x":"Представителями потерпевшего, гражданского истца могут быть адвокаты, а представителями гражданского истца, являющегося юридическим лицом, также иные лица, правомочные в соответствии с Гражданским кодексом РО представлять его интересы. В качестве представителя потерпевшего или гражданского истца могут быть также допущены один из близких родственников потерпевшего или гражданского истца либо иное лицо, о допуске которого ходатайствует потерпевший или гражданский истец.","r":"УПК ст. 25"},{"d":"УПК РО","t":"Статья 26. Подозреваемый","x":"ч. 1. Подозреваемым является лицо: 1) либо в отношении которого возбуждено уголовное дело; 2) либо которое задержано в соответствии со статьями 51 и 52 настоящего Кодекса; 3) либо которое уведомлено о подозрении в совершении преступления дознавателем или следователем путем направления письменного уведомления, в котором должны быть указаны: а) дата и место его составления; б) фамилия, инициалы лица, его составившего; в) фамилия, имя и отчество подозреваемого, число, месяц, год и место его рождения; г) описание преступления с указанием места, времени и иных обстоятельств его совершения; д) пункт, часть, статья Уголовного кодекса РО, предусматривающие ответственность за данное преступление. ч. 2. Подозреваемый вправе: 1) знать, в чем он подозревается, и получить копию постановления о возбуждении уголовного дела; 2) давать объяснения и показания по поводу имеющегося в отношении его подозрения либо отказаться от дачи объяснений и показаний. При согласии подозреваемого дать показания он должен быть предупрежден о том, что его показания могут быть использованы в качестве доказательств по уголовному делу, в том числе и при его последующем отказе от этих показаний; 3) пользоваться помощью защитника и иметь свидание с ним наедине и конфиденциально до первого допроса подозреваемого, но не более 10 минут, а также воспользоваться телефонным звонком (разговором) длительностью не более 2-х минут; 4) представлять доказательства; 5) заявлять ходатайства и отводы; 6) давать показания на русском языке; 7) знакомиться с протоколами следственных действий, произведенных с его участием, и…","r":"УПК ст. 26"},{"d":"УПК РО","t":"Статья 27. Обвиняемый","x":"ч. 1. Обвиняемым признается лицо, в отношении которого вынесено постановление о привлечении его в качестве обвиняемого. ч. 2. Обвиняемый, по уголовному делу которого назначено судебное разбирательство, именуется подсудимым. Обвиняемый, в отношении которого вынесено решение о признании виновным, именуется осужденным. Обвиняемый, в отношении которого вынесен оправдательный приговор, является оправданным. ч. 3. Обвиняемый вправе защищать свои права и законные интересы и иметь достаточное время и возможность для подготовки к защите. ч. 4. Обвиняемый вправе: 1) знать, в чем он обвиняется, и получить копию постановления о возбуждении уголовного дела; 2) получить копию обвинительного заключения; 3) возражать против обвинения, давать показания по предъявленному ему обвинению либо отказаться от дачи показаний. При согласии обвиняемого дать показания он должен быть предупрежден о том, что его показания могут быть использованы в качестве доказательств по делу, в том числе и при его последующем отказе от этих показаний, за исключением случая, предусмотренного пунктом 1 части второй статьи 62 настоящего Кодекса; 4) представлять доказательства; 5) заявлять ходатайства и отводы; 6) давать показания и объясняться на русском языке; 7) пользоваться помощью защитника, в том числе бесплатно в случаях, предусмотренных настоящим Кодексом; 8) иметь свидания с защитником наедине и конфиденциально, в том числе до первого допроса обвиняемого, без ограничения их числа и продолжительности; 9) участвовать с разрешения следователя в следственных действиях, производимых по его ходатайству или…","r":"УПК ст. 27"},{"d":"УПК РО","t":"Статья 28. Защитник","x":"ч. 1. Защитник - лицо, осуществляющее в установленном настоящим Кодексом порядке защиту прав и интересов подозреваемых и обвиняемых и оказывающее им юридическую помощь при производстве по уголовному делу. ч. 2. В качестве защитников участвуют адвокаты. ч. 3. Защитник участвует в уголовном деле: 1) с момента вынесения постановления о привлечении лица в качестве обвиняемого, за исключением случаев, предусмотренных пунктами 2 - 5 настоящей части; 2) с момента возбуждения уголовного дела в отношении конкретного лица; 3) с момента фактического задержания лица, подозреваемого в совершении преступления; 4) с момента начала осуществления иных мер процессуального принуждения или иных процессуальных действий, затрагивающих права и свободы лица, подозреваемого в совершении преступления; 5) с момента начала осуществления процессуальных действий, затрагивающих права и свободы лица, в отношении которого проводится проверка сообщения о преступлении. ч. 4. Адвокат вступает в уголовное дело в качестве защитника по предъявлении удостоверения адвоката. ч. 5. С момента вступления в уголовное дело защитник вправе: 1) иметь с подозреваемым, обвиняемым свидания; 2) собирать и представлять доказательства, необходимые для оказания юридической помощи; 3) привлекать специалиста в соответствии со статьей 51 настоящего Кодекса; 4) присутствовать при предъявлении обвинения; 5) участвовать в допросе подозреваемого, обвиняемого, а также в иных следственных действиях, производимых с участием подозреваемого, обвиняемого либо по его ходатайству или ходатайству самого защитника в порядке, установленном…","r":"УПК ст. 28"},{"d":"УПК РО","t":"Статья 29. Приглашение, назначение и замена защитника","x":"ч. 1. Защитник приглашается подозреваемым, обвиняемым, его законным представителем, а также другими лицами по поручению или с согласия подозреваемого, обвиняемого. Подозреваемый, обвиняемый вправе пригласить несколько защитников. ч. 2. По просьбе подозреваемого, обвиняемого участие защитника обеспечивается следователем, дознавателем, прокурором или судом.","r":"УПК ст. 29"},{"d":"УПК РО","t":"Статья 30. Обязательное участие защитника","x":"Участие защитника в уголовном процессе обязательно в следующих случаях: 1) подозреваемый или обвиняемый требует защитника; 2) обвиняемый обвиняется в совершении тяжкого или особо-тяжкого преступления в порядке письменного производства по уголовному делу; 3) подозреваемый, обвиняемый в силу физических или психических недостатков не может самостоятельно осуществлять свое право на защиту.","r":"УПК ст. 30"},{"d":"УПК РО","t":"Статья 31. Отказ от защитника","x":"ч. 1. Подозреваемый, обвиняемый вправе в любой момент производства по уголовному делу отказаться от помощи защитника. Такой отказ допускается только по инициативе подозреваемого или обвиняемого. ч. 2. Отказ от защитника не обязателен для следователя, дознавателя и суда. ч. 3. Отказ от защитника не лишает подозреваемого, обвиняемого права в дальнейшем ходатайствовать о допуске защитника к участию в производстве по уголовному делу. Допуск защитника не влечет за собой повторения процессуальных действий, которые к этому моменту уже были произведены.","r":"УПК ст. 31"},{"d":"УПК РО","t":"Статья 32. Гражданский ответчик","x":"ч. 1. В качестве гражданского ответчика может быть привлечено физическое или юридическое лицо, которое в соответствии с Гражданским кодексом РО несет ответственность за вред, причиненный преступлением. О привлечении физического или юридического лица в качестве гражданского ответчика следователь, дознаватель или судья выносит постановление, а суд - определение. ч. 2. Гражданский ответчик вправе: 1) знать сущность исковых требований и обстоятельства, на которых они основаны; 2) возражать против предъявленного гражданского иска; 3) давать объяснения и показания по существу предъявленного иска; 4) отказаться свидетельствовать против самого себя, своего супруга (своей супруги) и других близких родственников. При согласии гражданского ответчика дать показания он должен быть предупрежден о том, что его показания могут быть использованы в качестве доказательств по уголовному делу, в том числе и в случае его последующего отказа от этих показаний; 5) давать показания на русском языке; 6) иметь представителя; 7) собирать и представлять доказательства; 8) заявлять ходатайства и отводы; 9) знакомиться по окончании предварительного расследования с материалами уголовного дела, относящимися к предъявленному гражданскому иску, и делать из уголовного дела соответствующие выписки, снимать за свой счет копии с тех материалов дела, которые касаются гражданского иска, в том числе с использованием технических средств; 10) участвовать в судебном разбирательстве уголовного дела в судах первой, второй, кассационной инстанций; 11) выступать в судебных прениях; 12) приносить жалобы на действия…","r":"УПК ст. 32"},{"d":"УПК РО","t":"Статья 33. Представитель гражданского ответчика","x":"ч. 1. Представителями гражданского ответчика могут быть адвокаты, а представителями гражданского ответчика, являющегося юридическим лицом, также иные лица, правомочные в соответствии с Гражданским кодексом РО представлять его интересы. ч. 2. Представитель гражданского ответчика имеет те же права, что и представляемое им лицо. ч. 3. Личное участие в производстве по уголовному делу гражданского ответчика не лишает его права иметь представителя.","r":"УПК ст. 33"},{"d":"УПК РО","t":"Статья 34. Свидетель","x":"ч. 1. Свидетелем является лицо, которому могут быть известны какие-либо обстоятельства, имеющие значение для расследования и разрешения уголовного дела, и которое вызвано для дачи показаний, за исключением случаев, предусмотренных частью третьей настоящей статьи. ч. 2. Вызов и допрос свидетелей осуществляются в порядке, установленном законом. ч. 3. Не подлежат допросу в качестве свидетелей: 1) судья, присяжный заседатель - об обстоятельствах уголовного дела, которые стали им известны в связи с участием в производстве по данному уголовному делу; 2) адвокат, защитник подозреваемого, обвиняемого - об обстоятельствах, ставших ему известными в связи с обращением к нему за юридической помощью или в связи с ее оказанием, за исключением случаев, если о допросе в качестве свидетеля ходатайствует адвокат, защитник подозреваемого, обвиняемого с согласия и в интересах подозреваемого, обвиняемого; 3) адвокат - об обстоятельствах, которые стали ему известны в связи с оказанием юридической помощи, за исключением случаев, если о допросе в качестве свидетеля ходатайствует адвокат с согласия лица, которому он оказывал юридическую помощь; 4) Депутат Федерального Собрания - об обстоятельствах, которые стали им известны в связи с осуществлением ими своих полномочий. ч. 4. Свидетель вправе: 1) отказаться свидетельствовать против самого себя, своего супруга (своей супруги) и других близких родственников. При согласии свидетеля дать показания он должен быть предупрежден о том, что его показания могут быть использованы в качестве доказательств по уголовному делу, в том числе и в случае его…","r":"УПК ст. 34"},{"d":"УПК РО","t":"Статья 35. Эксперт","x":"ч. 1. Эксперт - лицо, обладающее специальными знаниями и назначенное в порядке, установленном настоящим Кодексом, для производства судебной экспертизы и дачи заключения. ч. 2. Эксперт вправе: 1) знакомиться с материалами уголовного дела, относящимися к предмету судебной экспертизы; 2) ходатайствовать о предоставлении ему дополнительных материалов, необходимых для дачи заключения, либо привлечении к производству судебной экспертизы других экспертов; 3) участвовать с разрешения следователя и суда в процессуальных действиях и задавать вопросы, относящиеся к предмету судебной экспертизы; 4) давать заключение в пределах своей компетенции, в том числе по вопросам, хотя и не поставленным в постановлении о назначении судебной экспертизы, но имеющим отношение к предмету экспертного исследования; 5) приносить жалобы на действия (бездействие) и решения следователя, дознавателя, прокурора и суда, ограничивающие его права; 6) отказаться от дачи заключения по вопросам, выходящим за пределы специальных знаний, а также в случаях, если представленные ему материалы недостаточны для дачи заключения. Отказ от дачи заключения должен быть заявлен экспертом в письменном виде с изложением мотивов отказа. ч. 3. Эксперт не вправе: 1) без ведома следователя и суда вести переговоры с участниками уголовного судопроизводства по вопросам, связанным с производством судебной экспертизы; 2) самостоятельно собирать материалы для экспертного исследования; 3) проводить без разрешения следователя, прокурора, дознавателя, суда исследования, могущие повлечь полное или частичное уничтожение объектов либо…","r":"УПК ст. 35"},{"d":"УПК РО","t":"Статья 36. Специалист","x":"ч. 1. Специалист - лицо, обладающее специальными знаниями, привлекаемое к участию в процессуальных действиях в порядке, установленном настоящим Кодексом, для содействия в обнаружении, закреплении и изъятии предметов и документов, применении технических средств в исследовании материалов уголовного дела, для постановки вопросов эксперту, а также для разъяснения сторонам и суду вопросов, входящих в его профессиональную компетенцию. ч. 2. Вызов специалиста и порядок его участия в следственных и иных процессуальных действиях, судебных заседаниях определяются законом. ч. 3. Стороне защиты не может быть отказано в удовлетворении ходатайства о привлечении к участию в производстве по уголовному делу в порядке, установленном настоящим Кодексом, специалиста для разъяснения вопросов, входящих в его профессиональную компетенцию. ч. 4. Специалист вправе: 1) отказаться от участия в производстве по уголовному делу, если он не обладает соответствующими специальными знаниями; 2) задавать вопросы участникам следственного действия с разрешения следователя и суда; 3) знакомиться с протоколом следственного действия, в котором он участвовал, и делать заявления и замечания, которые подлежат занесению в протокол; 4) приносить жалобы на действия (бездействие) и решения следователя, прокурора и суда, ограничивающие его права. ч. 5. Специалист не вправе уклоняться от явки по вызовам следователя или в суд, а также разглашать данные предварительного расследования, ставшие ему известными в связи с участием в производстве по уголовному делу в качестве специалиста, если он был об этом заранее…","r":"УПК ст. 36"},{"d":"УПК РО","t":"Статья 37. Обстоятельства, исключающие участие в производстве по уголовному делу","x":"ч. 1. Прокурор, следователь, дознаватель, эксперт, специалист не может участвовать в производстве по уголовному делу, если он: 1) является потерпевшим по делам частного и частно-публичного обвинения, гражданским истцом, гражданским ответчиком по данному делу; 2) участвовал в качестве присяжного заседателя, эксперта, специалиста, переводчика, понятого, помощника судьи, секретаря судебного заседания, защитника, законного представителя подозреваемого, обвиняемого, представителя потерпевшего, гражданского истца или гражданского ответчика; 3) является близким родственником или родственником любого из участников производства по данному уголовному делу. ч. 2. Лица, указанные в части первой настоящей статьи, не могут участвовать в производстве по уголовному делу также в случаях, если имеются иные обстоятельства, дающие основание полагать, что они лично, прямо или косвенно, заинтересованы в исходе данного уголовного дела. ч. 3. Наличие информации о внепроцессуальном обращении, поступившем прокурору, дознавателю или следователю по делу, находящемуся в его производстве, само по себе не может рассматриваться в качестве основания для отвода. ч. 4. Эксперт не может участвовать в производстве по уголовному делу, если обнаружится его некомпетентность.","r":"УПК ст. 37"},{"d":"УПК РО","t":"Статья 38. Недопустимость участия в производстве по уголовному делу лиц, подлежащих отводу","x":"ч. 1. При наличии оснований для отвода, предусмотренных настоящей главой, прокурор, следователь, дознаватель, эксперт, специалист, защитник, а также представители потерпевшего, гражданского истца или гражданского ответчика обязаны устраниться от участия в производстве по уголовному делу. ч. 2. В случае, если лица, указанные в части первой настоящей статьи, не устранились от участия в производстве по уголовному делу, отвод им может быть заявлен подозреваемым, обвиняемым, его законным представителем, защитником, а также государственным обвинителем, потерпевшим, гражданским истцом, гражданским ответчиком или их представителями. ч. 3. В случае отказа в удовлетворении заявления об отводе подача повторного заявления об отводе тем же лицом и по тем же основаниям не допускается. ч. 4. Решение об отказе в удовлетворении заявления об отводе, принятое в ходе досудебного производства по делу, не является препятствием для последующей подачи заявления об отводе тем же лицом в отношении того же лица и по тем же основаниям в ходе судебного производства по делу. ч. 5. Вопрос об отводе следователя, дознавателя, прокурора разрешается вышестоящим должностным лицом (прокурором) в течение 12 часов после поступления соответствующего заявления. В случае несогласия сторон с решением об отказе в удовлетворении отвода, заявитель вправе обратиться с жалобой в суд либо прокурору для проверки законности и обоснованности принятого решения.","r":"УПК ст. 38"},{"d":"УПК РО","t":"Статья 39. Недопустимость повторного участия судьи в рассмотрении дела","x":"ч. 1. Судья, принимавший участие в рассмотрении уголовного дела в суде первой инстанции, не может участвовать в рассмотрении данного дела в суде второй инстанции, а равно участвовать в новом рассмотрении дела в суде первой или второй инстанции в случае отмены вынесенных с его участием приговора, а также определения, постановления о прекращении дела. ч. 2. Судья, принимавший участие в рассмотрении дела в суде второй инстанции, не может участвовать в рассмотрении этого дела в суде первой инстанции, а равно в новом рассмотрении того же дела в суде второй инстанции после отмены приговора, определения, постановления, вынесенного с его участием.","r":"УПК ст. 39"},{"d":"УПК РО","t":"Статья 40. Заявление об отводе судьи","x":"ч. 1. При наличии обстоятельств, предусмотренных статьями 37 и 39 настоящего Кодекса, судье может быть заявлен отвод участниками процесса. ч. 2. Отвод судье заявляется до начала судебного следствия, а в случае рассмотрения дела судом с участием присяжных заседателей - до формирования коллегии присяжных заседателей. В ходе дальнейшего судебного заседания заявление об отводе допускается лишь в случае, когда основание для него ранее не было известно стороне.","r":"УПК ст. 40"},{"d":"УПК РО","t":"Статья 41. Порядок рассмотрения заявлений об отводе","x":"ч. 1. Заявление об отводе судьи рассматривается этим же судьей, а в случае коллегиального рассмотрения уголовного дела - судебной коллегией без участия судьи, в отношении которого заявлен отвод. Отвод судебной коллегии рассматривается этой же коллегией. ч. 2. Заявление об отводе прокурора рассматривается вышестоящим прокурором, а если отвод заявлен Генеральному прокурору РО, то заявление об отводе рассматривается этим же должностным лицом. Заявление об отводе прокурора, заявленное на стадии судебного разбирательства, рассматривается судом. ч. 3. Заявление об отводе следователя, дознавателя рассматривается прокурором. ч. 4. Заявление об отводе эксперта, специалиста рассматривается прокурором, а на стадии судебного разбирательства - судом.","r":"УПК ст. 41"},{"d":"УПК РО","t":"Статья 42. Обстоятельства, подлежащие доказыванию","x":"ч. 1. При производстве по уголовному делу подлежат доказыванию: 1) событие преступления (время, место, способ и другие обстоятельства совершения преступления); 2) виновность лица в совершении преступления, форма его вины и мотивы; 3) обстоятельства, характеризующие личность обвиняемого; 4) характер и размер вреда, причиненного правонарушением; 5) обстоятельства, исключающие противоправность и наказуемость деяния; 6) обстоятельства, смягчающие и отягчающие наказание; 7) обстоятельства, которые могут повлечь за собой освобождение от уголовной ответственности и наказания. ч. 2. Подлежат выявлению также обстоятельства, способствовавшие совершению преступления.","r":"УПК ст. 42"},{"d":"УПК РО","t":"Статья 43. Доказательства","x":"ч. 1. Доказательствами по уголовному делу являются любые сведения, на основе которых суд, прокурор, следователь, дознаватель в порядке, определенном настоящим Кодексом, устанавливает наличие или отсутствие обстоятельств, подлежащих доказыванию при производстве по уголовному делу, а также иных обстоятельств, имеющих значение для дела. ч. 2. В качестве доказательств допускаются: 1) показания подозреваемого, обвиняемого; 2) показания потерпевшего, свидетеля; 3) заключение и показания эксперта; 3.1) заключение и показания специалиста; 4) вещественные доказательства; 5) протоколы следственных и судебных действий; 6) иные документы.","r":"УПК ст. 43"},{"d":"УПК РО","t":"Статья 44. Недопустимые доказательства","x":"ч. 1. Доказательства, полученные с нарушением требований настоящего Кодекса, являются недопустимыми. Недопустимые доказательства не имеют юридической силы и не могут быть положены в основу обвинения, а также использоваться для доказывания любого из обстоятельств, предусмотренных статьей 42 настоящего Кодекса. ч. 2. К недопустимым доказательствам относятся: 1) показания подозреваемого, обвиняемого, данные в ходе досудебного производства по уголовному делу или делу об административном правонарушении в отсутствие защитника, включая случаи отказа от защитника, и не подтвержденные подозреваемым, обвиняемым в суде; 2) показания потерпевшего, свидетеля, основанные на догадке, предположении, слухе, а также показания свидетеля, который не может указать источник своей осведомленности; 3) иные доказательства, полученные с нарушением требований настоящего Кодекса.","r":"УПК ст. 44"},{"d":"УПК РО","t":"Статья 44.1. Показания подозреваемого","x":"Показания подозреваемого - сведения, сообщенные им на допросе, проведенном в ходе досудебного производства в соответствии с требованиями статей 96 - 98 настоящего Кодекса.","r":"УПК ст. 44.1"},{"d":"УПК РО","t":"Статья 44.2. Показания обвиняемого","x":"ч. 1. Показания обвиняемого - сведения, сообщенные им на допросе, проведенном в ходе досудебного производства или в суде. ч. 2. Признание обвиняемым своей вины в совершении преступления может быть положено в основу обвинения лишь при подтверждении его виновности совокупностью имеющихся по уголовному делу доказательств.","r":"УПК ст. 44.2"},{"d":"УПК РО","t":"Статья 44.3. Показания потерпевшего","x":"ч. 1. Показания потерпевшего - сведения, сообщенные им на допросе, проведенном в ходе досудебного производства или в суде. ч. 2. Потерпевший может быть допрошен о любых обстоятельствах, подлежащих доказыванию при производстве по уголовному делу, в том числе о своих взаимоотношениях с подозреваемым, обвиняемым.","r":"УПК ст. 44.3"},{"d":"УПК РО","t":"Статья 44.4. Показания свидетеля","x":"ч. 1. Показания свидетеля - сведения, сообщенные им на допросе, проведенном в ходе досудебного производства по уголовному делу или в суде. ч. 2. Свидетель может быть допрошен о любых относящихся к уголовному делу обстоятельствах, в том числе о личности обвиняемого, потерпевшего и своих взаимоотношениях с ними и другими свидетелями.","r":"УПК ст. 44.4"},{"d":"УПК РО","t":"Статья 44.5. Заключение и показания эксперта и специалиста","x":"ч. 1. Заключение эксперта - представленные в письменном виде содержание исследования и выводы по вопросам, поставленным перед экспертом лицом, ведущим производство по уголовному делу, или сторонами. ч. 2. Показания эксперта - сведения, сообщенные им на допросе, проведенном после получения его заключения, в целях разъяснения или уточнения данного заключения. ч. 3. Заключение специалиста - представленное в письменном виде суждение по вопросам, поставленным перед специалистом сторонами. ч. 4. Показания специалиста - сведения, сообщенные им на допросе об обстоятельствах, требующих специальных познаний, а также разъяснения своего мнения.","r":"УПК ст. 44.5"},{"d":"УПК РО","t":"Статья 44.6. Вещественные доказательства","x":"ч. 1. Вещественными доказательствами признаются любые предметы: 1) которые служили орудиями, оборудованием или иными средствами совершения правонарушения или сохранили на себе следы преступления; 2) на которые были направлены противоправные действия; 2.1) деньги, ценности и иное имущество, полученные в результате совершения преступления; 3) иные предметы и документы, которые могут служить средствами для обнаружения преступления и установления обстоятельств уголовного дела, в том числе записи с нательных видеорегистраторов. ч. 2. Предметы, указанные в части первой настоящей статьи, осматриваются, признаются вещественными доказательствами и приобщаются к уголовному делу. Порядок хранения вещественных доказательств устанавливается настоящей статьей и статьей 44.7 настоящего Кодекса. ч. 3. Изъятые в ходе досудебного производства, но не признанные вещественными доказательствами предметы, включая электронные носители информации, и документы подлежат возврату лицам, у которых они были изъяты.","r":"УПК ст. 44.6"},{"d":"УПК РО","t":"Статья 44.7. Хранение и предоставление вещественных доказательств","x":"ч. 1. Вещественные доказательства по уголовному делу, ведущемуся в форме предварительного расследования без письменной отчетности, хранятся у дознавателя, следователя в течение 72 часов с момента вынесения итогового решения по уголовному делу в соответствии со статьей 82 настоящего Кодекса или освобождения лица от задержания в соответствии со статьей 53 настоящего Кодекса. ч. 2. При поступлении жалобы на действия (бездействие), решения следователя, дознавателя при производстве по уголовному делу без письменной отчетности, срок хранения вещественных доказательств, указанный в части первой настоящей статьи, приостанавливается до окончания производства по жалобе. ч. 3. Вещественные доказательства по уголовному делу, ведущемуся в форме предварительного расследования с письменной отчетностью, хранятся в материалах уголовного дела. ч. 4. Судьба вещественных доказательств по уголовному делу, ведущемуся в форме предварительного расследования с письменной отчетностью, разрешается судом в приговоре или прокурором, рассматривающим уголовное дело по существу, в решении по уголовному делу. Решение о судьбе вещественных доказательств по уголовному делу исполняется по окончанию сроков апелляционного обжалования приговора суда или сроков обжалования решения прокурора, рассматривающего уголовное дело по существу.","r":"УПК ст. 44.7"},{"d":"УПК РО","t":"Статья 44.8. Протоколы следственных действий и судебного заседания","x":"Протоколы следственных действий и протоколы судебных заседаний допускаются в качестве доказательств, если они соответствуют требованиям, установленным настоящим Кодексом.","r":"УПК ст. 44.8"},{"d":"УПК РО","t":"Статья 44.9. Иные документы","x":"ч. 1. Иные документы допускаются в качестве доказательств, если изложенные в них сведения имеют значение для установления обстоятельств, указанных в статье 42 настоящего Кодекса. ч. 2. Документы могут содержать сведения, зафиксированные как в письменном, так и в ином виде. К ним могут относиться материалы фото- и киносъемки, аудио- и видеозаписи и иные носители информации, полученные, истребованные или представленные в порядке, установленном статьей 46 настоящего Кодекса. ч. 3. Документы приобщаются к материалам уголовного дела и хранятся в течение всего срока его хранения. По ходатайству законного владельца изъятые и приобщенные к уголовному делу документы или их копии могут быть переданы ему. ч. 4. Документы, обладающие признаками, указанными в части первой статьи 44.6 настоящего Кодекса, признаются вещественными доказательствами.","r":"УПК ст. 44.9"},{"d":"УПК РО","t":"Статья 45. Доказывание","x":"Доказывание состоит в собирании, проверке и оценке доказательств в целях установления обстоятельств, предусмотренных статьей 42 настоящего Кодекса.","r":"УПК ст. 45"},{"d":"УПК РО","t":"Статья 46. Собирание доказательств","x":"ч. 1. Собирание доказательств осуществляется в ходе уголовного процесса следователем, прокурором, дознавателем и судом путем производства следственных и иных процессуальных действий, предусмотренных настоящим Кодексом. ч. 2. Подозреваемый, обвиняемый, а также потерпевший, гражданский истец, гражданский ответчик и их представители вправе собирать и представлять письменные документы и предметы для приобщения их к уголовному делу в качестве доказательств. ч. 3. Защитник вправе собирать доказательства путем: 1) получения предметов, документов и иных сведений; 2) опроса лиц с их согласия; 3) истребования справок, характеристик, иных документов от органов государственной власти, общественных объединений и организаций, которые обязаны предоставлять запрашиваемые документы или их копии.","r":"УПК ст. 46"},{"d":"УПК РО","t":"Статья 47. Проверка доказательств","x":"Проверка доказательств производится следователем, прокурором, судом путем сопоставления их с другими доказательствами, имеющимися в уголовном деле, а также установления их источников, получения иных доказательств, подтверждающих или опровергающих проверяемое доказательство.","r":"УПК ст. 47"},{"d":"УПК РО","t":"Статья 48. Правила оценки доказательств","x":"ч. 1. Каждое доказательство подлежит оценке с точки зрения относимости, допустимости, достоверности, а все собранные доказательства в совокупности - достаточности для разрешения уголовного дела. ч. 2. В случаях, указанных в части второй статьи 44 настоящего Кодекса, суд, прокурор, следователь, дознаватель признает доказательство недопустимым. ч. 3. Суд, прокурор, следователь, дознаватель вправе признать доказательство недопустимым по ходатайству подозреваемого, обвиняемого или по собственной инициативе. Доказательство, признанное недопустимым, не подлежит включению в обвинительное заключение.","r":"УПК ст. 48"},{"d":"УПК РО","t":"Статья 49. Использование в доказывании результатов оперативно-розыскной деятельности","x":"В процессе доказывания запрещается использование результатов оперативно-розыскной деятельности, если они не отвечают требованиям, предъявляемым к доказательствам настоящим Кодексом.","r":"УПК ст. 49"},{"d":"УПК РО","t":"Статья 50. Преюдиция","x":"Обстоятельства, установленные приговором суда, либо иным вступившим в законную силу решением суда, принятым в рамках гражданского или административного судопроизводства, признаются судом, прокурором, следователем, дознавателем без дополнительной проверки. При этом такие приговор или решение не могут предрешать виновность лиц, не участвовавших ранее в рассматриваемом уголовном деле.","r":"УПК ст. 50"},{"d":"УПК РО","t":"Статья 51. Основания задержания подозреваемого","x":"ч. 1. Дознаватель, следователь вправе задержать лицо по подозрению в совершении преступления, за которое может быть назначено наказание в виде лишения свободы, при наличии одного из следующих оснований: 1) когда это лицо застигнуто при совершении преступления или непосредственно после его совершения; 2) когда потерпевшие или очевидцы укажут на данное лицо как на совершившее преступление; 3) когда на этом лице или его одежде, при нем или в его жилище будут обнаружены явные следы преступления; 4) когда это лицо находится в ориентировке; 5) когда имеются иные данные, дающие основание подозревать лицо в совершении преступления. ч. 2. Генеральный прокурор РО или его заместители вправе давать поручения в устной и письменной форме о производстве задержания при наличии оснований, установленных частью первой настоящей статьи. ч. 3. Лицо не может быть задержано по подозрению в совершении преступления, по которому истекли сроки давности уголовного преследования.","r":"УПК ст. 51"},{"d":"УПК РО","t":"Статья 52. Порядок задержания подозреваемого","x":"Задержание лица производится в следующей последовательности: а) применить специальные средства с целью ограничить свободу лица; б) предъявить свое служебное удостоверение или иной идентификационный знак, подтверждающий принадлежность к органам государственной власти; в) на усмотрение сотрудника, проводящего задержание, провести обыск; г) разъяснить основания задержания и права, установленные пунктами 2, 3 части 2 статьи 26 настоящего Кодекса; Пояснение: Рекомендуемая форма оглашения прав гражданина изложенная в данных пунктах: \"Вы можете давать показания и объяснения по поводу подозрений в нарушении уголовного кодекса, осознавая их использование в деле, либо отказаться от дачи объяснений и показаний. Вы можете воспользоваться помощью защитника и иметь свидание с ним наедине, воспользоваться телефонным звонком длительностью которого не должна превышать 2-х минут.\". Допустимо использовать иную формулировку, если она отражает в полной мере права, которые должны быть разъяснены согласно данному этапу задержания. д) доставить подозреваемого в территориальный орган власти, отдел внутренних дел или иное место для дознания или следствия, а в случае, предусмотренном статьей 83.1 настоящего Кодекса, - в суд; д.1) в случае, если должностное лицо, производящее задержание, не уполномочено вести предварительное расследование по уголовному делу, связанному с задержанием - передать задержание и материалы дела уполномоченному на это лицу; е) провести идентификацию личности задержанного и проверку на принадлежность задержанного к государственным органам; ж) реализовать права задержанного,…","r":"УПК ст. 52","k":"порядок задержания ; что зачитать задержанному ; какие права разъяснить при задержании ; миранда на сервере ; последовательность задержания ; что говорить при задержании ; форма оглашения прав ; право на звонок 2 минуты ; адвокат при задержании сколько ждать ; когда делать обыск при задержании ; обыск на усмотрение сотрудника ; как правильно задержать ; задержал что дальше по порядку ; процедура задержания подозреваемого"},{"d":"УПК РО","t":"Статья 53. Основания освобождения подозреваемого","x":"ч. 1. Подозреваемый и обвиняемый подлежит освобождению, если: 1) не подтвердилось подозрение в совершении преступления; 2) задержание было произведено с нарушением требований статьи 51 настоящего Кодекса; 3) общая продолжительность задержания превышает 60 минут, а в случае задержания лица, являющегося служащим органов государственной власти или в случае применения судебного контроля - 90 минут; 4) дальнейшее ограничение свободы невозможно в соответствии с требованиями настоящего Кодекса. ч. 2. При освобождении подозреваемый и обвиняемый вправе требовать разъяснить ему дату, время, место и основания задержания, дату, время и основания освобождения, осведомить его о том, какое должностное лицо произвело задержание. ч. 3. При задержании лица, являющегося служащим органов государственной власти, факт наличия оснований для освобождения подозреваемого, предусмотренных пунктами 1, 2, 4 части первой настоящей статьи, может быть установлен только прокурором, прибывшим на задержание для рассмотрения его материалов.","r":"УПК ст. 53"},{"d":"УПК РО","t":"Статья 54. Субъекты задержания","x":"ч. 1. В процессе задержания участвуют: а) должностные лица, которые осуществляют задержание; б) дознаватели или следователи, осуществляющие предварительное расследование по делу; в) задержанный, в отношении которого проводится задержание; г) адвокат; д) руководство задержанного, вызванное в порядке статьи 83 настоящего Кодекса; е) работники Генеральной прокуратуры РО, один сотрудник Следственного Комитета; ё) прокурор, вызванный в порядке статьи 83 настоящего Кодекса, либо с целью осуществления надзора; ж) сотрудник ПС ФСБ; з) судья при проведении судебного контроля. ч. 2. Присутствие иных лиц в процессе задержания не допускается. Субъекты задержания вправе потребовать посторонних граждан отойти от места задержания на 5 метров, а также покинуть помещение, если задержание проводится в закрытом помещении.","r":"УПК ст. 54"},{"d":"УПК РО","t":"Статья 55. Запрет определенных действий","x":"ч. 1. Запрет определенных действий в качестве меры пресечения избирается по судебному решению в отношении подозреваемого или обвиняемого и заключается в возложении на подозреваемого или обвиняемого обязанностей своевременно являться по вызовам следователя или в суд, соблюдать один или несколько запретов, установленных судом, а также в осуществлении контроля за соблюдением возложенных на него запретов. Запрет определенных действий может быть избран в любой момент производства по уголовному делу для обеспечения исполнения приговора суда или при наличии достаточных оснований полагать, что обвиняемый, подозреваемый: 1) скроется от предварительного расследования или суда; 2) может продолжать заниматься преступной деятельностью; 3) может угрожать свидетелю, иным участникам уголовного судопроизводства, уничтожить доказательства либо иным путем воспрепятствовать производству по уголовному делу. ч. 2. При решении вопроса о необходимости избрания меры пресечения в виде запрета определенных действий в отношении подозреваемого или обвиняемого в совершении преступления должны учитываться также тяжесть преступления, его совершение с применением насилия либо с угрозой его применения, сведения о личности подозреваемого или обвиняемого, его возраст, состояние здоровья, семейное положение, род занятий и другие обстоятельства. ч. 3. Мера пресечения отменяется соответствующим решением суда, когда в ней отпадает необходимость.","r":"УПК ст. 55"},{"d":"УПК РО","t":"Статья 56. Основания применения иных мер процессуального принуждения","x":"В целях обеспечения установленного настоящим Кодексом порядка уголовного процесса, надлежащего исполнения приговора, дознаватель, следователь, прокурор, суд вправе применить к подозреваемому или обвиняемому следующие меры процессуального принуждения: 1) обязательство о явке; 2) привод; 3) временное отстранение от должности.","r":"УПК ст. 56"},{"d":"УПК РО","t":"Статья 57. Обязательство о явке","x":"ч. 1. При необходимости у подозреваемого, обвиняемого, а также потерпевшего или свидетеля может быть взято обязательство о явке. ч. 2. Обязательство о явке состоит в письменном обязательстве лица, указанного в части первой настоящей статьи, своевременно являться по вызовам прокурора, следователя, дознавателя или в суд. Лицу разъясняются последствия нарушения обязательства, о чем делается соответствующая отметка в обязательстве.","r":"УПК ст. 57"},{"d":"УПК РО","t":"Статья 58. Привод","x":"ч. 1. В случае неявки по вызову без уважительных причин подозреваемый, обвиняемый, а также потерпевший, свидетель могут быть подвергнуты приводу. Приводу подлежит также осужденный. ч. 2. Привод состоит в принудительном доставлении лица к следователю, дознавателю, прокурору или в суд, а также на обязательные или исправительные работы. ч. 3. При наличии причин, препятствующих явке по вызову в назначенный срок, лица, указанные в части первой настоящей статьи, незамедлительно уведомляют орган, которым они вызывались.","r":"УПК ст. 58"},{"d":"УПК РО","t":"Статья 59. Временное отстранение от должности","x":"ч. 1. Временное отстранение от должности в качестве меры процессуального принуждения может быть назначено только судом. При необходимости временного отстранения от должности подозреваемого или обвиняемого следователь, дознаватель возбуждает перед судом соответствующее ходатайство. Суд может применить данную меру пресечения и по собственной инициативе. ч. 2. В течение 24 часов с момента поступления ходатайства судья выносит постановление, а суд - определение о временном отстранении подозреваемого или обвиняемого от должности либо об отказе в удовлетворении ходатайства. ч. 3. Постановление о временном отстранении подозреваемого или обвиняемого от должности направляется по месту его работы. ч. 4. Временное отстранение подозреваемого или обвиняемого от должности отменяется на основании постановления судьи, определения суда, когда в применении этой меры отпадает необходимость.","r":"УПК ст. 59"},{"d":"УПК РО","t":"Статья 60. Лица, имеющие право заявить ходатайство","x":"ч. 1. Подозреваемый, обвиняемый, его защитник, потерпевший, его законный представитель и представитель, эксперт, гражданский истец, гражданский ответчик, их представители, и иное лицо, права и законные интересы которых затронуты в ходе досудебного или судебного производства, вправе заявить ходатайство о производстве процессуальных действий или принятии процессуальных решений для установления обстоятельств, имеющих значение для уголовного дела, обеспечения прав и законных интересов лица, заявившего ходатайство, либо представляемых им лица или организации. ч. 2. Ходатайство заявляется следователю, дознавателю, прокурору либо в суд. ч. 3. Правом заявлять ходатайство в ходе судебного разбирательства обладает также государственный обвинитель.","r":"УПК ст. 60"},{"d":"УПК РО","t":"Статья 61. Заявление ходатайства","x":"ч. 1. Ходатайство может быть заявлено в любой момент производства по уголовному делу. Письменное ходатайство приобщается к уголовному делу, устное - фиксируется на видеозаписи следственного действия или судебного заседания. ч. 2. Отклонение ходатайства не лишает заявителя права вновь заявить ходатайство.","r":"УПК ст. 61"},{"d":"УПК РО","t":"Статья 62. Сроки рассмотрения ходатайства","x":"Ходатайство подлежит рассмотрению и разрешению непосредственно после его заявления. В случаях, когда немедленное принятие решения по ходатайству, заявленному в ходе предварительного расследования, невозможно, оно должно быть разрешено не позднее суток со дня его заявления.","r":"УПК ст. 62"},{"d":"УПК РО","t":"Статья 63. Разрешение ходатайства","x":"Об удовлетворении ходатайства либо о полном или частичном отказе в его удовлетворении следователь, дознаватель, прокурор, судья выносят постановление, а суд - определение, которое доводится до сведения лица, заявившего ходатайство. Решение по ходатайству может быть обжаловано в порядке, установленном главой 16 настоящего Кодекса.","r":"УПК ст. 63"},{"d":"УПК РО","t":"Статья 64. Право обжалования","x":"ч. 1. Действия (бездействие) и решения следователя, дознавателя, прокурора и суда могут быть обжалованы в установленном настоящим Кодексом порядке участниками уголовного процесса, а также иными лицами в той части, в которой производимые процессуальные действия и принимаемые процессуальные решения затрагивают их интересы. ч. 2. При нарушении разумных сроков уголовного процесса в ходе досудебного производства по уголовному делу участники таковых, а также иные лица, интересы которых затрагиваются, могут обратиться к прокурору с жалобой, которая должна быть рассмотрена в порядке и в сроки, установленные статьей 65 настоящего Кодекса.","r":"УПК ст. 64"},{"d":"УПК РО","t":"Статья 65. Порядок рассмотрения жалобы прокурором","x":"ч. 1. Прокурор рассматривает жалобу в течение трех суток со дня ее получения. В исключительных случаях, когда для проверки жалобы необходимо истребовать дополнительные материалы либо принять иные меры, допускается рассмотрение жалобы в срок до четырех суток, о чем извещается заявитель. ч. 2. По результатам рассмотрения жалобы прокурор выносит постановление о полном или частичном удовлетворении жалобы либо об отказе в ее удовлетворении. ч. 3. В случае удовлетворения жалобы, поданной в соответствии с частью второй статьи 64 настоящего Кодекса, в постановлении должны быть указаны процессуальные действия, осуществляемые для ускорения рассмотрения дела, и сроки их осуществления. ч. 4. Заявитель должен быть незамедлительно уведомлен о решении, принятом по жалобе, и дальнейшем порядке его обжалования. ч. 5. В случаях, предусмотренных настоящим Кодексом, следователь, дознаватель вправе обжаловать действия (бездействие) и решения прокурора вышестоящему прокурору.","r":"УПК ст. 65"},{"d":"УПК РО","t":"Статья 66. Судебный порядок рассмотрения жалоб","x":"ч. 1. Постановления следователя, дознавателя об отказе в возбуждении уголовного дела, о прекращении уголовного дела, а равно иные действия (бездействие) и решения следователя, дознавателя и прокурора, которые способны причинить ущерб конституционным правам и свободам участников уголовного процесса либо затруднить доступ граждан к правосудию, могут быть обжалованы в суд. ч. 2. Жалоба может быть подана в суд заявителем, его защитником, законным представителем или представителем непосредственно. ч. 3. Судья проверяет законность и обоснованность действий (бездействия) и решений следователя, дознавателя, прокурора не позднее чем через 3 суток со дня поступления жалобы в судебном заседании с участием заявителя и его защитника, законного представителя или представителя, если они участвуют в уголовном деле, иных лиц, чьи интересы непосредственно затрагиваются обжалуемыми действием (бездействием) или решением, а также с участием прокурора, следователя, дознавателя. Неявка лиц, своевременно извещенных о времени рассмотрения жалобы и не настаивающих на ее рассмотрении с их участием, не является препятствием для рассмотрения жалобы судом. ч. 4. В начале судебного заседания судья объявляет, какая жалоба подлежит рассмотрению, представляется явившимся в судебное заседание лицам, разъясняет их права и обязанности. Затем заявитель, если он участвует в судебном заседании, обосновывает жалобу, после чего заслушиваются другие явившиеся в судебное заседание лица. Заявителю предоставляется возможность выступить с репликой. ч. 5. По результатам рассмотрения жалобы судья в форме постановления, а…","r":"УПК ст. 66"},{"d":"УПК РО","t":"Статья 67. Жалоба и представление на приговор, определение, постановление суда","x":"Жалобы и представления на приговоры, определения, постановления судов первой и апелляционной инстанций, а также жалобы и представления на судебные решения, принимаемые в ходе досудебного производства по уголовному делу, приносятся в порядке, установленном настоящим Кодексом и Федеральным законом.","r":"УПК ст. 67"},{"d":"УПК РО","t":"Статья 68. Процессуальные издержки","x":"ч. 1. Процессуальными издержками являются связанные с уголовным судопроизводством расходы, которые возмещаются за счет средств бюджета либо средств участников уголовного процесса. ч. 2. К процессуальным издержкам относятся: 1) суммы, выплачиваемые потерпевшему на покрытие расходов, связанных с выплатой вознаграждения представителю потерпевшего; 2) вознаграждение, выплачиваемое эксперту, специалисту за исполнение ими своих обязанностей в ходе уголовного процесса, за исключением случаев, когда эти обязанности исполнялись ими в порядке служебного задания; 3) суммы, выплачиваемые адвокату за оказание им юридической помощи в случае участия адвоката в уголовном процессе по назначению; 4) суммы, израсходованные на производство судебной экспертизы в экспертных учреждениях; 5) иные расходы, понесенные в ходе уголовного судопроизводства и предусмотренные настоящим Кодексом. ч. 3. Суммы, указанные в части второй настоящей статьи, выплачиваются по постановлению следователя, прокурора или судьи либо по определению суда.","r":"УПК ст. 68"},{"d":"УПК РО","t":"Статья 69. Взыскание процессуальных издержек","x":"ч. 1. Процессуальные издержки взыскиваются с осужденных, а также с лиц, уголовное дело или уголовное преследование в отношении которых прекращено по основаниям, не дающим права на реабилитацию, или возмещаются за счет средств бюджета. ч. 2. В случае реабилитации лица процессуальные издержки возмещаются за счет средств бюджета.","r":"УПК ст. 69"},{"d":"УПК РО","t":"Статья 70. Основания возникновения права на реабилитацию","x":"ч. 1. Право на реабилитацию включает в себя право на возмещение имущественного вреда, устранение последствий морального вреда и восстановление в трудовых, пенсионных, жилищных и иных правах. Вред, причиненный гражданину в результате уголовного преследования, возмещается государством в полном объеме независимо от вины следователя, дознавателя, прокурора и суда. ч. 2. Право на реабилитацию, в том числе право на возмещение вреда, связанного с уголовным преследованием, имеют: 1) подсудимый, в отношении которого вынесен оправдательный приговор; 2) подсудимый, уголовное преследование в отношении которого прекращено в связи с отказом государственного обвинителя от обвинения; 3) подозреваемый или обвиняемый, уголовное преследование в отношении которого прекращено по основаниям, предусмотренным пунктами 1, 2, 4 и 5 части первой статьи 17 и пунктом 1 статьи 18 настоящего Кодекса; 4) осужденный - в случаях полной или частичной отмены вступившего в законную силу обвинительного приговора суда и прекращения уголовного дела по основаниям, предусмотренным статьей 17 настоящего Кодекса. ч. 3. Право на возмещение вреда в порядке, установленном настоящей главой, имеет также любое лицо, незаконно подвергнутое мерам процессуального принуждения в ходе производства по уголовному делу.","r":"УПК ст. 70"},{"d":"УПК РО","t":"Статья 71. Признание права на реабилитацию","x":"Суд в приговоре, определении, постановлении, а следователь, дознаватель в постановлении признают за оправданным либо лицом, в отношении которого прекращено уголовное преследование, право на реабилитацию.","r":"УПК ст. 71"},{"d":"УПК РО","t":"Статья 72. Возмещение имущественного вреда","x":"Возмещение реабилитированному имущественного вреда включает в себя возмещение: 1) заработной платы, пенсии, пособия, других средств, которых он лишился в результате уголовного преследования; 2) конфискованного или обращенного в доход государства на основании приговора или решения суда его имущества; 3) штрафов и процессуальных издержек, взысканных с него во исполнение приговора суда; 4) сумм, выплаченных им за оказание юридической помощи; 5) иных расходов.","r":"УПК ст. 72"},{"d":"УПК РО","t":"Статья 73. Возмещение морального вреда","x":"ч. 1. Прокурор от имени государства приносит официальное извинение реабилитированному за причиненный ему вред. ч. 2. Иски о компенсации за причиненный моральный вред в денежном выражении предъявляются в порядке гражданского судопроизводства. ч. 3. По требованию реабилитированного суд, прокурор, следователь, дознаватель обязаны в срок не позднее двух суток направить письменные сообщения о принятых решениях, оправдывающих гражданина, по месту его работы, учебы или месту жительства.","r":"УПК ст. 73"},{"d":"УПК РО","t":"Статья 74. Обжалование решения о производстве выплат","x":"Постановление судьи о производстве выплат, возврате имущества может быть обжаловано в порядке, установленном законодательством РО.","r":"УПК ст. 74"},{"d":"УПК РО","t":"Статья 75. Восстановление иных прав реабилитированного","x":"ч. 1. Восстановление трудовых, пенсионных, жилищных и иных прав реабилитированного производится в порядке, определяемом законодательством РО. Если требование о возмещении вреда судом не удовлетворено или реабилитированный не согласен с принятым судебным решением, то он вправе обратиться в суд в порядке гражданского судопроизводства. ч. 2. Реабилитированным, которые были лишены на основании судебного решения специальных, воинских и почетных званий, классных чинов, а также государственных наград, восстанавливаются соответствующие звания, классные чины и возвращаются государственные награды.","r":"УПК ст. 75"},{"d":"УПК РО","t":"Статья 76. Возмещение вреда юридическим лицам","x":"Вред, причиненный юридическим лицам незаконными действиями (бездействием) и решениями суда, прокурора, следователя, дознавателя, возмещается государством в полном объеме в порядке и сроки, которые установлены настоящей главой.","r":"УПК ст. 76"},{"d":"УПК РО","t":"Статья 77. Поводы и основания к возбуждению уголовного дела","x":"ч. 1. Поводами к возбуждению уголовного дела являются: 1) заявление о преступлении; 2) явка с повинной; 3) сообщение о совершенном или готовящемся преступлении, полученное из иных источников; 4) непосредственное обнаружение органом уголовного преследования, должностными лицами таких органов сведений, указывающих на признаки преступления; 5) постановление прокурора о направлении соответствующих материалов в орган предварительного расследования для решения вопроса об уголовном преследовании. ч. 2. Основанием для возбуждения уголовного дела является наличие достаточных данных, указывающих на признаки уголовного правонарушения. ч. 3. Производство по уголовному делу ведется с письменной отчетностью или без нее.","r":"УПК ст. 77"},{"d":"УПК РО","t":"Статья 77.1. Порядок рассмотрения сообщения о правонарушении","x":"ч. 1. Следователь, дознаватель обязаны принять, проверить сообщение о любом совершенном или готовящемся правонарушении и в пределах компетенции, установленной настоящим Кодексом, принять по нему решение в срок не позднее 3 суток со дня поступления указанного сообщения. При проверке сообщения о правонарушении следователь вправе получать объяснения, образцы для сравнительного исследования, истребовать документы, вещественные доказательства и предметы, изымать их в порядке, установленном настоящим Кодексом, назначать судебную экспертизу, принимать участие в ее производстве и получать заключение эксперта в разумный срок, производить осмотр места происшествия, документов, предметов, вещественных доказательств, трупов, освидетельствование, требовать производства документальных проверок, ревизий, исследований документов, предметов, трупов, привлекать к участию в этих действиях специалистов, давать обязательное для исполнения поручение о проведении оперативно-розыскных мероприятий. ч. 2. Заявителю выдается документ о принятии сообщения о преступлении с указанием данных о лице, его принявшем, а также даты и времени его принятия. ч. 3. Отказ в приеме сообщения о преступлении может быть обжалован прокурору или в суд в порядке, установленном статьями 65 и 66 настоящего Кодекса.","r":"УПК ст. 77.1"},{"d":"УПК РО","t":"Статья 78. Возбуждение уголовного дела","x":"Уголовное дело считается возбужденным: 1) с момента вынесения дознавателем, следователем постановления о возбуждении уголовного дела, в котором должны быть указаны: а) дата, время и место его вынесения; б) кем оно вынесено; в) повод и основание для возбуждения уголовного дела; г) пункт, часть, статья Уголовного кодекса РО, на основании которых возбуждается дело; 2) при задержании лица дознавателем, следователем в порядке главы 12 настоящего Кодекса за совершение преступления публичного обвинения с момента фиксации преступления публичного обвинения, а по делам частного и частно-публичного обвинения - с момента поступления заявления о преступлении при его фиксации, за исключением случаев, предусмотренных п. 1 настоящей статьи. В случаях возбуждения уголовного дела в порядке пункта 2 части 1 настоящей статьи, сотрудник, ведущий уголовное дело, обязан хранить доказательства оснований для возбуждения уголовного дела в течение 48 часов, запись должна быть цельная, со звуком, без элементов монтажа.","r":"УПК ст. 78"},{"d":"УПК РО","t":"Статья 79. Предварительное расследование","x":"ч. 1. Предварительное расследование производится в форме предварительного следствия либо в форме дознания. ч. 2. Предварительное расследование начинается с момента возбуждения уголовного дела.","r":"УПК ст. 79"},{"d":"УПК РО","t":"Статья 80. Подследственность","x":"ч. 1. Предварительное расследование производится следователями и дознавателями. ч. 2. Предварительное следствие производится: 1) следователями Следственного комитета РО - по уголовным делам о любых преступлениях; 2) следователями органов федеральной службы безопасности - по уголовным делам о любых преступлениях, не ведущихся с письменной отчетностью и относящихся к федеральной юрисдикции (Ф), за исключением уголовных дел, предусмотренных статьями 91, 101 Уголовного кодекса РО. ч. 3. Дознание производится: 1) дознавателями органов внутренних дел (полиции) - по уголовным делам о любых преступлениях, относящихся к региональной юрисдикции (Р), за исключением уголовных дел, подследственных органам, предусмотренным пунктами 2, 3 настоящей статьи, а также уголовных дел, предусмотренных статьями 91, 101 Уголовного кодекса РО; 2) дознавателями органов Федеральной Службы Охраны РО - по уголовным делам о любых преступлениях, не ведущихся с письменной отчетностью и относящихся к федеральной юрисдикции (Ф), за исключением уголовных дел, предусмотренных статьями 91, 101 Уголовного кодекса РО; 3) дознавателями органов военной полиции Вооруженных Сил РО - по уголовным делам о любых преступлениях, предусмотренных главой 21 Уголовного кодекса РО (В) или о любых преступлениях, совершенных военнослужащими Вооруженных Сил РО, по отношению к военнослужащим ВС РО, за исключением уголовных дел, предусмотренных статьями 91, 101 Уголовного кодекса РО. ч. 4. Споры о подследственности уголовного дела разрешает прокурор. Прокурор вправе перераспределить дело к производству органа вопреки общим…","r":"УПК ст. 80"},{"d":"УПК РО","t":"Статья 80.1. Соединение уголовных дел","x":"ч. 1. В одном производстве могут быть соединены уголовные дела в отношении: 1) нескольких лиц, совершивших одно или несколько преступлений в соучастии; 2) одного лица, совершившего несколько преступлений; 3) лица, обвиняемого в заранее не обещанном укрывательстве преступлений, расследуемых по этим уголовным делам. ч. 2. Соединение уголовных дел допускается также в случаях, когда лицо, подлежащее привлечению в качестве обвиняемого, не установлено, но имеются достаточные основания полагать, что несколько преступлений совершены одним лицом или группой лиц. ч. 3. Соединение уголовных дел, находящихся в производстве следователя, дознавателя, производится на основании его постановления. Решение о соединении уголовных дел о преступлениях, подследственных в соответствии со статьей 80 настоящего Кодекса разным органам предварительного расследования, принимается на основании решения прокурора об определении подследственности. ч. 4. При соединении уголовных дел срок производства по ним определяется по уголовному делу, имеющему наиболее длительный срок предварительного расследования. При этом срок производства по остальным уголовным делам поглощается наиболее длительным сроком и дополнительно не учитывается.","r":"УПК ст. 80.1"},{"d":"УПК РО","t":"Статья 80.2. Возбуждение и соединение уголовных дел при выявлении нового преступления в ходе предварительного расследования","x":"В случае, если в ходе предварительного расследования становится известно о совершении нового преступления, отнесенного к подследственности того же органа предварительного расследования, и при наличии оснований для соединения уголовных дел, предусмотренных частями первой и второй статьи 80.1 настоящего Кодекса, следователь, дознаватель вправе без выделения в отдельное производство материалов возбудить уголовное дело, которое соединяется с расследуемым уголовным делом.","r":"УПК ст. 80.2"},{"d":"УПК РО","t":"Статья 80.3. Выделение уголовного дела","x":"Следователь, дознаватель вправе выделить из уголовного дела в отдельное производство другое уголовное дело.","r":"УПК ст. 80.3"},{"d":"УПК РО","t":"Статья 80.4. Недопустимость разглашения данных предварительного расследования","x":"ч. 1. Данные предварительного расследования не подлежат разглашению, за исключением случаев, предусмотренных частями второй, четвертой и шестой настоящей статьи. ч. 2. Данные предварительного расследования могут быть преданы гласности лишь с разрешения следователя, дознавателя и только в том объеме, в каком ими будет признано это допустимым, если разглашение не противоречит интересам предварительного расследования и не связано с нарушением прав, свобод и законных интересов участников уголовного судопроизводства. ч. 3. Следователь предупреждает участников уголовного судопроизводства о недопустимости разглашения без соответствующего разрешения данных предварительного расследования, о чем у них берется подписка с предупреждением об ответственности в соответствии со статьей 95.1 Уголовного кодекса РО. ч. 4. Запрет на предание гласности данных предварительного расследования не распространяется на сведения: 1) о нарушении закона органами государственной власти и их должностными лицами; 2) распространенные следователем или прокурором в средствах массовой информации, информационно-телекоммуникационной сети \"Интернет\" или иным публичным способом; 3) оглашенные в открытом судебном заседании. ч. 5. Разглашение данных о частной жизни участников уголовного судопроизводства без их согласия не допускается. ч. 6. Не является разглашением данных предварительного расследования: 1) изложение сведений по уголовному делу в ходатайствах, заявлениях, жалобах и иных процессуальных документах по этому делу, а также в заявлениях и иных документах, подаваемых в государственные и межгосударственные…","r":"УПК ст. 80.4"},{"d":"УПК РО","t":"Статья 80.5. Основания, порядок и сроки приостановления предварительного расследования","x":"ч. 1. Предварительное расследование приостанавливается при наличии одного из следующих оснований: 1) лицо, подлежащее привлечению в качестве обвиняемого, не установлено; 2) подозреваемый или обвиняемый скрылся от следствия либо место его нахождения не установлено по иным причинам; 3) место нахождения подозреваемого или обвиняемого известно, однако реальная возможность его участия в уголовном деле отсутствует. ч. 2. О приостановлении предварительного расследования следователь выносит постановление, копию которого направляет прокурору. ч. 3. Если по уголовному делу привлечено два или более обвиняемых, а основания для приостановления относятся не ко всем обвиняемым, то следователь вправе выделить в отдельное производство и приостановить уголовное дело в отношении отдельных обвиняемых. ч. 4. По основаниям, предусмотренным пунктами 1 и 2 части первой настоящей статьи, предварительное расследование приостанавливается лишь по истечении его срока. По основаниям, предусмотренным пунктом 3 части первой настоящей статьи, предварительное расследование может быть приостановлено и до окончания его срока.","r":"УПК ст. 80.5"},{"d":"УПК РО","t":"Статья 80.6. Действия следователя после приостановления предварительного расследования","x":"ч. 1. Приостановив предварительное расследование, следователь уведомляет об этом потерпевшего, его представителя, гражданского истца, гражданского ответчика или их представителей и одновременно разъясняет им порядок обжалования данного решения. ч. 2. После приостановления предварительного расследования следователь: 1) принимает меры по установлению лица, подлежащего привлечению в качестве подозреваемого или обвиняемого; 2) устанавливает место нахождения подозреваемого или обвиняемого, а если он скрылся, принимает меры по его розыску. ч. 3. После приостановления предварительного расследования производство следственных действий не допускается.","r":"УПК ст. 80.6"},{"d":"УПК РО","t":"Статья 80.7. Возобновление приостановленного предварительного расследования","x":"ч. 1. Предварительное расследование возобновляется на основании решения следователя после того, как: 1) отпали основания его приостановления; 2) возникла необходимость производства следственных действий, которые могут быть осуществлены без участия подозреваемого, обвиняемого; 3) прокурором отменено постановление о приостановлении предварительного расследования. ч. 2. О возобновлении предварительного расследования сообщается подозреваемому, обвиняемому, его защитнику, потерпевшему, его представителю, гражданскому истцу, гражданскому ответчику или их представителям, а также прокурору.","r":"УПК ст. 80.7"},{"d":"УПК РО","t":"Статья 80.8. Розыск подозреваемого, обвиняемого, осужденного","x":"ч. 1. Если место нахождения подозреваемого, обвиняемого неизвестно, то следователь поручает его розыск. ч. 2. Розыск подозреваемого, обвиняемого может быть объявлен как во время производства предварительного расследования, так и одновременно с его приостановлением. ч. 3. В розыск могут быть объявлены лица, признанные виновными в совершении преступления вступившим в законную силу решением должностного лица, за которое им назначено наказание в виде реального лишения свободы или более строгое наказание в случае, если указанное наказание не приведено в исполнение.","r":"УПК ст. 80.8"},{"d":"УПК РО","t":"Статья 81. Основания для ведения предварительного расследования без письменной отчетности","x":"В случае, если уголовное дело в отношении лица возбуждено в связи с задержанием лица в порядке главы 12 настоящего Кодекса в порядке п. 2 ст. 78 настоящего Кодекса, то предварительное расследование по уголовному делу ведется без письменной отчетности в рамках этого задержания.","r":"УПК ст. 81"},{"d":"УПК РО","t":"Статья 82. Окончание предварительного расследования без письменной отчетности","x":"Установив, что по уголовному делу собраны достаточные материалы для окончания предварительного расследования без письменной отчетности, следователь, дознаватель выносит по уголовному делу следующее решение: 1) о признании лица виновным в совершении преступления и назначении ему наказания в соответствии с разделом III Уголовного кодекса РО; 2) о признании лица невиновным в совершении преступления.","r":"УПК ст. 82"},{"d":"УПК РО","t":"Статья 83. Особый порядок предварительного расследования без письменной отчетности","x":"ч. 1. При задержании подозреваемого, являющегося служащим органов государственной власти, об этом через рацию департамента и (или) горячую линию правительства уведомляется прокурор, руководство задержанного, а в случае задержания адвоката - председатель палаты адвокатов РО. На время ожидания ответа указанных лиц задержание приостанавливается, но не более чем на 10 минут. В случае ответа прокурора время задержания приостанавливается до его приезда, но не более чем на 10 минут. ч. 2. В случае невозможности прибытия прокурора задержанный государственный служащий подлежит освобождению. ч. 3. Дознаватель, следователь передает материалы уголовного дела прокурору. Прокурор выслушивает позиции сторон, рассматривает материалы дела, после чего дает оценку законности задержания и самостоятельно выносит решение по уголовному делу в порядке ст. 82 настоящего Кодекса.","r":"УПК ст. 83"},{"d":"УПК РО","t":"Статья 83.1. Судебный контроль при проведении предварительного расследования по уголовному делу без письменной отчетности","x":"ч. 1. При проведении предварительного расследования по уголовному делу без письменной отчетности подозреваемый, обвиняемый вправе требовать осуществления судебного контроля за действиями (бездействием), решениями дознавателя, следователя и иных лиц, участвующих в производстве по уголовному делу. Подозреваемый и обвиняемый должен объяснить следователю, дознавателю, какие действия (бездействие), решения должны быть проверены на законность судьей, осуществляющим судебный контроль. ч. 2. В случае заявления подозреваемым, обвиняемым требования, указанного в части первой настоящей статьи, дознаватель, следователь, прокурор должны доставить задержанного в здание суда, вызвать через рацию судью, а затем предоставить судье все необходимые материалы, обосновывающие обжалуемое подозреваемым, обвиняемым действие (бездействия), решения. Дознаватель, следователь ожидают ответ судьи в течение 10 минут, в случае ответа судьи о принятии вызова для проведения судебного контроля дознаватель, следователь ожидают прибытие судьи в течение 10 минут. В случае отсутствия ответа или неприбытия судьи в указанный срок проведение судебного контроля при проведении предварительного расследования необязательно. ч. 3. Судья, осуществляющий судебный контроль, проверяет законность действий (бездействия), решений следователя, дознавателя, прокурора, если о таковой проверке требует подозреваемый или обвиняемый. Судья, осуществляющий судебный контроль, присутствует при проведении предварительного расследования по уголовному делу без письменной отчетности до его окончания и рассматривает требования…","r":"УПК ст. 83.1"},{"d":"УПК РО","t":"Статья 84. Ведение предварительного расследования с письменной отчетностью","x":"ч. 1. За исключением случаев, предусмотренных статьей 81 настоящего Кодекса, уголовное дело ведется с обязательной письменной отчетностью в порядке, установленном настоящей главой. ч. 2. Процессуальные документы могут быть выполнены типографским, электронным способами. В случае отсутствия бланков процессуальных документов, выполненных типографским, электронным, они могут быть написаны от руки. ч. 3. Предварительное расследование с письменной отчетностью ведется только в форме предварительного следствия.","r":"УПК ст. 84"},{"d":"УПК РО","t":"Статья 85. Сроки предварительного расследования с письменной отчетностью","x":"Предварительное расследование по уголовному делу с письменной отчетностью должно быть закончено в срок, не превышающий недели со дня возбуждения уголовного дела. В срок предварительного расследования включается время со дня возбуждения уголовного дела и до дня его направления прокурору с обвинительным заключением.","r":"УПК ст. 85"},{"d":"УПК РО","t":"Статья 86. Порядок привлечения в качестве обвиняемого","x":"ч. 1. Если при предварительном расследовании по уголовному делу с письменной отчетностью следователь установит наличие достаточных доказательств, дающих основания для обвинения лица в совершении преступления, следователь выносит постановление о привлечении данного лица в качестве обвиняемого. ч. 2. В постановлении должны быть указаны: 1) дата и место его составления; 2) кем составлено постановление; 3) фамилия, имя и отчество лица, привлекаемого в качестве обвиняемого, число, месяц, год и место его рождения; 4) описание правонарушения с указанием времени, места его совершения, а также иных обстоятельств; 5) пункт, часть, статья Уголовного кодекса РО, предусматривающие ответственность за данное преступление; 6) решение о привлечении лица в качестве обвиняемого по расследуемому уголовному делу. ч. 3. При обвинении лица в совершении нескольких преступлений в постановлении о привлечении его в качестве обвиняемого должно быть указано, какие деяния вменяются ему по каждой из этих норм закона. ч. 4. При привлечении по одному уголовному делу в качестве обвиняемых нескольких лиц постановление о привлечении в качестве обвиняемого выносится в отношении каждого из них.","r":"УПК ст. 86"},{"d":"УПК РО","t":"Статья 87. Окончание предварительного расследования с письменной отчетностью","x":"ч. 1. Признав, что все следственные действия по уголовному делу произведены, а собранные доказательства достаточны для составления обвинительного заключения, следователь или дознаватель уведомляет об этом обвиняемого и разъясняет ему право на ознакомление со всеми материалами уголовного дела как лично, так и с помощью защитника, законного представителя, после чего составляет обвинительное заключение и передает уголовное дело с обвинительным заключением на рассмотрение прокурору. ч. 2. В обвинительном заключении должны содержаться: 1) фамилии и имена обвиняемого или обвиняемых; 2) данные о личности каждого из них; 3) существо обвинения, место и время совершения преступления, его способы, мотивы, цели, последствия и другие обстоятельства, имеющие значение для данного уголовного дела; 4) формулировку предъявленного обвинения с указанием пункта, части, статьи Уголовного кодекса РО, предусматривающих ответственность за данное преступление; 5) перечень доказательств, подтверждающих обвинение, и краткое изложение их содержания; 6) перечень доказательств, на которые ссылается сторона защиты, и краткое изложение их содержания; 7) обстоятельства, смягчающие и отягчающие наказание; 8) данные о потерпевшем, характере и размере вреда, причиненного ему преступлением; 9) данные о гражданском истце и гражданском ответчике; 10) ссылки на тома и листы уголовного дела; 11) список подлежащих вызову в судебное заседание лиц со стороны обвинения и защиты; 12) дату и место составления обвинительного заключения, подпись следователя (следователей). ч. 3. Прокурор в течение суток рассматривает…","r":"УПК ст. 87"},{"d":"УПК РО","t":"Статья 88. Общие правила производства следственных действий","x":"ч. 1. Следственные действия, предусмотренные статьями 89, 91, 92, главой 26 настоящего Кодекса, производятся на основании решения следователя, дознавателя, прокурора. ч. 2. Следственные действия, предусмотренные статьями 93 - 95 настоящего Кодекса, производятся на основании судебного решения. ч. 3. Производство следственного действия в ночное время не допускается, за исключением случаев, не терпящих отлагательства. ч. 4. При производстве следственных действий недопустимо применение насилия, угроз и иных незаконных мер, а равно создание опасности для жизни и здоровья участвующих в них лиц. ч. 5. Для производства следственных действий, которые могут быть произведены только на основании судебного решения, в соответствии с частью второй настоящей статьи, дознаватель, следователь, прокурор возбуждают перед судом соответствующее ходатайство, которое суд рассматривает в порядке, установленном законом.","r":"УПК ст. 88"},{"d":"УПК РО","t":"Статья 88.1. Протоколирование следственного действия","x":"ч. 1. При проведении следственных действий, предусмотренных статьями 89 - 94, главой 26 настоящего Кодекса, следователь, дознаватель обязаны осуществлять видеопротоколирование хода указанных следственных действий. Видеоматериалы, полученные в ходе видеопротоколирования следственных действий, хранятся в материалах уголовного дела в качестве вещественных доказательств в соответствии с требованиями настоящего Кодекса. ч. 2. При проведении следственного действия, предусмотренного статьей 95 настоящего Кодекса, следователь, дознаватель составляет письменный протокол следственного действия, в котором указывает: дату и место составления протокола, проведения следственного действия; имя, фамилию, должность следователя, дознавателя, составляющего протокол; основания для проведения следственного действия; подробное описание результатов проведения следственного действия.","r":"УПК ст. 88.1"},{"d":"УПК РО","t":"Статья 89. Осмотр","x":"ч. 1. Осмотр места происшествия, местности, жилища, иного помещения, предметов и документов производится в целях обнаружения следов правонарушения, выяснения других обстоятельств, имеющих значение для уголовного дела. ч. 2. Осмотр места происшествия, документов и предметов может быть произведен до возбуждения уголовного дела.","r":"УПК ст. 89"},{"d":"УПК РО","t":"Статья 90. Задержание","x":"Основания и порядок производства задержания регулируется главой 12 настоящего Кодекса.","r":"УПК ст. 90"},{"d":"УПК РО","t":"Статья 91. Освидетельствование","x":"ч. 1. Для обнаружения на теле человека особых примет, следов правонарушения, телесных повреждений, выявления состояния опьянения или иных свойств и признаков, имеющих значение для уголовного дела или дела об административном правонарушении, если для этого не требуется производство судебной экспертизы, может быть произведено освидетельствование подозреваемого, обвиняемого, потерпевшего, а также свидетеля с его согласия, за исключением случаев, когда освидетельствование необходимо для оценки достоверности его показаний. В случаях, не терпящих отлагательства, освидетельствование может быть произведено до возбуждения уголовного дела или дела об административном правонарушении. ч. 2. Освидетельствование производится следователем. При необходимости следователь привлекает к участию в производстве освидетельствования врача или другого специалиста.","r":"УПК ст. 91"},{"d":"УПК РО","t":"Статья 92. Следственный эксперимент","x":"В целях проверки и уточнения данных, имеющих значение для уголовного дела или дела об административном правонарушении, следователь вправе произвести следственный эксперимент путем воспроизведения действий, а также обстановки или иных обстоятельств определенного события. При этом проверяется возможность восприятия каких-либо фактов, совершения определенных действий, наступления какого-либо события, а также выявляются последовательность происшедшего события и механизм образования следов. Производство следственного эксперимента допускается, если не создается опасность для здоровья участвующих в нем лиц.","r":"УПК ст. 92"},{"d":"УПК РО","t":"Статья 93. Личный обыск и обыск жилища","x":"ч. 1. Личный обыск допускается либо на основании судебного решения, либо при задержании подозреваемого в порядке главы 12 настоящего Кодекса. ч. 2. Обыск в жилище производится на основании судебного решения. ч. 3. До начала обыска следователь или дознаватель предъявляет судебное решение, разрешающее его производство, если оно обязательно для осуществления обыска. ч. 4. До начала обыска следователь или дознаватель предлагает добровольно выдать подлежащие изъятию предметы, документы и ценности, которые могут иметь значение для уголовного дела. Если они выданы добровольно и нет оснований опасаться их сокрытия, то следователь вправе не производить обыск. ч. 5. При производстве обыска могут вскрываться любые помещения, если владелец отказывается добровольно их открыть. При этом не должно допускаться не вызываемое необходимостью повреждение имущества. ч. 6. Следователь, дознаватель принимает меры к тому, чтобы не были оглашены выявленные в ходе обыска обстоятельства частной жизни лица, в помещении которого был произведен обыск, его личная и (или) семейная тайна, а также обстоятельства частной жизни других лиц. ч. 7. Следователь, дознаватель вправе запретить лицам, присутствующим в месте, где производится обыск, покидать его, а также общаться друг с другом или иными лицами до окончания обыска. ч. 8. При производстве обыска во всяком случае изымаются предметы и документы, изъятые из оборота. ч. 9. Изъятые предметы, документы и ценности предъявляются другим лицам, присутствующим при обыске, и в случае необходимости упаковываются и опечатываются на месте обыска. ч. 10. При…","r":"УПК ст. 93","k":"личный обыск без суда ; когда допускается личный обыск ; обыск при задержании законно ли ; обыск в жилище нужно ли решение суда ; предложить выдать добровольно перед обыском"},{"d":"УПК РО","t":"Статья 94. Выемка","x":"ч. 1. Выемка производится для изъятия определенных предметов и документов, имеющих значение для уголовного дела, если точно известно, где и у кого они находятся. ч. 2. Выемка производится только на основании судебного решения. ч. 3. До начала выемки следователь или дознаватель предлагает выдать предметы и документы, подлежащие изъятию, а в случае отказа производит выемку принудительно.","r":"УПК ст. 94"},{"d":"УПК РО","t":"Статья 95. Контроль и запись переговоров","x":"ч. 1. При наличии достаточных оснований полагать, что телефонные и иные переговоры подозреваемого, обвиняемого и других лиц могут содержать сведения, имеющие значение для уголовного дела, их контроль и запись допускаются при производстве по уголовным делам о преступлениях средней тяжести, тяжких и особо тяжких преступлениях на основании судебного решения. ч. 2. При наличии угрозы совершения насилия, вымогательства и других преступных действий в отношении потерпевшего, свидетеля или их близких родственников, родственников, близких лиц контроль и запись телефонных и иных переговоров допускаются по письменному заявлению указанных лиц, а при отсутствии такого заявления - на основании судебного решения.","r":"УПК ст. 95"},{"d":"УПК РО","t":"Статья 96. Место и время допроса","x":"ч. 1. Допрос проводится по месту производства предварительного расследования. Следователь, дознаватель вправе, если признает это необходимым, провести допрос в месте нахождения допрашиваемого. ч. 2. Допрос не может длиться непрерывно более часа.","r":"УПК ст. 96"},{"d":"УПК РО","t":"Статья 97. Порядок вызова на допрос","x":"ч. 1. Свидетель, потерпевший вызывается на допрос повесткой, в которой указываются, кто и в каком качестве вызывается, к кому и по какому адресу, дата и время явки на допрос, а также последствия неявки без уважительных причин. ч. 2. Повестка вручается лицу, вызываемому на допрос, под расписку либо передается с помощью средств связи. В случае временного отсутствия лица, вызываемого на допрос, повестка передается администрации по месту его работы или по поручению следователя иным лицам и организациям, которые обязаны передать повестку лицу, вызываемому на допрос. ч. 3. Лицо, вызываемое на допрос, обязано явиться в назначенный срок либо заранее уведомить следователя о причинах неявки. В случае неявки без уважительных причин лицо, вызываемое на допрос, может быть подвергнуто приводу либо к нему могут быть применены иные меры процессуального принуждения, предусмотренные настоящим Кодексом. ч. 4. Лицо может быть допрошено на месте, если оно задержано в порядке главы 12 настоящего Кодекса.","r":"УПК ст. 97"},{"d":"УПК РО","t":"Статья 98. Общие правила проведения допроса","x":"ч. 1. Задавать наводящие вопросы запрещается. В остальном следователь свободен при выборе тактики допроса. ч. 2. Допрашиваемое лицо вправе пользоваться документами и записями. ч. 3. Ход проведения допроса должен быть в полном объеме зафиксирован на аудио- и (или) видеозапись. Указанная аудио- и (или) видеозапись хранится при уголовном деле. ч. 4. Если свидетель явился на допрос с адвокатом, приглашенным им для оказания юридической помощи, то адвокат присутствует при допросе и пользуется правами, предусмотренными настоящим Кодексом.","r":"УПК ст. 98"},{"d":"УПК РО","t":"Статья 99. Очная ставка","x":"ч. 1. Если в показаниях ранее допрошенных лиц имеются существенные противоречия, то следователь вправе провести очную ставку. ч. 2. Следователь выясняет у лиц, между которыми проводится очная ставка, знают ли они друг друга и в каких отношениях находятся между собой. Допрашиваемым лицам поочередно предлагается дать показания по тем обстоятельствам, для выяснения которых проводится очная ставка. После дачи показаний следователь может задавать вопросы каждому из допрашиваемых лиц. Лица, между которыми проводится очная ставка, могут с разрешения следователя задавать вопросы друг другу. ч. 3. В ходе очной ставки следователь вправе предъявить вещественные доказательства и документы. ч. 4. Оглашение показаний допрашиваемых лиц, содержащихся в протоколах предыдущих допросов, а также воспроизведение аудио- и (или) видеозаписи этих показаний допускаются лишь после дачи показаний указанными лицами или их отказа от дачи показаний на очной ставке. ч. 5. В протоколе очной ставки показания допрашиваемых лиц записываются в той очередности, в какой они давались. Каждое из допрашиваемых лиц подписывает свои показания, каждую страницу протокола и протокол в целом. ч. 6. Если свидетель явился на очную ставку с адвокатом, приглашенным им для оказания юридической помощи, то адвокат участвует в очной ставке и пользуется правами, предусмотренными настоящим Кодексом.","r":"УПК ст. 99"},{"d":"УПК РО","t":"Статья 100. Предъявление для опознания","x":"ч. 1. Следователь может предъявить для опознания лицо или предмет свидетелю, потерпевшему, подозреваемому или обвиняемому. ч. 2. Опознающие предварительно допрашиваются об обстоятельствах, при которых они видели предъявленные для опознания лицо или предмет, а также о приметах и особенностях, по которым они могут его опознать. ч. 3. Не может проводиться повторное опознание лица или предмета тем же опознающим и по тем же признакам. ч. 4. Лицо предъявляется для опознания вместе с другими лицами, по возможности внешне сходными с ним. Общее число лиц, предъявляемых для опознания, должно быть не менее трех. Это правило не распространяется на опознание трупа. Перед началом опознания опознаваемому предлагается занять любое место среди предъявляемых лиц, о чем в протоколе опознания делается соответствующая запись. ч. 5. При невозможности предъявления лица опознание может быть проведено по его фотографии, предъявляемой одновременно с фотографиями других лиц, внешне сходных с опознаваемым лицом. Количество фотографий должно быть не менее трех. ч. 6. Предмет предъявляется для опознания в группе однородных предметов в количестве не менее трех. При невозможности предъявления предмета его опознание проводится в порядке, установленном частью пятой настоящей статьи. ч. 7. Если опознающий указал на одно из предъявленных ему лиц или один из предметов, то опознающему предлагается объяснить, по каким приметам или особенностям он опознал данные лицо или предмет. Наводящие вопросы недопустимы. ч. 8. В целях обеспечения безопасности опознающего предъявление лица для опознания по решению…","r":"УПК ст. 100"},{"d":"УПК РО","t":"Статья 101. Проверка показаний на месте","x":"ч. 1. В целях установления новых обстоятельств, имеющих значение для уголовного дела, показания, ранее данные подозреваемым или обвиняемым, а также потерпевшим или свидетелем, могут быть проверены или уточнены на месте, связанном с исследуемым событием. ч. 2. Проверка показаний на месте заключается в том, что ранее допрошенное лицо воспроизводит на месте обстановку и обстоятельства исследуемого события, указывает на предметы, документы, следы, имеющие значение для уголовного дела, определенные действия. Какое-либо постороннее вмешательство в ход проверки и наводящие вопросы недопустимы. ч. 3. Не допускается одновременная проверка на месте показаний нескольких лиц. ч. 4. Проверка показаний начинается с предложения лицу указать место, где его показания будут проверяться. Лицу, показания которого проверяются, после свободного рассказа и демонстрации действий могут быть заданы вопросы.","r":"УПК ст. 101"},{"d":"УПК РО","t":"Статья 101.1. Арест","x":"Арест - процедура заключения под стражу и помещения в учреждение для отбывания наказания лица, признанного виновным в совершении преступления, за которое ему было назначено наказание в виде реального лишения свободы. Процедура ареста проходит в следующем порядке: 1) в отношении арестовываемого лица проводится личный обыск и изымаются предметы, которые могут представлять опасность; начальство виновного лица производит процедуру увольнения; в случае если наказание за совершённое преступление предусматривает наказание в виде лишение специального воинского звания (военного билета), руководство военнослужащего изымает военный билет. 2) должностное лицо, производящее арест, разъясняет арестовываемому лицу основания для ареста, включая пункт, часть, статью Уголовного кодекса РО, предусматривающие уголовную ответственность за преступление, за совершение которого ему назначено наказание в виде лишения свободы; 3) должностное лицо, производящее арест, заполняет бланк, где указывает данные арестовываемого, пункт, часть, статью Уголовного кодекса РО, предусматривающие уголовную ответственность за преступление, за совершение которого ему назначено наказание в виде лишения свободы, срок лишения свободы, иные данные, после чего помещает арестовываемого под стражу.","r":"УПК ст. 101.1","k":"обыск при аресте обязателен ; порядок ареста ; что делать при аресте ; изъять опасные предметы при аресте ; арест процедура ; чем арест отличается от задержания ; военный билет при аресте ; обыск обязателен когда"},{"d":"УПК РО","t":"Статья 102. Категории лиц, в отношении которых применяется особый порядок производства по уголовным делам","x":"ч. 1. Требования настоящей главы применяются при производстве по уголовным делам в отношении: 1) сенатора Федерального Собрания РО; 2) судьи; 3) руководителя органа государственной власти и его заместителя, в том числе министра и его заместителя; 4) Премьер-Министра РО и его заместителя; 6) Генерального Прокурора РО и его заместителей. ч. 2. Порядок производства по уголовным делам в отношении лиц, указанных в части первой настоящей статьи, устанавливается настоящим Кодексом с изъятиями, предусмотренными настоящей главой.","r":"УПК ст. 102"},{"d":"УПК РО","t":"Статья 103. Возбуждение уголовного дела","x":"ч. 1. Решение о возбуждении уголовного дела в отношении лица, указанного в части первой статьи 102 настоящего Кодекса, либо о привлечении его в качестве обвиняемого, если уголовное дело было возбуждено в отношении других лиц или по факту совершения деяния, содержащего признаки правонарушения, принимается органами следствия с согласия Верховного Суда РО. ч. 2. Не допускается возбуждение в отношении судьи уголовного дела по признакам преступления, предусмотренного статьей 96 Уголовного кодекса РО, в случае, если соответствующий судебный акт, вынесенный этим судьей или с его участием, вступил в законную силу и не отменен в установленном процессуальным законом порядке как неправосудный.","r":"УПК ст. 103"},{"d":"УПК РО","t":"Статья 104. Задержание","x":"ч. 1. Депутат Федерального Собрания РО, судья, Генеральный прокурор РО и его заместители, руководители органов государственной власти, в том числе министры, их заместители, Премьер-Министр РО, его заместитель, иные лица установленные законодательством как неприкосновенные, задержанные по подозрению в совершении правонарушения в порядке главы 12 настоящего Кодекса, должны быть освобождены немедленно после установления их личности.","r":"УПК ст. 104"},{"d":"УПК РО","t":"Статья 105. Полномочия судьи по поступившему в суд уголовному делу","x":"ч. 1. По поступившему уголовному делу судья принимает одно из следующих решений: 1) о направлении уголовного дела по подсудности; 2) о назначении судебного заседания; 3) о возвращении уголовного дела прокурору. ч. 2. Решение судьи оформляется постановлением, в котором указываются: 1) дата и место вынесения постановления; 2) наименование суда, фамилия и инициалы судьи, вынесшего постановление; 3) основания принятого решения. ч. 3. Решение принимается в срок не позднее 2 суток со дня поступления уголовного дела в суд. По просьбе стороны суд вправе предоставить ей возможность для дополнительного ознакомления с материалами уголовного дела. ч. 4. Копия постановления судьи направляется обвиняемому, потерпевшему и прокурору.","r":"УПК ст. 105"},{"d":"УПК РО","t":"Статья 106. Вопросы, подлежащие выяснению по поступившему в суд уголовному делу","x":"По поступившему в суд уголовному делу судья должен выяснить в отношении каждого из обвиняемых следующее: 1) подсудно ли уголовное дело данному суду; 2) подлежит ли избранию, отмене или изменению мера пресечения; 3) подлежат ли удовлетворению заявленные ходатайства и поданные жалобы; 4) имеются ли основания возвращения уголовного дела прокурору настоящим Кодексом.","r":"УПК ст. 106"},{"d":"УПК РО","t":"Статья 107. Назначение судебного заседания","x":"ч. 1. При отсутствии оснований для принятия решений, предусмотренных пунктами 1 и 3 части первой статьи 105 настоящего Кодекса, судья выносит постановление о назначении судебного заседания. ч. 2. В постановлении помимо вопросов, предусмотренных частью второй статьи 105 настоящего Кодекса, разрешаются следующие вопросы: 1) о месте, дате и времени судебного заседания; 2) о рассмотрении уголовного дела судьей единолично или судом коллегиально; 3) о назначении защитника; 4) о вызове в судебное заседание лиц по спискам, представленным сторонами либо по инициативе суда; 5) о рассмотрении уголовного дела в закрытом судебном заседании; 6) о мере пресечения. ч. 3. В постановлении также должны содержаться решения о назначении судебного заседания с указанием фамилии, имени каждого обвиняемого и квалификации вменяемого ему в вину преступления, а также о мере пресечения. ч. 4. Стороны должны быть извещены о месте, дате и времени судебного заседания не менее чем за сутки до его начала.","r":"УПК ст. 107"},{"d":"УПК РО","t":"Статья 109. Возвращение уголовного дела прокурору","x":"ч. 1. Судья по ходатайству стороны или по собственной инициативе возвращает уголовное дело прокурору для устранения препятствий его рассмотрения судом в случае, если обвинительное заключение составлено с нарушением требований настоящего Кодекса, что исключает возможность постановления судом приговора или вынесения иного решения на основе данного заключения. ч. 2. Судья по ходатайству стороны возвращает уголовное дело прокурору для устранения препятствий к его рассмотрению судом в случаях, если после направления уголовного дела в суд наступили новые общественно опасные последствия инкриминируемого обвиняемому деяния, являющиеся основанием для предъявления ему обвинения в совершении более тяжкого преступления.","r":"УПК ст. 109"},{"d":"УПК РО","t":"Статья 110. Вызовы в судебное заседание","x":"Судья дает распоряжение о вызове в судебное заседание лиц, указанных в его постановлении, а также принимает иные меры по подготовке судебного заседания.","r":"УПК ст. 110"},{"d":"УПК РО","t":"Статья 111. Срок начала разбирательства в судебном заседании","x":"Рассмотрение уголовного дела в судебном заседании должно быть начато не позднее 2 суток со дня вынесения судьей постановления о назначении судебного заседания.","r":"УПК ст. 111"},{"d":"УПК РО","t":"Статья 112. Подготовительная часть судебного заседания","x":"Подготовка к судебному следствию в судебном заседании происходит в следующем порядке: в назначенное время председательствующий открывает судебное заседание, объявляет, какое уголовное дело подлежит разбирательству; председательствующий, помощник судьи или секретарь судебного заседания докладывает о явке лиц, которые должны участвовать в судебном заседании, и сообщает о причинах неявки отсутствующих; явившиеся свидетели и лица, в отношении которых уголовные дела выделены в отдельное производство в связи с заключением с ними досудебного соглашения о сотрудничестве, до начала их допроса удаляются из зала судебного заседания; председательствующий устанавливает личность подсудимого, выясняя его фамилию, имя, отчество, год, месяц, день и место рождения, выясняет, владеет ли он языком, на котором ведется уголовное судопроизводство, место жительства подсудимого, место работы, род занятий, образование, семейное положение и другие данные, касающиеся его личности. Затем председательствующий выясняет, вручена ли подсудимому и когда именно копия обвинительного заключения, постановления прокурора об изменении обвинения; председательствующий объявляет состав суда, сообщает, кто является обвинителем, защитником, потерпевшим, гражданским истцом, гражданским ответчиком или их представителями, а также секретарем судебного заседания, экспертом, специалистом и переводчиком; председательствующий разъясняет подсудимому, потерпевшему, гражданскому истцу, гражданскому ответчику, эксперту, специалисту их права в судебном заседании, предусмотренные настоящим Кодексом и Федеральным законом;…","r":"УПК ст. 112"},{"d":"УПК РО","t":"Статья 113. Судебное следствие","x":"ч. 1. Судебное следствие проходит в следующем порядке: 1) государственный обвинитель излагает предъявленное подсудимому обвинение; 2) председательствующий опрашивает подсудимого, понятно ли ему обвинение, признает ли он себя виновным и желает ли он или его защитник выразить свое отношение к предъявленному обвинению; 3) судом исследуются доказательства по делу. Очередность исследования доказательств определяется стороной, представляющей доказательства суду. Первой представляет доказательства сторона обвинения. После исследования доказательств, представленных стороной обвинения, исследуются доказательства, представленные стороной защиты; 4) сторонами по делу допрашиваются поочередно подсудимый, потерпевший, свидетели, эксперт. После допроса подсудимого, потерпевшего, свидетелей, эксперта сторонами суд вправе задавать им свои вопросы. ч. 2. При допросе подсудимого, потерпевшего, свидетелей, эксперта не допускаются вопросы, не имеющие отношение к делу, наводящие вопросы и вопросы, на которые допрашиваемым стороне уже давался ответ по существу. Такие вопросы подлежат снятию судом, а данные на них ответы не заносятся в протокол судебного заседания и не учитываются при постановлении приговора.","r":"УПК ст. 113"},{"d":"УПК РО","t":"Статья 114. Прения сторон","x":"ч. 1. Прения сторон состоят из речей обвинителя и защитника. При отсутствии защитника в прениях сторон участвует подсудимый. ч. 2. В прениях сторон могут также участвовать потерпевший и его представитель. Гражданский истец, гражданский ответчик, их представители, подсудимый вправе ходатайствовать об участии в прениях сторон. ч. 3. Последовательность выступлений участников прений сторон устанавливается судом. При этом первым во всех случаях выступает обвинитель, а последними - подсудимый и его защитник. Гражданский ответчик и его представитель выступают в прениях сторон после гражданского истца и его представителя. ч. 4. Участник прений сторон не вправе ссылаться на доказательства, которые не рассматривались в судебном заседании или признаны судом недопустимыми. ч. 5. Суд не вправе ограничивать продолжительность прений сторон. При этом председательствующий вправе останавливать участвующих в прениях лиц, если они касаются обстоятельств, не имеющих отношения к рассматриваемому уголовному делу, а также доказательств, признанных недопустимыми. ч. 6. После произнесения речей всеми участниками прений сторон каждый из них может выступить еще один раз с репликой. Право последней реплики принадлежит подсудимому или его защитнику. ч. 7. После окончания прений сторон председательствующий предоставляет подсудимому последнее слово. Никакие вопросы к подсудимому во время его последнего слова не допускаются. ч. 8. Если участники прений сторон или подсудимый в последнем слове сообщат о новых обстоятельствах, имеющих значение для уголовного дела, или заявят о необходимости предъявить суду…","r":"УПК ст. 114"},{"d":"УПК РО","t":"Статья 115. Требования к приговору","x":"ч. 1. Приговор постановляется именем РО. ч. 2. Приговор суда должен быть законным, обоснованным и справедливым и признается таковым, если он постановлен в соответствии с требованиями настоящего Кодекса и основан на правильном применении уголовного закона. ч. 3. Приговор постановляется судом в совещательной комнате. Во время постановления приговора в этой комнате могут находиться лишь судьи, входящие в состав суда по данному уголовному делу. По окончании рабочего времени, а также в течение рабочего дня суд вправе сделать перерыв для отдыха с выходом из совещательной комнаты. Судьи не вправе разглашать суждения, имевшие место при обсуждении и постановлении приговора, или иным способом раскрывать тайну совещания судей.","r":"УПК ст. 115"},{"d":"УПК РО","t":"Статья 116. Содержание приговора","x":"ч. 1. Приговор суда по уголовному делу может быть оправдательным или обвинительным. Приговор по уголовному делу всегда должен быть составлен в полном объеме. ч. 2. Приговор состоит из вводной, описательно-мотивировочной и резолютивной частей. ч. 3. В вводной части приговора указываются следующие сведения: а) о постановлении приговора именем РО; б) дата и место постановления приговора; в) наименование суда, постановившего приговор, состав суда, данные о помощнике судьи, секретаре судебного заседания, об обвинителе, о защитнике, потерпевшем, гражданском истце, гражданском ответчике и об их представителях; г) фамилия, имя подсудимого и иные данные о личности подсудимого, имеющие значение для уголовного дела; д) пункт, часть, статья Уголовного кодекса РО, предусматривающие ответственность за преступление, в совершении которого обвиняется подсудимый. ч. 4. В описательно-мотивировочной части оправдательного приговора излагаются: а) существо предъявленного обвинения; б) обстоятельства уголовного дела, установленные судом; в) основания оправдания подсудимого и доказательства, их подтверждающие; г) мотивы, по которым суд отвергает доказательства, представленные стороной обвинения; д) мотивы решения в отношении гражданского иска. Примечание: не допускается включение в оправдательный приговор формулировок, ставящих под сомнение невиновность оправданного. ч. 5. Резолютивная часть оправдательного приговора должна содержать: а) фамилию, имя подсудимого; б) решение о признании подсудимого невиновным и основания его оправдания; в) решение об отмене меры пресечения, если она была избрана;…","r":"УПК ст. 116"},{"d":"УПК РО","t":"Статья 117. Оглашение приговора","x":"ч. 1. После составления приговора суд в назначенное время оглашает его. ч. 2. В случае назначения подсудимому наказания в виде лишения свободы его берут под стражу в зале суда немедленно с последующим арестом.","r":"УПК ст. 117"},{"d":"УПК РО","t":"Статья 117.1. Особое производство по делам о злостном неисполнении судебного акта и неуважении к суду","x":"ч. 1.Суд, не осуществляя общий процессуальный порядок производства по уголовным делам, предусмотренный главой 29 настоящего Кодекса, вправе самостоятельно вести преследование и квалифицировать неуважение к суду и злостное неисполнение судебного акта по статье 91 и статье 101 Уголовного Кодекса РО соответственно. ч. 2. Привлечение к ответственности за совершение преступлений, предусмотренных частью 1 настоящей статьи, производствится на основании постановления суда о проведении особого производства по факту злостного неисполнения судебного акта или неуважения к суду, которое составляется по форме содержания приговоров, установленной статьей 116 настоящего Кодекса. ч. 3. Доказывание и доказательства в рамках особого производство по делам о злостном неисполнении судебного акта и неуважении к суду обязаны соответствовать требованиям, предъявляемым к ним настоящим Кодексом, и должны быть получены судом в результате выполнения судебных действий.","r":"УПК ст. 117.1"},{"d":"УПК РО","t":"Статья 118. Судебные акты, которые могут быть обжалованы в апелляционном порядке","x":"В апелляционном порядке могут быть оспорены только судебные акты первой инстанции в течение 48 часов с момента их вынесения.","r":"УПК ст. 118"},{"d":"УПК РО","t":"Статья 119. Право на апелляционное обжалование","x":"ч. 1. Апелляционную жалобу имеют право подать: а) подозреваемый, обвиняемый, гражданский ответчик, их законный представитель или защитник; б) гражданский истец, потерпевший, их законный представитель - в части, которая касается их интересов и в рамках требований, заявленных таковыми в суде первой инстанции; в) иные лица в случаях, предусмотренных этим Законом, а также в части, которая касается их интересов. ч. 2. Апелляционное представление имеет право подать прокурор.","r":"УПК ст. 119"},{"d":"УПК РО","t":"Статья 120. Особенности апелляционного обжалования отдельных судебных решений","x":"ч. 1. Апелляционная жалоба (представление) обязана содержать в себе мотивированные и обоснованные действующим законодательством аргументы. Апелляционная жалоба (представление) не считается мотивированной, если ее подает лицо, которое было должным образом уведомлено о судебном заседании, но не явилось на таковое, а затем ссылается на то, что суд не учел его аргументы или аргументы его стороны. Апелляционная жалоба (представление) не считается мотивированной, если ее подает представитель лица, привлеченный после заседания, при этом само лицо не явилось на судебное заседание и впоследствии утверждает, что суд не учел его аргументы или аргументы его стороны. ч. 2. Акт суда первой инстанции, принятый по результатам заочного производства, не может быть обжалован в апелляционном порядке на основании рассмотрения производства с отсутствием участника или участников судебного производства. ч. 3. Судебный акт суда первой инстанции не может быть обжалован в апелляционном порядке на основании отрицания либо возражения обстоятельств, которые никем не оспаривались во время судебного рассмотрения и изучение которых было признано судом нецелесообразным. ч. 4. В случае жалобы на приговор в суд апелляционной инстанции в подтверждение или опровержение доводов, приведенных в апелляционной жалобе (представлению), дополнительных материалов (новых доказательств) стороны вправе ходатайствовать об их приобщении к делу и исследовании либо высказать возражения по таким ходатайствам. С апелляционной жалобой (представлением) на приговор суд апелляционной инстанции после выступления сторон разрешает…","r":"УПК ст. 120"},{"d":"УПК РО","t":"Статья 121. Порядок и сроки апелляционного обжалования","x":"ч. 1. Апелляционная жалоба (представление), если иное не предусмотрено настоящим Законом, может быть подана на приговор либо иной судебный акт. ч. 2. Сроки подачи апелляционной жалобы (представления) устанавливаются в 48 часов с момента вступления судебного акта в юридическую силу. ч. 3. Сроки подачи апелляционного заявления в рамках соглашения с правосудием устанавливаются действующим законодательством и нормами соглашения. ч. 4. После поступления апелляционной жалобы (представления) в канцелярию суд рассматривает вопрос о её принятии в срок до 48 часов, а в случае принятия принимает дальнейшее решение.","r":"УПК ст. 121"},{"d":"УПК РО","t":"Статья 122. Требования к апелляционной жалобе, представлению","x":"ч. 1. Апелляционная жалоба (представление) подается в письменном виде и по установленной форме и в соответствии с указанными в форме требованиями. Заявитель обязан в полном объеме обоснованно и аргументировано указать, в чем заключается незаконность или необоснованность судебного решения. ч. 2. Если в апелляционной жалобе (представлении) указываются обстоятельства, которые не были изучены в суде первой инстанции, либо доказательства, которые не подавались суду первой инстанции, то в ней указываются таковые причины. ч. 3. Апелляционная жалоба (представление) подписывается лицом, которое ее подает. Если апелляционную жалобу подает защитник, адвокат или законный представитель любой из сторон, то к ней добавляется договор об оказании юридических услуг либо иной документ, необходимый для подтверждения законности и полномочий представителя. ч. 4. Апелляционная жалоба (представление) в административном или гражданском производстве может содержать ходатайство лица о рассмотрении дела с его участием. При отсутствии такого ходатайства считается, что лицо не желает участвовать в судебном заседании апелляционной инстанции.","r":"УПК ст. 122"},{"d":"УПК РО","t":"Статья 123. Оставление апелляционной жалобы, представления без движения, отказ в принятии жалобы (представления) к производству или продолжении производства","x":"ч. 1. Судья, установив, что апелляционная жалоба (представление) на приговор или иной акт суда первой инстанции подана без соответствия требованиям, предусмотренным настоящим Кодексом, принимает решение об отказе в принятии таковой жалобы (представления) к производству. ч. 2. Апелляционная жалоба (представление) не принимается к производству: а) в случаях, предусмотренных частью 1 настоящей статьи; б) апелляционную жалобу (представление) подало лицо, которое не имеет права подавать таковую; в) апелляционная жалоба (представление) не подлежит рассмотрению в суде апелляционной инстанции; г) апелляционная жалоба (представление) подана после окончания срока апелляционного обжалования. ч. 3. Судья отказывает в принятии жалобы (представления) к производству, если апелляционная жалоба (представление) подана на судебный акт, который не подлежит обжалованию в апелляционном порядке, или судебное решение оспорено исключительно на основаниях, по которым оно не может быть обжаловано в соответствии с положениями настоящего Закона. ч. 4. Оставление апелляционной жалобы (представления) без движения или отказ в принятии к производству может быть обжалован в кассационном порядке. ч. 5. Оставление апелляционной жалобы (представления) без движения или отказ в принятии к производству не лишают права повторного обращения в суд апелляционной инстанции в порядке, предусмотренном законом, в рамках сроков на апелляционное обжалование.","r":"УПК ст. 123"},{"d":"УПК РО","t":"Статья 124. Последствия подачи апелляционной жалобы, представления","x":"ч. 1. Подача апелляционной жалобы, представления на приговор или иной судебный акт не останавливает вступление такового в законную силу и исполнение такового, за исключением случаев, предусмотренных частью 2 текущей статьи. ч. 2. В случае, если заявлено ходатайство о приостановлении действия силы решения или иного акта суда первой инстанции, то суд при наличии весомых оснований приостанавливает действие такового.","r":"УПК ст. 124"},{"d":"УПК РО","t":"Статья 125. Подготовление к апелляционному рассмотрению","x":"ч. 1. Судья в течение 48 часов после принятия апелляционной жалобы, представления к производству: а) устанавливает дату судебного заседания; б) рассматривает возражения, поданные сторонами против апелляционного заявления; в) рассматривает иные ходатайства, в том числе ходатайства о проведении заочного судебного заседания; г) рассматривает иные вопросы, обстоятельства, необходимые для апелляционного рассмотрения. ч. 2. Обвиняемый подлежит обязательному вызову на судебное заседание для участия в апелляционном рассмотрении, если в апелляционной жалобе (представлении) затрагивается вопрос про ухудшение его положения или если суд признает обязательным участие такового.","r":"УПК ст. 125"},{"d":"УПК РО","t":"Статья 126. Границы пересмотра судом апелляционной инстанции","x":"ч. 1. Суд апелляционной инстанции пересматривает судебные решения суда первой инстанции в рамках апелляционной жалобы, представления. ч. 2. Суд апелляционной инстанции вправе выйти за границы апелляционных требований, если таковым не ухудшается положение обвиняемого, ответчика либо лица, в отношении которого разрешается вопрос про применение мер государственного принуждения, ограничения либо лишения свободы. Если рассмотрение апелляционной жалобы (представления) дает основания для принятия решения в пользу лиц, в интересах которых апелляционные жалобы не поступили, суд апелляционной инстанции обязан принять таковое решение. ч. 3. По ходатайству участников судебного производства суд апелляционной инстанции обязан повторно изучить обстоятельства, установленные во время производства, при условии, что таковые изучены судом первой инстанции не полностью либо с нарушениями, а также может изучить доказательства, которые не изучались судом первой инстанции, либо если доказательства стали известны после вынесения судебного решения, которое обжалуется. ч. 4. Суд апелляционной инстанции не вправе рассматривать обвинения, которые не были предъявлены в суде первой инстанции.","r":"УПК ст. 126"},{"d":"УПК РО","t":"Статья 127. Особенности рассмотрения в апелляционном порядке гражданских и административных дел","x":"ч. 1. Апелляционные жалобы на акты суда по административным или гражданским делам рассматриваются судом апелляционной инстанции без уведомления (вызова) участников дела в следующих случаях: а) отсутствие ходатайств от всех участников дела о рассмотрении дела с их участием; б) неприбытие ни одного из участников дела в судебное заседание, хотя они были должным образом уведомлены о дате, времени и месте судебного заседания; в) апелляционная жалоба (представление) на акт суда первой инстанции, проведенного в порядке заочного производства. ч. 2. С учетом конкретных обстоятельств дела суд апелляционной инстанции может рассмотреть апелляционные жалобы по делам, указанным в части первой настоящей статьи, в судебном заседании с обязательным вызовом участников дела. ч. 3. В случае рассмотрения жалобы с вызовом участников на слушание процесс проведения устанавливается в соответствии со статьей 110 настоящего Закона.","r":"УПК ст. 127"},{"d":"УПК РО","t":"Статья 128. Апелляционное рассмотрение в уголовном процессе","x":"ч. 1. Апелляционное рассмотрение проводится в соответствии с правилами и процессами судебного рассмотрения в суде первой инстанции с учетом особенностей, предусмотренных этой главой и иными правовыми нормами действующего законодательства. ч. 2. Председательствующий судья в необходимом таковому объеме докладывает содержание обжалуемого судебного решения, аргументы участников судебного решения, изложенные в апелляционных жалобах и возражениях, а также выясняет, поддерживают ли свои апелляционные жалобы и возражения лица, которые их подали. ч. 3. Для изложения аргументов, а также в прениях сторон первенство в выступлении предоставляется лицу, которое подало апелляционную жалобу. Если апелляционные жалобы подали обе стороны предыдущего разбирательства, первым излагает свои аргументы обвиняемый либо представитель такового. После этого слово предоставляется другим участникам судебного производства. ч. 4. Неприбытие на заседание сторон или иных участников производства не препятствует проведению заседания. В случае, если участник процесса не уведомил суд о своем отсутствии по весомой причине, таковой может быть привлечен к ответственности, предусмотренной законом. ч. 5. Перед уходом суда в совещательную комнату для вынесения решения касаемо законности и обоснованности решения суда первой инстанции обвиняемому или его представителю предоставляется последнее слово. Во время последнего слова ответчика не допускается заявление возражений, протестов в сторону речи такового.","r":"УПК ст. 128"},{"d":"УПК РО","t":"Статья 129. Полномочия суда апелляционной инстанции впоследствии рассмотрения апелляционной жалобы","x":"ч. 1. Впоследствии апелляционного рассмотрения по жалобе на приговор, решение или акт суда первой инстанции суд апелляционной инстанции вправе: а) об оставлении приговора, определения, постановления без изменения, а жалобы или представления без удовлетворения; б) об отмене обвинительного приговора и о вынесении оправдательного приговора; в) об отмене обвинительного приговора и о вынесении обвинительного приговора; г) об отмене приговора, определения, постановления суда первой инстанции и о передаче дела на новое судебное разбирательство в суд первой инстанции со стадии подготовки к судебному заседанию или судебного разбирательства; д) об отмене оправдательного приговора и о вынесении оправдательного приговора; е) об отмене определения или постановления и о вынесении оправдательного приговора либо иного судебного решения; ж) об отмене приговора, определения, постановления или иного акта и о возвращении уголовного дела прокурору; з) об отмене приговора, определения, постановления, решения или иного акта и о прекращении уголовного дела; и) об изменении приговора или иного обжалуемого судебного решения; к) о прекращении апелляционного производства. ч. 2. Указания суда апелляционной инстанции обязательны для суда первой инстанции и для прокурора, если уголовное дело возвращено для устранения обстоятельств, препятствующих вынесению законного и обоснованного решения.","r":"УПК ст. 129"},{"d":"УПК РО","t":"Статья 130. Изменение приговора или решения суда судом апелляционной инстанции","x":"ч. 1. Суд апелляционной инстанции изменяет приговор в случае: а) смягчения назначенного наказания, если признает, что наказание по своей строгости не соответствует тяжести нарушения и личности обвиняемого, ответчика; б) изменения правовой квалификации нарушения; в) изменения штрафных сумм; г) изменения правовой квалификации деяния, которое предусматривает ответственность за менее тяжкое деяние; д) применения дополнительных санкций, предусмотренных законом, в случае, если на усмотрение суда предыдущее решение суда вынесло менее строгое наказание; е) увеличения срока отбытия наказания, если признает, по своей строгости не соответствует тяжести нарушения и личности обвиняемого, ответчика; ё) в иных случаях по усмотрению суда.","r":"УПК ст. 130"},{"d":"УПК РО","t":"Статья 131. Основания для отмены или изменения судебного акта судом апелляционной инстанции","x":"ч. 1. Основанием для отмены или изменения судебного решения при рассмотрении дела в суде апелляционной инстанции являются: а) неполное выяснение обстоятельств, имеющих значение для дела, или их недоказанность; б) несоответствие выводов суда, изложенных в судебном решении, фактическим обстоятельствам дела; в) существенное нарушение требований действующего законодательства судом первой инстанции; г) нарушение или неправильное применение судом норм закона; д) рассмотрение дела в отсутствие кого-либо из участвующих в деле лиц, не извещенных надлежащим образом о времени и месте судебного заседания; е) принятие дела к производству в нарушение норм, установленных настоящим Законом; ё) судебный акт вынесен незаконным составом суда; ж) нарушены правила подсудности; з) не выполнено требований о ведении фиксации судебного заседания, только в случае надобности и по решению апелляционной инстанции.","r":"УПК ст. 131"},{"d":"УПК РО","t":"Статья 132. Неполнота судебного рассмотрения","x":"ч. 1. Неполным признается судебное разбирательство, в ходе которого остались неисследованными обстоятельства, выяснение которых может иметь важное значение для принятия законного, обоснованного и справедливого судебного решения, в частности, в случае если: а) судом были отклонены ходатайства участников судебного производства о допросе определенных лиц, исследовании доказательств или совершении других процессуальных действий для подтверждения или опровержения обстоятельств, выяснение которых может иметь существенное значение для принятия законного, обоснованного и справедливого судебного решения; б) необходимость исследования того или иного основания вытекает из новых данных, установленных при рассмотрении дела в суде апелляционной инстанции.","r":"УПК ст. 132"},{"d":"УПК РО","t":"Статья 133. Несоответствие выводов суда первой инстанции фактическим обстоятельствам производства","x":"ч. 1. Судебное решение считается таким, которое не соответствует фактическим обстоятельствам, если: а) выводы суда не подтверждаются доказательствами, изученными во время судебного рассмотрения; б) суд не взял во внимание доказательства, которые могли существенно повлиять на его выводы; в) при наличии спорных доказательств, которые имеют существенное значение для решений суда, в судебном решении не указано, почему суд взял во внимание одни доказательства и признал ничтожность других; г) выводы суда, изложенные в судебном решении, содержат существенные противоречия. ч. 2. Приговор подлежит отмене или изменению по указанным основаниям только тогда, когда несоответствие выводов суда фактическим обстоятельствам производства повлияло или могло повлиять на решение вопроса о виновности или невиновности обвиняемого, на правильность применения закона.","r":"УПК ст. 133"},{"d":"УПК РО","t":"Статья 134. Судебные решения, которые могут быть обжалованы в кассационном порядке","x":"ч. 1. В кассационном порядке могут быть обжалованы приговоры, решения и акты суда первой инстанции, если такой акт вступил в законную силу и с момента его вынесения прошло 48 часов. В случае, если с момента вступления в законную силу акта суда первой инстанции прошло 168 часов, то таковой акт не может быть обжалован в кассационном порядке. ч. 2. Решение (определение, постановление, приговор) суда апелляционной инстанции может быть обжаловано в кассационном порядке лицами, имеющими право на подачу апелляционной жалобы, в течение 168 часов с момента оглашения решения судом апелляционной инстанции. ч. 3. Кассационная жалоба (представление) обязана содержать в себе мотивированные и обоснованные действующим законодательством аргументы. Кассационная жалоба (представление) не считается мотивированной, если ее подает лицо, которое было должным образом уведомлено о судебном заседании в суде первой инстанции, но не явилось на таковое, а затем ссылается на то, что суд не учел его аргументы или аргументы его стороны. Кассационная жалоба (представление) не считается мотивированной, если ее подает представитель лица, привлеченный после заседания, при этом само лицо не явилось на судебное заседание суда первой инстанции и впоследствии утверждает, что суд не учел его аргументы или аргументы его стороны. ч. 4. На подачу кассационной жалобы имеют право лица, указанные в части первой статьи 119 настоящего Кодекса.","r":"УПК ст. 134"},{"d":"УПК РО","t":"Статья 135. Требования к кассационной жалобе, представлению","x":"ч. 1. Кассационная жалоба подается в письменном виде и по установленной форме. Заявитель обязан в полном объеме обоснованно и аргументировано указать, в чем заключается незаконность или необоснованность судебного решения. ч. 2. Если в кассационной жалобе (представлении) указываются обстоятельства, которые не были изучены во время апелляции, либо доказательства, которые не подавались суду в предыдущих инстанциях, то в ней указываются таковые причины. ч. 3. Кассационная жалоба подписывается лицом, которое ее подает. Если кассационную жалобу подает защитник, адвокат или законный представитель любой из сторон, то к ней добавляется договор об оказании юридических услуг либо иной документ, необходимый для подтверждения законности и полномочий представителя.","r":"УПК ст. 135"},{"d":"УПК РО","t":"Статья 136. Принятие, оставление кассационной жалобы без движения, отказ в принятии к производству или продолжении производства","x":"ч. 1. Суд кассационной инстанции начинает кассационное производство в течение 48 часов со дня поступления кассационной жалобы, если нет оснований для оставления кассационной жалобы без движения, отказа в принятии таковой жалобы к производству или продолжении производства. Вопрос о начале кассационного производства суд кассационной инстанции решает без вызова сторон. ч. 2. Судья, установив, что кассационная жалоба на приговор или иной акт суда апелляционной инстанции подана без соответствия требованиям, предусмотренным настоящим Кодексом, принимает решение об отказе в принятии таковой жалобы (представления) к производству. ч. 3. Кассационная жалоба не принимается к производству: а) в случаях, предусмотренных частью 2 настоящей статьи; б) кассационную жалобу подало лицо, которое не имеет права подавать таковую; в) кассационная жалоба подана на судебный акт, который не подлежит обжалованию в кассационном порядке; г) из кассационной жалобы, поданных к ней судебных решений и иных документов предвидится, что оснований для удовлетворения жалобы нет; д) кассационная жалоба подана после окончания срока кассационного обжалования. ч. 4. Судья отказывает в принятии жалобы (представления) к производству, если кассационная жалоба подана на судебное решение, которое не подлежит обжалованию в кассационном порядке, или судебное решение оспорено исключительно на основаниях, по которым оно не может быть обжаловано в соответствии с положениями настоящего Закона. ч. 5. Оставление кассационной жалобы без движения или отказ в принятии к производству не лишают права повторного обращения в суд…","r":"УПК ст. 136"},{"d":"УПК РО","t":"Статья 138. Последствия подачи кассационной жалобы","x":"ч. 1. Подача кассационной жалобы на приговор или иной судебный акт не останавливает вступление такового в законную силу и исполнение такового, за исключением случаев, предусмотренных частью 2 настоящей статьи. ч. 2. В случае, если заявлено ходатайство о приостановлении действия силы решения или иного судебного акта предыдущей инстанции, то суд при наличии весомых оснований приостанавливает действие такового.","r":"УПК ст. 138"},{"d":"УПК РО","t":"Статья 139. Подготовление к кассационному рассмотрению","x":"ч. 1. Судья в течение 48 часов после принятия кассационной жалобы к производству: а) устанавливает дату судебного заседания; б) рассматривает возражения, поданные сторонами против кассационного заявления; в) рассматривает иные ходатайства, в том числе ходатайства о проведении заочного судебного заседания; г) рассматривает иные вопросы, обстоятельства, необходимые для кассационного рассмотрения. ч. 2. Обвиняемый подлежит обязательному вызову в судебное заседание для участия в кассационном рассмотрении, если в кассационной жалобе затрагивается вопрос про ухудшение его положения или если суд признает обязательным участие такового.","r":"УПК ст. 139"},{"d":"УПК РО","t":"Статья 140. Границы пересмотра судом кассационной инстанции","x":"ч. 1. Суд кассационной инстанции проверяет правильность применения судами первой и апелляционной инстанции норм материального и процессуального права, правовой оценки обстоятельств и не имеет права исследовать доказательства, устанавливать и признавать доказанными обстоятельства, которые не были установлены в обжалуемом судебном решении, рассматривать вопрос про достоверность того или иного доказательства. ч. 2. Суд кассационной инстанции пересматривает судебные акты судов первой и апелляционной инстанций в рамках кассационной жалобы. Суд кассационной инстанции вправе выйти за границы кассационных требований, если таковым не ухудшается положение обвиняемого. Если рассмотрение кассационной жалобы дает основания для принятия решения в пользу лиц, в интересах которых жалобы не поступили, суд кассационной инстанции обязан принять таковое решение.","r":"УПК ст. 140"},{"d":"УПК РО","t":"Статья 141. Кассационное рассмотрение","x":"ч. 1. Кассационное рассмотрение проводится в соответствии с правилами и процессами судебного рассмотрения в суде апелляционной инстанции с учетом особенностей, предусмотренных настоящей главой и законом. ч. 2. Председательствующий судья в необходимом таковому объеме докладывает содержание обжалуемого судебного решения, аргументы участников судебного решения, изложенные в кассационных жалобах и возражениях, а также выясняет, поддерживают ли свои кассационные жалобы и возражения лица, которые их подали. ч. 3. Для изложения аргументов первенство в выступлении предоставляется лицу, которое подало кассационную жалобу. Если кассационные жалобы подали обе стороны предыдущего разбирательства, первым излагает свои аргументы обвиняемый либо представитель такового. После этого слово предоставляется другим участникам судебного производства. ч. 4. После окончания кассационного рассмотрения суд удаляется в совещательную комнату для вынесения судебного решения. ч. 5. Суд кассационной инстанции не связан доводами кассационных жалобы или представления и вправе проверить производство по уголовному делу в полном объеме.","r":"УПК ст. 141"},{"d":"УПК РО","t":"Статья 142. Полномочия суда кассационной инстанции впоследствии рассмотрения кассационной жалобы","x":"ч. 1. Суд кассационной инстанции впоследствии рассмотрения кассационной жалобы вправе: а) оставить кассационные жалобу или представление без удовлетворения; б) отменить приговор, определение или постановление суда и все последующие судебные решения и передать уголовное дело на новое судебное рассмотрение либо возвратить дело прокурору; в) отменить приговор суда апелляционной инстанции и передать уголовное дело на новое апелляционное рассмотрение; г) отменить решение суда кассационной инстанции и передать уголовное дело на новое кассационное рассмотрение; д) отменить решение суда кассационной инстанции и оставить без изменения либо изменить приговор, определение или постановление суда и (или) последующие судебные решения; е) оставить кассационные жалобу без рассмотрения по существу при наличии оснований, предусмотренных Законом, или прекратить производство по кассационным жалобе, если после принятия кассационных жалобы к производству суда от лица, их подавшего, поступило заявление об отказе от кассационных жалобы и отказ принят судом. ч. 2. Кассационная инстанция не вправе устанавливать или считать доказанными обстоятельства, которые не были установлены либо были отвергнуты судом первой или апелляционной инстанции, предрешать вопросы о достоверности или недостоверности того или иного доказательства, преимуществе одних доказательств перед другими и определять, какое судебное постановление должно быть принято при новом рассмотрении дела. Дополнительные доказательства судом кассационной инстанции не принимаются. ч. 3. Указания вышестоящего суда о толковании закона являются…","r":"УПК ст. 142"},{"d":"УПК РО","t":"Статья 143. Основания для отмены или изменения судебного решения судом кассационной инстанции","x":"ч. 1. Основанием для отмены или изменения судебного акта при рассмотрении дела в суде кассационной инстанции являются: а) неполнота судебного рассмотрения; б) несоответствие выводов суда, изложенных в судебном решении, фактическим обстоятельствам дела; в) существенное нарушение требований действующего законодательства судом; г) нарушение или неправильное применение закона. ч. 2. Дополнительные обстоятельства, позволяющие отменить судебное решение: а) судебное решение вынесено незаконным составом суда; б) нарушены правила подсудности; в) не выполнено требований о ведении фиксации судебного заседания, только в случае надобности и по решению апелляционной инстанции.","r":"УПК ст. 143"},{"d":"УПК РО","t":"Статья 144. Основные понятия, используемые в настоящем Кодексе","x":"Если не оговорено иное, основные понятия, используемые в настоящем Кодексе, имеют следующие значения: 1) алиби - нахождение подозреваемого или обвиняемого в момент совершения преступления в другом месте; 2) апелляционная инстанция - суд, рассматривающий в апелляционном порядке уголовные дела по жалобам и представлениям на приговоры, определения и постановления суда; 3) близкие лица - иные, за исключением близких родственников и родственников, лица, состоящие в свойстве с потерпевшим, свидетелем, а также лица, жизнь, здоровье и благополучие которых дороги потерпевшему, свидетелю в силу сложившихся личных отношений; 4) близкие родственники - супруг, супруга, родители, дети, усыновители, усыновленные, родные братья и родные сестры, дедушка, бабушка, внуки; 5) вердикт - решение о виновности или невиновности подсудимого, вынесенное коллегией присяжных заседателей; 6) государственный обвинитель - поддерживающее от имени государства обвинение в суде по уголовному делу должностное лицо органа прокуратуры; 7) дознаватель - должностное лицо органа дознания, правомочное либо уполномоченное осуществлять предварительное расследование в форме дознания, а также иные полномочия, предусмотренные настоящим Кодексом; 8) дознание - форма предварительного расследования, осуществляемого дознавателем, по уголовному делу, по которому производство предварительного следствия необязательно; 9) досудебное производство - уголовное судопроизводство с момента получения сообщения о преступлении до направления прокурором уголовного дела в суд для рассмотрения его по существу; 10) жилище - индивидуальный…","r":"УПК ст. 144"},{"d":"ФЗ «Об обороне»","t":"Статья 1. Основы обороны","x":"1.1. В настоящем Федеральном законе под обороной понимается система политических, экономических, военных, социальных, правовых и иных мер по подготовке к вооруженной защите и вооруженная защита РО, целостности и неприкосновенности ее территории. 1.2. Оборона организуется и осуществляется в соответствии с Конституцией РО, федеральными конституционными законами, федеральными законами, настоящим Федеральным законом, законами РО и иными нормативными правовыми актами. 1.3. В целях обороны создаются Вооруженные Силы РО, также именуемые Армией. 1.4. Создание и существование формирований, имеющих военную организацию или вооружение и военную технику либо в которых предусматривается прохождение военной службы, не предусмотренных федеральными законами, запрещаются и преследуются по закону.","r":"ФЗ-2 ст. 1"},{"d":"ФЗ «Об обороне»","t":"Статья 2. Законодательство РО в области обороны","x":"Законодательство РО в области обороны основывается на Конституции РО и включает в себя федеральные конституционные законы, федеральные законы, настоящий Федеральный закон.","r":"ФЗ-2 ст. 2"},{"d":"ФЗ «Об обороне»","t":"Статья 3. Руководство и управление Вооруженными Силами РО","x":"3.1. Общее руководство Вооруженными Силами РО осуществляет Премьер-Министр РО. 3.2. Руководство Вооруженными Силами РО осуществляет Министр обороны и его заместители. 3.3. Управление территориальными органами Вооруженных Сил РО (войсковыми частями) осуществляют командиры бригад. Командиры бригад подчинены Премьер-Министру РО, Министру обороны и его заместителям. 3.4. Правительство РО утверждает Уставы органов Вооруженных Сил РО (войсковых частей).","r":"ФЗ-2 ст. 3","k":"кто руководит армией ; кому подчиняется армия по закону ; министр обороны руководит ; командир бригады кому подчинён ; премьер руководит вооружёнными силами"},{"d":"ФЗ «Об обороне»","t":"Статья 4. Вооруженные Силы РО и их предназначение","x":"Вооруженные Силы РО являются составной частью военной организации государства и предназначены для вооруженной защиты национальных интересов, суверенитета, целостности и неприкосновенности территории РО военными методами, а также для выполнения задач в соответствии с актами Премьер-Министра РО.","r":"ФЗ-2 ст. 4","k":"для чего вооружённые силы ; предназначение армии ; зачем армия"},{"d":"ФЗ «Об обороне»","t":"Статья 5. Правовая основа деятельности Вооруженных Сил РО","x":"Правовую основу деятельности Вооруженных Сил РО составляют Конституция РО, настоящий Федеральный закон, другие федеральные законы, нормативные правовые акты Премьер-Министра РО, а также нормативные правовые акты федерального органа исполнительной власти в сфере обороны и иные нормативные правовые акты РО, регулирующие деятельность Вооруженных Сил РО.","r":"ФЗ-2 ст. 5"},{"d":"ФЗ «Об обороне»","t":"Статья 6. Основные задачи Вооруженных Сил РО","x":"6.1. Основными задачами Вооруженных Сил РО являются: 1) предотвращение и отражение агрессии против РО и ее союзников; 2) участие в защите государственной границы РО и ее охрана в воздушном пространстве и подводной среде; 3) обеспечение национальных интересов РО; 4) организация и ведение территориальной обороны, участие в обеспечении режимов военного и чрезвычайного положений; 5) организация на подведомственной территории Вооруженных Сил РО патрульно-постовой службы и блокпостов на дорогах, идущих из городской части в областную, с целью обеспечения безопасности гражданского населения и военнослужащих в области. 6.2. Иные задачи Вооруженных Сил РО устанавливаются нормативными актами Премьер-Министра РО.","r":"ФЗ-2 ст. 6","k":"задачи вооружённых сил ; что делает армия по закону ; основные задачи армии ; территориальная оборона"},{"d":"ФЗ «Об обороне»","t":"Статья 7. Привлечение Вооруженных Сил РО к выполнению задач с использованием вооружения не по их предназначению","x":"7.1. Вооруженные Силы РО могут привлекаться к выполнению задач с использованием вооружения не по их предназначению на основании решения Премьер-Министра РО. 7.2. Вооруженные Силы РО для выполнения поставленных задач могут применять имеющиеся в их распоряжении силы и средства, при этом физическая сила, специальные средства, оружие, боевая и специальная техника применяются в случаях и порядке, установленном федеральными законами и иными нормативными правовыми актами РО.","r":"ФЗ-2 ст. 7","k":"армия применяет оружие не по назначению ; привлечение армии к задачам ; армия может применять силу когда"},{"d":"ФЗ «Об обороне»","t":"Статья 8. Имущество Вооруженных Сил РО","x":"8.1. Имущество Вооруженных Сил РО является федеральной собственностью и может находиться в Вооруженных Силах РО в оперативном управлении или на правах хозяйственного ведения и вооруженной охране.","r":"ФЗ-2 ст. 8"},{"d":"ФЗ «Об обороне»","t":"Статья 9. Соблюдение и уважение прав и свобод человека","x":"9.1. При обращении к лицу, при обращении лица к военнослужащему Вооруженных Сил РО военнослужащий Вооруженных Сил РО обязан назвать свои должность, звание, фамилию, предъявить по просьбе гражданина служебное удостоверение. 9.2. Сотрудники, находящиеся при исполнении обязанностей, предусматривающих засекречивание своей личности, обязаны предоставить жетон и назвать позывной и номер жетона обратившемуся. Образцы жетонов устанавливаются Правительством РО.","r":"ФЗ-2 ст. 9","k":"обязан ли военный представиться ; назвать звание и фамилию гражданину ; показать удостоверение гражданину ; гражданин просит удостоверение ; представиться при обращении к гражданину ; обязан ли показывать удостоверение"},{"d":"ФЗ «Об обороне»","t":"Статья 10. Основы деятельности Вооруженных Сил РО","x":"10.1. Деятельность Вооруженных Сил РО включает: комплектование личным составом, размещение (дислокацию) войск (сил), поддержание боевой и мобилизационной готовности, боевое дежурство, боевую службу и службу оперативных дежурных, оперативную, боевую и мобилизационную подготовку войск (сил), разведывательную деятельность, службу войск, подготовку кадров и выполнение возложенных задач, а также всестороннее обеспечение войск (сил). 10.2. Комплектование Вооруженных Сил РО осуществляется в соответствии с законодательством РО военнослужащими путем добровольного поступления граждан на военную службу по контракту.","r":"ФЗ-2 ст. 10","k":"чем занимается армия ; деятельность вооружённых сил ; боевое дежурство караульная служба закон"},{"d":"ФЗ «Об обороне»","t":"Статья 11. Обязанности Вооруженных Сил РО","x":"11.1. На Вооруженные Силы РО возлагаются следующие обязанности: 1) обеспечивать безопасность на охраняемых в соответствии с законодательством РО объектах; 2) обеспечивать правоохранительные структуры РО вооружением и боеприпасами; 3) поддерживать боеготовность и обороноспособность РО; 4) обеспечивать безопасность и сохранение режимности войсковых частей; 5) принимать меры по организации деятельности органов военной полиции, предупреждения правонарушений среди военнослужащих; 6) участвовать в обеспечении режима военного положения и режима чрезвычайного положения в случае их введения на территории РО или в отдельных ее местностях. 11.2. Иные обязанности возлагаются на Вооруженные Силы РО в соответствии с законодательством РО, нормативными правовыми актами Премьер-Министра РО. 11.3. Порядок выполнения возложенных на Вооруженные Силы РО обязанностей, если он не является предметом регулирования федеральных законов, нормативных правовых актов Премьер-Министра РО или нормативных правовых актов Правительства РО, определяется Министерством обороны.","r":"ФЗ-2 ст. 11","k":"обязанности армии по закону ; что обязана армия ; охрана объектов обязанность армии ; армия обеспечивает вооружением"},{"d":"ФЗ «Об обороне»","t":"Статья 12. Права Вооруженных Сил РО","x":"12.1. Вооруженным Силам РО для выполнения возложенных на них обязанностей предоставляются следующие права: 1) требовать от граждан соблюдения общественного порядка на подведомственной территории; при нарушении общественного порядка задержать и передать сотрудникам правоохранительных органов; 2) пресекать преступления на подведомственной территории воинской части Вооруженных Сил, в рамках определяемых законом РО; 3) принимать необходимые меры по охране места совершения предполагаемого преступления до прибытия правоохранительных органов; 4) доставлять граждан в служебное помещение правоохранительных органов в целях передачи задержанного сотрудникам правоохранительных органов; 5) производить обыск транспортных средств, нарушивших правила, установленные на охраняемых Вооруженными Силами объектах; 6) производить личный обыск граждан в пунктах пропуска на охраняемых важных государственных объектах в соответствии с законодательством о закрытых территориях; 7) беспрепятственно входить в любое время суток на территории и в помещения охраняемых Вооруженными Силами объектов, осматривать их в целях задержания лиц, незаконно проникших либо пытавшихся проникнуть на охраняемые объекты, с последующей передачей правоохранительным органам; 8) вести разведку в районах выполнения служебно-боевых задач, проводить оперативные мероприятия, направленные на предотвращение преступлений в отношении имущества и служащих Вооруженных Сил РО, в рамках определенных законами РО; 9) организовывать блокпосты в случае объявления военного и (или) чрезвычайного положения, согласно актам Премьер-Министра РО;…","r":"ФЗ-2 ст. 12","k":"права армии по закону ; что имеет право армия ; задержать и передать правоохранителям ; требовать соблюдения порядка на территории ; пресекать преступления на подведомственной территории ; права военнослужащих в отношении граждан по закону ; имею ли право задержать по закону ; имеет ли армия право на обыск ; обыск транспорта нарушителя на объекте ; личный обыск в пункте пропуска ; право военных на личный обыск граждан"},{"d":"ФЗ «Об обороне»","t":"Статья 13. Поддержание боевой и мобилизационной готовности Вооруженных Сил РО","x":"13.1. Министерство обороны РО осуществляет планирование боевой и мобилизационной готовности Вооруженных Сил РО. Контроль за ее состоянием обеспечивают министр обороны, командиры войсковых частей и соединений. 13.2. Приведение Вооруженных Сил РО в высшие степени боевой готовности осуществляется на основании актов Председателя Правительства РО, Министерства обороны РО. 13.3. В целях своевременного наращивания боевой готовности и подготовки Вооруженных Сил РО к отражению агрессии проводится комплекс необходимых мероприятий, направленных на повышение боевой готовности Вооруженных Сил РО и мобилизационной готовности страны. Такие мероприятия регулируются нормативными правовыми актами Министерства обороны. 13.4. Для поддержания боевой выучки органов военного управления, войск (сил) проводится оперативная, боевая подготовка. Порядок таких подготовок устанавливается командиром войсковой части. 13.5. Порядок прохождения курса военной подготовки для выдачи документа о прохождении военной службы (также — военного билета) устанавливается командиром войсковой части с утверждением Министра обороны РО.","r":"ФЗ-2 ст. 13"},{"d":"ФЗ «Об обороне»","t":"Статья 14. Ускоренная военная подготовка","x":"Гражданин РО, находящийся на службе в правоохранительных (силовых) структурах и годный к военной службе по состоянию здоровья и отвечающий установленным настоящим Федеральным законом требованиям к гражданам, поступающим на военную службу по контракту, вправе заключить с Министерством обороны РО договор об ускоренной военной подготовке на срок, установленный внутренним уставом Вооруженных Сил РО.","r":"ФЗ-2 ст. 14"},{"d":"ФЗ «Об обороне»","t":"Статья 15. Права и обязанности гражданина, проходящего ускоренную военную подготовку","x":"15.1. На гражданина, проходящего ускоренную военную подготовку, распространяются такие же права и обязанности, как и на любого военнослужащего, проходящего добровольную военную службу по контракту, а также права и обязанности, предусмотренные пунктами \"2\", \"3\", \"4\" и \"5\" настоящей статьи. 15.2. Гражданин, прошедший ускоренную военную подготовку, имеет право на получение военного билета с присвоенным воинским званием Сержант. 15.3. Действие трудового договора, заключенного между гражданином, проходящим ускоренную военную подготовку, и работодателем, приостанавливается на период ускоренной военной подготовки. 15.4. За гражданином, проходящим ускоренную военную подготовку, сохраняется место работы (службы), должность, а также специальное звание. 15.5. Гражданин, заключивший договор об ускоренной военной подготовке, обязан предупредить работодателя за три календарных дня о приостановлении трудового договора на период прохождения ускоренной военной подготовки.","r":"ФЗ-2 ст. 15"},{"d":"ФЗ «Об обороне»","t":"Статья 16. Служба войск","x":"16.1. Служба войск регламентирует повседневную деятельность Вооруженных Сил РО по поддержанию внутреннего порядка, безопасности военной службы, условий жизни и быта военнослужащих, а также выполнение ими должностных обязанностей. 16.2. Служба войск включает внутреннюю, гарнизонную и караульную службы и организуется на основе общевоинских уставов Вооруженных Сил РО и других нормативных правовых актов Министерства обороны РО. 16.3. Районы (позиции) несения боевого дежурства, районы сосредоточения войск, постоянного места дислокации войск включают внутреннюю, гарнизонную и караульную службы.","r":"ФЗ-2 ст. 16","k":"служба войск что это ; внутренняя гарнизонная караульная служба закон ; караульная служба по закону"},{"d":"ФЗ «Об обороне»","t":"Статья 17. Применение оружия, специальных средств и физической силы","x":"1. Военнослужащий (сотрудник) вооруженных сил имеет право лично или в составе подразделения (группы) применять физическую силу, в том числе боевые приемы борьбы, если несиловые способы не обеспечивают выполнения возложенных на войска вооруженных сил задач, в следующих случаях: 1) для пресечения преступлений и административных правонарушений; 2) для задержания и доставления в полицию лиц, подозреваемых в совершении преступления, а также лиц, в отношении которых имеется повод к возбуждению дела об административном правонарушении; 3) для преодоления противодействия законным требованиям военнослужащего (сотрудника) войск вооруженных сил. 1.2. Военнослужащий (сотрудник) войск вооруженных сил имеет право применять физическую силу во всех случаях, когда настоящим Федеральным законом разрешено применение специальных средств, вооружения, военной и специальной техники. 2.1. Военнослужащий (сотрудник) войск вооруженных сил имеет право лично или в составе подразделения (группы) применять специальные средства в следующих случаях: 1) для отражения нападения на гражданина или военнослужащего (сотрудника) войск вооруженных сил; 2) для пресечения преступления или административного правонарушения; 3) для пресечения сопротивления, оказываемого военнослужащему (сотруднику) войск вооруженных сил; 4) для задержания лица, застигнутого при совершении преступления и пытающегося скрыться; 5) для задержания лица, если это лицо может оказать вооруженное сопротивление или воспрепятствовать исполнению военнослужащим (сотрудником) войск вооруженных сил возложенных на него обязанностей; 6) для…","r":"ФЗ-2 ст. 17","k":"применение оружия по закону ; когда военный может применить силу по закону ; применение спецсредств военнослужащим ; боевые приёмы борьбы ; физическая сила военнослужащий закон ; когда можно стрелять по закону об обороне ; право на применение оружия"},{"d":"ФЗ «Об обороне»","t":"Статья 18. Порядок пользования Вооруженными Силами РО воздушным пространством РО","x":"Пользование воздушным пространством РО Вооруженными Силами РО осуществляется в соответствии с законодательством о воздушном пространстве, а также иными нормативными правовыми актами РО.","r":"ФЗ-2 ст. 18"},{"d":"ФЗ «Об обороне»","t":"Статья 19. Обеспечение вооружением, военной техникой и другими материальными средствами","x":"19.1. Обеспечение Вооруженных Сил РО вооружением, военной техникой и другими материальными средствами организует командир войсковой части. 19.2. Вооружением, военной техникой и другими материальными средствами Вооруженные Силы РО обеспечиваются в объемах, полностью удовлетворяющих их потребности. 19.3. Вооруженные Силы РО обеспечивают силовые государственные организации вооружением, боеприпасами, организуют и проводят поставки. 19.4. В обязанности Вооруженных Сил РО входит постоянное материальное обеспечение государственных структур.","r":"ФЗ-2 ст. 19"},{"d":"ФЗ «Об обороне»","t":"Статья 20. Ответственность за препятствование Вооруженным Силам РО в выполнении задач в области обороны","x":"20.1. Препятствование Вооруженным Силам РО в выполнении задач в области обороны и военной безопасности, в том числе путем блокирования военных городков, районов (позиций) несения боевого дежурства, районов сосредоточения войск, постоянного места дислокации войск, объектов военной инфраструктуры, не допускается. 20.2. Лица, виновные в препятствовании Вооруженным Силам РО в выполнении задач в области обороны, несут ответственность в соответствии с законодательством РО.","r":"ФЗ-2 ст. 20","k":"препятствуют армии ; блокируют военный городок ; мешают армии выполнять задачи ; ответственность за препятствование армии"},{"d":"ФЗ «Об обороне»","t":"Статья 21. Физическая форма военнослужащих","x":"Военнослужащие Вооруженных Сил РО обязаны следить за своим состоянием здоровья и регулярно (не менее раза в месяц) проходить комплексный медицинский осмотр у сотрудников государственных медицинских организаций. Осмотр может быть проведен индивидуально либо как часть общей проверки, назначенной Министром социальной политики.","r":"ФЗ-2 ст. 21","k":"медосмотр раз в месяц по закону ; физическая форма военнослужащих ; обязательный медосмотр военных"},{"d":"ФЗ «Об обороне»","t":"Статья 22. Судебный, прокурорский надзор","x":"22.1. Судебный надзор за деятельностью Вооруженных Сил РО осуществляется в соответствии с федеральными законами. 22.2. Надзор за исполнением Вооруженными Силами РО законов осуществляют органы прокуратуры с полномочиями, предоставленными федеральным законодательством. 22.3. Действия (бездействие) сотрудника Вооруженных Сил РО, нарушающие права и законные интересы гражданина, государственного органа, общественного объединения, религиозной и иной организации, могут быть обжалованы в вышестоящий орган или вышестоящему должностному лицу, в органы прокуратуры РО либо в суд.","r":"ФЗ-2 ст. 22","k":"кто надзирает за армией ; прокуратура и армия ; обжаловать действия военнослужащего ; надзор за вооружёнными силами"},{"d":"ФЗ «Об обороне»","t":"Статья 23. Государственный контроль","x":"23.1. Государственный контроль за деятельностью Вооруженных Сил РО осуществляют Премьер-Министр РО и его заместитель, Правительство РО в пределах полномочий, Министр обороны в пределах полномочий, определяемых Конституцией РО, федеральными конституционными законами и федеральными законами. 23.2. Ведомственный контроль за деятельностью Вооруженных Сил РО осуществляется в порядке, определяемом Министерством обороны РО. Одобрен Государственной Думой 21 августа 2026 года Подписан Премьер Министром РО 21 августа 2026 года [https://docs.google.com/document/d/1QHgZAGSaYE8wCeD3eZUd_-D3LGJTw6azcp_RjCNI71w/edit?tab=t.0](https://docs.google.com/document/d/1QHgZAGSaYE8wCeD3eZUd_-D3LGJTw6azcp_RjCNI71w/edit?tab=t.0)","r":"ФЗ-2 ст. 23","k":"кто контролирует армию ; государственный контроль над армией"},{"d":"ФЗ «Об оружии»","t":"Статья 1.1. Основная цель настоящего Закона","x":"Основная цель настоящего Закона - регламентация правил хранения, ношения и использования оружия гражданами, закон направлен на защиту жизни и здоровья граждан, собственности, обеспечение общественной безопасности в РО.","r":"ФЗ-8 ст. 1.1"},{"d":"ФЗ «Об оружии»","t":"Статья 1.2. Основные понятия, применяемые в настоящем законе","x":"а) Государственные силовые структуры - специально организуемые и содержимые государством службы, создаваемые в интересах защиты (охраны) конституционного строя и безопасности государства. В РО к таковым относятся органы внутренней безопасности, федеральной службы, охраны, а также Армии. б) Оружие - устройства и предметы, конструктивно предназначенные для поражения живой или иной цели, подачи сигналов; в) Огнестрельное оружие - оружие, предназначенное для механического поражения цели на расстоянии метаемым снаряжением, получающим направленное движение за счет энергии порохового или иного заряда; г) Холодное оружие - оружие, предназначенное для поражения цели при помощи мускульной силы человека при непосредственном контакте с объектом поражения; д) Боеприпасы - предметы вооружения и метаемое снаряжение, предназначенные для поражения цели и содержащие разрывной, метательный, пиротехнический или вышибной заряды либо их сочетание; е) Бронежилет - индивидуальное защитное средство, предназначенное для обеспечения безопасности человека при воздействии на него холодного и огнестрельного оружия; ж) Наручники - это устройство в виде двух закрывающихся на ключ металлических браслетов, соединенных между собой небольшой цепочкой. Они используются силовыми государственными структурами либо выполняющими аналогичные функции негосударственными организациями для ограничения свободы действий человека посредством сковывания его рук. Наручники надеваются на кисти рук и в той или иной степени лишают закованного свободы движений; з) Специальные средства - это комплекс различных устройств,…","r":"ФЗ-8 ст. 1.2","k":"что такое служебное оружие ; какие структуры силовые ; определение оружия по закону ; что считается оружием"},{"d":"ФЗ «Об оружии»","t":"Статья 2.1. По доступности оружия к обороту, оно подразделяется на","x":"а) Служебное оружие - оружие, предназначенное для использования сотрудниками государственных структур и имеющее перед серийным номером префикс соответствующей организации; б) Гражданское оружие - оружие, предназначенное для использования гражданами в целях самообороны, для занятий спортом и охоты, а также в культурных и образовательных целях и имеющее перед серийным номером префикс A, иной другой или номера вовсе отсутствуют; в) Охотничье оружие - оружие, предназначенное для использования гражданами в целях охоты, самообороны, а также в образовательных целях, купленное в специализированных охотничьих магазинах.","r":"ФЗ-8 ст. 2.1","k":"виды оружия ; чем служебное оружие отличается от гражданского ; гражданское оружие это ; префикс на оружии"},{"d":"ФЗ «Об оружии»","t":"Статья 2.2. К специальным средствам относятся","x":"а) Служебные бронежилеты, тяжелые и сверхтяжелые бронежилеты; б) Электрошокер; в) Резиновая дубинка; г) Наручники; д) Гранаты любого типа; е) Электрическая дубинка; ж) Дрон государственного образца; з) Медицинские препараты и инструменты (Дефибриллятор, эпинефрин, стимуляторы).","r":"ФЗ-8 ст. 2.2","k":"что относится к спецсредствам ; бронежилет это спецсредство ; наручники спецсредство ; дубинка электрошокер закон ; гранаты спецсредства ; список спецсредств"},{"d":"ФЗ «Об оружии»","t":"Статья 3.1","x":"Гражданское огнестрельное оружие разрешено к приобретению, хранению, ношению и использованию в соответствии с главой VIII настоящего Закона всеми гражданами, имеющими лицензию на право хранения, ношения и использования гражданского оружия, выданную в соответствии с главой IX настоящего Закона уполномоченным сотрудником МВД, и действующую медицинскую справку с пометкой о физическом и психическом здоровье.","r":"ФЗ-8 ст. 3.1","k":"гражданскому можно оружие ; нужна ли лицензия на оружие гражданскому ; у гражданского пистолет законно ли"},{"d":"ФЗ «Об оружии»","t":"Статья 3.2","x":"Охотничье оружие разрешено к приобретению, хранению, ношению и использованию в соответствии с главой VIII настоящего Закона всеми гражданами, имеющими лицензию на право хранения, ношения и использования гражданского оружия, выданную в соответствии с главой IX настоящего Закона, действующую медицинскую справку с пометкой о физическом и психическом здоровье, и лицензию на охоту.","r":"ФЗ-8 ст. 3.2"},{"d":"ФЗ «Об оружии»","t":"Статья 3.3","x":"Гражданское холодное оружие разрешено к приобретению, хранению, ношению и использованию в соответствии с главой VIII настоящего Закона всеми гражданами, имеющими действующую медицинскую справку с пометкой о физическом и психическом здоровье.","r":"ФЗ-8 ст. 3.3"},{"d":"ФЗ «Об оружии»","t":"Статья 3.4","x":"Запрещено к приобретению, хранению, ношению и применению всеми гражданами оружие, имеющее полностью или частично нечитаемый серийный номер, за исключением охотничьего оружия. Исключение: Сотрудники силовых государственных организаций при исполнении могут использовать оружие с полностью или частично нечитаемым серийным номером.","r":"ФЗ-8 ст. 3.4","k":"оружие со стёртым номером ; нечитаемый серийный номер ; нашёл оружие без номера ; спиленный номер на оружии"},{"d":"ФЗ «Об оружии»","t":"Статья 3.5","x":"Гражданское огнестрельное и охотничье оружие разрешено к приобретению исключительно в специализированных оружейных магазинах и (или) охотничьих магазинах.","r":"ФЗ-8 ст. 3.5"},{"d":"ФЗ «Об оружии»","t":"Статья 4.1","x":"Служебное оружие разрешено к хранению, ношению и использованию только сотрудникам государственных силовых структур. Исключение: Использование и открытое ношение служебного оружия сотрудниками силовых государственных структур не при исполнении запрещено.","r":"ФЗ-8 ст. 4.1","k":"кому можно служебное оружие ; гражданский с служебным оружием ; оружие с префиксом у гражданского ; служебное оружие не при исполнении ; ношение служебного оружия вне службы"},{"d":"ФЗ «Об оружии»","t":"Статья 4.2","x":"Сотрудникам государственных структур для хранения, ношения и использования служебного оружия требуется наличие лицензии на гражданское оружие, выданной в соответствии с главой IX настоящего Закона. Исключение: военнослужащие Армии.","r":"ФЗ-8 ст. 4.2","k":"нужна ли военным лицензия на оружие ; лицензия военнослужащим ; надо ли мне лицензия на автомат"},{"d":"ФЗ «Об оружии»","t":"Статья 4.3","x":"Запрещена покупка, продажа, передача лицам, не состоящим в государственных силовых структурах, служебного оружия. Исключение: осуществление процедуры обмена оружием/боеприпасами согласно указам и постановлениям Премьер-Министра, его заместителя и (или) Министра обороны, его заместителей.","r":"ФЗ-8 ст. 4.3","k":"продать служебное оружие ; передать оружие гражданскому ; отдать автомат другу закон ; обмен оружием между структурами"},{"d":"ФЗ «Об оружии»","t":"Статья 5.1","x":"Спецсредства разрешены к хранению, ношению и использованию только сотрудникам государственных силовых структур, а также сотрудникам Вести Москва, Больницы. Примечание 1: Сотрудники правительства, обладающие статусом неприкосновенности, вправе носить служебные бронежилеты. Примечание 2: Сотрудникам государственных силовых структур разрешено использовать только служебные бронежилеты. Исключение: Использование и открытое ношение спецсредств сотрудниками государственных структур не при исполнении запрещено, за исключением дефибрилляторов.","r":"ФЗ-8 ст. 5.1","k":"кому можно спецсредства ; гражданский с бронежилетом ; у гражданского наручники ; неприкосновенные бронежилет ; спецсредства гражданским"},{"d":"ФЗ «Об оружии»","t":"Статья 5.2","x":"Сотрудникам государственных структур для хранения, ношения и использования спецсредств не требуется наличие специальных лицензий.","r":"ФЗ-8 ст. 5.2"},{"d":"ФЗ «Об оружии»","t":"Статья 5.3","x":"Запрещена покупка, продажа, передача лицам, не состоящим в государственных структурах, спецсредств. Исключение: осуществление процедуры обмена спецсредствами согласно указам и постановлениям Премьер-Министра или его заместителя, и (или) Министра обороны, его заместителей.","r":"ФЗ-8 ст. 5.3"},{"d":"ФЗ «Об оружии»","t":"Статья 5.4","x":"Дефибриллятор MK2 разрешен для хранения, перевозки и использования всем гражданам.","r":"ФЗ-8 ст. 5.4"},{"d":"ФЗ «Об оружии»","t":"Статья 5.5","x":"Шприц с эпинефрином (обычным, списанным или улучшенным) легален для ношения, использования всем гражданам.","r":"ФЗ-8 ст. 5.5"},{"d":"ФЗ «Об оружии»","t":"Статья 5.6","x":"Имеющиеся в РО специальные средства либо объекты, обладающие свойствами, схожими с ними, являются легальными для использования или хранения всеми гражданами РО до момента, пока иное не установлено настоящим законом.","r":"ФЗ-8 ст. 5.6"},{"d":"ФЗ «Об оружии»","t":"Статья 5.7","x":"Лёгкие бронежилеты как средства индивидуальной защиты разрешены к приобретению, хранению и ношению всем гражданам, имеющим лицензию на право хранения, ношения и использования гражданского оружия, выданную в соответствии с главой IX настоящего Закона уполномоченным сотрудником МВД, и действующую медицинскую справку с пометкой о физическом и психическом здоровье.","r":"ФЗ-8 ст. 5.7","k":"лёгкий бронежилет гражданскому ; можно ли гражданскому броник ; лицензия на бронежилет"},{"d":"ФЗ «Об оружии»","t":"Статья 5.8","x":"Лёгкие бронежилеты разрешены к приобретению исключительно в специализированных оружейных магазинах.","r":"ФЗ-8 ст. 5.8"},{"d":"ФЗ «Об оружии»","t":"Статья 5.9","x":"Граждане обязаны по первому законному требованию сотрудника правоохранительных органов предъявить документы, подтверждающие право на ношение легкого бронежилета.","r":"ФЗ-8 ст. 5.9","k":"документы на бронежилет ; потребовать документы на броник у гражданского ; гражданский в бронежилете на кпп"},{"d":"ФЗ «Об оружии»","t":"Статья 6.1","x":"Разрешены к приобретению, хранению, ношению и использованию боеприпасы калибров, находящихся в ассортименте оружейных магазинов, всем гражданам, имеющим лицензию на право хранения, ношения и использования гражданского оружия и действующую медицинскую справку с пометкой о психическом и физическом здоровье.","r":"ФЗ-8 ст. 6.1"},{"d":"ФЗ «Об оружии»","t":"Статья 6.2","x":"Разрешены к хранению, ношению и использованию только сотрудникам государственных силовых структур, имеющим лицензию на право хранения, ношения и использования гражданского оружия, действующую медицинскую справку с пометкой о психическом и физическом здоровье, боеприпасы любого калибра. Исключение: военнослужащие Армии вправе хранить, носить, использовать боеприпасы без лицензии на право хранения, ношения и использования гражданского оружия.","r":"ФЗ-8 ст. 6.2","k":"патроны любого калибра кому ; боеприпасы военным ; гражданский с патронами ; какие патроны можно"},{"d":"ФЗ «Об оружии»","t":"Статья 7.1","x":"Граждане вправе защищать свое жилище от незаконных проникновений и вправе использовать свое оружие для этого.","r":"ФЗ-8 ст. 7.1","k":"самооборона в жилище ; защита дома оружием ; стрелять в того кто вломился в дом"},{"d":"ФЗ «Об оружии»","t":"Статья 7.2","x":"Граждане, причинившие любой вред лицу, незаконно проникшему на территорию жилища, или угрожавшему смертью владельцу на территории его жилища, не несут уголовной ответственности.","r":"ФЗ-8 ст. 7.2","k":"ответственность за вред нападавшему в доме ; убил вломившегося ответственность"},{"d":"ФЗ «Об оружии»","t":"Статья 7.3","x":"Гражданам запрещено обнажать и использовать оружие в общественных местах, кроме случаев самообороны, когда против гражданина совершается вооруженное или групповое нападение. Примечание: Если нападение совершено одиночным нападающим без оружия, использование оружия для отражения нападения возможно, однако причиненный нападающему вред должен быть соразмерен реальной угрозе нападения и не выходить за пределы необходимой обороны.","r":"ФЗ-8 ст. 7.3","k":"гражданский достал оружие на улице ; можно ли гражданскому доставать оружие в общественном месте ; самооборона на улице закон ; обнажил оружие в городе ; гражданский с пистолетом в руках на улице ; групповое нападение самооборона"},{"d":"ФЗ «Об оружии»","t":"Статья 8.1. Ношение огнестрельного оружия","x":"Часть 1. На территории РО ношение оружия гражданами запрещено, за исключением случаев, предусмотренных настоящим законом. Исключение: Гражданские лица, обладающие лицензией на охоту, а также владеющие действующей лицензией на гражданское оружие, обладают правом открытого ношения за спиной и использования охотничьего оружия с целью охоты на территориях зон охоты. Часть 2. Сотрудники государственных силовых структур, которым в установленном законом порядке предоставлено право на ношение служебного оружия, вправе носить оружие на территории любых объектов. Часть 3. Граждане обязаны по первому законному требованию сотрудника правоохранительных органов предъявить документы, подтверждающие право владения оружием. Часть 4. Сотрудники государственных силовых структур при исполнении служебных обязанностей вправе носить огнестрельное оружие без постановки его на предохранитель.","r":"ФЗ-8 ст. 8.1","k":"ношение оружия гражданами ; открытое ношение оружия ; гражданский с ружьём за спиной ; охотничье оружие ношение ; можно ли носить оружие в городе"},{"d":"ФЗ «Об оружии»","t":"Статья 8.2. Хранение огнестрельного оружия","x":"Часть 1. Хранение огнестрельного оружия осуществляется в разряженном состоянии, с включенным предохранителем, в запираемом сейфе, обеспечивающем сохранность оружия и исключающем доступ посторонних лиц.","r":"ФЗ-8 ст. 8.2","k":"как хранить оружие ; хранение оружия дома сейф ; оружие должно быть разряжено"},{"d":"ФЗ «Об оружии»","t":"Статья 8.3. Перевозка огнестрельного оружия, боеприпасов и специальных средств","x":"Часть 1. Перевозка огнестрельного оружия, боеприпасов и специальных средств в багажнике транспортного средства запрещается, за исключением случаев перевозки в служебном транспорте государственных структур.","r":"ФЗ-8 ст. 8.3","k":"оружие в багажнике ; нашли оружие в багажнике машины ; перевозка оружия в машине ; патроны в багажнике законно ли ; досмотр багажника оружие"},{"d":"ФЗ «Об оружии»","t":"Статья 8.4. Ношение и использование холодного оружия","x":"Часть 1. Ношение и использование холодного оружия запрещено на всей территории РО, за исключением случаев, предусмотренных настоящим законом. Исключение: Использование ножей, топоров для сбора грибов, бревен и охоты в специализированных зонах. Часть 2. Допустимо открытое ношение кастета, когда кастет закреплен на поясе и (или) ремне. Часть 3. Граждане обязаны по первому законному требованию сотрудника правоохранительных органов предъявить документы, подтверждающие право владения оружием. Примечание: Сотрудники силовых государственных структур имеют право потребовать убрать холодное оружие.","r":"ФЗ-8 ст. 8.4","k":"холодное оружие ношение ; нож у гражданского ; кастет законно ли ; гражданский с ножом ; топор в машине"},{"d":"ФЗ «Об оружии»","t":"Статья 9.1","x":"Лицензия на право владения, хранения, ношения и использования в соответствии с главой VIII настоящего Закона гражданского оружия (лицензия на гражданское оружие/лицензия на оружие) выдается уполномоченными сотрудниками МВД после успешной сдачи экзамена и оплаты лицензии.","r":"ФЗ-8 ст. 9.1","k":"кто выдаёт лицензию на оружие ; как получить лицензию на оружие ; лицензия мвд экзамен"},{"d":"ФЗ «Об оружии»","t":"Статья 9.2","x":"Лицензия выдается бессрочно, порядок проведения экзаменов определяется Правительством Москвы. Стоимость лицензии составляет 15.000₽ и 5.000₽ за экзамен в рабочее время и в нерабочее 20.000₽ и 10.000₽. Оплата за проведение экзамена достается сотруднику, который проводил экзамен. С гос. служащих взимается плата только за проведение экзамена.","r":"ФЗ-8 ст. 9.2","k":"сколько стоит лицензия на оружие ; лицензия бессрочная ; экзамен на оружие цена"},{"d":"ФЗ «Об оружии»","t":"Статья 9.3. Запрет на выдачу лицензии на право владения, хранения, ношения и использования гражданского оружия","x":"Часть 1. Лицензия не выдается гражданам, имеющим судимость. Часть 2. Уполномоченное лицо, производящее арест, обязано изъять лицензию на гражданское оружие, если лицо, совершившее преступление, использовало оружие в качестве орудия преступления.","r":"ФЗ-8 ст. 9.3","k":"изъять лицензию при аресте ; судимость лицензия на оружие ; лицензия у преступника ; оружие как орудие преступления лицензия"},{"d":"ФЗ «Об оружии»","t":"Статья 9.4","x":"Указанная в настоящей главе лицензия выдается и является действительной только при наличии действующей медицинской карты с пометкой о физическом и психическом здоровье.","r":"ФЗ-8 ст. 9.4","k":"медкарта для лицензии на оружие ; медицинская справка оружие"},{"d":"ФЗ «Об оружии»","t":"Статья 10.1","x":"Государственные правоохранительные структуры имеют право на проведение гласных и негласных следственных и оперативных мероприятий в рамках ведения надзора и контроля за законностью оборота оружия, боеприпасов и специальных средств гражданскими лицами.","r":"ФЗ-8 ст. 10.1"},{"d":"ФЗ «Об оружии»","t":"Статья 10.2","x":"Пренебрежительное отношение к огнестрельному оружию и спецсредствам запрещено.","r":"ФЗ-8 ст. 10.2","k":"пренебрежительное отношение к оружию ; размахивает оружием"},{"d":"ФЗ «Об оружии»","t":"Статья 10.3","x":"Сотрудники Генеральной Прокуратуры вправе вести надзорную деятельность и контролировать законность оборота оружия, боеприпасов и специальных средств государственными служащими независимо от их должностного положения и принадлежности к определенной структуре посредством гласных и негласных следственных и оперативных мероприятий в случае, если иного не предусмотрено законом. Примечание: В случае военного положения армия вправе вести надзорную деятельность и контролировать законность оборота оружия, боеприпасов и специальных средств государственными служащими независимо от их должностного положения и принадлежности к определенной структуре посредством гласных и негласных следственных и оперативных мероприятий в случае, если иного не предусмотрено законом.","r":"ФЗ-8 ст. 10.3"},{"d":"ФЗ «Об оружии»","t":"Статья 10.4","x":"Сотрудники отделов внутренних расследований при МВД и Федеральной Службе Безопасности имеют право надзора и контроля за законностью оборота оружия, боеприпасов и специальных средств сотрудников в структуре своих государственных формирований посредством проведения гласных и негласных следственных и оперативных мероприятий в случае, если иного не предусмотрено законом.","r":"ФЗ-8 ст. 10.4"},{"d":"ФЗ «Об оружии»","t":"Статья 10.5","x":"За нарушение положений настоящего Закона к виновному лицу может применяться наказание в виде лишения лицензии на право владения, хранения, ношения и использования гражданского оружия.","r":"ФЗ-8 ст. 10.5","k":"наказание за нарушение закона об оружии ; лишение лицензии на оружие"},{"d":"ФЗ «Об оружии»","t":"Статья 10.6","x":"В случае аннулирования лицензии в связи с нарушением одной или нескольких статей данного закона сотрудники правоохранительных органов обязаны изъять оружие, боеприпасы и спецсредства, найденные при обыске личных вещей либо транспортного средства нарушителя. Одобрен Государственной Думой 21 августа 2026 года Подписан Премьер Министром РО 21 августа 2026 года","r":"ФЗ-8 ст. 10.6","k":"аннулировали лицензию изъять оружие ; изъятие оружия при обыске ; нашли оружие при досмотре что делать"},{"d":"ФЗ «Об особом статусе должностных лиц»","t":"Статья 1.1. Статус неприкосновенности должностных лиц","x":"1. Перечень лиц, обладающих статусом неприкосновенности: а) Государственные советники; б) Председатель Правительства РО и его заместители; в) Федеральные Министры и их заместители; г) Судьи всех инстанций; д) Руководители государственных организаций регионального и федерального уровней, расположенные в столичном регионе, и их заместители; е) Председатель Следственного комитета РО и его заместители; ё) Председатель Государственной Думы; ж) Депутаты Государственной Думы. 2. Расследование в отношении лиц, указанных в статье 1, части 1 настоящего закона, невозможно без снятия статуса неприкосновенности уполномоченным лицом. 3. Лица, указанные в статье 1, части 1 настоящего закона, обладают статусом неприкосновенности в течение всего периода исполнения ими своих обязанностей, равно всего периода пребывания на указанной должности, если иное не указано в настоящем законе. 4. Первыми лицами РО являются лица, занимающие высшие государственные должности, а именно: Государственные советники, Премьер-Министр и его заместители, Федеральные Министры и их заместители, Председатель Верховного суда.","r":"ФЗ-10 ст. 1.1","k":"кто неприкосновенный ; список неприкосновенных лиц ; депутат неприкосновенность ; судья неприкосновенность ; министр на кпп можно ли задержать ; кого нельзя задерживать ; статус неприкосновенности кто имеет ; советник правительства неприкосновенность ; неприкосновенные лица перечень"},{"d":"ФЗ «Об особом статусе должностных лиц»","t":"Статья 1.2. Статус правовой защиты должностных лиц","x":"1. Правовая защита - кратковременное изменение статуса должностного лица, гарантирующее ему частичную неприкосновенность. А именно: к лицу, обладающему статусом правовой защиты во время её действия, не допускается привод, задержание, привлечение к административной ответственности, за исключением случаев, предусмотренных главой 8 Кодекса об административных правонарушениях, личный обыск и обыск его вещей, а также обыск личного и используемого им транспорта. Исключением являются случаи, в которых упомянутое лицо совершило преступление, представляет преступную угрозу жизни окружающим людям, а также при наличии постановления (ордера) правомочного лица, решения суда или с разрешения Генерального прокурора или его заместителей, в случае выявленного ими правонарушения. В таком случае статус правовой защиты останавливается. 2. Перечень лиц, обладающих статусом правовой защиты: а) Лица, участвующие в поставках государственных организаций, согласно ч. 3 настоящей статьи. б) Военнослужащие Армии, согласно ч. 4 настоящей статьи. в) Лица, удостоенные высшей государственной награды - звания Героя РО, в соответствии с государственным реестром, согласно ч. 5 настоящей статьи. г) Сотрудники ФСО во время осуществления охранной функции и сопровождения первых лиц, за исключением стажеров. Директор ФСО и его заместители при исполнении должностных обязанностей. д) Сотрудники ФССП во время работы по судебным актам. е) Сотрудники прокуратуры и Следственного комитета при исполнении служебных обязанностей. ё) Кандидаты в Премьер Министры РО, согласно ч. 6 настоящей статьи. ж) Агенты Первой Службы…","r":"ФЗ-10 ст. 1.2","k":"правовая защита должностного лица ; кандидат в премьеры задержание ; во время дебатов задержать ; статус правовой защиты что это ; частичная неприкосновенность"},{"d":"ФЗ «Об особом статусе должностных лиц»","t":"Статья 2.1. Понятие статуса неприкосновенности","x":"1. Лицо, обладающее статусом неприкосновенности, не может быть привлечено к административной ответственности, равно как в отношении такого лица не может быть применена штрафная санкция. Исключение: штрафы, назначенные судом, постановлением прокуратуры РО, а также штрафы за превышение скоростного режима, фиксируемые в автоматическом режиме камерами контроля скорости. 2. Транспортное средство, которое используется неприкосновенным лицом, не может быть подвергнуто остановке или досмотру со стороны силовых ведомств, включая транспортные средства, оказывающие сопровождение. 3. Лицо, обладающее статусом неприкосновенности, не может быть привлечено к уголовной ответственности иначе как в порядке, установленном настоящим Федеральным законом. 4. Лицо, обладающее статусом неприкосновенности, может быть отстранено от исполнения должностных обязанностей руководством Генеральной прокуратуры РО или решением Верховного суда РО. 5. Лицо, обладающее статусом неприкосновенности, не может подвергаться процедуре досмотра или обыска. 6. Организованный кортеж с лицом, обладающим статусом неприкосновенности, вне зависимости от состава такого кортежа, при условии наличия в составе кортежа специального транспортного средства, оборудованного проблесковыми маячками, не может быть остановлен, досмотрен или обыскан. 7. Подтверждением статуса неприкосновенности гражданских (правительственных) служащих, за исключением служащих ФСО, а также руководителей всех иных государственных структур (организаций), является служебное удостоверение. В случае, если при проведении процедуры задержания и(или) ареста…","r":"ФЗ-10 ст. 2.1","k":"неприкосновенного можно оштрафовать ; неприкосновенный нарушил что делать ; штраф неприкосновенному лицу ; административная ответственность неприкосновенных ; что можно с неприкосновенным ; можно ли обыскать неприкосновенного ; досмотр неприкосновенного лица ; кого нельзя обыскивать ; обыск депутата ; досмотр машины министра"},{"d":"ФЗ «Об особом статусе должностных лиц»","t":"Статья 3.1. Расследование в отношении неприкосновенного лица","x":"1. Расследования по преступлениям и административным правонарушениям в отношении лица, обладающего статусом неприкосновенности, регулируется Уголовно-Процессуальным кодексом РО. Одобрен Государственной Думой 21 августа 2026 года Подписан Премьер Министром РО 21 августа 2026 года [https://docs.google.com/document/d/1wmIHhNIrMoUaRk7t1m5bhjnyR9zToEwfZZbkqwdYHkY/edit?tab=t.0](https://docs.google.com/document/d/1wmIHhNIrMoUaRk7t1m5bhjnyR9zToEwfZZbkqwdYHkY/edit?tab=t.0) [https://docs.google.com/document/d/1D230ElSFp5bFG1ONbb6N_ea8qJl2bunBoLj8Gl_1Kb4/edit?tab=t.0](https://docs.google.com/document/d/1D230ElSFp5bFG1ONbb6N_ea8qJl2bunBoLj8Gl_1Kb4/edit?tab=t.0) [https://docs.google.com/document/d/1kEJ27qVvFKpkFJM13sROwW0LsbefFi9NV1YAtI0IGq4/edit?tab=t.0](https://docs.google.com/document/d/1kEJ27qVvFKpkFJM13sROwW0LsbefFi9NV1YAtI0IGq4/edit?tab=t.0)","r":"ФЗ-10 ст. 3.1","k":"как расследуют неприкосновенных ; неприкосновенный совершил преступление ; расследование в отношении депутата"},{"d":"Кодекс этики","t":"Статья 1. Цели и задачи Кодекса","x":"1. Настоящий Кодекс устанавливает обязательные для государственных служащих РО (далее – государственные служащие) этические нормы и правила служебного поведения, направленные на повышение эффективности выполнения государственными служащими своих должностных обязанностей, укрепление авторитета государственной власти, доверия граждан к государственным органам и обеспечение единых стандартов поведения государственных служащих. 2. Задачами настоящего Кодекса являются: формирование у государственных служащих нравственных основ профессиональной деятельности; предупреждение коррупционных и иных правонарушений; обеспечение добросовестного, эффективного и беспристрастного исполнения должностных обязанностей; повышение культуры служебных отношений и внешнего вида государственных служащих.","r":"Кодекс этики ст. 1"},{"d":"Кодекс этики","t":"Статья 2. Сфера действия","x":"1. Настоящий Кодекс распространяется на всех государственных, государственных гражданских служащих, военнослужащих, а также иных лиц, замещающих государственные должности РО и субъектов РО, если иное не предусмотрено специальными нормативными правовыми актами. 2. Положения настоящего Кодекса применяются также к лицам, замещающим должности в государственных корпорациях, государственных компаниях, государственных казенных учреждениях и учреждениях здравоохранения в части, не противоречащей специальным нормативным правовым актам.","r":"Кодекс этики ст. 2","k":"распространяется ли кодекс этики на военных ; кодекс этики для военнослужащих ; на кого действует кодекс этики"},{"d":"Кодекс этики","t":"Статья 3. Основные понятия","x":"Для целей настоящего Кодекса используются следующие основные понятия: государственный служащий – гражданин РО, исполняющий обязанности по государственной должности государственной службы на профессиональной основе и получающий денежное содержание (вознаграждение) за счет средств федерального бюджета или бюджета субъекта РО; служебное поведение – совокупность действий и поступков государственного служащего при исполнении должностных обязанностей, а также во внеслужебное время, если такие действия и поступки могут повлиять на авторитет государственного органа или доверие граждан к государственной власти; этика государственного служащего – система нравственных требований и правил поведения, основанных на принципах законности, справедливости, беспристрастности, честности, добросовестности и уважения к правам и свободам человека и гражданина; внешний вид – совокупность требований к одежде, обуви, прическе, аксессуарам, макияжу и иным элементам внешнего облика государственного служащего при исполнении им должностных обязанностей; конфликт интересов – ситуация, при которой личная заинтересованность (прямая или косвенная) государственного служащего влияет или может повлиять на надлежащее, объективное и беспристрастное исполнение им должностных обязанностей.","r":"Кодекс этики ст. 3"},{"d":"Кодекс этики","t":"Статья 4. Принципы служебного поведения","x":"Государственный служащий обязан руководствоваться следующими принципами: законность и верховенство Конституции РО и федеральных законов; приоритет прав и свобод человека и гражданина; профессионализм и компетентность; беспристрастность и независимость; честность и неподкупность; добросовестность и ответственность; уважение к коллегам, гражданам и организациям; конфиденциальность и сохранение служебной тайны; политическая нейтральность; скромность и умеренность в поведении и внешнем виде.","r":"Кодекс этики ст. 4","k":"принципы поведения госслужащего ; принципы служебного поведения ; как должен вести себя служащий"},{"d":"Кодекс этики","t":"Статья 5. Приоритет прав и свобод человека и гражданина","x":"1. Государственный служащий обязан признавать, соблюдать и защищать права и свободы человека и гражданина. Исполнение должностных обязанностей должно быть направлено на обеспечение благополучия граждан, удовлетворение их законных интересов и предоставление государственных услуг качественно и своевременно. 2. При осуществлении своих полномочий государственный служащий не должен допускать дискриминации граждан по признакам пола, расы, национальности, языка, происхождения, имущественного и должностного положения, места жительства, отношения к религии, убеждений, принадлежности к общественным объединениям, а также по другим обстоятельствам.","r":"Кодекс этики ст. 5"},{"d":"Кодекс этики","t":"Статья 6. Законность","x":"1. Государственный служащий обязан строго соблюдать Конституцию РО, федеральные конституционные законы, федеральные законы, иные нормативные правовые акты РО, законы и иные нормативные правовые акты субъектов РО, а также настоящий Кодекс.","r":"Кодекс этики ст. 6"},{"d":"Кодекс этики","t":"Статья 7. Профессионализм и компетентность","x":"1. Государственный служащий обязан постоянно повышать свою квалификацию, профессиональный уровень, изучать изменения законодательства и правоприменительную практику, стремиться к эффективному выполнению должностных обязанностей. 2. Государственный служащий не вправе принимать на себя обязательства, которые заведомо не может исполнить, а также давать гражданам и организациям необоснованные обещания.","r":"Кодекс этики ст. 7"},{"d":"Кодекс этики","t":"Статья 8. Беспристрастность и независимость","x":"1. Государственный служащий при исполнении должностных обязанностей обязан быть беспристрастным, исключающим влияние на его служебную деятельность каких-либо личных, имущественных, финансовых и иных интересов, а также воздействие со стороны политических партий, общественных объединений, религиозных организаций и иных лиц. 2. Государственный служащий не должен оказывать предпочтение каким-либо лицам, организациям, группам или территориям, обязан принимать решения в рамках закона и исключительно на основе объективных критериев.","r":"Кодекс этики ст. 8"},{"d":"Кодекс этики","t":"Статья 9. Честность и неподкупность","x":"1. Государственный служащий обязан быть честным и порядочным, не допускать обмана, фальсификации документов, сокрытия информации, имеющей значение для принятия решений. 2. Государственному служащему запрещается получать в связи с исполнением должностных обязанностей вознаграждения от физических и юридических лиц (подарки, денежное вознаграждение, ссуды, услуги, оплату развлечений, отдыха, транспортных расходов и иные вознаграждения), за исключением случаев, предусмотренных законодательством РО.","r":"Кодекс этики ст. 9","k":"честность госслужащего ; подделка документов этика ; взял вознаграждение ; неподкупность"},{"d":"Кодекс этики","t":"Статья 10. Конфиденциальность","x":"1. Государственный служащий обязан соблюдать конфиденциальность служебной информации, ставшей ему известной в связи с исполнением должностных обязанностей, в том числе после прекращения государственной службы. 2. Государственный служащий не вправе использовать служебную информацию в личных целях, а также передавать ее третьим лицам, если это не предусмотрено законодательством РО.","r":"Кодекс этики ст. 10","k":"конфиденциальность служебной информации ; слил информацию этика ; разглашение служебной информации"},{"d":"Кодекс этики","t":"Статья 11. Уважение к коллегам и гражданам","x":"1. Государственный служащий обязан проявлять уважение к коллегам, гражданам и представителям организаций, соблюдать правила делового этикета, быть вежливым, корректным, внимательным и терпимым. 2. Государственный служащий не должен допускать действий, унижающих честь и достоинство других лиц, проявлений грубости, высокомерия, пренебрежительного тона, а также использования нецензурных слов, кличек, прозвищ и фамильярного обращения.","r":"Кодекс этики ст. 11","k":"уважение к гражданам ; хамить гражданам ; грубость с гражданскими ; вежливость с гражданами ; унижение достоинства гражданина"},{"d":"Кодекс этики","t":"Статья 12. Общие требования к служебному поведению","x":"1. Государственный служащий обязан исполнять должностные обязанности добросовестно, на высоком профессиональном уровне, в пределах установленных полномочий. 2. Государственный служащий должен воздерживаться от поведения, которое могло бы вызвать сомнение в объективном исполнении им должностных обязанностей, а также избегать конфликтных ситуаций, способных нанести ущерб его репутации или авторитету государственного органа. 3. Государственный служащий не должен использовать свое служебное положение для оказания влияния на деятельность государственных органов, органов местного самоуправления, организаций, должностных лиц, государственных служащих и граждан при решении вопросов личного характера.","r":"Кодекс этики ст. 12"},{"d":"Кодекс этики","t":"Статья 13. Обращение и субординация","x":"1. Государственные служащие при исполнении должностных обязанностей обязаны обращаться друг к другу и к гражданам на «Вы», независимо от занимаемой должности и возраста. 2. При обращении к лицам, имеющим специальные звания, классные чины или дипломатические ранги, допускается использование установленного нормативными правовыми актами порядка обращения (например, перед воинским званием военнослужащие добавляют слово «товарищ»). 3. Искажение воинских званий, классных чинов, дипломатических рангов, употребление нецензурных слов, кличек и прозвищ, грубость и фамильярное обращение несовместимы с понятием служебной чести и достоинством государственного служащего и влекут за собой ответственность, предусмотренную законодательством РО. 4. Государственный служащий обязан соблюдать субординацию, выполнять законные поручения вышестоящих руководителей, отданные в пределах их должностных полномочий, и не допускать действий, нарушающих порядок подчиненности.","r":"Кодекс этики ст. 13","k":"на вы или на ты ; обращение на вы к гражданам ; как обращаться к гражданам ; тыкать гражданскому ; обращение к старшему по званию этика ; можно ли на ты"},{"d":"Кодекс этики","t":"Статья 14. Взаимоотношения с коллегами","x":"1. Государственный служащий должен строить взаимоотношения с коллегами на принципах взаимного уважения, сотрудничества, корректности и доброжелательности. 2. Государственный служащий не вправе допускать по отношению к коллегам действий, унижающих их честь и достоинство, проявлений дискриминации, травли, а также распространения сведений, порочащих их репутацию, не основанных на достоверных фактах. 3. Государственный служащий обязан оказывать содействие коллегам в выполнении общих задач, обмениваться опытом и информацией в рамках, не противоречащих требованиям конфиденциальности.","r":"Кодекс этики ст. 14","k":"отношения с коллегами ; травля коллег ; дискриминация сослуживцев ; распространение слухов о коллегах"},{"d":"Кодекс этики","t":"Статья 15. Взаимоотношения с гражданами и организациями","x":"1. Государственный служащий при взаимодействии с гражданами и представителями организаций обязан быть вежливым, тактичным, терпеливым, проявлять готовность к диалогу и оказанию необходимой помощи в рамках своей компетенции. 2. Государственный служащий не должен допускать пренебрежительного отношения к гражданам, игнорирования их законных просьб и обращений, создания искусственных препятствий для реализации их прав. 3. Государственный служащий обязан соблюдать установленные сроки рассмотрения обращений граждан и организаций, предоставлять достоверную информацию о порядке и условиях получения государственных услуг.","r":"Кодекс этики ст. 15","k":"как общаться с гражданскими ; вежливость на посту ; пренебрежительное отношение к гражданам ; игнорировать гражданина"},{"d":"Кодекс этики","t":"Статья 16. Запреты и ограничения, связанные с государственной службой","x":"Государственному служащему при исполнении должностных обязанностей запрещается: допускать высказывания и действия, дискриминирующие граждан по каким-либо признакам; использовать служебное положение в интересах политических партий, общественных, религиозных объединений и иных организаций, если это не предусмотрено законодательством; принимать подарки, денежные средства, услуги или иные выгоды от физических и юридических лиц в связи с исполнением должностных обязанностей; разглашать сведения, составляющие государственную, служебную или иную охраняемую законом тайну, а также сведения, ставшие ему известными в связи с исполнением должностных обязанностей, в том числе сведения, касающиеся частной жизни и здоровья граждан; заниматься предпринимательской деятельностью лично или через доверенных лиц, участвовать в управлении коммерческой организацией, за исключением случаев, предусмотренных законодательством; использовать в неслужебных целях средства материально-технического, финансового и информационного обеспечения, другое государственное имущество и служебную информацию; допускать публичные высказывания, суждения и оценки, в том числе в средствах массовой информации, в отношении деятельности государственных органов, их руководителей, включая решения вышестоящего государственного органа либо государственного органа, в котором государственный служащий замещает должность, если это не входит в его должностные обязанности; принимать без письменного разрешения представителя нанимателя награды, почетные и специальные звания (за исключением научных) иностранных государств,…","r":"Кодекс этики ст. 16","k":"что запрещено госслужащему ; запреты для служащих ; дискриминация граждан ; служебное положение в интересах партии"},{"d":"Кодекс этики","t":"Статья 17. Конфликт интересов","x":"1. Государственный служащий обязан принимать меры по недопущению любой возможности возникновения конфликта интересов. 2. Государственный служащий обязан в письменной форме уведомить своего непосредственного начальника о возникшем конфликте интересов или о возможности его возникновения, как только ему станет об этом известно. 3. Представитель нанимателя, если ему стало известно о возникновении у государственного служащего личной заинтересованности, которая приводит или может привести к конфликту интересов, обязан принять меры по предотвращению или урегулированию конфликта интересов, вплоть до отстранения государственного служащего от замещаемой должности.","r":"Кодекс этики ст. 17","k":"конфликт интересов этика ; уведомить начальника о конфликте интересов"},{"d":"Кодекс этики","t":"Статья 18. Подарки и иные вознаграждения","x":"1. Государственному служащему запрещается принимать от граждан и организаций подарки, денежные средства, ссуды, услуги, оплату развлечений, отдыха, транспортных расходов и иные вознаграждения, если такие действия связаны с исполнением должностных обязанностей. 2. Подарки, полученные государственными служащими в связи с протокольными мероприятиями, служебными командировками и другими официальными мероприятиями, признаются федеральной собственностью или собственностью субъекта РО и передаются государственным служащим по акту в государственный орган, за исключением случаев, предусмотренных законодательством. 3. Государственный служащий, сдавший подарок, полученный им в связи с протокольным мероприятием, служебной командировкой или другим официальным мероприятием, может его выкупить в порядке, устанавливаемом нормативными правовыми актами РО.","r":"Кодекс этики ст. 18","k":"подарки госслужащему ; можно ли принимать подарки ; гражданский предлагает деньги ; оплата развлечений служащему ; принял подарок"},{"d":"Кодекс этики","t":"Статья 19. Использование служебного положения","x":"1. Государственный служащий не вправе использовать свое служебное положение для оказания влияния на деятельность государственных органов, органов местного самоуправления, организаций, должностных лиц, государственных служащих и граждан при решении вопросов личного характера. 2. Государственный служащий не вправе использовать преимущества своего должностного положения для предвыборной агитации, а также для агитации по вопросам референдума. 3. Государственный служащий обязан соблюдать нейтральность, исключающую возможность какого-либо влияния на свою служебную деятельность решений политических партий, других общественных объединений, религиозных объединений и иных организаций.","r":"Кодекс этики ст. 19","k":"использование служебного положения ; решать личные вопросы через должность"},{"d":"Кодекс этики","t":"Статья 20. Поведение во внеслужебное время","x":"1. Государственный служащий во внеслужебное время должен вести себя достойно, не допускать поступков, порочащих честь и достоинство государственного служащего, подрывающих авторитет государственной власти и доверие граждан к государственным органам. 2. Государственный служащий должен воздерживаться от публичных высказываний, суждений и оценок, которые могут быть истолкованы как выражение позиции государственного органа, если такие высказывания не согласованы с уполномоченным руководителем. 3. Государственный служащий не должен допускать появления в общественных местах в состоянии алкогольного, наркотического или иного токсического опьянения, оскорбляющем человеческое достоинство и общественную нравственность.","r":"Кодекс этики ст. 20","k":"поведение вне службы ; во внеслужебное время ; публичные высказывания служащего ; порочащие поступки вне службы ; как вести себя не на службе"},{"d":"Кодекс этики","t":"Статья 21. Общие требования к внешнему виду","x":"1. Внешний вид государственного служащего при исполнении должностных обязанностей должен свидетельствовать о высоком уровне деловой культуры, быть аккуратным, сдержанным, соответствовать официальному характеру деятельности государственного органа. 2. Государственный служащий обязан соблюдать деловой стиль одежды, отдавая предпочтение строгим классическим костюмам, однотонным неярким цветам, избегая вызывающих и экстравагантных элементов. 3. Требования к внешнему виду, установленные настоящей главой, не распространяются на государственных служащих, для которых предусмотрено ношение специальной форменной одежды (униформы), если иное не установлено специальными нормами.","r":"Кодекс этики ст. 21","k":"внешний вид госслужащего ; деловой стиль одежды ; аккуратный внешний вид"},{"d":"Кодекс этики","t":"Статья 22. Разрешенные элементы одежды и внешнего вида для мужчин","x":"1. Государственным служащим мужского пола при исполнении должностных обязанностей разрешается ношение следующих элементов одежды и аксессуаров: строгий деловой костюм (пиджак и брюки) неярких цветов (черный, серый, темно-синий, коричневый, бежевый, оливковый и иные приглушенные тона); брюки классического покроя; классические джинсы однотонных неярких цветов без потертостей, декоративных элементов и надписей; рубашки (сорочки) однотонные или с неброским рисунком, преимущественно светлых тонов; поло однотонного неяркого цвета; пиджак (блейзер) классического кроя; однотонные кеды или кроссовки сдержанных цветов, кожаные туфли; кожаные перчатки; классические наручные часы; классические или солнцезащитные очки с однотонной неяркой оправой и линзами; аксессуары (галстук, ремень, сумка, портфель) с символикой, названием или логотипом бренда, если размеры такой символики не являются ярко выраженными. 2. Государственным служащим мужского пола разрешается ношение обручального кольца, а также иных ювелирных изделий, не являющихся броскими и не привлекающих излишнего внимания, за исключением случаев, предусмотренных статьей 24 настоящего Кодекса.","r":"Кодекс этики ст. 22","k":"что можно носить мужчинам ; разрешённая одежда служащих мужчин ; джинсы разрешены"},{"d":"Кодекс этики","t":"Статья 23. Разрешенные элементы одежды и внешнего вида для женщин","x":"1. Государственным служащим женского пола при исполнении должностных обязанностей разрешается ношение следующих элементов одежды и аксессуаров: строгий деловой костюм (жакет и юбка или брюки) неярких цветов; классические брюки; классические джинсы однотонных неярких цветов без потертостей, декоративных элементов и надписей; юбки и платья длиной не выше середины бедра, неярких цветов; блузки, рубашки, водолазки однотонные или с неброским рисунком; поло однотонного неяркого цвета; пиджак (жакет, блейзер) классического кроя; однотонные кеды или кроссовки сдержанных цветов, туфли, балетки; кожаные перчатки; классические наручные часы; аккуратные серьги, не привлекающие чрезмерного внимания; классические или солнцезащитные очки с однотонной неяркой оправой и линзами; дневной макияж, выполненный в сдержанных тонах; аксессуары (платок, шарф, ремень, сумка) с символикой, названием или логотипом бренда, если размеры такой символики не превышают 10 квадратных сантиметров и не являются ярко выраженными. 2. Государственным служащим женского пола разрешается ношение ювелирных изделий, не являющихся броскими и не привлекающих излишнего внимания.","r":"Кодекс этики ст. 23","k":"что можно носить женщинам ; разрешённая одежда служащих женщин ; юбка какой длины"},{"d":"Кодекс этики","t":"Статья 24. Запрещенные элементы одежды и внешнего вида","x":"1. Государственному служащему при исполнении должностных обязанностей запрещается ношение следующих элементов одежды, обуви и аксессуаров: спортивная одежда (спортивные костюмы, шорты, майки, футболки с надписями, толстовки и т.п.), за исключением случаев, когда это предусмотрено должностными обязанностями или специальными нормативными правовыми актами; пляжная одежда и обувь (пляжные шорты, сланцы, вьетнамки и т.п.); одежда и обувь, имеющие названия и (или) логотипы брендов, за исключением аксессуаров, указанных в пункте 11 части 1 статьи 22 и пункте 14 части 1 статьи 23 настоящего Кодекса; одежда и обувь с декоративными рисунками, надписями, стразами, пайетками, крупной фурнитурой; светящаяся обувь; неопрятная одежда или обувь, под которой понимаются элементы гардероба, имеющие потертости, тканевые вставки (заплатки), дыры, неотстиранные пятна, небрежную форму; татуировки на видных частях тела (все татуировки должны быть скрыты одеждой и не должны быть заметны для окружающих, за исключением однотонных, не содержащих запрещенной или неподобающей облику госсотрудника символики); линзы неестественных цветов; окрашивание волос в яркие или неестественные цвета; яркий и выделяющийся макияж и (или) грим; прически неофициального стиля (ирокезы и иные экстравагантные прически); украшения из металла и бижутерия для мужчин, за исключением классических наручных часов и обручального кольца; иные элементы одежды, обуви и аксессуаров, не соответствующие деловому стилю и способные нанести ущерб авторитету государственного органа. 2. Ношение классических солнцезащитных очков и очков для…","r":"Кодекс этики ст. 24","k":"что запрещено носить ; спортивная одежда запрещена ; шорты майки на службе ; запрещённая одежда госслужащих ; толстовка на службе"},{"d":"Кодекс этики","t":"Статья 25. Контроль за соблюдением требований к внешнему виду","x":"1. Руководители государственных органов и начальники структурных подразделений осуществляют контроль за соблюдением государственными служащими, находящимися в их подчинении, требований настоящей главы. 2. При выявлении нарушений требований к внешнему виду руководитель государственного органа или начальник структурного подразделения обязан потребовать от государственного служащего устранения нарушения, а при повторном или грубом нарушении – принять меры дисциплинарного воздействия в соответствии с законодательством РО.","r":"Кодекс этики ст. 25","k":"кто следит за внешним видом ; начальник проверяет внешний вид ; нарушил внешний вид кто наказывает"},{"d":"Кодекс этики","t":"Статья 26. Особенности для отдельных категорий служащих","x":"1. Сотрудники государственных казенных учреждений, государственных компаний, учреждений здравоохранения имеют право отступать от требований к внешнему виду, установленных настоящей главой, в случаях, когда это обусловлено спецификой выполняемых ими трудовых (служебных) функций, в порядке, установленном локальными нормативными актами соответствующих организаций. 2. Для государственных служащих, замещающих должности, предусматривающие ношение форменной одежды, требования к внешнему виду определяются соответствующими нормативными правовыми актами о форменной одежде и знаках различия.","r":"Кодекс этики ст. 26"},{"d":"Кодекс этики","t":"Статья 27. Виды ответственности","x":"1. Нарушение государственным служащим положений настоящего Кодекса влечет за собой дисциплинарную или административную ответственность в порядке статьи 9.6 КоАП РО. Одобрен Государственной Думой 21 августа 2026 года Подписан Премьер Министром РО 21 августа 2026 года","r":"Кодекс этики ст. 27","k":"ответственность за нарушение кодекса этики ; что будет за нарушение этики ; наказание за этику ; коап 9.6 этика"},{"d":"ФКЗ «О вводимых правовых режимах»","t":"Статья 1. Военное положение","x":"1. Под военным положением понимается особый правовой режим, вводимый на территории РО или в отдельных ее местностях в соответствии с Конституцией РО, Премьер-Министром РО в случае агрессии против РО или непосредственной угрозы агрессии. 2. Целью введения военного положения является создание условий для отражения или предотвращения агрессии против РО. 3. Период действия военного положения начинается с даты и времени начала действия военного положения, которые устанавливаются указом Премьер-Министром РО о введении военного положения, и заканчивается датой и временем отмены (прекращения действия) военного положения. 4. В период действия военного положения в соответствии с настоящим Федеральным законом могут в той мере, в какой это необходимо для обеспечения обороны страны и безопасности государства, ограничиваться права и свободы граждан РО, деятельность организаций независимо от организационно-правовых форм и форм собственности, права их должностных лиц, в том числе применяя меры и временные ограничения, предусмотренные для чрезвычайного положения. На граждан, организации и их должностных лиц могут возлагаться дополнительные обязанности. 5. Общая или частичная мобилизация, если она не была объявлена ранее, при введении военного положения на территории РО или в отдельных ее местностях объявляется в соответствии с федеральными законами и иными нормативными правовыми актами РО.","r":"ФКЗ-3 ст. 1","k":"что такое военное положение ; военное положение определение ; цель военного положения"},{"d":"ФКЗ «О вводимых правовых режимах»","t":"Статья 2. Введение военного положения","x":"1. Военное положение на территории РО или в отдельных ее местностях вводится и отменяется указом Премьер-Министра РО в соответствии с настоящим федеральным законом. 2. Премьер-Министр РО незамедлительно сообщает о введении военного положения Федеральному Собранию. 3. Указ Премьер-Министра РО о введении военного положения прекращает действие по истечении двенадцати часов с момента принятия такого решения, о чем население РО или соответствующих ее отдельных местностей оповещается в том же порядке, в каком оно оповещалось о введении военного положения.","r":"ФКЗ-3 ст. 2","k":"кто вводит военное положение ; как вводится военное положение ; указ о военном положении ; кто отменяет военное положение"},{"d":"ФКЗ «О вводимых правовых режимах»","t":"Статья 3. Причины для введения военного положения","x":"1. В соответствии с Конституцией РО основанием для введения Премьер-Министром РО военного положения на территории РО или в отдельных ее местностях является агрессия против РО или непосредственная угроза агрессии. 2. Иными причинами для введения военного положения на территории РО или в отдельных ее местностях являются: 1) попытка совершения государственного переворота; 2) угроза жизни высших чинов государственных структур, Правительства или Премьер-Министра РО; 3) повышенная активность криминогенной организации и/или лиц, причастных к криминогенной активности, служащей подрывом безопасности суверенитета РО и/или первых лиц государства (далее - Правительство РО, Вице Премьер-Министр РО, Председатель Правительства РО).","r":"ФКЗ-3 ст. 3","k":"причины военного положения ; когда вводят военное положение ; основания для военного положения ; агрессия против ро"},{"d":"ФКЗ «О вводимых правовых режимах»","t":"Статья 4. Меры, применяемые на территории, на которой введено военное положение","x":"На основании указов Премьер-Министра РО на территории, на которой введено военное положение, применяются следующие меры: 1) усиление охраны общественного порядка и обеспечения общественной безопасности, охраны военных, важных государственных и специальных объектов, объектов, обеспечивающих жизнедеятельность населения, функционирование транспорта, коммуникаций и связи, объектов энергетики, а также объектов, представляющих повышенную опасность для жизни и здоровья людей и для окружающей природной среды; 2) введение и обеспечение особого режима въезда на территорию, на которой введено военное положение, и выезда с нее, а также ограничение свободы передвижения по ней; 3) запрещение или ограничение проведения собраний, митингов и демонстраций, шествий и пикетирования, а также иных массовых мероприятий, запрещение забастовок; 4) ограничение движения транспортных средств и осуществление их обыска; 5) предоставление силовым государственным организациям права при необходимости осуществлять проверку документов, личный обыск, обыск их вещей, жилища, транспортных средств; 6) задержание и арест граждан в случае нарушения запретов и ограничений, установленных указами Премьер-Министра РО на территории, на которой введено военное положение; 7) принудительное и контролируемое перемещение граждан с территории, на которой введено военное положение, на территории, на которых военное положение не введено, или на иные территории; 8) введение контроля за работой типографий, средств массовой информации, использование их работы для нужд обороны; введение военной цензуры; 9) введение в органах…","r":"ФКЗ-3 ст. 4","k":"что меняется при военном положении ; меры военного положения ; усиление охраны при военном положении ; ограничения при военном положении"},{"d":"ФКЗ «О вводимых правовых режимах»","t":"Статья 5. Руководство территорией, на которой введено военное положение, осуществляет Федеральная служба безопасности","x":"1. Для осуществления единого управления силами и средствами, обеспечивающими режим военного положения, руководство над настоящими структурами передается Федеральной службе безопасности в лице Директора, его заместителей и иного начальствующего состава. 2. Федеральная служба безопасности на территории военного положения: 1) издает в пределах своих полномочий приказы и распоряжения по вопросам обеспечения режима военного положения, обязательные для исполнения на соответствующей территории всеми организациями и должностными лицами указанных организаций, гражданами, а также начальниками (командирами) органов силовых государственных организаций; 2) определяет особый режим въезда на территорию, на которой введено военное положение, и выезда с нее; 3) выдворяет в установленном порядке за пределы территории, на которой введено военное положение, лиц, нарушающих режим военного положения; 4) оповещает через средства массовой информации население соответствующей территории о порядке выполнения отдельных мер, применяемых в условиях военного положения.","r":"ФКЗ-3 ст. 5","k":"кто руководит при военном положении ; фсб руководит военным положением ; кому подчиняемся при военном положении"},{"d":"ФКЗ «О вводимых правовых режимах»","t":"Статья 6. Обеспечение режима военного положения","x":"Для обеспечения режима военного положения в порядке, установленном нормативными правовыми актами Премьер-Министра РО, могут быть привлечены Вооруженные Силы РО и иные силовые организации, органы медицинской службы.","r":"ФКЗ-3 ст. 6","k":"армия при военном положении ; привлечение вооружённых сил к военному положению ; что делает армия при военном положении"},{"d":"ФКЗ «О вводимых правовых режимах»","t":"Статья 7. Чрезвычайное положение","x":"1. Чрезвычайное положение – положение, вводимое на территории всей РО или в ее отдельных местностях для предотвращения незаконной деятельности, либо устранения результатов террористических актов, либо катастроф различного характера. 2. Чрезвычайное положение вводится и отменяется соответствующим указом Премьер-Министра РО.","r":"ФКЗ-3 ст. 7","k":"что такое чрезвычайное положение ; чп определение ; кто вводит чрезвычайное положение ; чем чп отличается от военного положения"},{"d":"ФКЗ «О вводимых правовых режимах»","t":"Статья 8. Срок действия чрезвычайного положения","x":"1. Чрезвычайное положение вправе вводиться на срок, не превышающий 12 часов с момента публикации соответствующего указа. 2. По истечении срока, указанного в настоящей статье, чрезвычайное положение считается прекращенным. В случае, если в течение этого срока цели введения чрезвычайного положения не были достигнуты, может вводиться режим военного положения с соблюдением требований, установленных настоящим Федеральным законом для введения чрезвычайного положения.","r":"ФКЗ-3 ст. 8","k":"сколько длится чрезвычайное положение ; срок чп 12 часов ; когда заканчивается чп"},{"d":"ФКЗ «О вводимых правовых режимах»","t":"Статья 9. Причины для введения чрезвычайного положения","x":"Чрезвычайное положение вводится лишь при наличии обстоятельств, которые представляют собой непосредственную угрозу жизни и безопасности граждан или конституционному строю РО. К таким обстоятельствам относятся: 1) ухудшение криминогенной обстановки на территории РО или отдельных ее субъектов; 2) участившиеся случаи хищения государственного имущества; 3) попытка насильственного изменения конституционного строя, попытка захвата власти, террористический и/или террористические акты; 4) чрезвычайные ситуации (чрезвычайные происшествия) природного и/или технического характера, требующие проведения масштабных аварийно-спасательных и других работ.","r":"ФКЗ-3 ст. 9","k":"причины чрезвычайного положения ; когда вводят чп ; основания для чп"},{"d":"ФКЗ «О вводимых правовых режимах»","t":"Статья 10. Руководство территорией, на которой введено чрезвычайное положение, осуществляет Федеральная служба безопасности","x":"1. Для осуществления единого управления силами и средствами, обеспечивающими режим чрезвычайного положения, руководство над настоящими структурами передается Федеральной службе безопасности в лице Директора, его заместителей и иного начальствующего состава. 2. Федеральная служба безопасности на территории чрезвычайного положения: 1) издает в пределах своих полномочий приказы и распоряжения по вопросам обеспечения режима чрезвычайного положения, обязательные для исполнения на соответствующей территории всеми организациями и должностными лицами указанных организаций, гражданами, а также начальниками (командирами) органов силовых государственных организаций; 2) определяет особый режим въезда на территорию, на которой введено чрезвычайное положение, и выезда с нее; 3) выдворяет в установленном порядке за пределы территории, на которой введено чрезвычайное положение, лиц, нарушающих режим чрезвычайного положения; 4) оповещает через средства массовой информации население соответствующей территории о порядке выполнения отдельных мер, применяемых в условиях чрезвычайного положения.","r":"ФКЗ-3 ст. 10","k":"кто руководит при чп ; фсб при чрезвычайном положении"},{"d":"ФКЗ «О вводимых правовых режимах»","t":"Статья 11. Обеспечение режима чрезвычайного положения","x":"1. Вооруженные Силы РО, другие войска, воинские формирования и органы, выполняющие задачи в области обороны (далее - Вооруженные Силы РО, другие войска, воинские формирования и органы), применяются для отражения или предотвращения агрессии против суверенитета РО в соответствии с федеральными законами и иными нормативными правовыми актами РО. 2. Для обеспечения режима чрезвычайного положения используются силы и средства органов внутренних дел, федеральных органов безопасности, Вооруженные Силы РО, а также силы и средства органов государственных медицинских учреждений. 3. Государственные силовые структуры имеют право проводить обыск личных вещей гражданских, включая обыск транспорта и личного имущества на контрольно-пропускных пунктах и подконтрольных районах, объявленных указом Премьер-Министра РО. 4. Для координации действий сил и средств, обеспечивающих режим чрезвычайного положения, указом Премьер-Министра РО может быть создан объединенный оперативный штаб из представителей органов, обеспечивающих режим чрезвычайного положения.","r":"ФКЗ-3 ст. 11","k":"армия при чп ; вооружённые силы чрезвычайное положение"},{"d":"ФКЗ «О вводимых правовых режимах»","t":"Статья 12. Ограничения и чрезвычайные меры","x":"В период действия чрезвычайного положения в соответствии с настоящим Федеральным законом могут в той мере, в какой это необходимо для обеспечения обороны страны и безопасности суверенитета государства, ограничиваться права и свободы граждан РО, иностранных граждан, лиц без гражданства, деятельность организаций независимо от организационно-правовых форм и форм собственности, права их должностных лиц. На граждан, организации и их должностных лиц могут возлагаться дополнительные обязанности.","r":"ФКЗ-3 ст. 12","k":"ограничения прав при чп ; что ограничивают при чрезвычайном положении"},{"d":"ФКЗ «О вводимых правовых режимах»","t":"Статья 13. Меры и временные ограничения, применяемые при введении чрезвычайного положения","x":"Указом Премьер-Министра РО о введении чрезвычайного положения на период действия чрезвычайного положения может предусматриваться введение следующих мер и временных ограничений: 1) полное или частичное приостановление на территории, на которой введено чрезвычайное положение, полномочий органов исполнительной власти, органов государственной власти РО, а также органов местного самоуправления; 2) установление ограничений на свободу передвижения по территории, на которой введено чрезвычайное положение, а также введение особого режима въезда на указанную территорию и выезда с нее, включая установление ограничений на въезд на указанную территорию и пребывание на ней иностранных граждан и лиц без гражданства; 3) усиление охраны общественного порядка, объектов, подлежащих государственной охране, и объектов, обеспечивающих жизнедеятельность населения и функционирование транспорта; 4) запрет или ограничение проведения собраний, митингов и демонстраций, шествий и пикетирования, а также иных массовых мероприятий; запрещение забастовок и иных способов приостановления или прекращения деятельности организаций; 5) ограничение движения транспортных средств и осуществление их обыска; 6) приостановление деятельности частных организаций; 7) ограничение свободы печати и других средств массовой информации путем введения предварительной цензуры с указанием условий и порядка ее осуществления, а также временное изъятие или арест печатной продукции, радиопередающих, звукоусиливающих технических средств, множительной техники, установление особого порядка аккредитации журналистов; 8) проверка…","r":"ФКЗ-3 ст. 13","k":"меры при чп ; что запрещено при чрезвычайном положении ; комендантский час ; ограничения при чп список"},{"d":"ФКЗ «О вводимых правовых режимах»","t":"Статья 14. Полномочия Федеральной службы безопасности при введении чрезвычайного положения","x":"1. Для осуществления единого управления силами и средствами, обеспечивающими режим чрезвычайного положения, руководство над настоящими структурами передается Федеральной службе безопасности в лице Директора, его заместителей и иного начальствующего состава. 2. Федеральная служба безопасности на территории чрезвычайного положения: 1) издает в пределах своих полномочий приказы и распоряжения по вопросам обеспечения режима чрезвычайного положения, обязательные для исполнения на соответствующей территории всеми организациями и должностными лицами указанных организаций, гражданами, а также начальниками (командирами) органов силовых государственных организаций; 2) определяет особый режим въезда на территорию, на которой введено чрезвычайное положение, и выезда с нее; 3) выдворяет в установленном порядке за пределы территории, на которой введено чрезвычайное положение, лиц, нарушающих режим чрезвычайного положения; 4) оповещает через средства массовой информации население соответствующей территории о порядке выполнения отдельных мер, применяемых в условиях чрезвычайного положения. Одобрен Государственной Думой 21 августа 2026 года Подписан Премьер-Министром РО 21 августа 2026 года","r":"ФКЗ-3 ст. 14","k":"полномочия фсб при чп ; что может фсб при чрезвычайном положении"},{"d":"Лекция «Постовая служба»","t":"Общее","x":"# Лекция: Постовая служба > Постовая служба — одна из ключевых задач военнослужащего: защита территории от несанкционированного проникновения и поддержание порядка на посту.","r":"Лекция «Постовая служба»"},{"d":"Лекция «Постовая служба»","t":"1. Шаблоны докладов в `/f` — главное для отчёта","x":"Формат единый, меняется только средняя часть: /f Докладывает [Звание] Росгвардии [Имя Фамилия] - время [ЧЧ:ММ] - [КПП№N Алабино / Вышка \"Название\"] - заступил на пост - состояние стабильное - доклад окончил. /f Докладывает [Звание] Росгвардии [Имя Фамилия] - время [ЧЧ:ММ] - [КПП№N Алабино / Вышка \"Название\"] - состояние стабильное - доклад окончил. /f Докладывает [Звание] Росгвардии [Имя Фамилия] - время [ЧЧ:ММ] - [КПП№N Алабино / Вышка \"Название\"] - пост сдал - состояние стабильное - доклад окончил.","r":"Лекция «Постовая служба»","k":"как докладывать в рацию ; шаблон доклада на посту ; что писать в /f на кпп ; доклад заступил на пост ; формат доклада каждые 15 минут ; как написать доклад по рации ; текст доклада с поста ; команда для доклада ; докладывает звание имя фамилия время ; доклад сдал пост"},{"d":"Лекция «Постовая служба»","t":"Эталонный пример (из лекции)","x":"/f Докладывает Полковник Росгвардии Василиса Спасская - время 16:00 - КПП№1 Алабино - заступил на пост - состояние стабильное - доклад окончил. /f Докладывает Полковник Росгвардии Василиса Спасская - время 16:15 - КПП№1 Алабино - состояние стабильное - доклад окончил. /f Докладывает Полковник Росгвардии Василиса Спасская - время 16:30 - КПП№1 Алабино - состояние стабильное - доклад окончил. /f Докладывает Полковник Росгвардии Василиса Спасская - время 16:45 - КПП№1 Алабино - состояние стабильное - доклад окончил. /f Докладывает Полковник Росгвардии Василиса Спасская - время 17:00 - КПП№1 Алабино - пост сдал - состояние стабильное - доклад окончил. ⚠️ Чат — /f (IC, рация), не /fb. Доклад каждые 15 минут.","r":"Лекция «Постовая служба»","k":"пример доклада ; образец доклада с кпп ; как выглядит правильный доклад"},{"d":"Лекция «Постовая служба»","t":"2. Расстановка постов (полигон Алабино)","x":"Пост — Расстановка — Кол-во КПП №1 Алабино — Два военнослужащих слева и справа от ворот, один за воротами — 3 КПП №2 Алабино — Два военнослужащих слева и справа от шлагбаума, один за шлагбаумом — 3 Наблюдательная вышка Алабино — Два военнослужащих — 2 Вышка «Оружейки» — Один военнослужащий — 1 Вышка «Огневой рубеж» — Один военнослужащий — 1 Вышка «Лагерь» — Один военнослужащий — 1 При заступлении в рации указывается конкретный пост (КПП или вышка).","r":"Лекция «Постовая служба»","k":"сколько человек на кпп алабино ; расстановка на посту ; где стоять на кпп ; кто где стоит на посту ; сколько бойцов на вышке ; расстановка постов полигон ; слева и справа от ворот"},{"d":"Лекция «Постовая служба»","t":"3. Основные задачи караульного","x":"1. Охрана КПП — не допустить проникновение лиц без соответствующих разрешений. 2. Регулярные доклады — о ситуации на посту каждые 15 минут. 3. Доклад при заступлении — в рацию /f, с указанием КПП/вышки. 4. Экипировка — заступать только в полной: бронежилет, оружие, патроны, сухпайки. 5. Знание командного состава — знать в лицо высокопоставленных чинов армии. 6. Проверка документов — у всех прибывающих: паспорт, служебное удостоверение, жетон, бейджик. 7. Вежливое общение — тактично, независимо от ситуации. 8. Взаимодействие с гос. структурами (ФСБ, ГИБДД, Больница, Правительство): - узнать цель прибытия; - запросить служебные удостоверения; - сообщить по рации о прибытии и ожидать указаний.","r":"Лекция «Постовая служба»","k":"задачи караульного ; что делать на посту ; как часто докладывать ; каждые 15 минут доклад ; в какой экипировке заступать ; нужен ли бронежилет на пост ; что брать на пост ; сухпайки на посту ; полная экипировка"},{"d":"Лекция «Постовая служба»","t":"4. Действия при проникновении","x":"1. Немедленно сообщить по рации — это позволяет оперативно организовать оборону. 2. Усилить бдительность — быть готовым к возможной атаке на пост. 3. При отсутствии прямой угрозы — задержать, выяснить обстоятельства, вывести за территорию.","r":"Лекция «Постовая служба»","k":"кто-то пролез на территорию ; проникновение что делать ; нарушитель на территории ; перелез через забор ; чужой на базе ; задержать нарушителя на территории ; вывести за территорию"},{"d":"Лекция «Постовая служба»","t":"Категорически запрещено при проникновении","x":"- Покидать пост для нейтрализации нарушителей. - Игнорировать проникновение. - Паниковать и нарушать порядок на посту. - Самостоятельно вызывать поддержку других силовых структур (ФСБ, МВД). - Самостоятельно транспортировать задержанных в правоохранительные органы — это задача Военной Полиции.","r":"Лекция «Постовая служба»","k":"можно ли уйти с поста за нарушителем ; гнаться за нарушителем ; вызвать мвд самому ; везти задержанного в полицию ; самому доставить в отдел ; кто транспортирует задержанных ; куда везти задержанного ; покидать пост для задержания ; вызвать фсб ; паника на посту"},{"d":"Лекция «Постовая служба»","t":"5. Караульному запрещено","x":"1. Отдавать, продавать табельное оружие, боеприпасы, форму и спец. принадлежности. 2. Покидать пост без причины или разрешения, а также не доложив об этом по рации. Пропускать через КПП посторонних лиц без разрешения старшего состава. *Исключение:* лица с доступом к ЗОТ — после проверки документов. 3. Спать на посту. 4. Вступать в контакт с гражданскими на КПП. *Исключение:* проверка документов, удостоверяющих личность, и цели визита. 5. Заступать в караул без полного боекомплекта и обмундирования. 6. Вести себя неподобающим образом: хамить гражданским и военнослужащим, сидеть или лежать на посту, включать музыку, танцевать, выполнять физ. упражнения. 7. Пользоваться мобильными средствами связи. 8. Открывать огонь по гражданским без видимой причины; доставать оружие без угрозы для жизни.","r":"Лекция «Постовая служба»","k":"что запрещено караульному ; продать оружие ; отдать форму другому ; пропустить постороннего ; уйти с поста без доклада ; пропуск лиц с зот ; открывать огонь без причины ; доставать оружие без угрозы ; пустить на кпп без разрешения старшего"},{"d":"Лекция по субординации","t":"Понятие","x":"Субординация — строго установленная система подчинения по званию и должности, а также правила общения и поведения между военнослужащими. В Армии субординация: - обеспечивает чёткое выполнение приказов; - исключает хаос и самоуправство; - поддерживает уважение к званиям и командованию; - повышает эффективность подразделения.","r":"Лекция по субординации","k":"что такое субординация ; зачем субординация"},{"d":"Лекция по субординации","t":"Иерархия","x":"Каждый военнослужащий обязан: - знать своё звание; - знать, кому он подчиняется. > Принцип: приказ старшего по званию или должности обязателен к выполнению, если он не нарушает устав и правила сервера.","r":"Лекция по субординации","k":"кому я подчиняюсь ; обязателен ли приказ старшего ; приказ нарушает устав ; должен ли знать своё звание"},{"d":"Лекция по субординации","t":"Речевые формулы — выучить дословно","x":"Ситуация — Ответ Согласие — «Так точно» Несогласие — «Никак нет» Получен приказ — «Есть» Хотите обратиться — «[Звание] [Фамилия], разрешите обратиться» Не знаете ответа — «Не могу знать» Обращение к старшим по званию — с использованием звания, в уважительной форме. С уважением обращаться нужно ко всем военнослужащим, независимо от их должности.","r":"Лекция по субординации","k":"как ответить на приказ ; что говорить так точно ; никак нет когда ; разрешите обратиться как правильно ; не могу знать ; как обращаться к старшему по званию ; речевые формулы ; что отвечать командиру ; как правильно отвечать ; есть или так точно"},{"d":"Лекция по субординации","t":"Выполнение приказов","x":"Приказ — официальное распоряжение руководителя / командира / старшего по званию, обязательное для исполнения подчинёнными. Приказ: - выполняется быстро, точно, без личной инициативы; - не обсуждается публично; - может быть уточнён, если неясен.","r":"Лекция по субординации","k":"как выполнять приказ ; можно ли обсуждать приказ ; приказ непонятен ; инициатива при выполнении приказа ; уточнить приказ"},{"d":"Лекция по субординации","t":"Запрещено","x":"- игнорировать приказ; - спорить с командиром; - самовольно менять задачу (проявлять инициативу); - выполнять приказы не от своего командира без разрешения.","r":"Лекция по субординации","k":"спорить с командиром ; игнорировать приказ ; выполнять приказ чужого командира ; самовольно менять задачу ; проявлять инициативу"},{"d":"Лекция по субординации","t":"Дисциплинарная ответственность","x":"За нарушения правил внутреннего распорядка, внутреннего устава, НПА, а также уголовного, этического и трудового кодексов применяются взыскания: 1. устное предупреждение; 2. выговор (устный или строгий); 3. переаттестация; 4. понижение в звании; 5. увольнение из Армии (в тяжёлых случаях или при многочисленных нарушениях).","r":"Лекция по субординации","k":"какие взыскания бывают ; переаттестация ; понижение в звании ; что будет за нарушение субординации"},{"d":"Лекция по субординации","t":"Примеры нарушений","x":"Нарушение — Статья — Взыскание Вступать в неуставные отношения, спор или конфликт со старшим по званию — Ст. 23 ДУ — Предупреждение или выговор Игнорировать приказы старшего состава — ВУ ст. 1.3 (Беспрекословное выполнение приказов), ст. 5.4 (Сущность воинской дисциплины) — —","r":"Лекция по субординации","k":"примеры нарушений субординации ; конфликт со старшим по званию статья ; игнорировал приказ статья ; неуставные отношения статья"},{"d":"Лекция «Строевая подготовка»","t":"Термины","x":"Термин — Определение Строй — Установленное Уставом размещение военнослужащих, подразделений и воинских частей для их совместных действий в пешем порядке и на машинах Шеренга — Строй, в котором военнослужащие размещены один возле другого на одной линии на установленных интервалах Колонна — Строй, в котором военнослужащие расположены в затылок друг другу, а подразделения (машины) — одно за другим на дистанциях, установленных Уставом или командиром","r":"Лекция «Строевая подготовка»","k":"что такое шеренга ; что такое колонна ; что такое строй ; строевые термины ; фланг интервал дистанция ; что значит равняйсь"},{"d":"Лекция «Строевая подготовка»","t":"Военнослужащим запрещено","x":"- Прогуливать либо опаздывать на построение без веской причины. - Самовольно покидать строй, а также вставать в уже сформированный строй без разрешения. → При опоздании: «[Звание] [Фамилия], разрешите встать в строй». - Выталкивать других военнослужащих из строя. - Совершать любые движения без команды (переодевать бронежилет, доставать оружие, доставать телефон и т.п.). - Разговаривать и издавать звуки без разрешения старших в строю. - Есть, пить, курить и совершать прочие повседневные действия вне построений. - Спать во время построения.","r":"Лекция «Строевая подготовка»","k":"опоздал в строй что сказать ; разрешите встать в строй ; можно ли выйти из строя ; вставать в строй без разрешения ; толкаться в строю ; движения без команды ; запрещено в строю"},{"d":"Лекция «Строевая подготовка»","t":"Вечернее построение","x":"- Проводится в дни, указанные генералитетом в новостях армии. О построении сообщается в общую рацию. - Каждое подразделение докладывает о проделанной за день работе. - До личного состава доводится информация. - Нарушать дисциплину в строю запрещено (телефон, разговоры, сон, самовольный выход, непристойные движения). - Перед тем как встать в строй — снять бронежилет и убрать оружие из-за спины.","r":"Лекция «Строевая подготовка»","k":"когда вечернее построение ; что происходит на вечернем построении ; телефон в строю ; разговоры в строю ; доклад подразделения на построении ; где узнать о построении"},{"d":"Лекция «Строевая подготовка»","t":"Доклад старшего в подразделении начальнику","x":"[Начальник] Ответственный офицер, рота ведомственной охраны. [Старший] Я! [Начальник] Выйдите из строя, подойдите ко мне! [Старший] Есть! *Старший выходит из строя, по кратчайшей траектории подходит к начальнику, с последним шагом выполняет воинское приветствие. Начальник выполняет воинское приветствие.* [Старший] Товарищ [Звание], [Ваше звание/должность] по вашему приказанию прибыл! [Начальник] [Звание] [Фамилия Имя], доложить о проделанной работе за день! [Старший] Есть! Рота ведомственной охраны в составе [Кол-во] человек, для проведения вечерней поверки построена, лиц незаконно отсутствующих не выявлено. За [Число] [Месяц] Рота Ведомственной Охраны работала в штатном режиме, [что было проделано за день от вашего подразделения]. Жалоб и заявлений среди военнослужащих не выявлено. [Ваша должность/ранг] роты ведомственной охраны, [Фамилия Имя]. [Начальник] Вольно, стать в строй! *Начальник опускает руку.* [Старший] Есть! *Старший поворачивается к своему подразделению.* [Старший] Вольно! *С первым шагом опускает руку и возвращается на место в строю.*","r":"Лекция «Строевая подготовка»","k":"как докладывать начальнику на построении ; выйдите из строя подойдите ко мне ; доклад старшего подразделения ; рота ведомственной охраны доклад ; как выйти из строя к начальнику"},{"d":"Принятие присяги","t":"Общее","x":"# Принятие присяги Когда: ежедневно 12:00 и 20:00 на плацу, а также в любое время по договорённости. О начале построения на присягу старший офицер докладывает в новости. Требование для повышения ранг 1 → 2. По ст. 1.11 Устава ВС присяга обязательна для каждого прибывшего в часть; отказ или грубое нарушение — основание для увольнения. > Присяга для ФСВНГ проводится отдельно от ВС РФ — будьте внимательны.","r":"Принятие присяги","k":"когда присяга ; во сколько присяга ; где проходит присяга ; присяга обязательна ; присяга для повышения ; присяга на плацу 12:00 20:00"},{"d":"Принятие присяги","t":"Как проходит присяга","x":"Инструктор собирает построение на плацу. Из строя поочерёдно вызывается один человек. Форма одежды: принимающий — «Парадный китель с брюками», дающий присягу — «Парадный мундир с брюками». Выбирается в меню F2 → Комплекты одежды → Фракционные.","r":"Принятие присяги","k":"как проходит присяга ; какая форма на присягу ; что надеть на присягу ; парадный китель или мундир ; где выбрать форму для присяги ; форма одежды присяга ; f2 комплекты одежды ; форма на присягу"},{"d":"Принятие присяги","t":"Вызов из строя","x":"Инструктор: Курсант (Фамилия) Курсант: Я Инструктор: Для принятия торжественной присяги ко мне! Курсант: Есть Курсант выходит из строя, подходит к офицеру по кратчайшей траектории и с последним шагом выполняет воинское приветствие — отдаёт честь. Только после этого докладывает: Товарищ Старший сержант, курсант (Фамилия) для принятия военной присяги прибыл! > Честь отдать обязательно. Доклад без воинского приветствия — нарушение порядка доклада и обращения к старшему, ст. 8 ДУ.","r":"Принятие присяги","k":"как выйти из строя на присяге ; что говорить когда вызвали на присягу ; для принятия торжественной присяги ко мне ; отдать честь на присяге ; как докладывать инструктору на присяге"},{"d":"Принятие присяги","t":"Передача текста","x":"Инструктор: /me протянул папку с текстом присяги в руки новобранцу Курсант: /me взял папку с текстом присяги в руки","r":"Принятие присяги","k":"папка с текстом присяги ; me взял папку ; отыгровка папки на присяге"},{"d":"Принятие присяги","t":"Принятие","x":"Инструктор: Военную присягу принять! Курсант: Есть Курсант поворачивается лицом к строю и произносит текст присяги — уже держа папку в руках: Я, (Фамилия Имя), торжественно присягаю на верность своему Отечеству — Российской Федерации. Клянусь свято соблюдать Конституцию Российской Федерации, строго выполнять требования воинских уставов, приказы командиров и начальников. Клянусь достойно исполнять воинский долг, мужественно защищать свободу, независимость и конституционный строй России, народ и Отечество. Курсант докладывает о принятии: Товарищ Старший сержант, курсант (Фамилия) военную присягу принял!","r":"Принятие присяги","k":"текст присяги ; что говорить на присяге ; слова присяги ; я торжественно присягаю ; военную присягу принять ; куда повернуться на присяге ; текст присяги полностью"},{"d":"Принятие присяги","t":"Завершение","x":"Инструктор: /do Присяга успешно принята новобранцем — Имя Фамилия. Поздравляю с принятием присяги, встать в строй Курсант: Есть Курсант возвращается в строй, вызывается следующий.","r":"Принятие присяги","k":"конец присяги ; do присяга принята ; что говорит инструктор в конце присяги ; встать в строй после присяги"},{"d":"Принятие присяги","t":"На что смотрят при проверке отчёта","x":"- Присяга отыгрывается, не пишется текстом. Письменная форма — только по веской причине, заранее согласованной с руководством. - Перед тем как встать в строй — снять бронежилет и убрать оружие из-за спины. - На плацу нельзя: телефон, разговоры, приём пищи, курение, неформальный вид — ст. 21 ДУ. Курение — ещё и ст. 12.1. - Имя и фамилия в полной форме: Алексей, а не Лёха.","r":"Принятие присяги","k":"отчёт по присяге что нужно ; можно ли присягу текстом ; письменная присяга ; снять бронежилет перед строем ; оружие за спиной на плацу ; телефон на плацу ; курить на плацу ; отклонили отчёт по присяге ; требования к скриншоту присяги"},{"d":"Система повышения","t":"Общее","x":"# Система повышения курсантов ФСВНГ Путь от 1 ранга до военного билета. Актуальная редакция на 19.09.2026.","r":"Система повышения","k":"система повышения ; как повышаться по рангам ; путь до военного билета ; сколько рангов"},{"d":"Система повышения","t":"Ранг 1 → 2","x":"Шесть требований. Выезд за территорию ВЧ — только в сопровождении сотрудников Кадровой службы ФСВНГ, самостоятельный выезд запрещён. # — Требование — Что нужно сделать 1 — Удостоверение — Получить в здании правительства 2 — Лекция по внутренним НПА — Прослушать. Инструктор проводит её разово, сразу по всем шести документам 3 — Лекция-экскурсия по ВЧ — Прослушать 4 — Государственная спец. связь — Присоединиться и получить роль, инструкция ниже 5 — Занятие по физподготовке — 2 скриншота: начало и конец тренировки 6 — Принятие присяги — 1 скриншот. Отыгровка по процедуре, ежедневно в 12:00 и 20:00 на плацу","r":"Система повышения","k":"как получить 2 ранг ; требования на 2 ранг ; что нужно для второго ранга ; с 1 на 2 ранг ; удостоверение где получить ; здание правительства удостоверение ; лекция по нпа ; экскурсия по вч ; спец связь роль ; физподготовка скриншоты ; присяга на 2 ранг ; присяга для второго ранга ; на каком ранге присяга ; выезд за территорию вч курсанту ; можно ли выезжать из части кадету ; кадет выезд в город"},{"d":"Система повышения","t":"Шесть документов лекции по НПА","x":"1. Лекция «Постовая служба» 2. Лекция по субординации 3. Лекция «Строевая подготовка» 4. Дресс-код ФСВНГ 5. Дисциплинарный устав 6. Устав ВС РФ и ФСВНГ Экзамен на этом этапе не сдаётся — он перенесён на этап 2 → 3 и сдаётся один раз по всему материалу целиком, а не по каждому блоку.","r":"Система повышения","k":"что входит в лекцию по нпа ; какие документы на лекции ; когда экзамен по нпа ; экзамен один или по каждому блоку ; что учить к экзамену"},{"d":"Система повышения","t":"Подключение к спец. связи","x":"Четыре шага. Результат — скриншот профиля с ролью Тверской и ником по форме. 1. Присоединиться к спец. связи «Государственные фракции РО»: https://discord.gg/5kTutqS8K 2. Нажать «Получить роль». Получение роли гос. служащего пока недоступно — получаете только Тверской: https://discord.com/channels/1538879177917210668/1538884293592354900/1543186737965309994 3. После этого появится сообщение о получении роли 4. Отредактировать свой ник по форме: Армия | Имя Фамилия | Статик","r":"Система повышения","k":"как подключиться к спец связи ; спецсвязь дискорд ; получить роль тверской ; государственные фракции ро дискорд ; ник по форме в дискорде ; роль гос служащего ; как получить роль"},{"d":"Система повышения","t":"Что идёт в отчёт","x":"- Скриншот профиля с ролью Тверской - Ник строго по форме Армия | Имя Фамилия | Статик","r":"Система повышения","k":"что в отчёт по спец связи ; скриншот профиля дискорд ; ник армия имя фамилия статик ; форма ника"},{"d":"Система повышения","t":"Ранг 2 → 3","x":"# — Требование — Доказательства 1 — Стрельбище — 2 скриншота: начало и завершение занятия 2 — Тренировочная площадка — 2 скриншота: начало и конец полосы препятствий 3 — Караул на КПП №1 или КПП №2 Алабино — 1 час — 5 скриншотов каждые 15 минут с докладом в /f 4 — Экзамен по внутренним НПА ФСВНГ — 1 скриншот результата. Один экзамен сразу по всем шести документам","r":"Система повышения","k":"как получить 3 ранг ; требования на 3 ранг ; что нужно для третьего ранга ; с 2 на 3 ранг ; стрельбище скриншоты ; полоса препятствий ; тренировочная площадка ; караул на кпп час ; экзамен по нпа ; сколько скриншотов на караул ; сколько задач на 3 ранг"},{"d":"Система повышения","t":"Тайминг караула","x":"Заступили в 16:00 → скриншоты в 16:00, 16:15, 16:30, 16:45, 17:00. Первый — заступление на пост, последний — сдача поста.","r":"Система повышения","k":"во сколько делать скриншоты на карауле ; каждые 15 минут скриншот ; сколько скринов за час ; первый и последний скриншот караула ; тайминг доклада"},{"d":"Система повышения","t":"После 3 ранга","x":"После присвоения 3 ранга курсант автоматически зачисляется в РВО — Роту вневедомственной охраны. Выбирать подразделение не нужно. Находясь в РВО, можно подать заявку на перевод в другое подразделение. Перевод — только по одобрению принимающего подразделения. Подразделение — Чем занимается РВО — Рота вневедомственной охраны — сюда зачисляют после 3 ранга ОМОН — Отряд мобильный особого назначения ОСБ — Отдел собственной безопасности — нарушения внутри ФСВНГ КС — Кадровая служба — кадровая работа по всему ФСВНГ АВНГ — Академия ВНГ — обучение курсантов Кадровая служба и АВНГ — два разных подразделения. Дальше военнослужащий растёт по системе повышения своей структуры.","r":"Система повышения","k":"что после 3 ранга ; куда попадаю после третьего ранга ; куда идти после третьего ранга ; рво автоматически ; зачисление в рво ; выбор подразделения ; омон рво осб ; какой отдел выбрать ; как перейти в омон ; как попасть в осб ; заявка в омон из рво ; перевод из рво ; можно ли выбрать подразделение ; что такое авнг ; авнг это ; кадровая служба и авнг разница ; кто обучает курсантов ; как попасть в кадровую службу ; как стать инструктором ; чем занимается кс"},{"d":"Система повышения","t":"Порядок подачи","x":"Шаг 1. Отчёт на повышение — подаётся через Google-форму: https://docs.google.com/forms/d/e/1FAIpQLSfbwGdN5GDH8ZOyQWyjBuToUWGr-g03veAsFkhylA7lY7-Dsw/viewform Шаг 2. Запрос на повышение — только после одобрения отчёта, в канал запроса, со ссылкой на одобренный отчёт.","r":"Система повышения","k":"как подать отчёт на повышение ; где форма отчёта ; гугл форма отчёта ; запрос на повышение куда ; порядок подачи на повышение ; сначала отчёт потом запрос ; куда кидать отчёт"},{"d":"Система повышения","t":"Форма запроса","x":"Четыре строки, порядок не менять. 1. Тег себя (через @) 2. Текущий ранг - ранг на который повышаетесь 3. Ссылка на ОДОБРЕННЫЙ ОТЧЁТ 4. @Тег Кадровой службы","r":"Система повышения","k":"форма запроса на повышение ; как оформить запрос ; что писать в запросе на повышение ; тег кадровой службы в запросе ; кого тегать в запросе на повышение ; шаблон запроса ; сколько строк в запросе"},{"d":"Система повышения","t":"Пример","x":"1. @Зам.КС | Денис Спасский | 65597 2. с 1 по 2 3. [ссылка на одобренный отчёт в #отчет-на-повышение-курсанты] 4. @[👮] Кадровая служба ФСВНГ Заявка не по форме не рассматривается. Первой строкой — свой тег через @, последней — тег Кадровой службы @[👮] Кадровая служба ФСВНГ. Ссылка в третьей строке — на уже одобренный отчёт.","r":"Система повышения","k":"пример запроса на повышение ; образец заявки на повышение ; заявка не по форме ; последняя строка кадровая служба ; с 1 по 2 в запросе"},{"d":"Система повышения","t":"Военный билет","x":"Подаётся по достижении 6 ранга в #запрос-военных-билетов: https://discord.com/channels/1538938584441163776/1550924926582653139. После подачи найти старший состав ФСВНГ и попросить выдать билет.","r":"Система повышения","k":"как получить военный билет ; военный билет с какого ранга ; 6 ранг билет ; запрос военных билетов ; кто выдаёт военный билет ; военник"},{"d":"Система повышения","t":"Доказательства","x":"Принимаются фото и видео только с этих сервисов: YouTube, Rutube, Google Drive, Yandex Disk, imgur, Yapx, Prnt, ibb. Фиксация должна исчерпывающе подтверждать выполнение требования. Правила приёма скриншотов уточняются у Кадровой службы.","r":"Система повышения","k":"какие хостинги для скриншотов ; куда заливать скриншоты ; imgur yapx prnt ; видео на youtube для отчёта ; где хранить доказательства ; принимают ли ссылки на диск"},{"d":"Частые ошибки в отчётах","t":"1. Отсутствие бодикамеры","x":"- Проект RP → бодикамера обязательна. - На скриншотах должна быть плашка бодикамеры с красным индикатором. - Бодикамера носится везде, кроме построения на плацу. Настройка: F2 → Настройки → Назначение клавиш → Бодикамера → назначить удобную клавишу.","r":"Частые ошибки в отчётах","k":"нет бодикамеры на скрине ; красный индикатор камеры ; как включить бодикамеру ; настроить клавишу бодикамеры ; плашка бодикамеры ; камера на построении нужна ; отклонили из-за камеры"},{"d":"Частые ошибки в отчётах","t":"2. Путаница чатов `/f` и `/fb`","x":"Чат — Тип — Назначение /f — IC (in-character) — Общение по рации в рамках RP. Доклады с караула — сюда /fb — OOC (out-of-character) — Вне роли: реальная жизнь, Discord и т.п.","r":"Частые ошибки в отчётах","k":"чем отличается /f от /fb ; куда докладывать f или fb ; что такое fb ; ooc чат ; ic чат ; написал в fb вместо f ; в какой чат доклад"},{"d":"Частые ошибки в отчётах","t":"3. Редактирование скриншотов — запрещено","x":"Нельзя: - делать частичный скриншот; - обрезать скриншоты; - использовать Photoshop и другие редакторы; - каким-либо образом изменять исходный скриншот. Обнаруженное редактирование = попытка ввести руководство в заблуждение → выговор. > Практический вывод: снимать полный экран целиком, отдавать файл как есть.","r":"Частые ошибки в отчётах","k":"можно ли обрезать скриншот ; фотошоп скриншота ; частичный скриншот ; отредактировал скрин ; скриншот полного экрана ; обрезанный скрин отклонили"},{"d":"Частые ошибки в отчётах","t":"4. Неправильный скриншот Discord","x":"- Нужен скриншот Discord своей фракции, а не общего Discord гос. фракций (State). - На скриншоте обязательно видны роли вашего аккаунта на сервере.","r":"Частые ошибки в отчётах","k":"какой скриншот дискорда нужен ; скрин дискорда фракции ; скриншот state дискорда ; роли на скриншоте дискорд ; не тот дискорд"},{"d":"Частые ошибки в отчётах","t":"5. Присяга в письменной форме","x":"- Все действия отыгрываются, проект RP. - Письменная форма — только по веской причине, о которой заранее сообщено руководству.","r":"Частые ошибки в отчётах","k":"присяга текстом ; написал присягу а не отыграл ; письменная присяга можно"},{"d":"Частые ошибки в отчётах","t":"6. Некорректные имя и фамилия","x":"Имя и фамилия — в нормальной форме. ❌ Недопустимо — ✅ Правильно Лёха — Алексей Тошик — Антон Данька — Даниил / Данил До исправления ФИО отчёты могут отклоняться.","r":"Частые ошибки в отчётах","k":"ник лёха отклонили ; какое имя в отчёте ; сокращённое имя ; имя в нормальной форме ; тошик данька ; имя не по форме"},{"d":"Частые ошибки в отчётах","t":"7. Заполнение отчёта не по форме","x":"Перед подачей проверить: - [ ] все ли пункты заполнены; - [ ] соблюдена ли последовательность пунктов; - [ ] не изменена ли структура формы; - [ ] соответствуют ли приложенные доказательства указанным пунктам. Перепутанные пункты или изменённая последовательность → отклонение.","r":"Частые ошибки в отчётах","k":"отчёт не по форме ; перепутал пункты в отчёте ; структура отчёта ; чек-лист перед подачей ; почему отклонили отчёт"},{"d":"Требования к доказательствам","t":"Допустимые хостинги","x":"Фото/видео фиксация принимается только с: Тип — Сервисы Видео — YouTube, Rutube Облако — Google Drive, Yandex Disk Картинки — imgur, Yapx, Prnt, ibb > Фиксация должна иметь исчерпывающие доказательства, подтверждающие то или иное деяние. Правила приёма скриншотов — канал «Требования к скриншотам для отчётов».","r":"Требования к доказательствам","k":"куда загружать скриншоты ; какие сайты для доказательств ; хостинг картинок для отчёта ; можно ли яндекс диск ; видео rutube"},{"d":"Требования к доказательствам","t":"Чек-лист перед загрузкой каждого скриншота","x":"- [ ] Полный экран, без обрезки и редактирования - [ ] Видна плашка бодикамеры с красным индикатором — камера включена везде, кроме построения на плацу - [ ] Виден игровой ник по форме Армия| Имя Фамилия | Статик - [ ] Виден таймер/время, если действие привязано ко времени (караул) - [ ] Доклад написан в /f, а не в /fb - [ ] Ссылка открывается без авторизации (доступ по ссылке для Google/Yandex Disk)","r":"Требования к доказательствам","k":"что должно быть на скриншоте ; чек-лист скриншота ; требования к скриншоту ; ник на скриншоте ; время на скриншоте ; плашка камеры на скрине ; как правильно сделать скриншот для отчёта"}];
